/* ═══════════════════════════════════════════════════════════
   UI POLISH v20 — Profile / Status Card Redesign
   ═══════════════════════════════════════════════════════════ */

/* stat-detail progress bar also thicker */
.stat-detail-prog-track {
  height: 9px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 5px;
  overflow: hidden;
}
.stat-detail-prog-bar {
  border-radius: 5px;
}

/* ── Status card new structure ── */
.sc-card {
  background: var(--bg-raised);
  border: 1.5px solid rgba(245,158,11,0.28);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 4px 32px rgba(0,0,0,0.35);
}

/* Avatar + radar side-by-side row on the Status card */
.sc-portrait-row {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px 6px;
}
.sc-portrait-row .sc-avatar-row { padding: 0; background: none; flex: 0 0 auto; }
.sc-portrait-row .sc-radar-wrap { flex: 1 1 0; padding: 0; min-width: 0; overflow: visible; }
.sc-portrait-row .sc-radar-svg  { max-width: 180px; width: 100%; }

/* iPhone SE & narrower viewports: stack vertically so neither element gets cramped */
@media (max-width: 380px) {
  .sc-portrait-row {
    flex-direction: column;
    align-items: center;
    gap: 14px;
  }
  .sc-portrait-row .sc-avatar         { width: 200px; }
  .sc-portrait-row .sc-radar-svg      { max-width: 240px; }
}

/* Class avatar portrait */
.sc-avatar-row {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  padding: 4px 12px 2px;
  /* Subtle radial spotlight behind the silhouette */
  background:
    radial-gradient(ellipse 50% 65% at 50% 70%,
      rgba(139, 92, 246, 0.18) 0%,
      rgba(139, 92, 246, 0.06) 45%,
      transparent 80%);
}
.sc-avatar {
  width: 160px;
  height: auto;
  max-width: 100%;
  object-fit: contain;
  filter: drop-shadow(0 6px 18px rgba(0, 0, 0, 0.45))
          drop-shadow(0 0 12px rgba(139, 92, 246, 0.22));
  user-select: none;
  -webkit-user-drag: none;
}
/* In the side-by-side portrait row, avatar is the dominant element (compact) */
.sc-portrait-row .sc-avatar { width: 160px; height: auto; }
/* Crossfade only when the player's class actually changed (set by JS). */
.sc-avatar-changed {
  animation: sc-avatar-in 480ms cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes sc-avatar-in {
  from { opacity: 0; transform: translateY(8px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0)   scale(1);    }
}
/* S+ rank: gold spotlight instead of purple */
.sc-card.sc-splus .sc-avatar-row {
  background:
    radial-gradient(ellipse 50% 65% at 50% 70%,
      rgba(245, 158, 11, 0.22) 0%,
      rgba(245, 158, 11, 0.08) 45%,
      transparent 80%);
}
.sc-card.sc-splus .sc-avatar {
  filter: drop-shadow(0 6px 18px rgba(0, 0, 0, 0.45))
          drop-shadow(0 0 14px rgba(245, 158, 11, 0.32));
}

/* Hero row */
.sc-hero {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 18px 10px;
}

.sc-rank-hero {
  position: relative;
  width: 58px;
  height: 58px;
  border-radius: 14px;
  /* Consumes the same --rank-color vars as .rank-badge so the Status
     panel's large rank pill matches whatever tier the user is at. */
  border: 2px solid var(--rank-color, var(--accent));
  background: var(--rank-color-bg, var(--accent-glow));
  box-shadow: 0 0 14px var(--rank-color-shadow, rgba(139,92,246,0.20));
  font-size: 24px;
  font-weight: 900;
  color: var(--rank-color, var(--accent));
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  letter-spacing: -1px;
  /* v2.1 — animated glow pulse. Rank should feel prestigious, not just
     functional. The drop-shadow + box-shadow combo breathes 2.6s,
     intensity oscillating between resting + amplified state. */
  animation: sc-rank-glow 2.6s ease-in-out infinite;
  overflow: visible;
}
/* Aura backdrop — a radial gradient pseudo-element behind the badge
   that pulses outward, creating a sense of ambient energy emanating
   from the rank. Uses --rank-color so each tier feels in-class. */
.sc-rank-hero::before {
  content: "";
  position: absolute;
  inset: -14px;
  background: radial-gradient(
    circle at 50% 50%,
    var(--rank-color, var(--accent)) 0%,
    transparent 60%);
  opacity: 0.18;
  border-radius: 22px;
  z-index: -1;
  animation: sc-rank-aura-breathe 3.2s ease-in-out infinite;
  pointer-events: none;
}
/* Inner highlight — a faint inset ring that subtly shifts brightness,
   suggesting an evolving frame without changing the actual border. */
.sc-rank-hero::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 10px;
  border: 1px solid var(--rank-color, var(--accent));
  opacity: 0.35;
  animation: sc-rank-frame-shimmer 4s ease-in-out infinite;
  pointer-events: none;
}
@keyframes sc-rank-glow {
  0%, 100% { box-shadow: 0 0 10px var(--rank-color-shadow, rgba(139,92,246,0.18)); }
  50%      { box-shadow: 0 0 22px var(--rank-color-shadow, rgba(139,92,246,0.45)),
                          0 0 6px  var(--rank-color, var(--accent)); }
}
@keyframes sc-rank-aura-breathe {
  0%, 100% { transform: scale(0.92); opacity: 0.14; }
  50%      { transform: scale(1.08); opacity: 0.30; }
}
@keyframes sc-rank-frame-shimmer {
  0%, 100% { opacity: 0.22; transform: scale(1);    }
  50%      { opacity: 0.55; transform: scale(0.97); }
}

.sc-rank-hero.splus {
  border-color: var(--gold);
  background: var(--gold-glow);
  color: var(--gold);
  animation: sc-gold-glow 2.4s ease-in-out infinite;
}

.sc-hero-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sc-hero-nameline {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sc-hero-name {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.3px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sc-hero-class {
  font-size: 0.88rem;
  font-weight: 600;
}

/* 3×2 stat grid */
/* ── RADAR CHART ── */
.sc-radar-wrap {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 8px 12px 16px;
}

.sc-radar-svg {
  width: 100%;
  max-width: 280px;
  height: auto;
  overflow: visible;
}

/* The filled shape: starts collapsed at centre, expands on .--animate */
.sc-radar-fill {
  transform-box: fill-box;        /* origin is relative to path's own bounding box */
  transform-origin: 50% 50%;
  transform: scale(0);
  opacity: 0;
  transition: transform 0.65s cubic-bezier(0.34, 1.3, 0.64, 1),
              opacity   0.35s ease;
}

.sc-radar-fill--animate {
  transform: scale(1);
  opacity: 1;
}

/* ─── v2.1 radar drama (subtle, "mystical progression interface") ───
   Five coordinated effects layered on the existing radar:
   1. Rings breathe in opacity on a staggered loop
   2. Axis dots pulse (scale + glow) with stat-color drop-shadow
   3. Dominant stat dot pulses faster + brighter
   4. Constellation lines slowly rotate around the center
   5. Energy core at the center (inner solid dot + outer expanding ring)

   All compositor-level CSS animations — no JS RAF loop. Stops when
   the Status tab isn't visible. */

/* Background rings — slow breathing opacity so the grid feels alive.
   Each ring gets a different delay so they shimmer in waves. */
.sc-radar-ring {
  animation: sc-radar-ring-breathe 4.5s ease-in-out infinite;
}
.sc-radar-ring[data-ring="1"] { animation-delay: 0s;    }
.sc-radar-ring[data-ring="2"] { animation-delay: 0.6s;  }
.sc-radar-ring[data-ring="3"] { animation-delay: 1.2s;  }
.sc-radar-ring[data-ring="4"] { animation-delay: 1.8s;  }
.sc-radar-ring[data-ring="5"] { animation-delay: 2.4s;  }
@keyframes sc-radar-ring-breathe {
  /* v3 Phase 1q — softer grid lines so the radar reads as atmospheric
     light rather than a technical mesh. Peak dropped 0.13 → 0.10. */
  0%, 100% { stroke: rgba(255,255,255,0.035); }
  50%      { stroke: rgba(255,255,255,0.10); }
}

/* Outer axis dots — pulse scale + drop-shadow tinted to their stat
   color. The current fill color is set inline on each <circle> via
   the stat.color, so the drop-shadow inherits it via 'currentColor'
   — but SVG drop-shadow doesn't actually use color. We instead make
   the dots GROW + change opacity, color stays as set inline. */
.sc-radar-dot {
  transform-box: fill-box;
  transform-origin: center;
  animation: sc-radar-dot-pulse 3.2s ease-in-out infinite;
}
.sc-radar-dot[data-stat-idx="0"] { animation-delay: 0s;    }
.sc-radar-dot[data-stat-idx="1"] { animation-delay: 0.45s; }
.sc-radar-dot[data-stat-idx="2"] { animation-delay: 0.9s;  }
.sc-radar-dot[data-stat-idx="3"] { animation-delay: 1.35s; }
.sc-radar-dot[data-stat-idx="4"] { animation-delay: 1.8s;  }
.sc-radar-dot[data-stat-idx="5"] { animation-delay: 2.25s; }
@keyframes sc-radar-dot-pulse {
  0%, 100% { transform: scale(1);    opacity: 0.7; }
  50%      { transform: scale(1.35); opacity: 1;   }
}
.sc-radar-dot--dom {
  animation-duration: 1.8s;
}
@keyframes sc-radar-dot-pulse-dom {
  0%, 100% { transform: scale(1);   opacity: 0.85; }
  50%      { transform: scale(1.7); opacity: 1;    }
}
.sc-radar-dot--dom { animation-name: sc-radar-dot-pulse-dom; }

/* Constellation lines — very faint hairline diagonals. Slowly rotate
   the whole group around the center for the "subtle rotating runes"
   feel. Since SVG <line> elements can't carry transform-origin
   reliably we rotate via a wrapping CSS animation on each — the
   center of rotation is the radar's CX/CY (50% / 50% inside the
   ~280 viewBox; we set transform-origin via CSS percentage). */
.sc-radar-constellation {
  transform-origin: center;
  transform-box: view-box;
  animation: sc-radar-constellation-rotate 60s linear infinite;
  /* Each line has the same animation — they rotate together as a set */
}
@keyframes sc-radar-constellation-rotate {
  from { transform: rotate(0deg);   }
  to   { transform: rotate(360deg); }
}

/* Energy core — small purple node at the radar center. Inner dot
   pulses scale; outer ring expands + fades repeatedly. Mirrors the
   XP-chart endpoint pattern for visual consistency across the app. */
.sc-radar-core {
  transform-box: fill-box;
  transform-origin: center;
  animation: sc-radar-core-pulse 1.6s ease-in-out infinite;
  filter: drop-shadow(0 0 4px #8b5cf6);
}
.sc-radar-core-ring {
  transform-box: fill-box;
  transform-origin: center;
  animation: sc-radar-core-ring-expand 2.4s ease-out infinite;
}
@keyframes sc-radar-core-pulse {
  0%, 100% { transform: scale(1);   opacity: 1;    }
  50%      { transform: scale(1.6); opacity: 0.75; }
}
@keyframes sc-radar-core-ring-expand {
  0%   { transform: scale(0.8); opacity: 0.7; }
  100% { transform: scale(4);   opacity: 0;   }
}

.sc-radar-lbl {
  /* viewBox-unit size, 18px so labels render ≥10px even when the radar
     compresses to ~140px wide on iPhone 14 (scale ~0.57). */
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', system-ui, sans-serif;
}

.sc-radar-sublbl {
  /* viewBox-unit size, 16px → renders ≥10px on screen at iPhone 14 scale */
  font-size: 16px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', system-ui, sans-serif;
}

/* W470 — WLT (Wealth) is economy-only, no combat role. On the radar it now
   reads as a subordinate stat, not a sixth combat peer: smaller/lighter label,
   muted slate fill (set inline), and a calmer, dimmer dot pulse. */
.sc-radar-lbl--econ {
  font-size: 14px;
  font-weight: 600;
  opacity: 0.8;
}
.sc-radar-sublbl--econ { opacity: 0.72; }
.sc-radar-dot--econ { animation-name: sc-radar-dot-pulse-econ; }
@keyframes sc-radar-dot-pulse-econ {
  0%, 100% { transform: scale(0.85); opacity: 0.4; }
  50%      { transform: scale(1);    opacity: 0.6; }
}

/* Bottom metrics strip — v3 Phase 1q polish */
.sc-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  background: rgba(0,0,0,0.18);
  border-top: 1px solid rgba(255,255,255,0.06);
}

.sc-metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px 4px 14px;
  border-right: 1px solid rgba(255,255,255,0.05);
  text-align: center;
  position: relative;
}

.sc-metric:last-child { border-right: none; }

.sc-metric-val {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  letter-spacing: -0.01em;
}
/* First metric (Total XP) reads as the hero number — gold + soft glow. */
.sc-metric:first-child .sc-metric-val {
  color: var(--gold);
  text-shadow: 0 0 12px rgba(245,158,11,0.28);
}
.sc-metric-lbl {
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--text-tertiary);
  text-transform: uppercase;
  margin-top: 5px;
}

/* Profile panel: profile-panel is the scrollable container */
#profile-panel {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
#profile-panel::-webkit-scrollbar { display: none; }

/* Stat row needs right padding for the › chevron */
.stat-body {
  padding-right: 8px;
}

/* ═══════════════════════════════════════════════════════════
   SETTINGS + RESET FLOW
   ═══════════════════════════════════════════════════════════ */

/* Gear button in header */
.header-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.settings-btn {
  /* v3 Phase 1z.136 — matched-pair styling with #header-collapse-btn.
     Was a bare 19px emoji with opacity 0.6; now a 34px squared icon
     button with a faint violet frame so the two controls (settings +
     compact toggle) read as a sibling pair in the top-right. */
  background: rgba(167, 139, 250, 0.06);
  border: 1px solid rgba(167, 139, 250, 0.22);
  font-size: 17px;
  cursor: pointer;
  padding: 0;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  border-radius: 8px;
  -webkit-tap-highlight-color: transparent;
  opacity: 0.85;
  transition: opacity 0.15s, background 0.15s, border-color 0.15s;
  flex-shrink: 0;
}
.settings-btn:active {
  opacity: 1;
  background: rgba(167, 139, 250, 0.16);
  border-color: rgba(167, 139, 250, 0.45);
}

/* ── Settings sheet (bottom sheet) ── */
.settings-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  z-index: 300;
}
.settings-overlay.hidden { display: none !important; }

.settings-sheet {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%) translateY(100%);
  width: 100%;
  max-width: 430px;
  max-height: 88vh;
  overflow-y: auto;
  z-index: 301;
  background: var(--bg-raised);
  border-radius: 22px 22px 0 0;
  padding-bottom: calc(28px + var(--safe-bottom));
  transition: transform 0.32s cubic-bezier(0.32, 1.1, 0.55, 1);
}
.settings-sheet.hidden { display: none !important; }
.settings-sheet.ss-open { transform: translateX(-50%) translateY(0); }

.settings-drag-handle {
  width: 36px;
  height: 4px;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 2px;
  margin: 12px auto 0;
}

.settings-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px 4px;
}

.settings-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
}

.settings-close-btn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--bg-card);
  border: none;
  color: var(--text-secondary);
  font-size: 13px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  -webkit-appearance: none;
}

.settings-app-ver {
  font-size: 0.75rem;
  color: var(--text-tertiary);
}

/* ── Check for Updates ── */
@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
/* ── Sound Toggle ── */
.settings-toggle {
  position: relative;
  width: 44px;
  height: 26px;
  border-radius: 13px;
  border: none;
  background: var(--border);
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.22s ease;
  padding: 0;
  -webkit-appearance: none;
  appearance: none;
}
.settings-toggle::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0,0,0,0.35);
  transition: transform 0.22s ease;
}
.settings-toggle[aria-checked="true"] {
  background: var(--accent);
}
.settings-toggle[aria-checked="true"]::after {
  transform: translateX(18px);
}

/* ── What's Coming ── */
/* ── Shared reset overlay ── */
.reset-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 400;
}
.reset-overlay.hidden { display: none !important; }

/* ── Reset modal (centered) ── */
.reset-modal {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 401;
  width: calc(100% - 48px);
  max-width: 340px;
  background: var(--bg-raised);
  border: 1.5px solid rgba(255, 59, 48, 0.3);
  border-radius: 20px;
  padding: 28px 24px 24px;
  text-align: center;
  animation: reset-modal-in 0.25s cubic-bezier(0.34, 1.3, 0.64, 1);
}
.reset-modal.hidden { display: none !important; }

@keyframes reset-modal-in {
  from { opacity: 0; transform: translate(-50%, -50%) scale(0.88); }
  to   { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

.reset-modal-icon {
  font-size: 2.6rem;
  line-height: 1;
  margin-bottom: 14px;
}

.reset-modal-title {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.3px;
  margin-bottom: 10px;
}

.reset-modal-body {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 22px;
}
.reset-modal-body strong {
  color: var(--danger);
  font-weight: 700;
}

.reset-modal-actions {
  display: flex;
  gap: 10px;
}

.reset-cancel-btn {
  flex: 1;
  padding: 13px;
  background: var(--bg-card);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.925rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  -webkit-appearance: none;
  transition: background 0.15s;
}
.reset-cancel-btn:active { background: var(--bg-card-active); }

.reset-continue-btn {
  flex: 1;
  padding: 13px;
  background: rgba(255, 59, 48, 0.12);
  border: 1.5px solid rgba(255, 59, 48, 0.4);
  border-radius: var(--radius-sm);
  color: var(--danger);
  font-size: 0.925rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  -webkit-appearance: none;
  transition: background 0.15s;
}
.reset-continue-btn:active { background: rgba(255, 59, 48, 0.22); }

/* Type-RESET input */
.reset-type-input {
  width: 100%;
  background: var(--bg-card);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 700;
  text-align: center;
  letter-spacing: 0.12em;
  padding: 13px 14px;
  outline: none;
  font-family: inherit;
  -webkit-appearance: none;
  margin-bottom: 18px;
  transition: border-color 0.2s;
}
.reset-type-input::placeholder {
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--text-tertiary);
}
.reset-type-input.valid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(255, 59, 48, 0.12);
}

.reset-confirm-btn {
  flex: 1;
  padding: 13px;
  background: var(--danger);
  border: none;
  border-radius: var(--radius-sm);
  color: #fff;
  font-size: 0.9rem;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;
  -webkit-appearance: none;
  transition: opacity 0.15s, transform 0.1s;
}
.reset-confirm-btn:not(:disabled):active {
  opacity: 0.85;
  transform: scale(0.97);
}
.reset-confirm-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

/* ── Stats panel ── */
#stats-panel {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

/* ── Next Stat Bonus card ── */
.stats-next-bonus-section {
  margin-bottom: 12px;
}

.nb-card {
  background: var(--bg-card);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  margin: 8px 0 0;
}

.nb-all-done {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  color: var(--text-secondary);
  font-size: 0.9rem;
}

/* ── No Alcohol Weekend Challenge badge on habit card ── */
.na-challenge-badge {
  display: inline-flex;
  align-items: center;
  margin-top: 5px;
  padding: 3px 9px;
  border-radius: 20px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.4;
}
.na-badge-start {
  background: rgba(245, 158, 11, 0.15);
  color: #f59e0b;
  border: 1px solid rgba(245, 158, 11, 0.35);
}
.na-badge-progress {
  background: rgba(249, 115, 22, 0.15);
  color: #f97316;
  border: 1px solid rgba(249, 115, 22, 0.35);
}
.na-badge-final {
  background: rgba(139, 92, 246, 0.12);
  color: #8b5cf6;
  border: 1px solid rgba(139, 92, 246, 0.35);
}
/* ── Friday Weekend Warrior Challenge Modal ── */
.fri-challenge-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.82);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 450;
}
.fri-challenge-overlay.hidden { display: none !important; }

.fri-challenge-modal {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 451;
  width: calc(100% - 40px);
  max-width: 360px;
  background: #0f1a12;
  border: 1.5px solid rgba(245, 158, 11, 0.5);
  border-radius: 22px;
  padding: 28px 22px 24px;
  text-align: center;
  box-shadow: 0 0 60px rgba(245, 158, 11, 0.18), 0 20px 60px rgba(0,0,0,0.6);
  animation: fri-modal-in 0.3s cubic-bezier(0.34, 1.3, 0.64, 1);
  overflow: hidden;
}
.fri-challenge-modal.hidden { display: none !important; }

@keyframes fri-modal-in {
  from { opacity: 0; transform: translate(-50%, -50%) scale(0.85); }
  to   { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

.fri-challenge-glow-bar {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, #f59e0b, #fbbf24, #f59e0b, transparent);
  border-radius: 22px 22px 0 0;
}

.fri-challenge-close-btn {
  position: absolute;
  top: 12px;
  right: 14px;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.07);
  border: none;
  color: rgba(255, 255, 255, 0.45);
  font-size: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  -webkit-appearance: none;
}

.fri-challenge-icon {
  font-size: 2.8rem;
  line-height: 1;
  margin-bottom: 8px;
  filter: drop-shadow(0 0 12px rgba(245,158,11,0.5));
}

.fri-challenge-title {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #f59e0b;
  margin-bottom: 14px;
  text-transform: uppercase;
}

.fri-challenge-msg {
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.85);
  line-height: 1.65;
  margin-bottom: 22px;
}

.fri-challenge-action-btn {
  width: 100%;
  padding: 14px;
  background: #f59e0b;
  color: #000;
  font-size: 0.95rem;
  font-weight: 800;
  font-family: inherit;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  letter-spacing: 0.04em;
  -webkit-appearance: none;
  transition: opacity 0.15s, transform 0.1s;
}
.fri-challenge-action-btn:active {
  opacity: 0.85;
  transform: scale(0.97);
}

/* Ensure lib-list uses correct accordion padding */
#lib-list {
  padding: 8px 16px 16px;
}

/* ══════════════════════════════════════════════════════════
   PERFECT DAY STREAK CELEBRATION SCREEN
   ══════════════════════════════════════════════════════════ */
.perfect-day-screen {
  position: fixed;
  inset: 0;
  z-index: 600;
  background: #050a07;
  display: flex;
  align-items: center;
  justify-content: center;
}
.perfect-day-screen.hidden { display: none !important; }

.pd-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.pd-content {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 48px 32px 40px;
  text-align: center;
  max-width: 390px;
  width: 100%;
}

/* Emoji */
.pd-emoji {
  font-size: 4.5rem;
  line-height: 1;
  animation: pd-emoji-pop 0.55s cubic-bezier(0.34, 1.9, 0.64, 1) both;
  filter: drop-shadow(0 0 24px var(--pd-color, #8b5cf6));
}
@keyframes pd-emoji-pop {
  from { transform: scale(0) rotate(-20deg); opacity: 0; }
  to   { transform: scale(1) rotate(0deg);   opacity: 1; }
}

/* Title */
.pd-title {
  font-size: clamp(1.6rem, 6vw, 2.4rem);
  font-weight: 900;
  letter-spacing: 0.05em;
  color: var(--pd-color, #8b5cf6);
  text-shadow:
    0 0 20px var(--pd-color, #8b5cf6),
    0 0 50px var(--pd-color, #8b5cf6);
  line-height: 1.1;
  min-height: 2.5rem; /* prevent layout jump during letter reveal */
}
/* Normal (non-reveal) titles animate in */
.pd-title:not(.pd-reveal) {
  animation: pd-title-slam 0.45s cubic-bezier(0.34, 1.5, 0.64, 1) 0.15s both;
}
@keyframes pd-title-slam {
  from { opacity: 0; transform: scale(0.7) translateY(24px); }
  to   { opacity: 1; transform: scale(1)   translateY(0);    }
}

/* Subtitle */
.pd-subtitle {
  font-size: 0.95rem;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.65;
  max-width: 290px;
  animation: pd-fade-up 0.45s ease 0.5s both;
}
@keyframes pd-fade-up {
  from { opacity: 0; transform: translateY(18px); }
  to   { opacity: 1; transform: translateY(0);    }
}

/* Bonus XP line */
.pd-bonus {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.3px;
  animation: pd-fade-up 0.45s ease 0.72s both;
}
.pd-bonus-xl {
  font-size: 2rem;
  font-weight: 900;
  letter-spacing: -0.5px;
  text-shadow: 0 0 20px rgba(245,158,11,0.7);
}

/* Dismiss button */
.pd-dismiss {
  margin-top: 12px;
  padding: 15px 52px;
  background: var(--pd-color, #8b5cf6);
  color: #000;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  font-family: inherit;
  -webkit-appearance: none;
  animation: pd-fade-up 0.3s ease both;
  transition: opacity 0.15s, transform 0.1s;
}
.pd-dismiss:active { opacity: 0.85; transform: scale(0.97); }
.pd-dismiss.hidden { display: none !important; }

/* Screen shake */
@keyframes pd-shake {
  0%,100%         { transform: translateX(0); }
  10%,30%,50%,70%,90% { transform: translateX(-7px) rotate(-0.5deg); }
  20%,40%,60%,80% { transform: translateX( 7px) rotate( 0.5deg); }
}
.pd-shake { animation: pd-shake 0.55s ease !important; }

/* ── CHOOSE YOUR PATH SCREEN ──────────────────────────── */
.path-screen {
  position: fixed;
  inset: 0;
  background: #0a0a0a;
  z-index: 900;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.path-screen.hidden { display: none !important; }

.path-header {
  padding: 52px 24px 16px;
  text-align: center;
  flex-shrink: 0;
}
.path-title {
  font-size: clamp(1.5rem, 6.5vw, 2rem);
  font-weight: 900;
  letter-spacing: 0.1em;
  color: #fff;
  margin-bottom: 8px;
}
.path-subtitle {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.01em;
}

.path-cards {
  flex: 0 0 auto;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 40px 28px 8px;
  display: flex;
  flex-direction: row;
  gap: 16px;
  justify-content: center;
  align-items: flex-start;
}

.path-card {
  background: #111;
  border: 2px solid rgba(255, 255, 255, 0.07);
  border-radius: 20px;
  padding: 28px 16px 22px;
  cursor: pointer;
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.12s;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  position: relative;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  flex: 1;
  max-width: 170px;
}

/* Color bar at top */
.path-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--pack-color, #8b5cf6);
  opacity: 0.5;
  transition: opacity 0.2s;
}

/* Tinted glow overlay when selected */
.path-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 14px;
  background: var(--pack-color, #8b5cf6);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
}

.path-card:active { transform: scale(0.96); }

.path-card.path-selected {
  border-color: var(--pack-color, #8b5cf6);
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.4);
}
.path-card.path-selected::before { opacity: 1; }
.path-card.path-selected::after  { opacity: 0.08; }

/* Checkmark badge */
.path-card-check {
  display: none;
  position: absolute;
  top: 9px;
  right: 9px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--pack-color, #8b5cf6);
  color: #000;
  font-size: 0.6rem;
  font-weight: 900;
  align-items: center;
  justify-content: center;
  z-index: 1;
}
.path-card.path-selected .path-card-check { display: flex; }

.path-card-emoji {
  font-size: 3rem;
  line-height: 1;
  margin-bottom: 6px;
  position: relative;
  z-index: 1;
}
.path-card-name {
  font-size: 0.95rem;
  font-weight: 800;
  color: #fff;
  letter-spacing: 0.01em;
  text-align: center;
  position: relative;
  z-index: 1;
}
.path-card-tagline {
  font-size: 0.72rem;
  color: rgba(255, 255, 255, 0.45);
  text-align: center;
  line-height: 1.45;
  position: relative;
  z-index: 1;
}
.path-card-count {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--pack-color, #8b5cf6);
  margin-top: 4px;
  position: relative;
  z-index: 1;
}
.path-card-sub {
  font-size: 0.63rem;
  color: rgba(255, 255, 255, 0.28);
  text-align: center;
  line-height: 1.35;
  font-style: italic;
  position: relative;
  z-index: 1;
  margin-top: 2px;
}

/* Informational note between cards and Continue button */
.path-note {
  flex-shrink: 0;
  text-align: center;
  font-size: 0.72rem;
  color: rgba(255, 255, 255, 0.55);
  line-height: 1.55;
  padding: 14px 28px 10px;
}
.path-note-highlight {
  color: #f59e0b;
  font-weight: 700;
}

/* Footer + continue button */
.path-footer {
  margin-top: auto;
  padding: 14px 20px calc(env(safe-area-inset-bottom, 0px) + 20px);
  flex-shrink: 0;
}
.path-continue-btn {
  width: 100%;
  padding: 17px;
  background: #8b5cf6;
  color: #000;
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  border: none;
  border-radius: 14px;
  cursor: pointer;
  font-family: inherit;
  -webkit-appearance: none;
  transition: opacity 0.2s, transform 0.1s, background 0.3s;
}
.path-continue-btn:disabled {
  opacity: 0.25;
  cursor: not-allowed;
}
.path-continue-btn:not(:disabled):active {
  transform: scale(0.97);
  opacity: 0.88;
}

/* W482 — the "Make Your Own warning popup" (.custom-warning-overlay / .cw-card / .cw-* )
   was removed with the stale pre-W479 two-tier scare modal (showCustomWarning). */

/* Flash overlay for path → onboarding transition */
.path-flash-overlay {
  position: fixed;
  inset: 0;
  background: #fff;
  pointer-events: none;
  opacity: 0;
  z-index: 950;
}
@keyframes path-flash-anim {
  0%   { opacity: 0; }
  25%  { opacity: 0.9; }
  100% { opacity: 0; }
}
.path-flash-overlay.active {
  animation: path-flash-anim 0.34s ease forwards;
}


/* ── SW UPDATE BANNER ─────────────────────────────────────── */
.sw-update-banner {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px 11px 16px;
  background: #13132a;
  border-bottom: 1px solid rgba(139, 92, 246, 0.3);
  box-shadow: 0 2px 16px rgba(0, 0, 0, 0.5);
  transform: translateY(-100%);
  transition: transform 0.28s cubic-bezier(0.34, 1.2, 0.64, 1);
}
.sw-update-banner--show {
  transform: translateY(0);
}
.sw-update-msg {
  flex: 1;
  font-size: 0.85rem;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.85);
  letter-spacing: 0.01em;
}
.sw-update-btn {
  padding: 7px 18px;
  background: #8b5cf6;
  color: #000;
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-family: inherit;
  -webkit-appearance: none;
  white-space: nowrap;
  flex-shrink: 0;
  transition: opacity 0.15s, transform 0.1s;
}
.sw-update-btn:active { opacity: 0.85; transform: scale(0.96); }
.sw-update-dismiss {
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.4);
  font-size: 0.9rem;
  cursor: pointer;
  padding: 4px 6px;
  line-height: 1;
  flex-shrink: 0;
  font-family: inherit;
  transition: color 0.15s;
}
.sw-update-dismiss:active { color: rgba(255, 255, 255, 0.8); }

/* ── COMPOUND EFFECT PROGRESS STRIP ─────────────────────── */
.compound-progress {
  padding: 10px 14px 4px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.compound-progress.hidden { display: none !important; }

/* v3 Phase 1o — the persistent bottom pack-progress strip is retired
   on the Habits screen. Pack progress is now reached via tapping the
   top "X / Y HABITS TODAY" tile, which opens #pack-progress-modal.
   The renderCompoundProgress path still writes to #compound-progress
   so the same builder + chip event delegation feeds the modal too —
   we just hide the footer surface. */
#compound-progress.compound-progress--footer { display: none !important; }
/* Footer variant — sits inside #main-footer above the Add Habits button */
.compound-progress--footer {
  padding: 0;
  gap: 10px;  /* breathing room between Morning Routine + Locked-In strips */
}
.compound-progress--footer .cp-prog-row {
  padding: 11px 14px;  /* slightly taller strips for the new layout */
}
/* When the row has missing canonical habits, give it a clickable affordance */
.cp-prog-row--addable {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.18s ease, border-color 0.18s ease;
}
.cp-prog-row--addable:hover  { background: rgba(245,158,11,0.14); border-color: rgba(245,158,11,0.35); }
.cp-prog-row--addable:active { transform: scale(0.99); }
.cp-prog-row--lockedin.cp-prog-row--addable:hover { background: rgba(124,58,237,0.18); border-color: rgba(124,58,237,0.45); }

.cp-prog-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 7px 12px;
  background: rgba(245,158,11,0.07);
  border: 1px solid rgba(245,158,11,0.18);
  border-radius: 11px;
}
/* W501 — compound XP meter: the banked → full projected compound XP this day
   will pay. Wraps to its own full-width line under the routine row. */
.cp-prog-xp {
  flex: 0 0 100%;
  margin-top: 2px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.cp-prog-xp-bar {
  flex: 1;
  height: 5px;
  border-radius: 3px;
  background: rgba(245,158,11,0.14);
  overflow: hidden;
}
.cp-prog-xp-fill {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, #f59e0b, #fbbf24);
  box-shadow: 0 0 8px rgba(245,158,11,0.5);
  transition: width 0.4s ease;
}
.cp-prog-xp-text {
  flex: 0 0 auto;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: rgba(245,158,11,0.7);
  white-space: nowrap;
}
.cp-prog-xp-text b { color: #fbbf24; font-weight: 800; }
.cp-prog-xp--done .cp-prog-xp-fill {
  background: linear-gradient(90deg, #16a34a, #22c55e);
  box-shadow: 0 0 8px rgba(34,197,94,0.5);
}
.cp-prog-xp--done .cp-prog-xp-text { color: rgba(34,197,94,0.8); }
.cp-prog-xp--done .cp-prog-xp-text b { color: #22c55e; }
.cp-prog-name {
  flex: 1;
  font-size: 12px;
  font-weight: 700;
  color: rgba(245,158,11,0.85);
}
.cp-prog-count {
  font-size: 12px;
  font-weight: 700;
  color: rgba(245,158,11,0.6);
}
.cp-prog-count.cp-prog-done {
  color: #22c55e;
}
.cp-prog-streak {
  font-size: 11px;
  font-weight: 600;
  color: var(--streak-color);
  margin-left: 4px;
}

/* ── COMPOUND EFFECT POPUP ──────────────────────────────── */
.compound-popup {
  position: fixed;
  inset: 0;
  z-index: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  background: rgba(0,0,0,0.55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.compound-popup.hidden { display: none !important; }

@keyframes cp-appear {
  from { opacity: 0; transform: scale(0.82) translateY(12px); }
  to   { opacity: 1; transform: scale(1)    translateY(0); }
}
@keyframes cp-disappear {
  from { opacity: 1; transform: scale(1)    translateY(0); }
  to   { opacity: 0; transform: scale(0.92) translateY(-8px); }
}

.cp-card {
  background: linear-gradient(160deg, #1c1400 0%, #241c00 60%, #1a1200 100%);
  border: 2px solid rgba(245,158,11,0.45);
  border-radius: 26px;
  padding: 32px 28px 26px;
  width: calc(100% - 48px);
  max-width: 340px;
  text-align: center;
