  position: relative;
  box-shadow: 0 0 36px rgba(245,158,11,0.16),
              0 12px 48px rgba(0,0,0,0.55);
  animation: bi-pop 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes bi-pop {
  from { opacity: 0; transform: scale(0.92); }
  to   { opacity: 1; transform: scale(1);    }
}

.bi-close-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--text-secondary);
  width: 30px;
  height: 30px;
  border-radius: 8px;
  font-size: 0.85rem;
  cursor: pointer;
  font-family: inherit;
  -webkit-appearance: none;
}
.bi-close-btn:active { background: rgba(255,255,255,0.10); }

.bi-icon {
  font-size: 1.8rem;
  text-align: center;
  margin-top: 4px;
  filter: drop-shadow(0 0 14px rgba(245,158,11,0.55));
}
.bi-title {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--gold);
  text-align: center;
  margin-top: 6px;
  letter-spacing: 0.02em;
}
.bi-subtitle {
  font-size: 0.88rem;
  color: var(--text-secondary);
  text-align: center;
  margin-top: 4px;
  margin-bottom: 18px;
  font-style: italic;
}

.bi-section {
  margin-bottom: 16px;
  padding: 12px 14px;
  background: rgba(255,255,255,0.025);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
}
.bi-section-label {
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--text-tertiary);
  margin-bottom: 8px;
}
.bi-tier {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 0;
  font-size: 0.88rem;
  color: var(--text-primary);
}
.bi-tier-day { color: var(--text-secondary); }
.bi-tier-xp  { color: var(--gold); font-weight: 700; font-variant-numeric: tabular-nums; }
.bi-tier--peak {
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid rgba(255,255,255,0.06);
}
.bi-tier--peak .bi-tier-xp { color: #fbbf24; }
.bi-section-foot {
  margin-top: 10px;
  font-size: 0.78rem;
  color: var(--text-tertiary);
  font-style: italic;
}

.bi-section--mr {
  border-color: rgba(245,158,11,0.28);
  background: rgba(245,158,11,0.05);
}
.bi-section--li {
  border-color: rgba(124,58,237,0.32);
  background: rgba(124,58,237,0.06);
}
.bi-pack-head {
  font-size: 0.95rem;
  margin-bottom: 6px;
  color: var(--text-primary);
}
.bi-section--mr .bi-pack-head b { color: var(--gold); }
.bi-section--li .bi-pack-head b { color: #c4b5fd; }
.bi-pack-body {
  font-size: 0.84rem;
  color: var(--text-secondary);
  line-height: 1.55;
}
.bi-pack-body b { color: var(--text-primary); font-weight: 700; }

.bi-done-btn {
  margin-top: 6px;
  width: 100%;
  padding: 14px;
  background: var(--gold);
  color: #1a1505;
  border: none;
  border-radius: 12px;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  cursor: pointer;
  -webkit-appearance: none;
  transition: transform 0.1s ease, opacity 0.18s ease;
}
.bi-done-btn:active { transform: scale(0.985); opacity: 0.94; }

.pr-tile {
  flex: 0 0 auto;
  width: 78px;
  min-height: 92px;
  background: var(--bg-card);
  border: 1.5px solid var(--border);
  border-radius: 11px;
  padding: 8px 4px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  font-family: inherit;
  -webkit-appearance: none;
  scroll-snap-align: start;
  position: relative;
  transition: transform 0.1s ease, border-color 0.18s ease, box-shadow 0.22s ease;
}
.pr-tile::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: var(--pr-accent, #a78bfa);
  border-radius: 11px 11px 0 0;
  opacity: 0.85;
}
.pr-tile:hover  { border-color: var(--pr-accent, rgba(167,139,250,0.55)); }
.pr-tile:active { transform: scale(0.97); }
.pr-tile-value {
  font-size: 1rem;
  font-weight: 800;
  color: var(--pr-accent, var(--text-primary));
  font-variant-numeric: tabular-nums;
  letter-spacing: 0;
  line-height: 1.05;
  text-align: center;
  word-break: break-word;
}
.pr-tile-label {
  font-size: 0.55rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-align: center;
  line-height: 1.2;
  text-transform: lowercase;
  letter-spacing: 0;
  /* Cap to two lines with ellipsis fallback so labels never blow up the box */
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ═══════════════════════════════════════════════════════════════
   PR DETAIL — bottom-sheet
   ═══════════════════════════════════════════════════════════════ */
.pr-detail-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.55);
  /* Stacks ABOVE the All-PRs sheet (z 360/361) so the detail sits on top
     and closing it leaves the user on the All-PRs grid. */
  z-index: 380;
  animation: pr-fade 0.20s ease-out;
}
.pr-detail-overlay.hidden { display: none !important; }
@keyframes pr-fade { from { opacity: 0 } to { opacity: 1 } }

.pr-detail-sheet {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 430px;
  max-height: 80vh;
  z-index: 381;
  background: var(--bg-raised);
  border: 1.5px solid var(--pr-accent, rgba(255,255,255,0.18));
  border-bottom: none;
  border-radius: 22px 22px 0 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding-bottom: calc(20px + var(--safe-bottom));
  animation: pr-up 0.30s cubic-bezier(0.32, 0.72, 0, 1);
}
.pr-detail-sheet.hidden { display: none !important; }
@keyframes pr-up {
  from { transform: translateX(-50%) translateY(100%); }
  to   { transform: translateX(-50%) translateY(0); }
}
.pr-drag-handle {
  width: 36px;
  height: 4px;
  background: rgba(255,255,255,0.16);
  border-radius: 2px;
  margin: 12px auto 0;
  flex-shrink: 0;
}
.pr-detail-header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 14px 18px 4px;
}
.pr-detail-icon  { font-size: 1.8rem; line-height: 1; }
.pr-detail-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.3;
}
.pr-detail-close {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--text-secondary);
  width: 32px; height: 32px;
  border-radius: 8px;
  font-family: inherit;
  font-size: 0.9rem;
  cursor: pointer;
  -webkit-appearance: none;
}
.pr-detail-body {
  padding: 8px 18px 14px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.pr-detail-value {
  font-size: 2.4rem;
  font-weight: 900;
  color: var(--pr-accent, var(--accent));
  text-align: center;
  line-height: 1;
  margin-top: 6px;
  font-variant-numeric: tabular-nums;
}
.pr-detail-meta {
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-bottom: 4px;
}
.pr-detail-motivation {
  font-size: 0.92rem;
  color: var(--text-primary);
  line-height: 1.5;
  font-style: italic;
  text-align: center;
  padding: 12px 14px;
  background: rgba(255,255,255,0.03);
  border-radius: 10px;
}
.pr-detail-beat {
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-align: center;
  color: var(--pr-accent, var(--accent));
  padding: 10px;
  border: 1px dashed var(--pr-accent, rgba(255,255,255,0.18));
  border-radius: 10px;
}

/* ═══════════════════════════════════════════════════════════════
   PR Tier 2 modal popup
   ═══════════════════════════════════════════════════════════════ */
.pr-popup {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.62);
  z-index: 380;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.pr-popup.hidden { display: none !important; }
.pr-popup-card {
  background: var(--bg-raised);
  border: 1.5px solid var(--pr-accent, rgba(167,139,250,0.45));
  border-radius: 18px;
  padding: 24px 22px 20px;
  width: 100%;
  max-width: 360px;
  text-align: center;
  box-shadow: 0 0 36px rgba(0,0,0,0.5),
              0 0 24px var(--pr-accent, rgba(167,139,250,0.30));
}
.pr-popup-label {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--gold);
}
.pr-popup-icon  { font-size: 2.6rem; margin: 12px 0 4px; }
.pr-popup-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 14px;
  line-height: 1.3;
}
.pr-popup-value {
  font-size: 2.6rem;
  font-weight: 900;
  color: var(--pr-accent, var(--accent));
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.pr-popup-prev {
  font-size: 0.85rem;
  color: var(--text-tertiary);
  margin-top: 6px;
}
.pr-popup-hint {
  font-size: 0.7rem;
  color: var(--text-tertiary);
  margin-top: 16px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.pr-popup--show .pr-popup-card {
  animation: pr-pop 0.32s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.pr-popup--hide .pr-popup-card {
  animation: pr-pop-out 0.20s ease-in forwards;
}
@keyframes pr-pop {
  from { opacity: 0; transform: scale(0.85); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes pr-pop-out {
  to { opacity: 0; transform: scale(0.92); }
}

/* ═══════════════════════════════════════════════════════════════
   PR Tier 3 full-screen takeover
   ═══════════════════════════════════════════════════════════════ */
.pr-takeover {
  position: fixed;
  inset: 0;
  z-index: 400;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.pr-takeover.hidden { display: none !important; }
.pr-takeover-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 40%,
      var(--pr-accent, #f59e0b) 0%,
      rgba(0,0,0,0.92) 60%,
      #000 100%);
  opacity: 0;
}
.pr-takeover-content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 32px;
  opacity: 0;
}
.pr-takeover-eyebrow {
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.32em;
  color: var(--pr-accent, var(--gold));
  text-transform: uppercase;
  margin-bottom: 18px;
  text-shadow: 0 0 24px var(--pr-accent, rgba(245,158,11,0.6));
}
.pr-takeover-headline {
  font-size: 2.4rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: #fff;
  line-height: 1.05;
  margin-bottom: 22px;
  text-shadow: 0 0 36px var(--pr-accent, rgba(245,158,11,0.55));
  text-transform: uppercase;
}
.pr-takeover-sub {
  font-size: 1.05rem;
  color: rgba(255,255,255,0.85);
  font-style: italic;
  max-width: 360px;
  line-height: 1.5;
}
.pr-takeover-hint {
  position: absolute;
  bottom: calc(36px + var(--safe-bottom));
  font-size: 0.7rem;
  color: rgba(255,255,255,0.5);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.pr-takeover--show .pr-takeover-bg      { animation: pr-bg-in 0.45s ease-out forwards; }
.pr-takeover--show .pr-takeover-content { animation: pr-content-in 0.55s 0.15s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
.pr-takeover--hide .pr-takeover-bg,
.pr-takeover--hide .pr-takeover-content { animation: pr-fade-out 0.30s ease-in forwards; }
@keyframes pr-bg-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes pr-content-in {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes pr-fade-out {
  to { opacity: 0; }
}

/* ═══════════════════════════════════════════════════════════════
   PERSONAL RECORDS — Status tab button (replaces inline strip)
   ═══════════════════════════════════════════════════════════════ */
.pr-open-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  width: calc(100% - 36px);
  margin: 4px 18px 12px;
  padding: 12px 14px;
  background: linear-gradient(135deg, rgba(245,158,11,0.10), rgba(245,158,11,0.04));
  border: 1px solid rgba(245,158,11,0.32);
  border-radius: 12px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  font-family: inherit;
  -webkit-appearance: none;
  text-align: left;
  transition: transform 0.1s ease, border-color 0.18s ease, background 0.22s ease;
}
.pr-open-btn:hover  { border-color: rgba(245,158,11,0.55); background: rgba(245,158,11,0.10); }
.pr-open-btn:active { transform: scale(0.99); }
/* ═══════════════════════════════════════════════════════════════
   PERSONAL RECORDS — All-PRs grid bottom-sheet
   ═══════════════════════════════════════════════════════════════ */
.pr-all-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.55);
  z-index: 360;
  animation: pr-fade 0.20s ease-out;
}
.pr-all-overlay.hidden { display: none !important; }
.pr-all-sheet {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 430px;
  max-height: 82vh;
  z-index: 361;
  background: var(--bg-raised);
  border: 1.5px solid rgba(245,158,11,0.32);
  border-bottom: none;
  border-radius: 22px 22px 0 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding-bottom: calc(20px + var(--safe-bottom));
  animation: pr-up 0.30s cubic-bezier(0.32, 0.72, 0, 1);
}
.pr-all-sheet.hidden { display: none !important; }
.pr-all-header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 10px 18px 12px;
}
.pr-all-icon  { font-size: 1.4rem; line-height: 1; }
.pr-all-title {
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--gold);
}
.pr-all-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  padding: 4px 18px 8px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

/* Grid-variant tiles — wider with 2 columns, more breathing room */
.pr-tile.pr-tile--grid {
  width: 100%;
  min-height: 104px;
  padding: 14px 10px 12px;
  border-radius: 13px;
  gap: 4px;
}
.pr-tile.pr-tile--grid::before {
  height: 3px;
  border-radius: 13px 13px 0 0;
}
.pr-tile.pr-tile--grid .pr-tile-value { font-size: 1.45rem; }
.pr-tile.pr-tile--grid .pr-tile-label { font-size: 0.7rem; }

/* ═══════════════════════════════════════════════════════════════
   STAT DETAIL — linked-habit row Add / Active controls
   ═══════════════════════════════════════════════════════════════ */
.sdh-row { gap: 8px; }
.sdh-row--have { opacity: 0.85; }

.sdh-add-btn {
  flex-shrink: 0;
  margin-left: auto;
  padding: 6px 12px;
  background: rgba(139, 92, 246, 0.14);
  border: 1px solid rgba(139, 92, 246, 0.45);
  color: #c4b5fd;
  border-radius: 8px;
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
  -webkit-appearance: none;
  -webkit-tap-highlight-color: transparent;
  transition: transform 0.1s ease, background 0.18s ease, border-color 0.18s ease;
  white-space: nowrap;
}
.sdh-add-btn:hover  { background: rgba(139, 92, 246, 0.22); border-color: rgba(139, 92, 246, 0.65); }
.sdh-add-btn:active { transform: scale(0.96); }

.sdh-active {
  flex-shrink: 0;
  margin-left: auto;
  padding: 6px 10px;
  border-radius: 8px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #22c55e;
  background: rgba(34, 197, 94, 0.10);
  border: 1px solid rgba(34, 197, 94, 0.30);
  white-space: nowrap;
}

/* When the row already has the habit, slightly fade the diff badge so
   the eye is drawn to the missing habits' Add buttons instead. */
.sdh-row--have .diff-badge { opacity: 0.55; }

/* ═══════════════════════════════════════════════════════════════
   AWAKENING — full-screen takeover (first class assignment)
   ═══════════════════════════════════════════════════════════════ */
.awakening-screen {
  position: fixed;
  inset: 0;
  z-index: 500;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.awakening-screen.hidden { display: none !important; }
.awk-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 38%,
      var(--awk-color, #8b5cf6) 0%,
      rgba(0,0,0,0.92) 55%,
      #000 100%);
  opacity: 0;
}
.awk-content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 32px;
  opacity: 0;
}
.awk-eyebrow {
  font-size: 0.92rem;
  font-weight: 900;
  letter-spacing: 0.4em;
  color: var(--awk-color, #fff);
  text-transform: uppercase;
  margin-bottom: 12px;
  text-shadow: 0 0 28px var(--awk-color, rgba(139,92,246,0.6));
}
.awk-avatar {
  width: 200px;
  height: auto;
  filter: drop-shadow(0 0 36px var(--awk-color, rgba(139,92,246,0.5)))
          drop-shadow(0 12px 28px rgba(0,0,0,0.6));
  margin-bottom: 14px;
}
.awk-name {
  font-size: 2.2rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  color: #fff;
  text-shadow: 0 0 28px var(--awk-color, rgba(139,92,246,0.55));
  text-transform: uppercase;
  margin-bottom: 12px;
}
.awk-desc {
  font-size: 1rem;
  color: rgba(255,255,255,0.85);
  font-style: italic;
  max-width: 340px;
  line-height: 1.55;
}
.awk-hint {
  position: absolute;
  bottom: calc(36px + var(--safe-bottom));
  font-size: 0.7rem;
  color: rgba(255,255,255,0.5);
  letter-spacing: 0.2em;
  text-transform: uppercase;
}
.awk-show .awk-bg      { animation: awk-bg-in 0.50s ease-out forwards; }
.awk-show .awk-content { animation: awk-cnt-in 0.65s 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
.awk-hide .awk-bg,
.awk-hide .awk-content { animation: awk-out 0.30s ease-in forwards; }
@keyframes awk-bg-in  { from { opacity: 0 } to { opacity: 1 } }
@keyframes awk-cnt-in { from { opacity: 0; transform: translateY(14px) scale(0.96); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes awk-out    { to { opacity: 0 } }

/* ═══════════════════════════════════════════════════════════════
   CLASS CHOICE — full-screen takeover
   ═══════════════════════════════════════════════════════════════ */
.class-choice-screen {
  position: fixed;
  inset: 0;
  z-index: 510;
}
.class-choice-screen.hidden { display: none !important; }
.cc-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 30%,
      rgba(139, 92, 246, 0.30) 0%,
      rgba(0,0,0,0.92) 55%,
      #000 100%);
  opacity: 0;
}
.cc-content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 28px 18px calc(28px + var(--safe-bottom));
  opacity: 0;
}
.cc-eyebrow {
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.32em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 10px;
  text-align: center;
  text-shadow: 0 0 22px rgba(245,158,11,0.55);
}
.cc-headline {
  font-size: 1.85rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: #fff;
  margin-bottom: 8px;
  text-align: center;
  text-transform: uppercase;
}
.cc-sub {
  font-size: 0.92rem;
  color: rgba(255,255,255,0.75);
  font-style: italic;
  margin-bottom: 22px;
  max-width: 340px;
  text-align: center;
  line-height: 1.5;
}
.cc-options {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  width: 100%;
  max-width: 460px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.cc-card {
  background: rgba(20, 20, 30, 0.85);
  border: 1.5px solid var(--cc-color, rgba(255,255,255,0.18));
  border-radius: 14px;
  padding: 12px 10px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  font-family: inherit;
  -webkit-appearance: none;
  text-align: center;
  transition: transform 0.1s ease, box-shadow 0.22s ease, border-color 0.18s ease;
}
.cc-card:hover  { box-shadow: 0 0 28px var(--cc-color, rgba(139,92,246,0.30)); }
.cc-card:active { transform: scale(0.97); }
.cc-card-avatar {
  width: 78px;
  height: auto;
  filter: drop-shadow(0 0 14px var(--cc-color, rgba(139,92,246,0.4)));
}
.cc-card-emoji { font-size: 1.3rem; line-height: 1; }
.cc-card-name {
  font-size: 0.92rem;
  font-weight: 900;
  color: var(--cc-color, #fff);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.cc-card-desc {
  font-size: 0.72rem;
  color: rgba(255,255,255,0.75);
  font-style: italic;
  line-height: 1.35;
  min-height: 2.7em;
}
.cc-card-cta {
  margin-top: 6px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--cc-color, #fff);
  padding: 6px 10px;
  border: 1px solid var(--cc-color, rgba(255,255,255,0.3));
  border-radius: 100px;
  text-transform: uppercase;
}
.cc-show .cc-bg      { animation: cc-bg-in 0.45s ease-out forwards; }
.cc-show .cc-content { animation: cc-cnt-in 0.55s 0.10s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
.cc-hide .cc-bg,
.cc-hide .cc-content { animation: cc-out 0.28s ease-in forwards; }
@keyframes cc-bg-in  { from { opacity: 0 } to { opacity: 1 } }
@keyframes cc-cnt-in { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes cc-out    { to { opacity: 0 } }

/* ═══════════════════════════════════════════════════════════════
   DUNGEON BOSSES — list of bosses in #quests-panel + full-screen
   detail modal (#boss-fs-overlay). Card visual lives in the .bcard
   block below; modal styling lives at the bottom of this file.
   ═══════════════════════════════════════════════════════════════ */
.bosses-section {
  margin: 8px 14px 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.bosses-section-label {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: var(--text-tertiary);
  margin-left: 2px;
}

/* ── Quests-tab gate grid (v2.0.4) ──────────────────────────────
   3-column × 2-row grid of rank-tier gates (6 cells total — exactly
   matches the 6 rank tiers E/D/C/B/A/S). Cell 1 is the active E gate;
   cells 2-6 are dim dashed placeholders. The grid reads as a roadmap
   of what's coming.

   Why 3×2 vs the previous 2×3: at 3 columns the whole roadmap fits
   above the fold on every common phone (grid height ≈ 292px, tiny
   share of even iPhone SE's 492px content budget). 2×3 spilled over
   on iPhone SE.

   Cell aspect 4:5 matches gate art exactly — `object-fit: cover` on
   a 4:5 cell with 4:5 source means no cropping, so the gold sigil
   at top-center and the runes on the doorframe stay visible at this
   smaller cell size.

   When SS is added (7th tier), grid extends to 3×3 with 2 trailing
   empty cells (or shifts to 4×2 — pick at the time). */
.gate-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  width: 96%;
  max-width: 600px;
  margin: 14px auto 24px;
}

.gate-cell {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: 10px;
  padding: 0;
  background: transparent;
  border: 0;
  font-family: inherit;
  -webkit-tap-highlight-color: transparent;
}

.gate-cell-img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 10px;
  pointer-events: none;
  user-select: none;
}

/* Rank pill scaled for the 3-col grid cell. At max-width 600px, cells
   reach ~190px wide on wide viewports / ~120px on iPhone SE. 32×32
   stays readable at large size without overpowering smaller phones
   (where it occupies ~27% of cell width — tight but legible). Reuses
   .rank-badge color tokens; overrides size + position only. */
.gate-cell-rank-pill {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 2;
  pointer-events: none;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  font-size: 13px;
  box-shadow: 0 0 8px rgba(139, 92, 246, 0.30);
}

/* Per-rank color tokens. Set via `data-rank="X"` on any rank-pill
   element. Consumed by .rank-badge / .sc-rank-hero / .rp-badge /
   .gate-cell-rank-pill (any element with --rank-color in scope picks
   them up automatically). Adding a new rank-pill surface in the
   future = just give it `data-rank` + a class that uses the vars,
   no per-surface CSS duplication.
   Pattern: bg = color @ 18%, border + text = full color, shadow @ 40%. */
[data-rank="E"] {
  --rank-color: #8b5cf6;          /* purple — brand default */
  --rank-color-bg: rgba(139, 92, 246, 0.18);
  --rank-color-shadow: rgba(139, 92, 246, 0.30);
}
[data-rank="D"] {
  --rank-color: #22d3ee;          /* cyan — D-rank lightning haze */
  --rank-color-bg: rgba(34, 211, 238, 0.18);
  --rank-color-shadow: rgba(34, 211, 238, 0.40);
}
[data-rank="C"] {
  --rank-color: #34d399;          /* emerald — C-rank vegetation */
  --rank-color-bg: rgba(52, 211, 153, 0.18);
  --rank-color-shadow: rgba(52, 211, 153, 0.40);
}
[data-rank="B"] {
  --rank-color: #fbbf24;          /* amber — B-rank sandstone */
  --rank-color-bg: rgba(251, 191, 36, 0.18);
  --rank-color-shadow: rgba(251, 191, 36, 0.40);
}
[data-rank="A"] {
  --rank-color: #ef4444;          /* red — A-rank ember/flame */
  --rank-color-bg: rgba(239, 68, 68, 0.18);
  --rank-color-shadow: rgba(239, 68, 68, 0.40);
}
[data-rank="S"] {
  --rank-color: #e879f9;          /* fuchsia — S-rank cosmic apex */
  --rank-color-bg: rgba(232, 121, 249, 0.18);
  --rank-color-shadow: rgba(232, 121, 249, 0.40);
}
/* S+ keeps its existing animated gold treatment via .rank-s-plus —
   no [data-rank="S+"] override needed. The .rank-s-plus class wins
   on specificity (two classes vs one attribute selector). */

/* All gate cells are buttons (cursor: pointer, focus ring, hover/
   pressed states). Unlocked cells expand to the dungeon view; locked
   cells fire a "Reach X rank to unlock" toast. Both interactions
   wired in renderQuestsPanel + setupQuestsGate via delegation on
   #quests-gate-grid. */
.gate-cell {
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.gate-cell:hover {
  transform: scale(1.02);
  box-shadow: 0 0 18px rgba(245, 158, 11, 0.32);
}
.gate-cell:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.55), 0 0 18px rgba(245, 158, 11, 0.32);
}
.gate-cell:active {
  transform: scale(0.98);
}

/* Locked-state. Dim the gate art so it reads as "you can see the
   path ahead but it's not yet open." Conservative filter — modest
   brightness drop + slight desaturation. If a specific rank's art
   reads poorly at these values (e.g., S-rank cosmic art going too
   dark), per-rank overrides can be added via [data-gate-rank="S"]
   selectors without touching the base. */
.gate-cell--locked .gate-cell-img {
  filter: brightness(0.45) saturate(0.7);
}
.gate-cell--locked:hover {
  /* Subtler hover for locked cells — still tappable for the toast,
     but shouldn't feel as inviting as the unlocked gate. */
  box-shadow: 0 0 14px rgba(139, 92, 246, 0.20);
}
.gate-cell--locked .gate-cell-rank-pill {
  /* Dim the pill alongside the art so the rank letter doesn't
     scream at full saturation against muted gate art. */
  opacity: 0.65;
}

/* Preview state (v2.0.1): rank locked, but the dungeon has bosses
   to view. Walkable — same dim treatment as locked, but no lock
   overlay (the gate is enterable; the engagement gate happens at
   the boss-detail level instead). The PREVIEW label sits inside
   the dungeon's cards, not on the gate cell. */
.gate-cell--preview .gate-cell-img {
  filter: brightness(0.55) saturate(0.75);
}
.gate-cell--preview:hover {
  /* Slightly more inviting than locked — the gate IS walkable. */
  box-shadow: 0 0 18px rgba(245, 158, 11, 0.22);
}
.gate-cell--preview .gate-cell-rank-pill {
  /* Lighter dim than locked-rank pill — the gate is reachable. */
  opacity: 0.85;
}

/* Lock overlay — center-bottom of the cell, hidden by default.
   Revealed only when the parent carries .gate-cell--locked. */
.gate-cell-lock-overlay {
  display: none;
  position: absolute;
  left: 0;
  right: 0;
  bottom: 12px;
  z-index: 3;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  pointer-events: none;
  text-align: center;
  padding: 0 6px;
}
.gate-cell--locked .gate-cell-lock-overlay {
  display: flex;
}
.gate-cell-lock-icon {
  font-size: 26px;
  line-height: 1;
  filter: drop-shadow(0 0 4px rgba(0, 0, 0, 0.85));
}
.gate-cell-lock-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
  text-transform: uppercase;
}

/* Empty-state copy inside the dungeon view when an unlocked rank
   has no bosses defined yet (D/C/B/A/S currently — only E has bosses
   in v2.0.5). Reachable code path activates when boss content lags
   behind gate availability. */
.dungeon-empty {
  text-align: center;
  font-style: italic;
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.5;
  padding: 28px 14px;
  margin: 0;
}

/* ── Dungeon-view (expanded state) ─────────────────────────────
   Replaces the gate when the user taps in. Back link, gold-serif
   dungeon header, italic flavor, then the existing boss cards. */
.dungeon-view {
  margin: 8px 14px 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.dungeon-view.hidden { display: none; }

.dungeon-back {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px 6px 6px;
  background: transparent;
  border: 0;
  border-radius: 8px;
  color: var(--accent);
  font-family: inherit;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.dungeon-back:hover  { background: var(--accent-glow); color: var(--text-primary); }
.dungeon-back:active { transform: scale(0.97); }
.dungeon-back-chev {
  font-size: 1.2rem;
  line-height: 1;
  font-weight: 900;
  margin-right: 2px;
}

.dungeon-header-block {
  text-align: center;
  margin: 4px 0 6px;
}
.dungeon-header {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.5rem;
  letter-spacing: 0.08em;
  color: var(--gold);
  margin: 0 0 6px;
  text-transform: uppercase;
  filter: drop-shadow(0 0 12px rgba(245, 158, 11, 0.30));
}
.dungeon-flavor {
  font-style: italic;
  color: var(--text-secondary);
  font-size: 0.86rem;
  line-height: 1.4;
  margin: 0;
  max-width: 320px;
  margin-left: auto;
  margin-right: auto;
}


/* ═══════════════════════════════════════════════════════════════
   BOSS CARD — CARDS.md spec
   5:7 portrait. Six stacked regions, percentages from spec:
     header ~10% · art ~45% · stats ~7% · flavor ~13% · cond ~8% · progress ~17%
   Outer border: 2px gradient deep-purple → gold (135deg = clockwise
   from top-left, per CARDS.md). Inner bg: var(--bg) so card "floats"
   against the parent screen rather than sitting on a contrasting
   backdrop (CARDS.md "minimal frame" decision).

   Tappable — opens the full-screen detail modal. Card is rendered as
   <button> for native keyboard handling; padding 0 + display flex
   keeps it visually identical to the previous div container.
   ═══════════════════════════════════════════════════════════════ */
.bosses-list--cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.bcard {
  position: relative;
  aspect-ratio: 5 / 7;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  border-radius: 6px;
  /* 2px gradient border via border-image. 135deg ≈ clockwise from
     top-left for a single linear gradient (the spec language is
     vibes-based; this hits the intended look). */
  border: 2px solid transparent;
  border-image: linear-gradient(135deg, #5b21b6 0%, #f59e0b 100%) 1;
  overflow: hidden;
  isolation: isolate; /* keep state-overlay children scoped */
  /* Button reset — card is a <button> for native a11y. */
  padding: 0;
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  -webkit-tap-highlight-color: transparent;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.bcard:hover {
  transform: scale(1.02);
  box-shadow: 0 0 18px rgba(245, 158, 11, 0.32);
}
.bcard:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.55), 0 0 18px rgba(245, 158, 11, 0.32);
}
.bcard:active {
  transform: scale(0.98);
}

/* ── Region a: Header strip (~10%) ───────────────────────────── */
.bcard-header {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  /* Symmetric horizontal padding so the centered name has room for
     the absolute-positioned rank pill on the left without colliding.
     32px ≈ pill width (22) + left inset (6) + breathing room. */
  padding: 6px 32px;
  min-height: 30px;
  background: rgba(255, 255, 255, 0.02);
  border-bottom: 1px solid rgba(245, 158, 11, 0.10);
}
.bcard-rank-pill {
  /* Pill is absolute-anchored top-left so the name can center freely
     in the strip's full width. Reuses .rank-badge color tokens;
     overrides size + position. */
  position: absolute;
  left: 6px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  border-radius: 5px;
  font-size: 10px;
  box-shadow: 0 0 6px rgba(139, 92, 246, 0.25);
}
.bcard-name {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 0.78rem;
  letter-spacing: 0.03em;
  color: var(--gold);
  text-align: center;
  /* Truncate per CARDS.md if name overflows. */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

/* ── Region b: Art window (~45%) ─────────────────────────────── */
.bcard-art {
  flex: 0 0 45%;
  position: relative;
  overflow: hidden;
}
.bcard-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  /* Atmospheric edges fade into card bg per CARDS.md "subject
     framing." Source art generated for 1:1; cell is wider than
     tall so cover crops slightly top/bottom — acceptable. */
}

/* ── Region c: Stat strip (~7%) ──────────────────────────────── */
.bcard-stats {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 4px 6px;
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  border-top: 1px solid rgba(245, 158, 11, 0.10);
  border-bottom: 1px solid rgba(245, 158, 11, 0.10);
  background: rgba(0, 0, 0, 0.20);
}
.bcard-stat-label {
  color: rgba(167, 139, 250, 0.85); /* gray-purple */
  font-weight: 700;
}
.bcard-stat-value {
  color: var(--gold);
  font-weight: 800;
}
.bcard-stat-sep {
  color: rgba(245, 158, 11, 0.30);
  margin: 0 2px;
}

/* ── Region d: Flavor (~13%) ─────────────────────────────────── */
.bcard-flavor {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-style: italic;
  font-size: 0.7rem;
  line-height: 1.35;
  color: #a8a3c4; /* gray-purple per CARDS.md */
  padding: 8px 10px;
  border-bottom: 1px solid rgba(245, 158, 11, 0.10);
}

/* ── Region e: Kill condition (~8%) ──────────────────────────── */
.bcard-cond {
  flex: 0 0 auto;
  text-align: center;
  font-size: 0.66rem;
  font-weight: 600;
  color: var(--text-primary);
  padding: 6px 8px;
  border-left: 2px solid rgba(245, 158, 11, 0.30);
  margin: 0 8px;
}

/* ── Region f: Progress (~17%) ───────────────────────────────── */
.bcard-progress {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 6px 8px 8px;
}
.bcard-dots {
  display: flex;
  gap: 4px;
}
.bcard-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(245, 158, 11, 0.20);
}
.bcard-dot--filled {
  background: var(--gold);
  box-shadow: 0 0 6px rgba(245, 158, 11, 0.55);
  border-color: var(--gold);
}
.bcard-progress-label {
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--text-secondary);
  letter-spacing: 0.04em;
}
.bcard-kills {
  font-size: 0.6rem;
  color: var(--text-tertiary);
  letter-spacing: 0.02em;
  margin-top: 2px;
}

/* ── State variants ──────────────────────────────────────────── */
/* Active: streak > 0. Soft purple-gold pulse on the outer border
   shadow. Subtle — meant to be peripheral signal, not loud. */
@keyframes bcard-active-pulse {
  0%, 100% { box-shadow: 0 0 8px rgba(139, 92, 246, 0.30); }
  50%      { box-shadow: 0 0 14px rgba(245, 158, 11, 0.45); }
}
.bcard--active {
  animation: bcard-active-pulse 2.4s ease-in-out infinite;
}

/* Defeated: kill_count > 0. Permanent gold tint replaces the gradient
   border + corner trophy overlay (rendered via .bcard-corner-trophy
   element when defeated). */
.bcard--defeated {
  border-image: linear-gradient(135deg, #f59e0b 0%, #fbbf24 100%) 1;
}
/* W298 — Rendell feedback: a boss cleared for its current cadence (e.g. a daily
   defeated today) fades its body + desaturates its art so the eye skips it; a
   crisp green check marks it done. Bright cards = still to hunt. Clears when the
   cadence resets. The content regions dim (not the whole button), so the corner
   check + trophy stay full-strength above the faded card. */
.bcard--cleared > .bcard-header,
.bcard--cleared > .bcard-stats,
.bcard--cleared > .bcard-flavor,
.bcard--cleared > .bcard-cond,
.bcard--cleared > .bcard-progress,
.bcard--cleared > .boss-archetype-pill { opacity: 0.42; }
.bcard--cleared > .bcard-art { opacity: 0.6; }
.bcard--cleared .bcard-art img { filter: saturate(0.45) brightness(0.82); }
.bcard--cleared.bcard--active { animation: none; }   /* cleared = quiet, no pulse */
.bcard--cleared .bcard-rank-pill { display: none; }  /* the green check takes the corner */
.bcard-corner-cleared {
  position: absolute;
  top: 4px;
  left: 4px;
  z-index: 6;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(34, 197, 94, 0.20);
  border: 1.2px solid #22c55e;
  color: #22c55e;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  filter: drop-shadow(0 0 5px rgba(34, 197, 94, 0.55));
  pointer-events: none;
}
.bcard-corner-trophy {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 4;
  font-size: 14px;
  filter: drop-shadow(0 0 4px rgba(245, 158, 11, 0.65));
  pointer-events: none;
}

/* Engaged (v2.0.1): user has actively chosen to hunt this boss.
   Solid gold border replaces the gradient default + a subtle constant
   sheen distinguishes from .bcard--active (which signals streak > 0).
   HUNTING label sits in the top-right slot via .bcard-hunting-label. */
.bcard--engaged {
  border-image: linear-gradient(135deg, #f59e0b 0%, #fbbf24 100%) 1;
  box-shadow: 0 0 12px rgba(245, 158, 11, 0.30);
}
.bcard-hunting-label {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 4;
  font-size: 0.55rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: var(--gold);
  background: rgba(245, 158, 11, 0.14);
  border: 1px solid rgba(245, 158, 11, 0.45);
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
  pointer-events: none;
  filter: drop-shadow(0 0 4px rgba(245, 158, 11, 0.40));
}

/* HUNTING/PREVIEW label collision fix (v2.0.1). The header strip
   centers the boss name in its content box. With a 32px symmetric
   padding, longer names like "THE STEEL WOLF" extended into the
   absolute-positioned label's territory in the top-right corner.
   When a label is present (engaged or preview), reserve ~76px on
   the right so the centered name shifts left and ellipsis-truncates
   for very long names ("The Forgotten Hour", etc.) without
   colliding with the corner label. The slight off-center is
   acceptable — it visually reads as "between rank pill and
   corner-label" anchors. */
.bcard--engaged .bcard-header,
.bcard--preview .bcard-header {
  padding-right: 76px;
}

/* Preview state (v2.0.1): rank-locked boss in a walkable dungeon.
   Visually similar to dormant (dim, non-committal) but with a
   muted-gold PREVIEW label in the corner where HUNTING would go. */
.bcard--preview {
  filter: saturate(0.65);
  opacity: 0.82;
}
.bcard--preview:hover {
  filter: none;
  opacity: 1;
}
.bcard-preview-label {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 4;
  font-size: 0.55rem;
  font-weight: 700;
  font-style: italic;
  letter-spacing: 0.16em;
  color: rgba(167, 139, 250, 0.85); /* muted purple */
  background: rgba(139, 92, 246, 0.12);
  border: 1px solid rgba(139, 92, 246, 0.32);
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
  pointer-events: none;
}

/* Dormant (v2.0.1): unlocked boss the user hasn't engaged. Slight
   desaturation + dim signals "not currently being hunted." Card stays
   tappable — opening the detail modal is how the user engages. */
.bcard--dormant {
  filter: saturate(0.7);
  opacity: 0.85;
}
.bcard--dormant:hover {
  /* Restore on hover so the user can read the card cleanly while
     considering whether to engage. */
  filter: none;
  opacity: 1;
}

/* v3 Phase 1z.277C — Boss archetype pill (display-only).
   Modeled on .habit-schedule-chip — compact, uppercase, tracked.
   Color theming via data-archetype attribute: aggressor red,
   sustainer green, caster blue. Sits in the boss card footer
   below .bcard-kills and in the boss detail modal name block.
   Never implies active combat — verified behavior decides victory. */
.boss-archetype-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: fit-content;
  max-width: calc(100% - 16px);
  margin: 6px auto 8px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--archetype-color, rgba(226, 232, 240, 0.86));
  border: 1px solid color-mix(in srgb, var(--archetype-color, #94a3b8) 38%, transparent);
  background: color-mix(in srgb, var(--archetype-color, #94a3b8) 10%, transparent);
}
.boss-archetype-pill[data-archetype="aggressor"] {
  --archetype-color: #ef4444;
}
.boss-archetype-pill[data-archetype="sustainer"] {
  --archetype-color: #22c55e;
}
.boss-archetype-pill[data-archetype="caster"] {
  --archetype-color: #3b82f6;
}
/* Boss detail modal header — pill + ARCHETYPE eyebrow label.
   Sits below the rank label, above the long flavor paragraph. */
.bfs-archetype-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 6px 0 2px;
}
.bfs-archetype-eyebrow {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(148, 163, 184, 0.78);
}
.bfs-archetype-row .boss-archetype-pill {
  margin: 0;
}
.bfs-archetype-disclaimer {
  margin: 4px 0 6px;
  text-align: center;
  font-size: 0.7rem;
  font-style: italic;
  color: rgba(148, 163, 184, 0.72);
  line-height: 1.35;
}



/* ═══════════════════════════════════════════════════════════════
   ACHIEVEMENTS — categorized layout + progress bars
   ═══════════════════════════════════════════════════════════════ */

/* ═══════════════════════════════════════════════════════════════
   STREAK FORGIVENESS — chips, modals, comeback screen
   ═══════════════════════════════════════════════════════════════ */

/* Shield + Honest Day chips on pack progress rows */
.cp-prog-shield {
  flex-shrink: 0;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 3px 7px;
  border-radius: 100px;
  background: rgba(96, 165, 250, 0.18);
  border: 1px solid rgba(96, 165, 250, 0.55);
  color: #93c5fd;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.18s ease, border-color 0.18s ease;
}
.cp-prog-shield:hover  { background: rgba(96, 165, 250, 0.28); border-color: rgba(96, 165, 250, 0.75); }
.cp-prog-shield:active { transform: scale(0.96); }

.cp-prog-honest {
  flex-shrink: 0;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 3px 7px;
  border-radius: 100px;
  background: rgba(167, 139, 250, 0.16);
  border: 1px solid rgba(167, 139, 250, 0.50);
  color: #c4b5fd;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.18s ease, border-color 0.18s ease;
}
.cp-prog-honest:hover  { background: rgba(167, 139, 250, 0.26); border-color: rgba(167, 139, 250, 0.70); }
.cp-prog-honest:active { transform: scale(0.96); }

/* Honest Day modal */
.honest-overlay,
.shield-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.62);
  z-index: 540;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.honest-overlay.hidden,
.shield-overlay.hidden { display: none !important; }

.honest-modal,
.shield-modal {
  position: fixed;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  z-index: 541;
  width: calc(100% - 48px);
  max-width: 360px;
  pointer-events: none;
}
.honest-modal.hidden,
.shield-modal.hidden { display: none !important; }
.hm-card,
.sm-card {
  background: var(--bg-raised);
  border: 1.5px solid rgba(167, 139, 250, 0.40);
  border-radius: 18px;
  padding: 24px 22px 18px;
  text-align: center;
  pointer-events: auto;
  box-shadow: 0 0 36px rgba(0,0,0,0.5), 0 0 24px rgba(167, 139, 250, 0.15);
  animation: hm-pop 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.sm-card { border-color: rgba(96, 165, 250, 0.40); box-shadow: 0 0 36px rgba(0,0,0,0.5), 0 0 24px rgba(96, 165, 250, 0.18); position: relative; }
@keyframes hm-pop { from { opacity: 0; transform: scale(0.9); } to { opacity: 1; transform: scale(1); } }

.hm-icon, .sm-icon  { font-size: 2.4rem; margin-bottom: 8px; line-height: 1; }
.hm-title, .sm-title {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 12px;
  letter-spacing: 0.02em;
}
.hm-body, .sm-body {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.55;
  margin-bottom: 18px;
}
.hm-body b, .sm-body b { color: var(--text-primary); font-weight: 700; }

.hm-actions { display: flex; gap: 8px; }
.hm-btn {
  flex: 1;
  padding: 11px 14px;
  border: none;
  border-radius: 10px;
  font-family: inherit;
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  cursor: pointer;
  -webkit-appearance: none;
  -webkit-tap-highlight-color: transparent;
  transition: transform 0.1s ease, opacity 0.18s ease;
}
.hm-btn:active { transform: scale(0.97); opacity: 0.9; }
.hm-btn-primary {
  background: linear-gradient(135deg, #a78bfa, #8b5cf6);
  color: #0a0a0a;
}
.hm-btn-secondary {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-secondary);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.sm-close {
  position: absolute;
  top: 10px; right: 10px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.10);
  color: var(--text-secondary);
  width: 28px; height: 28px;
  border-radius: 6px;
  font-family: inherit;
  cursor: pointer;
  font-size: 0.85rem;
  -webkit-appearance: none;
}

/* ═══════════════════════════════════════════════════════════════
   COMEBACK — full-screen welcome-back celebration
   ═══════════════════════════════════════════════════════════════ */
.comeback-screen {
  position: fixed;
  inset: 0;
  z-index: 550;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.comeback-screen.hidden { display: none !important; }
.cb-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 38%,
      rgba(34, 197, 94, 0.20) 0%,
      rgba(0, 0, 0, 0.94) 55%,
      #000 100%);
  opacity: 0;
}
.cb-content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 32px;
  opacity: 0;
}
.cb-eyebrow {
  font-size: 0.85rem;
  font-weight: 900;
  letter-spacing: 0.34em;
  color: #4ade80;
  text-transform: uppercase;
  margin-bottom: 26px;
  text-shadow: 0 0 22px rgba(34, 197, 94, 0.55);
}
.cb-line {
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.72);
  font-style: italic;
  line-height: 1.55;
  max-width: 360px;
  margin-bottom: 6px;
}
.cb-line-2 { color: rgba(255, 255, 255, 0.85); margin-bottom: 18px; }
.cb-message {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  line-height: 1.45;
  max-width: 360px;
  margin-bottom: 22px;
  text-shadow: 0 0 18px rgba(34, 197, 94, 0.30);
}
.cb-xp {
  font-size: 1.3rem;
  font-weight: 900;
  color: #4ade80;
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px rgba(34, 197, 94, 0.45);
}
.cb-hint {
  position: absolute;
  bottom: calc(36px + var(--safe-bottom));
  font-size: 0.7rem;
  color: rgba(255, 255, 255, 0.5);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.cb-show .cb-bg      { animation: cb-bg-in 0.55s ease-out forwards; }
.cb-show .cb-content { animation: cb-cnt-in 0.65s 0.20s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
.cb-hide .cb-bg,
.cb-hide .cb-content { animation: cb-out 0.32s ease-in forwards; }
@keyframes cb-bg-in  { from { opacity: 0 } to { opacity: 1 } }
@keyframes cb-cnt-in { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }
@keyframes cb-out    { to { opacity: 0 } }

/* ── Bonus Info popup — Streak Forgiveness section ── */
.bi-section--forgive {
  border-top: 1px solid var(--border);
  padding-top: 14px;
  margin-top: 4px;
}
.bi-section--forgive .bi-section-label {
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--text-tertiary);
  text-transform: uppercase;
  margin-bottom: 12px;
}
.bi-forgive-row {
  display: flex;
  gap: 10px;
  margin-bottom: 12px;
}
.bi-forgive-icon {
  flex-shrink: 0;
  font-size: 1.4rem;
  line-height: 1;
  width: 28px;
  text-align: center;
}
.bi-forgive-text { flex: 1; min-width: 0; }
.bi-forgive-title {
  font-size: 0.92rem;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 2px;
}
.bi-forgive-body {
  font-size: 0.78rem;
  color: var(--text-secondary);
  line-height: 1.5;
}
.bi-forgive-body b { color: var(--text-primary); font-weight: 700; }
.bi-forgive-stat {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}
.bi-stat-pill {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 3px 8px;
  border-radius: 100px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.10);
  color: var(--text-secondary);
}
.bi-stat-pill--quiet {
  color: var(--text-tertiary);
  background: transparent;
  border-color: rgba(255,255,255,0.06);
}

/* History info sheet — inline About this habit section */
.hi-about-section {
  margin-top: 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.hi-about-label {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--text-tertiary);
  text-transform: uppercase;
}
.hi-about-text {
  font-size: 0.86rem;
  color: var(--text-primary);
  line-height: 1.55;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 11px 13px;
  white-space: pre-wrap;
  word-wrap: break-word;
}
.hi-about-text--empty {
  color: var(--text-tertiary);
  font-style: italic;
}

/* ═══════════════════════════════════════════════════════════════
   AWAKENING — origin story typewriter
   ═══════════════════════════════════════════════════════════════ */
.awk-story {
  margin-top: 22px;
  max-width: 420px;
  font-family: ui-serif, Georgia, 'Times New Roman', serif;
  font-size: 0.92rem;
  font-style: italic;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.92);
  white-space: pre-line;
  text-align: left;
  text-wrap: pretty;
  hyphens: none;
  text-shadow: 0 0 18px rgba(0, 0, 0, 0.6);
  min-height: 120px;
  /* Faint cursor block at the end of the visible text while typing */
  position: relative;
}
.awk-story:not(.awk-story--done)::after {
  content: '▋';
  margin-left: 2px;
  color: var(--awk-color, #fff);
  animation: awk-cursor 0.9s steps(2) infinite;
}
@keyframes awk-cursor {
  50% { opacity: 0.3; }
}
.awk-story--done::after { content: ''; }
.awk-hint { font-size: 0.66rem; }

/* ═══════════════════════════════════════════════════════════════
   STATUS — 'Your Origin' link
   ═══════════════════════════════════════════════════════════════ */
.sc-origin-btn {
  /* v3 Phase 1q — compact + restrained. Inline-flex, gold gradient
     fill, subtle gold ring + glow. Important, not dominant. */
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  padding: 6px 12px 6px 10px;
  background: linear-gradient(180deg, rgba(245,184,66,0.14), rgba(245,184,66,0.04));
  border: 1px solid rgba(245,184,66,0.32);
  color: var(--gold);
  border-radius: 14px;
  font-family: inherit;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
  -webkit-appearance: none;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.1s ease, box-shadow 0.18s ease;
  align-self: flex-start;
  box-shadow: 0 0 10px rgba(245,184,66,0.18), inset 0 1px 0 rgba(255,255,255,0.04);
}
.sc-origin-btn:hover  {
  background: linear-gradient(180deg, rgba(245,184,66,0.18), rgba(245,184,66,0.06));
  border-color: rgba(245,184,66,0.55);
  box-shadow: 0 0 12px rgba(245,184,66,0.30), inset 0 1px 0 rgba(255,255,255,0.06);
}
.sc-origin-btn:active { transform: scale(0.96); }

@keyframes origin-fade { from { opacity: 0 } to { opacity: 1 } }

@keyframes origin-up {
  from { transform: translateX(-50%) translateY(100%); }
  to   { transform: translateX(-50%) translateY(0); }
}
/* ═══════════════════════════════════════════════════════════════
   THE BEGINNING — full-screen reveal after onboarding completion
   ═══════════════════════════════════════════════════════════════ */
.beginning-screen {
  position: fixed;
  inset: 0;
  z-index: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  background: #000;
}
.beginning-screen.hidden { display: none !important; }
.bg-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 30%,
      rgba(245, 158, 11, 0.10) 0%,
      rgba(20, 20, 35, 0.95) 50%,
      #000 100%);
  opacity: 0;
}
.bg-content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 36px 28px;
  opacity: 0;
}
.bg-eyebrow {
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.36em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 38px;
  text-shadow: 0 0 22px rgba(245, 158, 11, 0.45);
}
.bg-story {
  max-width: 480px;
  font-family: ui-serif, Georgia, 'Times New Roman', serif;
  font-size: 1.02rem;
  font-style: italic;
  line-height: 1.65;
  color: rgba(255, 250, 240, 0.92);
  white-space: pre-line;     /* honor template \n, allow natural wrap within */
  text-align: left;          /* prose feel — no orphan words from centering */
  text-wrap: pretty;         /* balance line lengths, avoid single-word lines */
  hyphens: none;
  text-shadow: 0 0 16px rgba(0, 0, 0, 0.7);
  min-height: 180px;
  position: relative;
}
.bg-story:not(.bg-story--done)::after {
  content: '▋';
  margin-left: 2px;
  color: var(--gold);
  animation: bg-cursor 0.9s steps(2) infinite;
}
@keyframes bg-cursor { 50% { opacity: 0.3 } }
.bg-story--done::after { content: ''; }
.bg-hint {
  position: absolute;
  bottom: calc(38px + var(--safe-bottom));
  font-size: 0.68rem;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.20em;
  text-transform: uppercase;
}
.bg-show .bg-bg      { animation: bg-bg-in 0.55s ease-out forwards; }
.bg-show .bg-content { animation: bg-cnt-in 0.65s 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
.bg-hide .bg-bg,
.bg-hide .bg-content { animation: bg-out 0.32s ease-in forwards; }
@keyframes bg-bg-in  { from { opacity: 0 } to { opacity: 1 } }
@keyframes bg-cnt-in { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }
@keyframes bg-out    { to { opacity: 0 } }

/* ═══════════════════════════════════════════════════════════════
   BOSS FULL-SCREEN DETAIL MODAL
   Replaces the v1.1.7 bottom-sheet. Opens from any .bcard tap. Lives
   above all tabs at z-index 200. Background matches app bg so the
   modal feels like a takeover-screen, not a floating sheet — no
   dimming scrim per the "full-screen takeover" spec direction.
   ═══════════════════════════════════════════════════════════════ */
.bfs-overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: var(--bg);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding-bottom: calc(40px + var(--safe-bottom));
}
.bfs-overlay.hidden { display: none !important; }

/* Lock background scroll while the modal is open. Applied to <body>
   in openBossFullScreen / removed in closeBossFullScreen. */
body.bfs-locked { overflow: hidden; }

/* ── Header bar — Back link (left), rank pill (right) ────────── */
.bfs-header {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: calc(8px + var(--safe-top)) 14px 8px;
  background: linear-gradient(180deg, var(--bg) 70%, rgba(19, 19, 42, 0));
}
.bfs-back {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px 8px 8px;
  background: transparent;
  border: 0;
  border-radius: 8px;
  color: var(--accent);
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.bfs-back:hover  { background: var(--accent-glow); color: var(--text-primary); }
.bfs-back:active { transform: scale(0.97); }
.bfs-back-chev {
  font-size: 1.4rem;
  line-height: 1;
  font-weight: 900;
  margin-right: 2px;
}
.bfs-rank-pill {
  /* Reuses .rank-badge — same letter pill as the boss-card header. */
  width: 28px;
  height: 28px;
  border-radius: 7px;
  font-size: 12px;
}

/* ── Hero art — square 1:1, full content width with bottom fade ── */
.bfs-hero {
  position: relative;
  width: 100%;
  max-width: 520px;
  aspect-ratio: 1 / 1;
  margin: 4px auto 0;
  overflow: hidden;
  border-radius: 12px;
}
.bfs-hero img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.bfs-hero-fade {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 30%;
  background: linear-gradient(180deg, rgba(19, 19, 42, 0) 0%, var(--bg) 100%);
  pointer-events: none;
}

/* ── Name + rank label ───────────────────────────────────────── */
.bfs-name-block {
  text-align: center;
  margin: 14px auto 4px;
  max-width: 520px;
  padding: 0 14px;
}
.bfs-name {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 2rem;
  letter-spacing: 0.05em;
  color: var(--gold);
  margin: 0;
  filter: drop-shadow(0 0 14px rgba(245, 158, 11, 0.32));
  text-transform: uppercase;
}
.bfs-rank-label {
  margin-top: 4px;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: rgba(167, 139, 250, 0.85);
  text-transform: uppercase;
}

/* ── Long flavor — italic gray-purple, larger than card ──────── */
.bfs-flavor {
  max-width: 520px;
  margin: 14px auto 18px;
  padding: 0 22px;
  font-style: italic;
  font-size: 1rem;
  line-height: 1.55;
  color: #a8a3c4;
  text-align: center;
}

/* ── Stats grid — 2-col label/value cells ────────────────────── */
.bfs-stats {
  max-width: 520px;
  margin: 0 auto 22px;
  padding: 0 14px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.bfs-stat-cell {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(245, 158, 11, 0.14);
  border-radius: 10px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.bfs-stat-label {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: rgba(167, 139, 250, 0.85);
  text-transform: uppercase;
}
.bfs-stat-value {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--gold);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

/* ── Sections — kill condition, progress, drops ──────────────── */
.bfs-section {
  max-width: 520px;
  margin: 0 auto 22px;
  padding: 18px 18px;
  border-top: 1px solid rgba(245, 158, 11, 0.12);
}
.bfs-section-label {
  margin: 0 0 10px;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--gold);
  text-transform: uppercase;
}
.bfs-section-body {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--text-primary);
}

/* v3 W202 — wearable/app requirement note under the kill condition.
   Muted + smaller so it reads as a calm clarification, not an alarm.
   Hidden by default; the boss-detail renderer shows it only for
   sleep/workout bosses. */
.bfs-verify-note {
  margin: 8px 0 0;
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--text-secondary, #9090a8);
  font-style: italic;
}
.bfs-verify-note.hidden { display: none; }

/* Current progress — larger dots than the card. */
.bfs-progress {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.bfs-dots {
  display: flex;
  gap: 8px;
}
.bfs-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(245, 158, 11, 0.20);
}
.bfs-dot--filled {
  background: var(--gold);
  border-color: var(--gold);
  box-shadow: 0 0 8px rgba(245, 158, 11, 0.55);
}
.bfs-progress-label {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}

/* Engagement section in the boss detail modal (v2.0.1). Two states:
   1. .bfs-engage-cta — not engaged: prominent gradient ENGAGE button
      + blurb. Gradient mirrors the card border (purple→gold).
   2. .bfs-engage-state — engaged: HUNTING SINCE date + Stop Hunting
      text-button. Subdued, since the commitment moment has passed. */
.bfs-section--engagement { padding-top: 14px; padding-bottom: 14px; }
.bfs-engage-cta.hidden,
.bfs-engage-state.hidden,
.bfs-engage-preview.hidden { display: none; }

.bfs-engage-cta { display: flex; flex-direction: column; align-items: center; gap: 10px; }

/* v3 Phase 1z.39 — Souls balance readout above the Engage Boss button.
   Compact, dark-fantasy palette aligned with the existing #souls-badge
   header pill. Two states: sufficient (gold) / insufficient (red ember). */
.bfs-souls-balance {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 8px 14px;
  background: linear-gradient(180deg, rgba(245, 184, 66, 0.10), rgba(245, 184, 66, 0.03));
  border: 1px solid rgba(245, 184, 66, 0.30);
  border-radius: 10px;
  width: 100%;
  max-width: 320px;
  box-sizing: border-box;
  transition: background 0.18s ease, border-color 0.18s ease;
}
.bfs-souls-balance__label {
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 1.8px;
  color: rgba(245, 184, 66, 0.85);
  text-transform: uppercase;
}
.bfs-souls-balance__value {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'Cinzel', serif;
  font-size: 1.05rem;
  font-weight: 700;
  color: #f5b842;
  letter-spacing: 0.4px;
  line-height: 1;
}
.bfs-souls-balance__icon {
  width: 16px;
  height: 16px;
  display: block;
  filter: drop-shadow(0 0 4px rgba(245, 184, 66, 0.45));
}
/* Insufficient state — red ember; matches the "Need N souls" toast intent. */
.bfs-souls-balance--insufficient {
  background: linear-gradient(180deg, rgba(239, 68, 68, 0.10), rgba(239, 68, 68, 0.03));
  border-color: rgba(239, 68, 68, 0.40);
}
.bfs-souls-balance--insufficient .bfs-souls-balance__label { color: rgba(248, 113, 113, 0.95); }
.bfs-souls-balance--insufficient .bfs-souls-balance__value { color: #f87171; }
.bfs-souls-balance--insufficient .bfs-souls-balance__icon  { filter: drop-shadow(0 0 4px rgba(239, 68, 68, 0.45)) hue-rotate(-50deg); }

.bfs-engage-btn {
  width: 100%;
  max-width: 320px;
  padding: 14px 18px;
  font-family: 'Cinzel', serif;
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 0.14em;
  color: #ffffff;
  background: linear-gradient(135deg, #5b21b6 0%, #f59e0b 100%);
  border: 0;
  border-radius: 10px;
  cursor: pointer;
  text-transform: uppercase;
  box-shadow: 0 0 16px rgba(245, 158, 11, 0.30);
  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.18s ease, filter 0.18s ease;
}
.bfs-engage-btn:hover  { transform: scale(1.02); box-shadow: 0 0 22px rgba(245, 158, 11, 0.45); }
.bfs-engage-btn:active { transform: scale(0.98); }
/* v3 Phase 1z.39 — visually soften when the user can't afford the engage
   cost. Button remains tappable (the existing balance toast handles the
   precise "Need N souls" message); this just makes the gate visible
   before tap. */
.bfs-engage-btn--insufficient {
  opacity: 0.55;
  filter: grayscale(0.35);
  box-shadow: 0 0 12px rgba(239, 68, 68, 0.25);
}
.bfs-engage-btn--insufficient:hover { box-shadow: 0 0 16px rgba(239, 68, 68, 0.35); }
/* v3 Phase 1z.58 — Carouser engage button outside Friday. Disabled
   state; muted purple ring instead of the broke-state red ring. */
.bfs-engage-btn--locked {
  opacity: 0.55;
  filter: grayscale(0.55);
  cursor: not-allowed;
  box-shadow: 0 0 12px rgba(139, 92, 246, 0.18);
}
.bfs-engage-btn--locked:hover { box-shadow: 0 0 12px rgba(139, 92, 246, 0.18); }
.bfs-engage-blurb {
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--text-secondary);
  text-align: center;
  max-width: 360px;
}

.bfs-engage-state {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
}
.bfs-engage-since {
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--gold);
  text-transform: uppercase;
  filter: drop-shadow(0 0 6px rgba(245, 158, 11, 0.30));
}
.bfs-disengage-btn {
  padding: 6px 12px 6px 8px;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 8px;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}
.bfs-disengage-btn:hover {
  background: rgba(239, 68, 68, 0.10);
  color: #ef4444;
  border-color: rgba(239, 68, 68, 0.45);
}
.bfs-disengage-btn:active { transform: scale(0.97); }

/* Preview-mode (v2.0.1): rank-locked boss in a walkable dungeon.
   Static "Reach X rank to engage" label in place of the ENGAGE
   button. Gray-purple muted treatment signals non-interactive — no
   hover, no cursor:pointer. Same vertical position the button would
   occupy so the modal layout doesn't shift between states. */
.bfs-engage-preview {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.bfs-engage-preview-label {
  width: 100%;
  max-width: 320px;
  padding: 14px 18px;
  text-align: center;
  font-family: 'Cinzel', serif;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  color: rgba(167, 139, 250, 0.85); /* muted purple, parallel to PREVIEW chip */
  background: rgba(139, 92, 246, 0.08);
  border: 1px solid rgba(139, 92, 246, 0.32);
  border-radius: 10px;
  text-transform: uppercase;
  cursor: default;
  user-select: none;
}

/* v3 Phase 1h — RELIC MERCY readout inside the boss-fs modal */
.bfs-mercy {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(15, 15, 36, 0.85);
  border: 1px solid var(--border);
}
.bfs-mercy-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
}
.bfs-mercy-label {
  font-size: 0.66rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--text-secondary);
}
.bfs-mercy-val {
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--gold-bright, var(--gold));
  font-variant-numeric: tabular-nums;
}
.bfs-mercy-note {
  margin: 8px 0 0;
  font-size: 0.72rem;
  font-style: italic;
  color: var(--text-tertiary);
  text-align: center;
}

/* ──────────────────────────────────────────────────────────────
   v3 Phase 1z.7 — Boss detail DEFEATED state surfaces.
   Visible only when the overlay carries .bfs-overlay--defeated.
   Replaces the legacy "HUNT AGAIN — N SOULS" CTA inside the
   engage-cta block by hiding the engage-cta entirely and surfacing
   these dedicated elements instead.
   ────────────────────────────────────────────────────────────── */
.bfs-hunt-complete-pill {
  display: none;
  margin-right: 6px;
  padding: 3px 8px;
  border-radius: 4px;
  background: rgba(245,184,66,0.10);
  border: 0.5px solid rgba(245,184,66,0.45);
  color: var(--gold, #f5b842);
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.10em;
  text-transform: uppercase;
}
.bfs-overlay--defeated .bfs-hunt-complete-pill { display: inline-flex; align-items: center; }

/* When defeated, hide the legacy hunt-pending UI: stats grid stays
   useful but the engage-cta and current-progress blocks are
   superseded by the new defeated surfaces. */
.bfs-overlay--defeated .bfs-engage-cta,
.bfs-overlay--defeated #bfs-engage-cta,
.bfs-overlay--defeated #bfs-engage-state,
.bfs-overlay--defeated #bfs-engage-preview { display: none !important; }

.bfs-defeated-hero {
  margin: 14px 18px 0;
  padding: 14px 16px;
  background:
    radial-gradient(120% 80% at 50% 0%, rgba(245,184,66,0.10) 0%, transparent 60%),
    linear-gradient(180deg, #1a1a3d 0%, #14142c 100%);
  border: 1px solid rgba(245,184,66,0.35);
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: 0 0 18px rgba(245,184,66,0.18), inset 0 1px 0 rgba(255,255,255,0.04);
}
.bfs-overlay--defeated .bfs-defeated-hero { display: flex; }
.bfs-defeated-hero.hidden { display: none !important; }

.bfs-defeated-portrait {
  width: 72px;
  height: 72px;
  border-radius: 10px;
  background: radial-gradient(circle at 35% 30%, rgba(239,68,68,0.4), rgba(60,8,8,0.85));
  border: 1px solid rgba(239,68,68,0.45);
  position: relative;
  overflow: hidden;
  flex: 0 0 auto;
  opacity: 0.78;
}
.bfs-defeated-portrait-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.5) saturate(0.65) grayscale(0.25);
}
.bfs-defeated-portrait-img[data-art="missing"] { display: none; }
.bfs-defeated-portrait-slash {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 2.4px;
  background: linear-gradient(90deg, transparent, var(--gold, #f5b842), transparent);
  box-shadow: 0 0 6px rgba(245,184,66,0.7);
  transform: translate(-50%, -50%) rotate(-22deg);
  pointer-events: none;
}
.bfs-defeated-meta { flex: 1; min-width: 0; }
.bfs-defeated-rank-pill {
  display: inline-flex;
  padding: 3px 8px;
  border-radius: 4px;
  background: rgba(239,68,68,0.08);
  border: 0.5px solid rgba(239,68,68,0.45);
  color: #ef4444;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.bfs-defeated-name {
  margin: 6px 0 2px;
  font-family: 'Cinzel', serif;
  font-weight: 600;
  font-size: 19px;
  color: var(--text-primary, #f5f5fa);
  letter-spacing: 0.07em;
  line-height: 1.15;
}
.bfs-defeated-subline {
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 11.5px;
  color: var(--text-secondary, #9090a8);
  letter-spacing: 0.01em;
  line-height: 1.4;
}

.bfs-last-drop {
  display: none;
  margin: 14px 18px 0;
  padding: 12px 14px;
  width: calc(100% - 36px);
  background: linear-gradient(180deg, #14143a 0%, #0e0e2a 100%);
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 11px;
  align-items: center;
  gap: 12px;
  text-align: left;
  cursor: pointer;
  font: inherit;
  color: inherit;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.03);
}
.bfs-overlay--defeated .bfs-last-drop { display: flex; }
.bfs-last-drop.hidden { display: none !important; }
.bfs-last-drop[data-rarity="common"]     { border-color: rgba(144,144,168,0.55); box-shadow: 0 0 10px rgba(144,144,168,0.20), inset 0 1px 0 rgba(255,255,255,0.03); }
.bfs-last-drop[data-rarity="rare"]       { border-color: rgba(121,180,255,0.55); box-shadow: 0 0 10px rgba(121,180,255,0.30), inset 0 1px 0 rgba(255,255,255,0.03); }
.bfs-last-drop[data-rarity="ultra_rare"] { border-color: rgba(168,85,247,0.65);  box-shadow: 0 0 12px rgba(168,85,247,0.36), inset 0 1px 0 rgba(255,255,255,0.03); }
.bfs-last-drop-art {
  position: relative;
  width: 44px;
  height: 44px;
  border-radius: 8px;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(139,92,246,0.18), rgba(245,158,11,0.10));
  border: 1px solid rgba(255,255,255,0.08);
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
}
.bfs-last-drop-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.bfs-last-drop-img[data-art="missing"] { display: none; }
.bfs-last-drop-slot-icon { font-size: 1.4rem; opacity: 0.55; }
.bfs-last-drop-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.bfs-last-drop-kicker {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9px;
  font-weight: 700;
  color: var(--gold, #f5b842);
  letter-spacing: 0.10em;
  text-transform: uppercase;
}
.bfs-last-drop-name {
  font-family: 'Cinzel', serif;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary, #f5f5fa);
  letter-spacing: 0.03em;
  line-height: 1.2;
}
.bfs-last-drop-meta {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-tertiary, #54546e);
}
.bfs-last-drop[data-rarity="rare"]       .bfs-last-drop-meta { color: #79b4ff; }
.bfs-last-drop[data-rarity="ultra_rare"] .bfs-last-drop-meta { color: #a855f7; }
.bfs-last-drop-chev { color: var(--text-secondary, #9090a8); font-size: 16px; flex: 0 0 auto; }

.bfs-hunt-history {
  margin: 14px 18px 0;
  padding: 12px 14px;
  background: linear-gradient(180deg, #14143a 0%, #0e0e2a 100%);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 11px;
}
.bfs-overlay--defeated .bfs-hunt-history { display: block; }
.bfs-hunt-history.hidden { display: none !important; }
.bfs-hunt-history-label {
  margin: 0 0 8px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--gold, #f5b842);
}
.bfs-hunt-history-list { display: flex; flex-direction: column; }
.bfs-hunt-history-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.bfs-hunt-history-row:last-child { border-bottom: none; }
.bfs-hunt-history-row-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold, #f5b842);
  box-shadow: 0 0 4px rgba(245,184,66,0.45);
  flex: 0 0 auto;
}
.bfs-hunt-history-row-when {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  color: var(--text-tertiary, #54546e);
  letter-spacing: 0.07em;
  text-transform: uppercase;
  min-width: 56px;
}
.bfs-hunt-history-row-name {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary, #f5f5fa);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bfs-hunt-history-row-rarity {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 4px;
  flex: 0 0 auto;
}
.bfs-hunt-history-row-rarity[data-rarity="common"]     { color: #9090a8; background: rgba(144,144,168,0.10); border: 0.5px solid rgba(144,144,168,0.45); }
.bfs-hunt-history-row-rarity[data-rarity="rare"]       { color: #79b4ff; background: rgba(121,180,255,0.10); border: 0.5px solid rgba(121,180,255,0.45); }
.bfs-hunt-history-row-rarity[data-rarity="ultra_rare"] { color: #a855f7; background: rgba(168,85,247,0.10); border: 0.5px solid rgba(168,85,247,0.45); }

.bfs-defeated-cta {
  display: none;
  margin: 14px 22px 22px;
}
.bfs-overlay--defeated .bfs-defeated-cta { display: block; }
.bfs-defeated-cta.hidden { display: none !important; }
.bfs-defeated-hunt-again {
  width: 100%;
  padding: 14px 16px;
  border-radius: 10px;
  border: 1px solid rgba(139,92,246,0.65);
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 0 14px rgba(139,92,246,0.40), inset 0 1px 0 rgba(255,255,255,0.18);
  transition: filter 0.16s ease, transform 0.12s ease;
}
.bfs-defeated-hunt-again:hover { filter: brightness(1.08); }
.bfs-defeated-hunt-again:active { transform: scale(0.985); }
.bfs-defeated-cta-foot {
  margin: 10px 0 0;
  text-align: center;
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 11px;
  color: var(--text-tertiary, #54546e);
  letter-spacing: 0.01em;
}

/* ═══════════════════════════════════════════════════════════════
   DROPS Phase 1 — Items tab Pokédex + reveal modal + card detail
   (v2.0.1). Each card is also an equippable item per EQUIPMENT.md;
   the v1 UI surfaces them as Pokédex collection only. Equip UI
   ships in Phase 3.
   ═══════════════════════════════════════════════════════════════ */

/* ── Items tab Pokédex ───────────────────────────────────────── */
.pokedex {
  padding: 22px 14px 40px;
  max-width: 560px;
  margin: 0 auto;
}
.pokedex-header {
  text-align: center;
  margin-bottom: 8px;
}
/* v3 Phase 1z.7 — Title row carries the optional "1 NEW" gold pulse pill
   beside the title. Hidden when no relics carry NEW state. */
.pokedex-title-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
}
.archive-new-count {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  background: rgba(245, 184, 66, 0.12);
  border: 0.5px solid rgba(245, 184, 66, 0.55);
  color: var(--gold, #f5b842);
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  box-shadow: 0 0 8px rgba(245, 184, 66, 0.32);
  animation: archive-new-count-pulse 2.2s ease-in-out infinite;
}
.archive-new-count.hidden { display: none !important; }
@keyframes archive-new-count-pulse {
  0%, 100% { box-shadow: 0 0 8px rgba(245, 184, 66, 0.32); }
  50%      { box-shadow: 0 0 14px rgba(245, 184, 66, 0.55); }
}
@media (prefers-reduced-motion: reduce) {
  .archive-new-count { animation: none; }
}

/* v3 Phase 1z.7 — Per-card NEW chip (top-right). Supersedes EQUIPPED
   on first acquisition. Sparkle glyph + gold gradient + shimmer
   keyframes. Card outer glow tinted by rarity for extra emphasis. */
.archive-card--new {
  box-shadow: 0 0 14px rgba(245, 184, 66, 0.30), inset 0 1px 0 rgba(255,255,255,0.04);
}
.archive-card--new-rare       { box-shadow: 0 0 14px rgba(121, 180, 255, 0.40), inset 0 1px 0 rgba(255,255,255,0.04); }
.archive-card--new-ultra_rare { box-shadow: 0 0 16px rgba(168,  85, 247, 0.45), inset 0 1px 0 rgba(255,255,255,0.04); }
.archive-card-new-chip {
  position: absolute;
  top: 7px;
  right: 7px;
  /* W455 — match the EQUIPPED badge box EXACTLY (same top/right, height,
     radius, font-size, padding, z-index) so the top-right status pill never
     shifts shape, size, or position between the NEW and EQUIPPED states. */
  z-index: 5;
  height: 16px;
  display: inline-flex;
  align-items: center;
  line-height: 1;
  box-sizing: border-box;
  gap: 3px;
  padding: 0 7px;
  border-radius: 999px;
  background: linear-gradient(180deg, #f5b842, #c08418);
  color: #1a1232;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.46rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  box-shadow: 0 0 10px rgba(245, 184, 66, 0.32), 0 1px 2px rgba(0,0,0,0.4);
  animation: archive-card-new-shimmer 2.4s ease-in-out infinite;
}
.archive-card-new-spark {
  display: inline-block;
  font-size: 9px;
  line-height: 1;
}
@keyframes archive-card-new-shimmer {
  0%, 100% { box-shadow: 0 0 10px rgba(245, 184, 66, 0.32), 0 1px 2px rgba(0,0,0,0.4); }
  50%      { box-shadow: 0 0 18px rgba(245, 184, 66, 0.60), 0 1px 2px rgba(0,0,0,0.4); }
}
@media (prefers-reduced-motion: reduce) {
  .archive-card-new-chip { animation: none; }
}

.pokedex-title {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.6rem;
  letter-spacing: 0.18em;
