}
.pdx-sec-glyph { width: 22px; height: 22px; flex: none; color: var(--ac, var(--gold)); }
.pdx-sec-titlewrap { flex: 1; min-width: 0; }
.pokedex-section-label {
  display: block;
  font-family: 'Cinzel', serif;
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.15em;
