.pdx-sec-minibar { width: 54px; height: 4px; border-radius: 3px; background: rgba(255,255,255,0.07); overflow: hidden; }
.pdx-sec-minibar i { display: block; height: 100%; border-radius: 3px; background: var(--ac, var(--gold)); box-shadow: 0 0 7px var(--acg, transparent); }
.pokedex-section-chevron {
