/* ═══════════════════════════════════════════════════════════════════
   Relic Marketplace — inline trade affordance + buy/sell confirm sheets
   (ports ClaudeDesign "Relic Marketplace" to scoped CSS classes)
   ═══════════════════════════════════════════════════════════════════ */
/* Each grid cell stacks the (unchanged) card button + its trade control. */
.pokedex-cell { display: flex; flex-direction: column; gap: 7px; }
.pokedex-cell > .pokedex-card { flex: 1 1 auto; }

/* ── Card-level trade button (compact for the 3-col grid) ───────────── */
.market-trade {
  width: 100%;
  box-sizing: border-box;
  height: 30px;
  border-radius: 9px;
  padding: 0 9px;
  display: flex; align-items: center; justify-content: space-between;
  font-family: "JetBrains Mono", ui-monospace, "SF Mono", monospace;
  font-size: 10px; font-weight: 700; letter-spacing: 0.08em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform 0.12s ease, box-shadow 0.16s ease, border-color 0.16s ease;
}
.market-trade:active { transform: scale(0.97); }
.market-trade-amt { display: inline-flex; align-items: center; gap: 4px; }
.market-souls { width: 11px; height: 11px; flex: none; display: block; }
.market-souls--big { width: 16px; height: 16px; }

/* BUY — affordable (gold, active) */
.market-trade--buy {
  background: linear-gradient(180deg, rgba(245,184,66,0.16), rgba(245,184,66,0.07));
  border: 1px solid rgba(245,184,66,0.55);
  color: #f5b842;
  box-shadow: 0 0 14px -3px rgba(245,184,66,0.30), inset 0 1px 0 rgba(245,184,66,0.14);
}
/* BUY — insufficient (muted, still tappable → opens the explainer sheet) */
.market-trade--buy.is-disabled {
  background: rgba(255,255,255,0.025);
  border: 1px solid rgba(255,255,255,0.10);
  color: #6b6b86;
  box-shadow: none;
}
/* SELL — secondary control */
.market-trade--sell {
  background: rgba(255,255,255,0.035);
  border: 1px solid rgba(245,184,66,0.30);
  color: #9090a8;
}
.market-trade--sell .market-trade-amt { color: #f5b842; }
.market-trade-need {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 8.5px; font-weight: 600; letter-spacing: 0.03em;
  color: #f5b842; opacity: 0.62; text-align: center; margin-top: 3px;
}

/* ── Overlay + bottom sheet ─────────────────────────────────────────── */
.market-overlay {
  position: fixed; inset: 0; z-index: 12200;
  background: rgba(4,4,13,0.66);
  backdrop-filter: blur(7px); -webkit-backdrop-filter: blur(7px);
  display: flex; align-items: flex-end; justify-content: center;
}
.market-overlay.hidden { display: none; }
.market-sheet {
  width: 100%; max-width: 480px;
  box-sizing: border-box;
  background: linear-gradient(180deg, #0e0e24 0%, #04040d 92%);
  border-top-left-radius: 24px; border-top-right-radius: 24px;
  border-top: 1px solid rgba(245,184,66,0.36);
  box-shadow: 0 -20px 60px -10px rgba(0,0,0,0.7), 0 -1px 0 rgba(245,184,66,0.13);
  padding: 12px 20px calc(24px + env(safe-area-inset-bottom, 0px));
  animation: market-sheet-up 0.30s cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes market-sheet-up { from { transform: translateY(100%); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
.market-sheet-grabber { width: 38px; height: 4px; border-radius: 4px; margin: 0 auto 4px; background: rgba(245,243,251,0.22); }
.market-sheet-hairline { height: 1px; margin: 12px -20px 0; background: linear-gradient(90deg, transparent, rgba(245,184,66,0.33) 30%, rgba(245,184,66,0.33) 70%, transparent); }

/* ── Sheet relic head ───────────────────────────────────────────────── */
.market-sheet-head { display: flex; gap: 14px; align-items: center; padding-top: 18px; }
.market-sheet-art {
  width: 76px; height: 76px; flex: none; border-radius: 14px;
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
  border: 1px solid rgba(121,180,255,0.33);
  background: radial-gradient(120% 120% at 50% 36%, rgba(121,180,255,0.18), #04040d 74%);
  box-shadow: 0 0 22px -6px rgba(121,180,255,0.4);
}
.market-sheet-art--ultra_rare {
  border-color: rgba(245,184,66,0.45);
  background: radial-gradient(120% 120% at 50% 36%, rgba(245,184,66,0.18), #04040d 74%);
  box-shadow: 0 0 22px -6px rgba(245,184,66,0.45);
}
.market-sheet-art-icon { font-size: 30px; line-height: 1; }
.market-sheet-art-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.market-sheet-headtext { min-width: 0; }
.market-sheet-rarity {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 10px; font-weight: 700; letter-spacing: 0.16em; color: #79b4ff;
}
.market-sheet-rarity--ultra_rare { color: #f5b842; text-shadow: 0 0 12px rgba(245,184,66,0.27); }
.market-sheet-name {
  font-family: "Cinzel", Georgia, serif; font-weight: 600; font-size: 19px;
  color: #f5f3fb; margin-top: 4px; line-height: 1.2;
}
.market-sheet-meta { display: flex; align-items: center; gap: 8px; margin-top: 7px; flex-wrap: wrap; }
.market-sheet-slot {
  padding: 3px 9px; border-radius: 7px; background: rgba(8,8,20,0.6);
  border: 1px solid rgba(245,184,66,0.33);
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9px; font-weight: 700;
  letter-spacing: 0.1em; color: #f5b842;
}
.market-sheet-source { font-size: 11.5px; color: #6b6b86; }

/* ── Ledger ─────────────────────────────────────────────────────────── */
.market-ledger {
  margin-top: 18px; padding: 15px 16px; border-radius: 14px;
  background: rgba(255,255,255,0.025); border: 1px solid rgba(255,255,255,0.07);
}
.market-ledger-rule { height: 1px; background: rgba(255,255,255,0.07); margin: 13px 0; }
.market-row { display: flex; align-items: center; justify-content: space-between; }
.market-row + .market-row { margin-top: 9px; }
.market-row-label {
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 11px; font-weight: 600;
  letter-spacing: 0.03em; color: #9090a8;
}
.market-row--big .market-row-label { font-size: 10.5px; letter-spacing: 0.14em; text-transform: uppercase; color: #6b6b86; }
.market-row-val { display: inline-flex; align-items: center; gap: 6px; font-family: "JetBrains Mono", ui-monospace, monospace; font-weight: 600; font-size: 14px; }
.market-row--big .market-row-val { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 26px; }
.market-row-val--gold { color: #f5b842; }
.market-row-val--ink  { color: #f5f3fb; }
.market-row-val--danger { color: #f0607a; }

/* ── Warnings ───────────────────────────────────────────────────────── */
.market-warn {
  margin-top: 13px; padding: 11px 14px; border-radius: 11px;
  font-size: 12.5px; line-height: 1.4;
}
.market-warn--danger {
  background: rgba(240,96,122,0.08); border: 1px solid rgba(240,96,122,0.28);
  color: #f3909f; text-align: center;
}
.market-warn--danger b { color: #f0607a; }
.market-warn--equip {
  background: rgba(245,184,66,0.08); border: 1px solid rgba(245,184,66,0.30);
  color: #f0d9a8; display: flex; align-items: center; gap: 11px; text-align: left;
}
.market-warn--equip b { color: #f5b842; }
.market-warn-glyph {
  width: 26px; height: 26px; flex: none; border-radius: 7px;
  background: rgba(245,184,66,0.14); border: 1px solid rgba(245,184,66,0.4);
  display: flex; align-items: center; justify-content: center;
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 13px; color: #f5b842;
}

/* ── Actions ────────────────────────────────────────────────────────── */
.market-actions { margin-top: 18px; }
.market-cta {
  width: 100%; height: 52px; border-radius: 14px; cursor: pointer;
  font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 15px;
  letter-spacing: 0.1em; text-transform: uppercase;
  background: linear-gradient(180deg, #f5b842 0%, #d99a26 100%);
  border: 1px solid #f5b842; color: #1c1405;
  box-shadow: 0 8px 24px -8px rgba(245,184,66,0.53), inset 0 1px 0 rgba(255,255,255,0.4);
  transition: transform 0.12s ease;
}
.market-cta:active { transform: scale(0.99); }
.market-cta.is-disabled {
  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.09);
  color: #6b6b86; cursor: not-allowed; box-shadow: none;
}
.market-dismiss {
  width: 100%; height: 44px; margin-top: 8px; background: transparent; border: none;
  font-family: -apple-system, "SF Pro Text", system-ui, sans-serif;
  font-size: 13.5px; font-weight: 500; color: #9090a8; cursor: pointer; letter-spacing: 0.01em;
}

@media (prefers-reduced-motion: reduce) {
  .market-sheet { animation: none; }
  .market-trade { transition: none; }
}
@media (max-width: 380px) {
  .market-trade { height: 28px; font-size: 9px; padding: 0 7px; }
  .market-sheet { padding-left: 16px; padding-right: 16px; }
}
/* END Relic Marketplace block */

.pokedex-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 6px 8px;
  border-radius: 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  -webkit-tap-highlight-color: transparent;
}
.pokedex-card:hover  { transform: translateY(-2px); box-shadow: 0 4px 14px rgba(0, 0, 0, 0.45); }
.pokedex-card:active { transform: scale(0.97); }
.pokedex-card-art {
  width: 100%;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.08), rgba(0, 0, 0, 0.40));
  margin-bottom: 6px;
}
.pokedex-card-art {
  position: relative;
  overflow: hidden;
}
.pokedex-card-slot-icon {
  font-size: 2.2rem;
  line-height: 1;
  filter: drop-shadow(0 0 6px rgba(245, 158, 11, 0.30));
}
/* Real card art layered over the emoji fallback. Object-fit cover so
   1:1 source PNGs fill the square art cell cleanly. If 404, JS removes
   the <img>, leaving the emoji + rarity gradient visible. */
.pokedex-card-art-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 8px;
  display: block;
}
/* ── W450 — Armory class + power (ClaudeDesign "Armory · Class & Power") ── */
/* archetype filter + PWR sort, above the rarity sections */
.pdx-controls { display: flex; align-items: center; gap: 7px; padding: 8px 2px 9px;
  position: sticky; top: 0; z-index: 30;
  background: linear-gradient(180deg, rgba(8,8,18,0.96), rgba(8,8,18,0.82) 72%, rgba(8,8,18,0));
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
.pdx-seg { display: flex; gap: 4px; background: rgba(16,16,38,0.7); border: 1px solid rgba(124,108,200,0.16); border-radius: 11px; padding: 3px; }
.pdx-seg-btn { border: none; background: transparent; cursor: pointer; border-radius: 8px; padding: 6px 10px; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9.5px; font-weight: 700; letter-spacing: 1px; color: #8a8aa8; text-transform: uppercase; }
.pdx-seg-btn[data-active="1"] { color: #f3f1fb; background: rgba(255,255,255,0.07); box-shadow: inset 0 0 0 1px rgba(255,255,255,0.08); }
.pdx-seg-btn--melee[data-active="1"]  { color: #ff9a96; background: rgba(239,68,68,0.14); }
.pdx-seg-btn--ranged[data-active="1"] { color: #86efac; background: rgba(34,197,94,0.14); }
.pdx-seg-btn--magic[data-active="1"]  { color: #a9cbff; background: rgba(59,130,246,0.16); }
.pdx-sortbtn { margin-left: auto; display: inline-flex; align-items: center; gap: 5px; background: rgba(16,16,38,0.7); border: 1px solid rgba(124,108,200,0.16); border-radius: 11px; padding: 7px 11px; cursor: pointer; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9.5px; font-weight: 700; letter-spacing: 1px; color: #8a8aa8; text-transform: uppercase; }
.pdx-sortbtn.is-on { color: #f5b842; border-color: rgba(245,184,66,0.4); background: rgba(245,184,66,0.08); }
.pdx-hint { padding: 0 2px 12px; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 8.5px; font-weight: 600; letter-spacing: 0.4px; line-height: 1.5; color: #5a5a76; }
.pdx-hint b { color: #8a8aa8; font-weight: 700; }
/* art footer on each card: class chip + PWR */
.pdx-artfoot { position: absolute; left: 0; right: 0; bottom: 0; z-index: 3; display: flex; align-items: flex-end; justify-content: space-between; padding: 16px 6px 6px; pointer-events: none; background: linear-gradient(180deg, rgba(8,8,16,0), rgba(8,8,16,0.82) 62%); }
.pdx-class { display: inline-flex; align-items: center; gap: 4px; border-radius: 6px; padding: 3px 6px 3px 5px; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 7.5px; font-weight: 800; letter-spacing: 0.6px; text-transform: uppercase; background: rgba(8,8,16,0.55); border: 1px solid color-mix(in srgb, var(--cc, #fff) 55%, transparent); color: var(--cc, #fff); }
.pdx-class svg { width: 10px; height: 10px; display: block; flex: none; }
.pdx-pwr { text-align: right; line-height: 1; }
.pdx-pwr .pn { display: block; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 17px; font-weight: 800; line-height: 0.9; color: #f3f1fb; text-shadow: 0 1px 4px rgba(0,0,0,0.6); }
.pdx-pwr .pl { display: block; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 6.5px; font-weight: 700; letter-spacing: 1.6px; color: rgba(255,255,255,0.6); }
/* power meter + "vs equipped" delta in the card body */
.pdx-pmeter { margin-top: 7px; height: 4px; border-radius: 3px; background: rgba(255,255,255,0.07); overflow: hidden; }
.pdx-pmeter i { display: block; height: 100%; border-radius: 3px; box-shadow: 0 0 6px rgba(255,255,255,0.12); }
.pdx-delta { margin-top: 6px; display: inline-flex; align-items: center; gap: 4px; font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 8px; font-weight: 800; letter-spacing: 0.4px; border-radius: 6px; padding: 3px 6px; text-transform: uppercase; }
.pdx-delta--best { color: #f5b842; background: rgba(245,184,66,0.12); border: 1px solid rgba(245,184,66,0.32); }
.pdx-delta--up, .pdx-delta--gain { color: #46d39a; background: rgba(70,211,154,0.12); border: 1px solid rgba(70,211,154,0.3); }
.pdx-delta--down { color: #8f8fa6; background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08); }
.pokedex-card-name {
  font-size: 0.7rem;
  font-weight: 700;
  text-align: center;
  color: var(--text-primary);
  letter-spacing: 0.02em;
  line-height: 1.2;
  /* W455 — reserve exactly two lines so 1-line and 2-line names occupy the
     SAME height. This keeps the source line, power meter, the EQUIPPED /
     vs-equipped delta chip, and the SELL/BUY bar on a fixed baseline across
     every card in the grid (was drifting whenever a name wrapped). */
  min-height: 2.4em;
  /* Truncate long names cleanly. */
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
/* Rarity tints — applied to the discovered card's art background and
   the section pip colors. Subtle so the card art (when it lands)
   can carry the visual weight. */
.pokedex-card--common     { border-color: rgba(167, 139, 250, 0.30); }
.pokedex-card--common     .pokedex-card-art { background: linear-gradient(135deg, rgba(167, 139, 250, 0.12), rgba(0, 0, 0, 0.40)); }
.pokedex-card--rare       { border-color: rgba(245, 158, 11, 0.45); box-shadow: 0 0 10px rgba(245, 158, 11, 0.18); }
.pokedex-card--rare       .pokedex-card-art { background: linear-gradient(135deg, rgba(245, 158, 11, 0.16), rgba(0, 0, 0, 0.40)); }
.pokedex-card--ultra_rare { border-color: rgba(251, 191, 36, 0.55); box-shadow: 0 0 14px rgba(251, 191, 36, 0.28); }
.pokedex-card--ultra_rare .pokedex-card-art {
  background: linear-gradient(135deg, rgba(232, 121, 249, 0.20), rgba(251, 191, 36, 0.16), rgba(0, 0, 0, 0.40));
}

/* Undiscovered placeholder cards. Still tap-able (toast). */
.pokedex-card--undiscovered {
  background: rgba(255, 255, 255, 0.02);
  border-style: dashed;
  border-color: rgba(255, 255, 255, 0.10);
  box-shadow: none;
}
.pokedex-card--undiscovered:hover { box-shadow: 0 2px 8px rgba(0, 0, 0, 0.40); }
.pokedex-card-art--undiscovered {
  background: rgba(0, 0, 0, 0.35) !important;
}
.pokedex-card-mystery {
  font-size: 2.4rem;
  font-weight: 900;
  color: var(--text-tertiary);
  font-family: 'Cinzel', serif;
}
/* ═══════════════════════════════════════════════════════════════
   v3 Phase 1g — Relic Archive polish (Items tab).
   Adds equipment-slot identity + equipped state + drop source to
   every card, plus a richer "mystery" treatment for undiscovered
   slots. Layered on top of the existing .pokedex-card primitives;
   no markup re-architecture.
   ═══════════════════════════════════════════════════════════════ */

/* Header flavor line beneath the progress bar */
.archive-flavor {
  margin: 4px auto 12px;
  font-style: italic;
  font-size: 0.74rem;
  color: var(--text-tertiary);
  letter-spacing: 0.02em;
}
/* W502 (IA) — Marketplace label: names the souls-spending home on the Items tab. */
.pokedex-market {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 12px;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid rgba(245,184,66,0.22);
  background: linear-gradient(180deg, rgba(245,184,66,0.08), rgba(245,184,66,0.02));
}
.pokedex-market-glyph { flex: none; color: var(--gold, #f5b842); font-size: 0.85rem; }
.pokedex-market-text {
  font-size: 0.72rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--text-secondary, #9ca3af);
}
.pokedex-market-text b {
  color: var(--gold, #f5b842);
  font-weight: 800;
  letter-spacing: 0.02em;
}

/* Armory CTA — secondary status line. .archive-armory-cta-text is
   the wrapper that stacks main + sub vertically so the existing
   icon + chevron still flank a single label slot. */
.archive-armory-cta .archive-armory-cta-text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  flex: 1;
}
.archive-armory-cta-main {
  flex: initial;
}
.archive-armory-cta-sub {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.10em;
  color: var(--text-secondary);
  text-transform: uppercase;
}

/* Slot badge — top-left pill on every card (discovered + mystery) */
.archive-slot-badge {
  position: absolute;
  top: 7px;
  left: 7px;
  z-index: 5;
  /* W455 — fixed-height pill so it mirrors the status badge on the right. */
  height: 16px;
  display: inline-flex;
  align-items: center;
  line-height: 1;
  box-sizing: border-box;
  padding: 0 7px;
  border-radius: 999px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.46rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #f8e7b0;
  background: rgba(10, 10, 24, 0.76);
  border: 1px solid rgba(245, 158, 11, 0.30);
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.35);
  pointer-events: none;
}

/* W466 — duplicate count chip on the relic card name line (Rendell's request:
   see how many you own from the grid without opening each item). Only shown
   when count > 1. */
.pdx-count {
  display: inline-block;
  margin-left: 5px;
  padding: 0 6px;
  border-radius: 999px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 800;
  line-height: 1.5;
  vertical-align: middle;
  color: #f8e7b0;
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.34);
}

/* Equipped badge — top-right pill. Replaces the old crossed-swords
   prefix with a clean gold pill that mirrors the slot-badge shape
   on the opposite corner. */
.pokedex-card-equipped-badge.archive-equipped-badge {
  position: absolute;
  top: 7px;
  right: 7px;
  left: auto;
  bottom: auto;
  z-index: 5;
  /* W455 — same fixed box as the slot badge + NEW chip so the top-right
     status pill sits in one fixed position regardless of EQUIPPED vs NEW. */
  height: 16px;
  display: inline-flex;
  align-items: center;
  line-height: 1;
  box-sizing: border-box;
  padding: 0 7px;
  border-radius: 999px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.46rem;
  font-weight: 900;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: #fff7e6;
  background: rgba(245, 158, 11, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow:
    0 0 12px rgba(245, 158, 11, 0.28),
    0 2px 8px rgba(0, 0, 0, 0.35);
  pointer-events: none;
}

/* Drop source line under each card's name */
.archive-item-source {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.52rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: rgba(242, 242, 247, 0.52);
  text-align: center;
  margin-top: 2px;
  line-height: 1.2;
  text-transform: uppercase;
  /* W455 — keep the drop-source to ONE line (ellipsis the rare long boss
     name) so it can't wrap and shove the power meter + delta chip out of
     alignment with the neighbouring cards. */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Mystery (undiscovered) card — richer than the old "?" placeholder.
   Adds a rarity teaser line + source hint beneath. Subtle dashed
   purple border + center glow. Slot badge stays in top-left so the
   user can still see which body part the relic fills. */
.archive-mystery-card {
  border-style: dashed !important;
  border-color: rgba(139, 92, 246, 0.28) !important;
}
.archive-mystery-card .pokedex-card-art--undiscovered {
  background:
    radial-gradient(circle at center, rgba(139, 92, 246, 0.16), rgba(12, 12, 28, 0.92)) !important;
}
.archive-mystery-mark {
  color: rgba(242, 242, 247, 0.40) !important;
  text-shadow: 0 0 14px rgba(139, 92, 246, 0.22);
}
.archive-mystery-rarity {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.54rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: rgba(248, 231, 176, 0.62);
  text-transform: uppercase;
  text-align: center;
  margin-top: 4px;
}
.archive-mystery-hint {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.50rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: rgba(242, 242, 247, 0.45);
  text-align: center;
  padding: 0 4px 4px;
  margin-top: 2px;
  line-height: 1.25;
}

/* Rarity header polish — ULTRA-RARE RELICS gets a faint glow */
.archive-rarity-header--ultra .pokedex-section-label {
  text-shadow: 0 0 12px rgba(245, 158, 11, 0.20);
}

/* W289 — MEGA RARE header: prismatic gradient text, the apex tier */
.archive-rarity-header--mythic .pokedex-section-label {
  background: linear-gradient(90deg, #5eeaff, #ff5db1, #ffd24a, #5eeaff);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 0 14px rgba(255, 210, 74, 0.30);
}

/* ─── Mystery (undiscovered) info modal ────────────────────── */
.mystery-card-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.82);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  z-index: 9300;
}
.mystery-card-overlay.hidden { display: none; }
.mystery-card-modal {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 9301;
  width: min(90vw, 360px);
  max-height: 88vh;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  background:
    radial-gradient(circle at top, rgba(58, 26, 99, 0.55), rgba(15, 15, 36, 0.98) 70%);
  border: 1px solid rgba(139, 92, 246, 0.45);
  border-radius: 18px;
  padding: 22px 22px 18px;
  text-align: center;
  box-shadow:
    0 24px 60px rgba(0, 0, 0, 0.7),
    0 0 28px rgba(139, 92, 246, 0.25);
  animation: mystery-rise 0.28s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
}
.mystery-card-modal.hidden { display: none; }
@keyframes mystery-rise {
  from { opacity: 0; transform: translate(-50%, -46%) scale(0.96); }
  to   { opacity: 1; transform: translate(-50%, -50%) scale(1);    }
}
.mystery-card-close {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 2;
}
.mystery-card-mark {
  font-family: 'Cinzel', serif;
  font-size: 3.4rem;
  font-weight: 900;
  color: rgba(248, 231, 176, 0.62);
  text-shadow: 0 0 20px rgba(139, 92, 246, 0.40);
  line-height: 1;
  margin-bottom: 8px;
}
.mystery-card-title {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.1rem;
  letter-spacing: 0.14em;
  color: var(--gold-bright, var(--gold));
  margin: 0 0 14px;
  text-transform: uppercase;
}
.mystery-card-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0 auto 14px;
  padding: 12px 12px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid var(--border);
  max-width: 280px;
}
.mystery-card-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
}
.mystery-card-row dt {
  font-size: 0.60rem;
  letter-spacing: 0.10em;
  color: var(--text-secondary);
  text-transform: uppercase;
  margin: 0;
}
.mystery-card-row dd {
  font-size: 0.74rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: 0.04em;
  margin: 0;
}
.mystery-card-howto {
  font-size: 0.78rem;
  color: rgba(242, 242, 247, 0.74);
  line-height: 1.45;
  margin: 0 0 16px;
  padding: 0 4px;
}
.mystery-card-actions {
  display: flex;
  gap: 10px;
}
.mystery-card-btn {
  flex: 1;
  padding: 11px 12px;
  border-radius: 12px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  cursor: pointer;
  border: 1px solid transparent;
  transition: transform 0.12s ease, box-shadow 0.18s ease, background 0.18s ease;
}
.mystery-card-btn:active { transform: scale(0.98); }
.mystery-card-btn--primary {
  color: #fff7e6;
  background:
    linear-gradient(180deg, rgba(139, 92, 246, 0.40), rgba(58, 26, 99, 0.96));
  border-color: rgba(245, 158, 11, 0.50);
  box-shadow:
    0 0 14px rgba(139, 92, 246, 0.30),
    inset 0 0 0 1px rgba(245, 158, 11, 0.12);
}
.mystery-card-btn--primary:hover {
  box-shadow:
    0 0 18px rgba(245, 158, 11, 0.36),
    inset 0 0 0 1px rgba(245, 158, 11, 0.20);
}
.mystery-card-btn--primary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}
.mystery-card-btn--cancel {
  color: #d8d4ea;
  background: rgba(36, 36, 72, 0.92);
  border-color: rgba(139, 92, 246, 0.30);
}
.mystery-card-btn--cancel:hover {
  background: rgba(48, 48, 96, 0.95);
  border-color: rgba(139, 92, 246, 0.50);
}

/* ── Reveal modal — cinematic Solo Leveling system-window ────── */
.reveal-overlay {
  position: fixed;
  inset: 0;
  z-index: 300;
  background: radial-gradient(circle at center, rgba(20, 10, 40, 0.92) 0%, rgba(0, 0, 0, 0.96) 70%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s ease;
  overflow: hidden;
}
.reveal-overlay.hidden { display: none !important; }
.reveal-overlay--showing {
  opacity: 1;
  pointer-events: auto;
}
.reveal-overlay--closing { opacity: 0; }

body.reveal-locked { overflow: hidden; }

/* System-window line — draws across the screen as the modal opens.
   Manhwa-style "system message" framing. */
.reveal-systemline {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(245, 158, 11, 0.85), transparent);
  box-shadow: 0 0 14px rgba(245, 158, 11, 0.65);
  transform: scaleX(0);
  transform-origin: center;
}
.reveal-systemline--top    { top: 40%; }
.reveal-systemline--bottom { bottom: 40%; }
.reveal-overlay--showing .reveal-systemline {
  animation: reveal-line-draw 0.42s 0.05s ease-out forwards;
}
@keyframes reveal-line-draw {
  0%   { transform: scaleX(0); opacity: 0; }
  100% { transform: scaleX(1); opacity: 1; }
}

/* Drifting particles (ultra-rare only). Three pseudo-elements
   drifting upward at staggered intervals — built with box-shadow
   to avoid asset dependencies. */
.reveal-particles {
  position: absolute;
  inset: 0;
  pointer-events: none;
  display: none;
}
.reveal-overlay--ultra_rare .reveal-particles { display: block; }
.reveal-overlay--ultra_rare .reveal-particles::before,
.reveal-overlay--ultra_rare .reveal-particles::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(251, 191, 36, 0.85);
  box-shadow:
    0 0 8px rgba(251, 191, 36, 0.65),
    -120px 220px 0 rgba(232, 121, 249, 0.65),
    140px 320px 0 rgba(251, 191, 36, 0.55),
    -210px 80px 0 rgba(245, 158, 11, 0.55),
    180px -60px 0 rgba(232, 121, 249, 0.55),
    -80px -180px 0 rgba(251, 191, 36, 0.55);
  left: 50%;
  top: 50%;
  animation: reveal-particles-drift 4s ease-in-out infinite;
}
.reveal-overlay--ultra_rare .reveal-particles::after {
  animation-delay: -2s;
  background: rgba(232, 121, 249, 0.75);
}
@keyframes reveal-particles-drift {
  0%, 100% { transform: translate(-50%, -50%); opacity: 0.85; }
  50%      { transform: translate(-50%, calc(-50% - 30px)); opacity: 1; }
}

/* The card itself — 5:7 portrait, materializes after the system
   lines draw in. Border + frame styled per rarity. */
.reveal-card {
  position: relative;
  z-index: 2;
  width: 76%;
  max-width: 280px;
  aspect-ratio: 5 / 7;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  border: 2px solid transparent;
  border-image: linear-gradient(135deg, #5b21b6 0%, #f59e0b 100%) 1;
  border-radius: 6px;
  overflow: hidden;
  padding: 14px 12px 16px;
  text-align: center;
  transform: scale(0);
  opacity: 0;
}
.reveal-overlay--showing .reveal-card {
  animation: reveal-card-materialize 0.6s 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}
@keyframes reveal-card-materialize {
  0%   { transform: scale(0); opacity: 0; }
  60%  { transform: scale(1.04); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}
/* Rare: gold border + soft pulse. Override the gradient. */
.reveal-overlay--rare .reveal-card {
  border-image: linear-gradient(135deg, #f59e0b 0%, #fbbf24 100%) 1;
  box-shadow: 0 0 22px rgba(245, 158, 11, 0.45);
}
.reveal-overlay--showing.reveal-overlay--rare .reveal-card {
  animation: reveal-card-materialize 0.6s 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards,
             reveal-card-rare-pulse 2.4s 1.0s ease-in-out infinite;
}
@keyframes reveal-card-rare-pulse {
  0%, 100% { box-shadow: 0 0 22px rgba(245, 158, 11, 0.40); }
  50%      { box-shadow: 0 0 32px rgba(245, 158, 11, 0.70); }
}
/* Ultra-rare: animated gold-violet shimmer border. */
.reveal-overlay--ultra_rare .reveal-card {
  border-image: linear-gradient(135deg, #e879f9 0%, #f59e0b 50%, #e879f9 100%) 1;
  box-shadow: 0 0 28px rgba(232, 121, 249, 0.50), 0 0 28px rgba(245, 158, 11, 0.45);
}
.reveal-overlay--showing.reveal-overlay--ultra_rare .reveal-card {
  animation: reveal-card-materialize 0.6s 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards,
             reveal-card-ultra-pulse 2.6s 1.0s ease-in-out infinite;
}
@keyframes reveal-card-ultra-pulse {
  0%, 100% { box-shadow: 0 0 28px rgba(232, 121, 249, 0.40), 0 0 28px rgba(245, 158, 11, 0.40); }
  50%      { box-shadow: 0 0 42px rgba(232, 121, 249, 0.75), 0 0 42px rgba(245, 158, 11, 0.65); }
}

.reveal-card-art {
  flex: 0 0 55%;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.20), rgba(245, 158, 11, 0.15), rgba(0, 0, 0, 0.55));
  border-radius: 4px;
  margin-bottom: 12px;
}
.reveal-card-art-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 4px;
  /* Match the slot-icon's staggered fade-in so real art doesn't snap
     in instantly before the rest of the reveal animation finishes. */
  opacity: 0;
  animation: reveal-fade-in 0.5s 0.85s ease-out forwards;
}
.reveal-slot-icon {
  font-size: 4.2rem;
  line-height: 1;
  filter: drop-shadow(0 0 16px rgba(245, 158, 11, 0.60));
  /* Stagger reveal so the icon fades in after the card frame. */
  opacity: 0;
  animation: reveal-fade-in 0.5s 0.85s ease-out forwards;
}
.reveal-card-rarity {
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 4px;
  opacity: 0;
  animation: reveal-fade-in 0.5s 0.95s ease-out forwards;
}
.reveal-overlay--ultra_rare .reveal-card-rarity {
  background: linear-gradient(90deg, #e879f9, #fbbf24, #e879f9);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}
.reveal-card-name {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.05rem;
  letter-spacing: 0.05em;
  color: var(--gold);
  margin: 0 0 4px;
  text-transform: uppercase;
  opacity: 0;
  animation: reveal-fade-in 0.5s 1.05s ease-out forwards;
}
.reveal-card-source {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-secondary);
  letter-spacing: 0.04em;
  margin-bottom: 8px;
  opacity: 0;
  animation: reveal-fade-in 0.5s 1.15s ease-out forwards;
}
.reveal-card-flavor {
  font-style: italic;
  font-size: 0.78rem;
  line-height: 1.4;
  color: #a8a3c4;
  margin: 0;
  padding: 0 6px;
  opacity: 0;
  animation: reveal-fade-in 0.5s 1.25s ease-out forwards;
}
/* Stat-bonus row inside the reveal modal — staggered ~200ms after
   flavor so the bonus reveal feels like the final beat of the
   sequence (flavor → stats → continue hint at 1.6s). */
.reveal-card-stats {
  margin-top: 10px;
  opacity: 0;
  animation: reveal-fade-in 0.5s 1.45s ease-out forwards;
}
@keyframes reveal-fade-in {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Shared stat-badge styling (also used in the carddetail modal).
   Tint per stat applied via .stat-badge--<id> modifier. Subtle
   color-tinted background + matching border + same-color text on the
   value/icon so the badge reads cleanly without going fluorescent. */
.stat-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  align-items: center;
}
.stat-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px 4px 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.10);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1;
}
.stat-badge-icon {
  width: 16px;
  height: 16px;
  object-fit: contain;
  flex-shrink: 0;
}
.stat-badge-value {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.stat-badge-label {
  font-weight: 700;
  letter-spacing: 0.10em;
  opacity: 0.85;
}
/* Per-stat color tints — values pulled from STATS[].color in app.js. */
.stat-badge--str   { background: rgba(239, 68, 68, 0.12);  border-color: rgba(239, 68, 68, 0.40);  color: #fca5a5; }
.stat-badge--vit   { background: rgba(34, 197, 94, 0.12);  border-color: rgba(34, 197, 94, 0.40);  color: #86efac; }
.stat-badge--int   { background: rgba(59, 130, 246, 0.12); border-color: rgba(59, 130, 246, 0.40); color: #93c5fd; }
.stat-badge--focus { background: rgba(234, 179, 8, 0.14);  border-color: rgba(234, 179, 8, 0.42);  color: #fde047; }
.stat-badge--will  { background: rgba(249, 115, 22, 0.14); border-color: rgba(249, 115, 22, 0.42); color: #fdba74; }
.stat-badge--wlt   { background: rgba(245, 158, 11, 0.14); border-color: rgba(245, 158, 11, 0.45); color: #fcd34d; }
.carddetail-stats {
  margin: 4px 0 8px;
}

.reveal-continue-hint {
  position: absolute;
  bottom: calc(40px + var(--safe-bottom));
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--text-secondary);
  text-transform: uppercase;
  opacity: 0;
  animation: reveal-continue-pulse 1.6s 1.6s ease-in-out infinite;
}
@keyframes reveal-continue-pulse {
  0%, 100% { opacity: 0.45; }
  50%      { opacity: 0.85; }
}

/* ── Card detail modal (static, non-cinematic) ──────────────── */
.carddetail-overlay {
  position: fixed;
  inset: 0;
  z-index: 280;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.carddetail-overlay.hidden { display: none !important; }
.carddetail-modal {
  position: relative;
  width: 100%;
  max-width: 360px;
  background: var(--bg-raised);
  border: 2px solid transparent;
  border-image: linear-gradient(135deg, #5b21b6 0%, #f59e0b 100%) 1;
  border-radius: 8px;
  padding: 22px 20px 18px;
  text-align: center;
}
.carddetail-overlay--rare .carddetail-modal {
  border-image: linear-gradient(135deg, #f59e0b 0%, #fbbf24 100%) 1;
  box-shadow: 0 0 18px rgba(245, 158, 11, 0.35);
}
.carddetail-overlay--ultra_rare .carddetail-modal {
  border-image: linear-gradient(135deg, #e879f9 0%, #f59e0b 50%, #e879f9 100%) 1;
  box-shadow: 0 0 22px rgba(232, 121, 249, 0.40), 0 0 22px rgba(245, 158, 11, 0.40);
}
.carddetail-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.55);
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  /* Sits above the card art image (which has position: absolute
     inside .carddetail-art). Without this z-index the close button
     reads as nearly-invisible gray-on-dark-art. */
  z-index: 2;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}
.carddetail-close:hover { background: rgba(0, 0, 0, 0.78); border-color: rgba(255, 255, 255, 0.32); }
.carddetail-art {
  width: 100%;
  /* 1:1 to match the 1254×1254 source art exactly. Was 5:4, which
     cropped the top of the artwork (e.g., hood point on Dream-Woven
     Hood). object-fit: cover still applies but with matching ratios
     no cropping actually happens. */
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.18), rgba(245, 158, 11, 0.12), rgba(0, 0, 0, 0.50));
  border-radius: 6px;
  margin-bottom: 14px;
}
.carddetail-art {
  position: relative;
  overflow: hidden;
}
.carddetail-slot-icon {
  font-size: 4rem;
  line-height: 1;
  filter: drop-shadow(0 0 12px rgba(245, 158, 11, 0.50));
}
.carddetail-card-art-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 6px;
  display: block;
}
.carddetail-rarity {
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 4px;
}
.carddetail-overlay--ultra_rare .carddetail-rarity {
  background: linear-gradient(90deg, #e879f9, #fbbf24, #e879f9);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}
.carddetail-name {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.2rem;
  letter-spacing: 0.05em;
  color: var(--gold);
  margin: 0 0 4px;
  text-transform: uppercase;
}
.carddetail-source {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--text-secondary);
  letter-spacing: 0.04em;
  margin-bottom: 12px;
}
.carddetail-flavor {
  font-style: italic;
  font-size: 0.86rem;
  line-height: 1.5;
  color: #a8a3c4;
  margin: 0 0 12px;
}
.carddetail-acquired {
  font-size: 0.72rem;
  color: var(--text-tertiary);
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.carddetail-stack {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--gold);
}

/* W495 — set membership tag (card-detail modal). One reductive line
   between the flavor text and the stat badges. */
.carddetail-set {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: 6px;
  margin: 6px auto 2px;
}
.carddetail-set.hidden { display: none; }
.carddetail-set-glyph { color: var(--gold); font-size: 0.78rem; }
.carddetail-set-name {
  font-family: 'Cinzel', Georgia, serif;
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--gold);
  letter-spacing: 0.02em;
}
.carddetail-set-note {
  font-size: 0.66rem;
  font-weight: 600;
  color: rgba(196, 181, 253, 0.7);
}

/* ───────────────────────────────────────────────────────────────
   W494 — Relic Upgrade row (card-detail modal). The terminal souls
   sink: spend souls to raise an owned relic's level (+1 to its
   dominant stat per level, max 3). Hidden unless owned + upgradeable;
   sits between the stat badges and the acquired/stack lines.
   ─────────────────────────────────────────────────────────────── */
.carddetail-upgrade {
  margin: 14px auto 2px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid rgba(139, 92, 246, 0.28);
  background: linear-gradient(180deg, rgba(139, 92, 246, 0.10), rgba(20, 16, 34, 0.30));
}
.carddetail-upgrade.hidden { display: none; }
.cdu-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}
.cdu-title {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(196, 181, 253, 0.85);
}
.cdu-level {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.74rem;
  font-weight: 800;
  color: var(--gold);
}
.cdu-pips { display: flex; gap: 6px; margin-bottom: 10px; }
.cdu-pip {
  flex: 1 1 auto;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.06);
}
.cdu-pip--on {
  background: linear-gradient(90deg, #c4b5fd, #f6c453);
  border-color: rgba(246, 196, 83, 0.55);
  box-shadow: 0 0 8px rgba(196, 181, 253, 0.45);
}
.cdu-current {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--gold);
  margin-bottom: 10px;
}
.cdu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  min-height: 42px;
  padding: 0 16px;
  border-radius: 12px;
  border: 1px solid rgba(246, 196, 83, 0.40);
  background: linear-gradient(180deg, rgba(246, 196, 83, 0.18), rgba(139, 92, 246, 0.16));
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-weight: 800;
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-primary);
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  user-select: none;
  -webkit-user-select: none;
  transition: transform 0.14s ease, box-shadow 0.18s ease, opacity 0.18s ease;
}
.cdu-btn:hover { transform: translateY(-1px); box-shadow: 0 6px 18px rgba(139, 92, 246, 0.30); }
.cdu-btn:active { transform: translateY(0); }
.cdu-btn-cost { display: inline-flex; align-items: center; gap: 4px; color: var(--gold); }
.cdu-souls { width: 12px; height: 12px; }
.cdu-btn--short, .cdu-btn--max { opacity: 0.5; cursor: default; }
.cdu-btn--short:hover, .cdu-btn--max:hover { transform: none; box-shadow: none; }
.cdu-gain {
  text-align: center;
  margin-top: 7px;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: rgba(196, 181, 253, 0.8);
}

/* ───────────────────────────────────────────────────────────────
   v3 Phase 1d — Card detail modal action button.
   Final CTA at the bottom of the carddetail modal. Two states
   (EQUIP TO BUILD / UNEQUIP) driven by JS class toggle. Replaces
   the prior unstyled default browser button.

   .carddetail-equip-btn              — shared shell (sizing, type,
                                        layout, transitions)
   .carddetail-equip-btn--primary     — EQUIP TO BUILD (purple→deep
                                        violet gradient, gold rim,
                                        outer purple glow)
   .carddetail-equip-btn--unequip     — UNEQUIP (muted navy gradient,
                                        soft purple border, lower-
                                        intensity glow, NOT a red
                                        danger button)

   Both states get hover lift + active press + :disabled treatment.
   ─────────────────────────────────────────────────────────────── */
.carddetail-equip-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-height: 50px;
  margin: 18px auto 4px;
  padding: 0 18px;
  border-radius: 14px;
  border: 1px solid rgba(139, 92, 246, 0.35);
  background: transparent;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-weight: 800;
  font-size: 0.85rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--text-primary);
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  user-select: none;
  -webkit-user-select: none;
  transition: transform 0.16s ease,
              box-shadow 0.20s ease,
              border-color 0.20s ease,
              background 0.20s ease,
              opacity 0.20s ease;
}
.carddetail-equip-btn.hidden { display: none; }

/* ─── EQUIP TO BUILD — primary CTA ─────────────────────────────
   Deep violet gradient body, gold rim accent, dual-color outer
   glow (purple ambient + gold halo). White-warm text reads as the
   "earned, empowered" action. */
/* Tiny rune glyph before the label on EQUIP (pseudo-element so the
   JS-controlled textContent isn't disturbed). Unequip omits it for
   visual hierarchy. */
.carddetail-equip-btn--primary::before {
  content: '✦';
  font-size: 0.95em;
  color: rgba(245, 158, 11, 0.92);
  filter: drop-shadow(0 0 6px rgba(245, 158, 11, 0.55));
  margin-right: 2px;
  line-height: 1;
}
.carddetail-equip-btn--primary {
  color: #fff7e6;
  background:
    linear-gradient(180deg,
      rgba(139, 92, 246, 0.36) 0%,
      rgba(58, 26, 99, 0.96) 100%);
  border-color: rgba(245, 158, 11, 0.55);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 0 0 1px rgba(245, 158, 11, 0.10),
    0 10px 22px rgba(0, 0, 0, 0.42),
    0 0 18px rgba(139, 92, 246, 0.22);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
}
.carddetail-equip-btn--primary:hover,
.carddetail-equip-btn--primary:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(245, 158, 11, 0.75);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.10),
    inset 0 0 0 1px rgba(245, 158, 11, 0.18),
    0 12px 26px rgba(0, 0, 0, 0.50),
    0 0 22px rgba(245, 158, 11, 0.20),
    0 0 24px rgba(139, 92, 246, 0.28);
  outline: none;
}
.carddetail-equip-btn--primary:active {
  transform: translateY(0);
  opacity: 0.96;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, 0.30),
    inset 0 0 0 1px rgba(245, 158, 11, 0.20),
    0 6px 14px rgba(0, 0, 0, 0.40),
    0 0 14px rgba(139, 92, 246, 0.18);
}

/* ─── UNEQUIP — secondary CTA ──────────────────────────────────
   Muted navy gradient, softer purple border, low-intensity glow.
   Still premium and clearly tappable — but visually says "you've
   already taken the empowering action, this just rolls it back."
   Explicitly NOT a destructive-red treatment. */
.carddetail-equip-btn--unequip {
  color: #e9e6f7;
  background:
    linear-gradient(180deg,
      rgba(36, 36, 72, 0.95) 0%,
      rgba(23, 23, 48, 0.98) 100%);
  border-color: rgba(139, 92, 246, 0.34);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    inset 0 0 0 1px rgba(255, 255, 255, 0.02),
    0 8px 18px rgba(0, 0, 0, 0.32);
}
.carddetail-equip-btn--unequip:hover,
.carddetail-equip-btn--unequip:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(139, 92, 246, 0.55);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    inset 0 0 0 1px rgba(255, 255, 255, 0.03),
    0 10px 22px rgba(0, 0, 0, 0.40),
    0 0 16px rgba(139, 92, 246, 0.18);
  outline: none;
}
.carddetail-equip-btn--unequip:active {
  transform: translateY(0);
  opacity: 0.95;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, 0.36),
    0 4px 10px rgba(0, 0, 0, 0.30);
}

/* ─── Disabled — applies to either variant ─────────────────── */
.carddetail-equip-btn:disabled,
.carddetail-equip-btn[aria-disabled="true"] {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
  filter: grayscale(0.20);
  box-shadow: none;
}

/* Tighter top spacing on very small phones */
@media (max-width: 360px) {
  .carddetail-equip-btn { margin-top: 14px; min-height: 46px; font-size: 0.8rem; }
}

/* ───────────────────────────────────────────────────────────────
   Sign in with Apple gate (v2.1 Phase A)
   Full-viewport mandatory gate. Sits OUTSIDE the tab system and
   renders before app.js mounts. See BACKEND.md §4.
   ─────────────────────────────────────────────────────────────── */
.signin-gate {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(var(--safe-top) + 32px) 24px calc(var(--safe-bottom) + 32px);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.signin-gate.hidden { display: none; }

.signin-gate-inner {
  width: 100%;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.signin-step {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
}
.signin-step.hidden { display: none; }

.signin-brand {
  font-family: 'Cinzel', serif;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.32em;
  color: var(--gold);
  text-align: center;
  margin-bottom: 4px;
}

.signin-title {
  font-family: 'Cinzel', serif;
  font-size: 1.55rem;
  font-weight: 900;
  color: var(--text-primary);
  text-align: center;
  margin: 0;
  letter-spacing: 0.02em;
}

.signin-blurb {
  font-size: 0.92rem;
  line-height: 1.45;
  color: var(--text-secondary);
  text-align: center;
  margin: 0 0 8px;
}

.signin-footnote {
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--text-tertiary);
  text-align: center;
  margin: 14px 0 0;
}

/* Apple HIG-compliant black button. Logo + text. */
.signin-apple-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  height: 50px;
  padding: 0 18px;
  background: #000;
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 12px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: opacity 0.15s ease, transform 0.12s ease;
}
.signin-apple-btn:active { transform: scale(0.985); opacity: 0.88; }
.signin-apple-logo {
  display: inline-block;
  width: 18px;
  height: 18px;
  background-color: #fff;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 384 512'><path d='M318.7 268.7c-.2-36.7 16.4-64.4 50-84.8-18.8-26.9-47.2-41.7-84.7-44.6-35.5-2.8-74.3 20.7-88.5 20.7-15 0-49.4-19.7-76.4-19.7C63.3 141.2 4 184.8 4 273.5q0 39.3 14.4 81.2c12.8 36.7 59 126.7 107.2 125.2 25.2-.6 43-17.9 75.8-17.9 31.8 0 48.3 17.9 76.4 17.9 48.6-.7 90.4-82.5 102.6-119.3-65.2-30.7-61.7-90-61.7-91.9zm-56.6-164.2c27.3-32.4 24.8-61.9 24-72.5-24.1 1.4-52 16.4-67.9 34.9-17.5 19.8-27.8 44.3-25.6 71.9 26.1 2 49.9-11.4 69.5-34.3z'/></svg>") no-repeat center / contain;
          mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 384 512'><path d='M318.7 268.7c-.2-36.7 16.4-64.4 50-84.8-18.8-26.9-47.2-41.7-84.7-44.6-35.5-2.8-74.3 20.7-88.5 20.7-15 0-49.4-19.7-76.4-19.7C63.3 141.2 4 184.8 4 273.5q0 39.3 14.4 81.2c12.8 36.7 59 126.7 107.2 125.2 25.2-.6 43-17.9 75.8-17.9 31.8 0 48.3 17.9 76.4 17.9 48.6-.7 90.4-82.5 102.6-119.3-65.2-30.7-61.7-90-61.7-91.9zm-56.6-164.2c27.3-32.4 24.8-61.9 24-72.5-24.1 1.4-52 16.4-67.9 34.9-17.5 19.8-27.8 44.3-25.6 71.9 26.1 2 49.9-11.4 69.5-34.3z'/></svg>") no-repeat center / contain;
  position: relative;
  top: -1px; /* optical centering */
}
.signin-apple-text { line-height: 1; }

.signin-alias-input {
  width: 100%;
  height: 50px;
  padding: 0 14px;
  background: var(--bg-raised);
  color: var(--text-primary);
  border: 1px solid var(--border);
  border-radius: 10px;
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-align: center;
  outline: none;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.signin-alias-input:focus {
  border-color: var(--border-accent);
  background: var(--bg-card);
}
.signin-alias-hint {
  font-size: 0.72rem;
  color: var(--text-tertiary);
  text-align: center;
  margin: -8px 0 4px;
}

.signin-alias-continue {
  width: 100%;
  height: 48px;
  background: var(--gold);
  color: #1a1a1a;
  border: 0;
  border-radius: 12px;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: filter 0.15s ease, transform 0.12s ease;
  box-shadow: 0 0 18px var(--gold-glow);
}
.signin-alias-continue:active { transform: scale(0.985); filter: brightness(0.92); }

.signin-error {
  font-size: 0.78rem;
  color: #fca5a5;
  text-align: center;
  min-height: 1.2em;
  margin: -2px 0 2px;
}
.signin-error:empty { display: none; }

/* ───────────────────────────────────────────────────────────────
   Sign-in alias-collision suggestion chips (v2.1.0 Phase B)
   Rendered when /v1/auth/verify returns 409 ALIAS_TAKEN with
   3 server-generated alternatives. Each chip is a tappable
   button that pre-fills the alias input on tap.
   ─────────────────────────────────────────────────────────────── */
.signin-suggestions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  justify-content: center;
  min-height: 0;
}
.signin-suggestions:empty { display: none; }
.signin-suggestions-label {
  width: 100%;
  font-size: 0.72rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  text-align: center;
  margin-bottom: 2px;
}
.signin-suggestion-chip {
  display: inline-flex;
  align-items: center;
  height: 30px;
  padding: 0 12px;
  background: rgba(245, 158, 11, 0.08);
  color: var(--gold);
  border: 1px solid rgba(245, 158, 11, 0.40);
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.12s ease, transform 0.12s ease;
}
.signin-suggestion-chip:hover {
  background: rgba(245, 158, 11, 0.16);
}
.signin-suggestion-chip:active {
  transform: scale(0.96);
}

/* ───────────────────────────────────────────────────────────────
   Settings → Account section (v2.1.0 Phase E partial restyle)
   ─────────────────────────────────────────────────────────────── */

/* Identity card — shows hunter's avatar (first letter), alias, and
   member-since date. Replaces the prior "Signed in as / Since" lines
   with a proper visual card. */
.account-identity-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 14px;
  background: rgba(245, 158, 11, 0.06);
  border: 1px solid rgba(245, 158, 11, 0.20);
  border-radius: 12px;
  margin-bottom: 14px;
}
.account-identity-avatar {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  color: #1a1a1a;
  font-family: 'Cinzel', serif;
  font-size: 1.4rem;
  font-weight: 900;
  border-radius: 50%;
  box-shadow: 0 0 14px var(--gold-glow);
  text-transform: uppercase;
  letter-spacing: 0;
}
.account-identity-text {
  flex: 1;
  min-width: 0;
}
.account-identity-alias {
  font-family: 'Cinzel', serif;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--gold);
  letter-spacing: 0.02em;
  margin-bottom: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.account-identity-since {
  font-size: 0.74rem;
  color: var(--text-tertiary);
  letter-spacing: 0.03em;
}

/* ───────────────────────────────────────────────────────────────
   Delete-account confirmation modal (v2.1.0 Phase E partial)
   Type-DELETE-to-confirm pattern. Two-button choice with the
   destructive option deliberately NOT default-highlighted.
   ─────────────────────────────────────────────────────────────── */

.delete-account-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(var(--safe-top) + 24px) 20px calc(var(--safe-bottom) + 24px);
}
.delete-account-overlay.hidden { display: none; }

.delete-account-modal {
  width: 100%;
  max-width: 380px;
  background: var(--bg-raised);
  border: 1px solid rgba(220, 38, 38, 0.30);
  border-radius: 14px;
  padding: 22px 20px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.65), 0 0 28px rgba(220, 38, 38, 0.10);
  animation: da-modal-pop 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes da-modal-pop {
  from { opacity: 0; transform: scale(0.92); }
  to   { opacity: 1; transform: scale(1); }
}

.delete-account-title {
  font-family: 'Cinzel', serif;
  font-size: 1.25rem;
  font-weight: 900;
  color: #fca5a5;
  margin: 0;
  text-align: center;
  letter-spacing: 0.02em;
}

.delete-account-body {
  font-size: 0.88rem;
  line-height: 1.45;
  color: var(--text-secondary);
  margin: 0;
}
.delete-account-body--warning {
  text-align: center;
  color: #fca5a5;
  font-weight: 700;
}

.delete-account-confirm-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 4px;
}
.delete-account-confirm-label {
  font-size: 0.78rem;
  color: var(--text-secondary);
  text-align: center;
}
.delete-account-confirm-label strong {
  color: #fca5a5;
  letter-spacing: 0.08em;
}
.delete-account-confirm-input {
  width: 100%;
  height: 44px;
  padding: 0 14px;
  background: var(--bg-card);
  color: var(--text-primary);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-align: center;
  text-transform: uppercase;
  outline: none;
  transition: border-color 0.15s ease;
}
.delete-account-confirm-input:focus {
  border-color: rgba(220, 38, 38, 0.55);
  background: var(--bg-card-active);
}

.delete-account-error {
  font-size: 0.78rem;
  color: #fca5a5;
  text-align: center;
  min-height: 1.1em;
  margin: -4px 0 0;
}
.delete-account-error:empty { display: none; }

.delete-account-actions {
  display: flex;
  gap: 10px;
  margin-top: 4px;
}
.delete-account-btn {
  flex: 1;
  height: 46px;
  border-radius: 10px;
  font-family: inherit;
  font-size: 0.92rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.15s ease, border-color 0.15s ease, opacity 0.15s ease, transform 0.12s ease;
}
.delete-account-btn:active { transform: scale(0.985); }
.delete-account-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* Cancel: neutral, default-highlighted (focus-ringed) — the safe
   action. Cancel is the path users should take 99% of the time. */
.delete-account-btn--cancel {
  background: var(--bg-card);
  color: var(--text-primary);
  border: 1px solid var(--border-accent);
}
.delete-account-btn--cancel:hover {
  background: var(--bg-card-active);
}

/* Confirm: destructive red. NOT default-highlighted — user must
   tap it explicitly with intent. Disabled until DELETE is typed. */
.delete-account-btn--confirm {
  background: rgba(220, 38, 38, 0.18);
  color: #fecaca;
  border: 1px solid rgba(220, 38, 38, 0.60);
}
.delete-account-btn--confirm:not(:disabled):hover {
  background: rgba(220, 38, 38, 0.28);
  border-color: rgba(220, 38, 38, 0.80);
}

/* Primary purple variant for restore-modal step1 "Choose File" — the
   user is opting into a flow that COULD be destructive but hasn't
   committed yet (file pick happens AFTER). Destructive red is reserved
   for the step2 "Restore now" final commit. */
.delete-account-btn--primary {
  background: rgba(139, 92, 246, 0.18);
  color: #ddd6fe;
  border: 1px solid rgba(139, 92, 246, 0.60);
}
.delete-account-btn--primary:not(:disabled):hover {
  background: rgba(139, 92, 246, 0.28);
  border-color: rgba(139, 92, 246, 0.80);
}

/* v2.1 Phase E — Settings → LEGAL row (Privacy Policy) */
.settings-legal-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 12px 14px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text-primary);
  font-size: 0.92rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.settings-legal-row:hover {
  background: var(--bg-card-active);
  border-color: var(--border-accent);
}
.settings-legal-row:active { transform: scale(0.99); }
.settings-legal-label { letter-spacing: 0.01em; }
.settings-legal-chevron {
  color: var(--text-secondary);
  font-size: 1rem;
  font-weight: 700;
}

/* v2.1 Phase E — Signing-out overlay. Brief loading state shown for
   ~600ms between Sign-out tap and reload. Reuses delete-account
   overlay aesthetic (centered dark panel, dim backdrop). */
.signing-out-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.signing-out-overlay.hidden { display: none; }
.signing-out-modal {
  background: var(--bg-raised);
  border: 1px solid var(--border-accent);
  border-radius: 14px;
  padding: 22px 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  min-width: 180px;
}
.signing-out-spinner {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 3px solid rgba(139, 92, 246, 0.25);
  border-top-color: var(--accent);
  animation: signing-out-spin 0.9s linear infinite;
}
@keyframes signing-out-spin {
  to { transform: rotate(360deg); }
}
.signing-out-label {
  color: var(--text-primary);
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.02em;
}

/* ═══════════════════════════════════════════════════════════════
   v2.1.0 STATUS HEADER REDESIGN — AgenticOS-flavored metric strip
   + today-strip + status pill row. Replaces the v1.x rank-section
   + progress-section. Existing IDs preserved; visual envelope
   restructured. Operator-console density at iPhone-width.
   ═══════════════════════════════════════════════════════════════ */

/* Hides DOM elements that JS render functions still write to but
   the new design no longer surfaces visually. Used on #rank-label
   and the standalone #progress-bar wrapper. */
.hidden-compat {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  pointer-events: none;
}

/* ─── 3-card metric strip ─────────────────────────────────── */
.metric-strip {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 6px;
  margin: 10px 0 12px;
}
.metric-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 9px 10px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
  overflow: hidden;
  min-width: 0; /* prevents grid blowout on narrow iPhone widths */
}
.metric-card--rank {
  border-color: rgba(139, 92, 246, 0.40);
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.12), var(--bg-card) 60%);
}
.metric-card--spark {
  border-color: rgba(245, 158, 11, 0.30);
}
.metric-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}
.metric-card-label {
  font-family: 'JetBrains Mono', ui-monospace, 'SFMono-Regular', monospace;
  font-size: 0.60rem;
  font-weight: 500;
  letter-spacing: 0.10em;
  color: var(--text-secondary);
  text-transform: uppercase;
}
.metric-card-reset {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.55rem;
  letter-spacing: 0.06em;
  color: var(--text-tertiary);
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.metric-card-bar {
  height: 4px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 2px;
  overflow: hidden;
}
/* Inherits width from JS-driven .rank-fill etc.; recolors per card */
.metric-card-bar-fill {
  height: 100%;
  background: var(--gold);
  border-radius: 2px;
  transition: width 0.4s ease;
}
.metric-card--rank .metric-card-bar-fill { background: var(--accent); }
.metric-card-body {
  display: flex;
  align-items: baseline;
  gap: 4px;
  flex-wrap: wrap;
  min-height: 18px;
}
.metric-card-value {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}
.metric-card--rank .metric-card-value {
  /* rank-badge is a span styled separately; restyle in this context */
  background: none !important;
  border: none !important;
  width: auto !important;
  height: auto !important;
  border-radius: 0 !important;
  padding: 0 !important;
  color: var(--accent) !important;
  font-size: 1.2rem;
  display: inline-block;
  box-shadow: none !important;
}
.metric-card-unit {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  color: var(--text-tertiary);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}
.metric-card-sub {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.60rem;
  color: var(--text-secondary);
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* v3 Phase 1z.266B — top BOSSES SLAIN card (replaces XP·30D sparkline).
   Reuses metric-card grid + sizing; only the count tint, the cursor
   pointer, and the right-side chevron are net-new. Crimson value matches
   the 1z.262 combat color family so the top card visually links with
   Hunter/Guild Notification boss kills. */
.metric-card.metric-card--bosses {
  cursor: pointer;
}
.metric-card.metric-card--bosses:active {
  transform: scale(0.985);
}
.metric-card-value--combat {
  color: #f0596b;
  text-shadow: 0 0 10px rgba(240, 89, 107, 0.35);
}
.metric-card-reset--chev {
  color: rgba(240, 89, 107, 0.55);
  font-weight: 700;
  font-size: 0.95rem;
  line-height: 1;
}
.metric-card-unit--cta {
  color: rgba(240, 89, 107, 0.82);
  font-weight: 700;
}
.metric-card-body--bosses {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.metric-card-sub b,
.metric-card--rank .metric-card-sub {
  color: var(--gold-bright, var(--gold));
  font-weight: 700;
}
.metric-card .rank-next {
  /* override v1.x rank-next styling inside the new card */
  background: none;
  padding: 0;
  border: none;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.60rem;
  color: var(--gold);
  font-weight: 700;
  letter-spacing: 0.04em;
}
.metric-card .rank-next.maxed { color: var(--gold-bright, var(--gold)); }
/* ─── Today-strip (habits count + streak + souls) ───────────── */
.today-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  background: rgba(139, 92, 246, 0.06);
  border: 1px solid rgba(139, 92, 246, 0.30);
  border-radius: 10px;
  margin-bottom: 10px;
  /* v3 Phase 1o — the tile is now the canonical access point for pack /
     routine progress (replaces the retired footer strip). Tappable. */
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
}
.today-strip:hover {
  background: rgba(139, 92, 246, 0.10);
  border-color: rgba(139, 92, 246, 0.45);
}
.today-strip:active { transform: scale(0.997); }
.today-strip:focus-visible {
  outline: 2px solid rgba(139, 92, 246, 0.65);
  outline-offset: 2px;
}
/* Tiny chevron sits inline after the HABITS TODAY label — restrained
   affordance, doesn't crowd the existing left-counter / right-pills
   layout. Purple-on-purple so it reads as "more info available." */
.today-strip-chevron {
  font-size: 0.95rem;
  line-height: 1;
  color: rgba(139, 92, 246, 0.7);
  margin-left: 2px;
  transition: transform 0.15s ease, color 0.15s ease;
}
.today-strip:hover .today-strip-chevron {
  color: rgba(139, 92, 246, 0.95);
  transform: translateX(1px);
}
/* v3 Phase 1k revert (1l) — the top header's "X / Y HABITS TODAY"
   tile is the canonical habit-progress summary on every tab. The
   Daily Objectives section header that briefly lived on the Habits
   tab was removed; the .today-strip-left counter is no longer
   hidden. (Body data-active-tab attribute is still set for any
   future tab-specific styling.) */
.today-strip-left {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}
.today-strip-value {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
}
.today-strip-divider {
  color: var(--text-tertiary);
  font-size: 1.2rem;
  line-height: 1;
}
.today-strip-target {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}
.today-strip-label {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  text-transform: uppercase;
  margin-left: 4px;
  white-space: nowrap;
}
.today-strip-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.today-strip-right .perfect-streak-display {
  /* compact the streak flame to pill density */
  margin: 0;
}

/* Souls-badge as compact pill inside the today-strip.
   .souls-badge--pill modifier on the existing button repurposes
   its appearance without breaking the click handler that opens
   the souls info modal. */
.souls-badge--pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px 3px 6px;
  background: rgba(245, 158, 11, 0.08);
  border: 1px solid rgba(245, 158, 11, 0.55);
  border-radius: 12px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  cursor: pointer;
}
.souls-badge--pill .souls-icon {
  width: 14px;
  height: 14px;
}
.souls-badge--pill .souls-balance {
  font-size: 0.74rem;
  font-weight: 700;
  color: var(--gold-bright, var(--gold));
  letter-spacing: 0.02em;
}
.souls-badge--pill .souls-label {
  font-size: 0.56rem;
  letter-spacing: 0.08em;
  color: var(--gold);
  text-transform: uppercase;
  font-weight: 600;
}

/* ─── Status pill row (active packs + class affinity) ──────── */
.status-pill-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  margin-bottom: 10px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.status-pill-row::-webkit-scrollbar { display: none; }
.status-pill-row.hidden { display: none; }
.status-pill-row-label {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.60rem;
  letter-spacing: 0.10em;
  color: var(--text-secondary);
  text-transform: uppercase;
  flex-shrink: 0;
  padding-right: 6px;
  border-right: 1px solid var(--border);
}
.status-pill-row-list {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: nowrap;
}
.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  border-radius: 12px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  letter-spacing: 0.04em;
  color: var(--text-primary);
  white-space: nowrap;
  text-transform: uppercase;
  font-weight: 600;
}
/* v3 Phase 1z.279 — .status-pill--duel header pill (v3 Phase 1x.5)
   removed along with the Duels subsystem. */

/* Status pill list — smooth opacity transition for the rotating ticker */
.status-pill-row-list {
  transition: opacity 350ms ease;
}
/* ─── XP·30D card tap affordance ──────────────────────────── */
.metric-card--spark {
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.metric-card--spark:hover {
  border-color: rgba(245, 158, 11, 0.55);
  background: var(--bg-card-active);
}
.metric-card--spark:active { transform: scale(0.99); }

/* ─── XP·30D detail bottom-sheet ──────────────────────────── */
#xp-detail-close {
  position: absolute;
  top: 14px;
  right: 14px;
}
/* Tier-1 "alive" treatment for the cumulative-XP chart.
   - Line gets a soft gold glow via drop-shadow filter
   - Endpoint dot pulses (radius + opacity oscillation)
   - Radar-ping ring expands outward from the endpoint on infinite loop
   - Line draws in from left to right when the sheet opens — handled
     by JS setting stroke-dasharray + transitioning stroke-dashoffset
     in openXpDetail() / populateXpDetail() */
#xp-detail-line {
  filter: drop-shadow(0 0 6px rgba(251, 191, 36, 0.55));
}
#xp-detail-dot {
  transform-box: fill-box;
  transform-origin: center;
  animation: xp-dot-pulse 1.4s ease-in-out infinite;
}
#xp-detail-dot-ping {
  transform-box: fill-box;
  transform-origin: center;
  animation: xp-dot-ping 1.8s ease-out infinite;
}
@keyframes xp-dot-pulse {
  0%, 100% { transform: scale(1);   opacity: 1;   }
  50%      { transform: scale(1.4); opacity: 0.75; }
}
@keyframes xp-dot-ping {
  0%   { transform: scale(1);   opacity: 0.55; }
  100% { transform: scale(4.5); opacity: 0;    }
}

/* ─── Tier-2: aurora light sweep ─────────────────────────────
   Second path overlaid on the main line. Uses a short stroke-
   dash "head" + huge gap so only ~30 user-units of the path are
   visible at any moment. Animation drives stroke-dashoffset from
   "head off-left-edge" to "head past right-edge" so the bright
   sliver travels start → end of the line on a 5s loop.

   JS sets --sweep-len on the element to the path's total length
   so the animation distance scales correctly with the chart's
   actual data range. The head length stays a fixed 30 units
   (~7.5% of the 400-unit viewBox width). */
#xp-detail-sweep {
  stroke-dasharray: 30 9999;
  filter: drop-shadow(0 0 4px #fef3c7) drop-shadow(0 0 8px rgba(251, 191, 36, 0.6));
  animation: xp-line-sweep 5s linear infinite;
  animation-delay: 0.9s; /* wait for the draw-in to finish */
}
@keyframes xp-line-sweep {
  0%   { stroke-dashoffset: calc(var(--sweep-len, 400px) + 30px); opacity: 0; }
  10%  { opacity: 0.95; }
  90%  { opacity: 0.95; }
  100% { stroke-dashoffset: -30px; opacity: 0; }
}

/* ─── Tier-2: floating particles ─────────────────────────────
   Four small circles inside the #xp-detail-particles group that's
   translated by JS to sit at the endpoint dot. Each particle drifts
   up + outward with a different vector + staggered delay so the
   emission feels organic. The 2.4s loop is long enough to read each
   particle's full arc; staggered delays keep one particle visible
   at any moment. */
.xp-particle {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: xp-particle-drift 2.4s ease-out infinite;
  filter: drop-shadow(0 0 2px rgba(251, 191, 36, 0.7));
}
.xp-particle--1 { animation-delay: 0.0s; --dx: -7;  --dy: -22; }
.xp-particle--2 { animation-delay: 0.7s; --dx:  6;  --dy: -28; }
.xp-particle--3 { animation-delay: 1.3s; --dx: -3;  --dy: -32; }
.xp-particle--4 { animation-delay: 1.9s; --dx:  9;  --dy: -19; }
@keyframes xp-particle-drift {
  0%   { transform: translate(0, 0);                                  opacity: 0;   }
  15%  { opacity: 0.85; }
  60%  { opacity: 0.55; }
  100% { transform: translate(calc(var(--dx) * 1px), calc(var(--dy) * 1px)); opacity: 0; }
}
/* ─── Narrow-viewport accommodations (iPhone width < 400px) ── */
@media (max-width: 400px) {
  .metric-card { padding: 8px 8px 9px; gap: 5px; }
  .metric-card-label { font-size: 0.55rem; letter-spacing: 0.08em; }
  .metric-card-reset { font-size: 0.52rem; }
  .metric-card-value { font-size: 0.95rem; }
  .metric-card--rank .metric-card-value { font-size: 1.05rem; }
  .metric-card-unit { font-size: 0.56rem; }
  .metric-card-sub { font-size: 0.56rem; }
  .today-strip-value, .today-strip-target { font-size: 1.25rem; }
  .today-strip-label { font-size: 0.58rem; }
}

/* ═══════════════════════════════════════════════════════════════
   v2.1 EQUIPMENT PANEL MODAL — preview of v3 PvP armory.
   Two entry points (avatar tap on Status tab, "VIEW YOUR ARMORY"
   button on Items tab). Full-screen overlay → centered panel art
   → 9 invisible tap targets layered over the slot regions.
   ═══════════════════════════════════════════════════════════════ */

.equipment-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 9000;
  animation: equipment-overlay-fade 0.25s ease-out forwards;
}
.equipment-overlay.hidden { display: none; }
@keyframes equipment-overlay-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.equipment-modal {
  position: fixed;
  inset: 0;
  z-index: 9001;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: max(24px, env(safe-area-inset-top)) 16px max(20px, env(safe-area-inset-bottom));
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  animation: equipment-modal-rise 0.35s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
}
.equipment-modal.hidden { display: none; }
@keyframes equipment-modal-rise {
  from { opacity: 0; transform: translateY(20px) scale(0.96); }
  to   { opacity: 1; transform: translateY(0)    scale(1);    }
}

.equipment-close {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  right: 14px;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid var(--border-accent);
  border-radius: 50%;
  color: var(--text-primary);
  font-size: 1rem;
  cursor: pointer;
  z-index: 2;
}
.equipment-close:hover { background: rgba(0, 0, 0, 0.7); }

.equipment-modal-header {
  text-align: center;
  margin-bottom: 14px;
  padding: 0 20px;
}
.equipment-modal-title {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.8rem;
  color: var(--gold-bright, var(--gold));
  letter-spacing: 0.06em;
  margin: 0 0 4px;
  filter: drop-shadow(0 0 12px rgba(251, 191, 36, 0.45));
}
.equipment-modal-sub {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  text-transform: uppercase;
  margin: 0;
}

/* ═══════════════════════════════════════════════════════════════
   v3 Phase 1d HUNTER BUILD — MOBA-style 6-slot armory.
   Replaces the legacy 9-slot body equipment panel. Embraces the
   square art at assets/items/*.png as item tiles, no transparent-
   icon pipeline required. Slots are rank-gated (E:2 / D:3 / C:4 /
   B:5 / A:6 / S+:6) and visualized as a 3-column grid of carved
   sockets. Empty slots show a + prompt; locked slots show a 🔒
   and the required rank to unlock.
   ═══════════════════════════════════════════════════════════════ */

.hunter-build-section {
  width: 100%;
  max-width: 440px;
  margin: 0 auto 18px;
  padding: 0 4px;
}
.hunter-build-section-label {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--text-secondary);
  text-transform: uppercase;
  margin: 0 0 10px;
  text-align: center;
}

.hunter-build-grid {
  /* v3 Phase 1f — 4×2 grid for the 8-slot typed loadout
     (HELM / AMULET / CAPE / WEAPON on row 1, PLATE / GLOVES /
     BOOTS / RING on row 2). Slightly tighter gap so 4 tiles fit
     comfortably across an iPhone Pro Max viewport.
     Narrow phones (≤380px) fall back to 2×4 so each tile keeps
     enough room for the slot-identity banner. */
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}
@media (max-width: 380px) {
  .hunter-build-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }
}
.hunter-build-slot {
  aspect-ratio: 1 / 1;
  border-radius: 14px;
  background:
    radial-gradient(circle at center,
      rgba(139, 92, 246, 0.18) 0%,
      rgba(12, 12, 28, 0.95) 80%);
  border: 1px solid rgba(139, 92, 246, 0.35);
  box-shadow:
    inset 0 0 14px rgba(0, 0, 0, 0.65),
    0 0 18px rgba(139, 92, 246, 0.10);
  overflow: hidden;
  position: relative;
  padding: 0;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.18s ease, border-color 0.18s ease;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}
.hunter-build-slot:hover {
  transform: translateY(-1px);
  box-shadow:
    inset 0 0 14px rgba(0, 0, 0, 0.65),
    0 0 22px rgba(139, 92, 246, 0.30);
}
.hunter-build-slot:active { transform: scale(0.98); }

/* Empty + locked tiles stack their centered content vertically
   under the 24px slot banner. Equipped tiles ignore this (their
   only flex child is the absolutely-positioned art image). */
.hunter-build-slot--empty,
.hunter-build-slot--locked {
  flex-direction: column;
  padding-top: 24px;
}
.hunter-build-slot--empty .hunter-build-slot-plus {
  font-family: 'Cinzel', serif;
  font-size: 2.4rem;
  font-weight: 900;
  color: rgba(139, 92, 246, 0.65);
  line-height: 1;
  filter: drop-shadow(0 0 8px rgba(139, 92, 246, 0.35));
}
.hunter-build-slot--empty .hunter-build-slot-empty-label {
  text-align: center;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.55rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: rgba(255, 255, 255, 0.55);
  margin-top: 6px;
  text-transform: uppercase;
}

.hunter-build-slot--locked {
  opacity: 0.55;
  filter: grayscale(0.4);
  cursor: not-allowed;
  border-color: rgba(255, 255, 255, 0.10);
  background: rgba(8, 8, 18, 0.85);
}
.hunter-build-slot--locked:hover {
  transform: none;
  box-shadow: inset 0 0 14px rgba(0, 0, 0, 0.65);
}
.hunter-build-slot-lock {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 6px;
  text-align: center;
}
.hunter-build-slot-lock-icon {
  font-size: 1.4rem;
  filter: drop-shadow(0 0 4px rgba(0, 0, 0, 0.6));
}
.hunter-build-slot-lock-label {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.5rem;
  letter-spacing: 0.10em;
  color: rgba(255, 255, 255, 0.55);
  line-height: 1.3;
  text-transform: uppercase;
}

.hunter-build-slot--equipped { border-color: rgba(245, 158, 11, 0.55); }
.hunter-build-slot--equipped:hover {
  box-shadow:
    inset 0 0 14px rgba(0, 0, 0, 0.55),
    0 0 22px rgba(245, 158, 11, 0.28);
}
.hunter-build-item-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.95) contrast(1.06);
  user-select: none;
  -webkit-user-select: none;
}
.hunter-build-item-fallback {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.4rem;
  color: rgba(255, 255, 255, 0.55);
}
/* ─── v3 Phase 1e — typed slot identity ─────────────────────────
   Every Hunter Build tile (equipped / empty / locked) gets a
   gold-rimmed pill in the top-left identifying the slot type:
   HELM / WEAPON / PLATE / GLOVES / BOOTS / RING. This anchors the
   equipment fantasy without reintroducing the body-socket art. */
/* Full-width TOP BANNER carrying the slot identity (HELM /
   WEAPON / PLATE / GLOVES / BOOTS / RING). Renders on every tile
   regardless of state. Replaces the prior top-left pill, which
   was too easy to lose on bright card art. The banner sits at
   z-index 8 — above the item-name bottom band (z-index 3) and
   the art (default) — so the slot identity is always visible. */
.hunter-build-slot-label {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 8;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #f8e7b0;
  background: linear-gradient(180deg,
    rgba(8, 8, 18, 0.94) 0%,
    rgba(8, 8, 18, 0.72) 100%);
  border-bottom: 1px solid rgba(245, 158, 11, 0.28);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.90);
  pointer-events: none;
}
.hunter-build-slot--equipped .hunter-build-slot-label {
  border-bottom-color: rgba(245, 158, 11, 0.55);
}
.hunter-build-slot--locked .hunter-build-slot-label {
  color: rgba(248, 231, 176, 0.65);
  border-bottom-color: rgba(255, 255, 255, 0.10);
}

/* Empty-slot "Tap to equip" helper line under the EMPTY label */
.hunter-build-slot-empty-hint {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.46rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.36);
  margin-top: 2px;
}

/* Item name band — sits below the slot label on equipped tiles.
   Replaces the prior centered .hunter-build-slot-name treatment
   (still kept for safety in case any stale render references it). */
.hunter-build-item-name {
  position: absolute;
  bottom: 0;
  left: 0; right: 0;
  z-index: 3;
  padding: 18px 6px 6px;
  background: linear-gradient(180deg,
    transparent 0%,
    rgba(0, 0, 0, 0.78) 100%);
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.55rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: #ffffff;
  text-transform: uppercase;
  text-align: center;
  line-height: 1.15;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9);
  pointer-events: none;
}
/* Rarity outlines — applied via build-rarity--{c,r,u} class */
.build-rarity--c { border-color: rgba(156, 163, 175, 0.55); }
.build-rarity--r { border-color: rgba(96, 165, 250, 0.70);
  box-shadow: inset 0 0 14px rgba(0, 0, 0, 0.55), 0 0 18px rgba(96, 165, 250, 0.22); }
.build-rarity--u { border-color: rgba(245, 158, 11, 0.85);
  box-shadow: inset 0 0 14px rgba(0, 0, 0, 0.55), 0 0 22px rgba(245, 158, 11, 0.35); }

/* ─── Build summary block ───────────────────────────────────── */
.hunter-build-summary {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px 14px 12px;
  border-radius: 14px;
  background: rgba(15, 15, 36, 0.85);
  border: 1px solid var(--border);
}
.hbs-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.74rem;
}
.hbs-label {
  color: var(--text-secondary);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.62rem;
}
.hbs-val {
  color: var(--text-primary);
  font-weight: 700;
  letter-spacing: 0.04em;
}
.hbs-val--power {
  color: var(--gold-bright, var(--gold));
  font-family: 'Cinzel', serif;
  font-size: 1.2rem;
  filter: drop-shadow(0 0 8px rgba(251, 191, 36, 0.45));
}

/* ─── v3 Phase 1z.213 — Equipment Bonuses · Sigil Grid ──────
   Compact 2-column stat-card grid inspired by the Claude
   Design "Sigil Grid" direction. Each cell carries:
     • a stat-tinted glyph chip (inline SVG sigil),
     • a Cinzel value in the stat color,
     • a small mono label.
   A final gold TOTAL cell sums the displayed bonuses. Outer
   container uses a gradient rim (gold→violet) over a near-
   black ground with a soft violet top-aura, so the whole
   panel reads like a magical artifact. The per-cell color
   is supplied at render time via a --stat-color custom
   property so this stylesheet stays single-rule. */
.hunter-build-bonuses {
  /* Outer gradient rim. The padding=1 + nested radial bg
     gives a 1px gold/violet hairline frame without an
     extra wrapper element. */
  padding: 1px;
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(245,184,66,0.35), rgba(167,139,250,0.30));
  box-shadow: 0 8px 24px rgba(0,0,0,0.40);
}
.hunter-build-bonuses .hbb-grid,
.hunter-build-bonuses > .hbb-empty {
  border-radius: 13px;
  padding: 10px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(167,139,250,0.10), transparent 60%),
    #10102a;
}
.hunter-build-bonuses .hbb-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.hbb-cell {
  --stat-color: #a78bfa;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 11px;
  border-radius: 10px;
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--stat-color) 12%, transparent),
    transparent);
  border: 1px solid color-mix(in srgb, var(--stat-color) 33%, transparent);
}
/* Fallback for browsers without color-mix() — older WebViews.
   Solid low-alpha tint approximates the gradient + border. */
@supports not (color: color-mix(in srgb, red, blue)) {
  .hbb-cell {
    background: rgba(167, 139, 250, 0.08);
    border-color: rgba(167, 139, 250, 0.25);
  }
  .hbb-cell--stat[style*="--stat-color:#ef4444"] { background: rgba(239, 68, 68, 0.08); border-color: rgba(239, 68, 68, 0.25); }
  .hbb-cell--stat[style*="--stat-color:#22c55e"] { background: rgba( 34,197, 94, 0.08); border-color: rgba( 34,197, 94, 0.25); }
  .hbb-cell--stat[style*="--stat-color:#3b82f6"] { background: rgba( 59,130,246, 0.08); border-color: rgba( 59,130,246, 0.25); }
  .hbb-cell--stat[style*="--stat-color:#9ca3af"] { background: rgba(156,163,175, 0.08); border-color: rgba(156,163,175, 0.30); }
  .hbb-cell--stat[style*="--stat-color:#f97316"] { background: rgba(249,115, 22, 0.08); border-color: rgba(249,115, 22, 0.25); }
  .hbb-cell--stat[style*="--stat-color:#a78bfa"] { background: rgba(167,139,250, 0.08); border-color: rgba(167,139,250, 0.25); }
}
.hbb-chip {
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--stat-color) 18%, transparent);
  border: 1px solid color-mix(in srgb, var(--stat-color) 66%, transparent);
  box-shadow: 0 0 8px color-mix(in srgb, var(--stat-color) 44%, transparent);
}
@supports not (color: color-mix(in srgb, red, blue)) {
  .hbb-chip {
    background: rgba(167, 139, 250, 0.12);
    border-color: rgba(167, 139, 250, 0.50);
    box-shadow: 0 0 8px rgba(167, 139, 250, 0.30);
  }
}
.hbb-cell-body { display: flex; flex-direction: column; }
.hbb-cell-val {
  font-family: 'Cinzel', serif;
  font-size: 1.10rem;
  font-weight: 700;
  line-height: 1;
  color: var(--stat-color);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 8px color-mix(in srgb, var(--stat-color) 55%, transparent);
}
@supports not (color: color-mix(in srgb, red, blue)) {
  .hbb-cell-val { text-shadow: 0 0 8px rgba(167, 139, 250, 0.40); }
}
.hbb-cell-label {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.50rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  color: var(--text-tertiary, #6b7280);
  margin-top: 3px;
}
/* v3 Phase 1z.215 — Gold TOTAL cell now uses the SAME chip +
   body layout as the stat cells (.hbb-cell base supplies the
   horizontal flex + 10px gap), so its value/label line up
   horizontally with neighbouring cards instead of floating
   center-only. The --stat-color custom property paints the
   chip glow + border + value glow in gold via the existing
   base rules. */
.hbb-cell--total {
  --stat-color: #f5b842;
  background: linear-gradient(180deg, rgba(245,184,66,0.16), transparent);
  border: 1px solid rgba(245,184,66,0.55);
}
.hbb-cell--total .hbb-cell-val {
  color: var(--gold-bright, var(--gold, #f5b842));
  text-shadow: 0 0 10px rgba(245,184,66,0.55);
}
.hbb-cell--total .hbb-cell-label {
  color: rgba(245,184,66,0.65);
}
.hbb-empty {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-style: italic;
  font-size: 0.90rem;
  color: var(--text-tertiary, #6b7280);
  text-align: center;
  padding: 14px 8px;
}

/* ───────────────────────────────────────────────────────────────
   W495 — Set-bonus progress block. Sits beneath the bonus sigil
   grid in the EQUIPMENT BONUSES panel; one card per set the player
   has any piece of equipped, each tier lit when active.
   ─────────────────────────────────────────────────────────────── */
.hbb-sets { margin-top: 14px; }
.hbb-sets-title {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(196, 181, 253, 0.75);
  margin-bottom: 8px;
}
.hbb-set {
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(139, 92, 246, 0.22);
  background: linear-gradient(180deg, rgba(139, 92, 246, 0.08), rgba(20, 16, 34, 0.22));
}
.hbb-set + .hbb-set { margin-top: 8px; }
.hbb-set-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}
.hbb-set-name {
  font-family: 'Cinzel', Georgia, serif;
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.02em;
}
.hbb-set-count {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--gold);
}
.hbb-set-tiers { display: flex; flex-direction: column; gap: 5px; }
.hbb-set-tier {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  opacity: 0.5;
}
.hbb-set-tier--on {
  opacity: 1;
  background: linear-gradient(90deg, rgba(246, 196, 83, 0.14), rgba(139, 92, 246, 0.10));
  box-shadow: inset 0 0 0 1px rgba(246, 196, 83, 0.30);
}
.hbb-set-tier-pc {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: rgba(196, 181, 253, 0.85);
  min-width: 26px;
}
.hbb-set-tier--on .hbb-set-tier-pc { color: var(--gold); }
.hbb-set-tier-bonus {
  flex: 1 1 auto;
  font-size: 0.66rem;
  font-weight: 700;
  color: var(--text-secondary, #9ca3af);
}
.hbb-set-tier--on .hbb-set-tier-bonus { color: var(--text-primary); }
.hbb-set-tier-on {
  color: var(--gold);
  font-size: 0.7rem;
  text-shadow: 0 0 8px rgba(246, 196, 83, 0.6);
}
/* Narrow-screen fallback — keeps the 2-col rhythm down to
   tiny widths so the cards never crush the value. Single
   column only at very small viewports. */
@media (max-width: 340px) {
  .hunter-build-bonuses .hbb-grid {
    grid-template-columns: 1fr;
    gap: 6px;
  }
}
.hbs-val--muted {
  color: var(--text-secondary);
  font-weight: 500;
  font-style: italic;
}
.hbs-row--power { padding-bottom: 6px; border-bottom: 1px solid var(--border); }
.hbs-row--hint  { padding-top: 4px; }

.equipment-modal-footer {
  text-align: center;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  letter-spacing: 0.08em;
  color: var(--text-tertiary);
  text-transform: uppercase;
  margin: 8px auto 0;
  max-width: 440px;
}

/* ═══════════════════════════════════════════════════════════════
   BUILD PICKER / "Select Relic" — compact MOBA-style item picker
   (v3 Phase 1d follow-up).
   The item DETAIL modal carries the large art; this picker is a
   fast inventory scan. Mobile-first compact grid, square art
   tiles capped at ~150px wide, name + 2 stat chips below the art.
   Rarity-tinted borders + corner badges for rarity/equipped state.
   ═══════════════════════════════════════════════════════════════ */
.build-picker-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  z-index: 9100;
}
.build-picker-overlay.hidden { display: none; }

.build-picker-sheet {
  position: fixed;
  inset: 0;
  z-index: 9101;
  display: flex;
  flex-direction: column;
  padding: max(20px, env(safe-area-inset-top)) 14px max(16px, env(safe-area-inset-bottom));
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  background: var(--bg);
  animation: build-picker-rise 0.28s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
}
.build-picker-sheet.hidden { display: none; }
@keyframes build-picker-rise {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0);    }
}

/* Header + slot-context line are width-capped so they line up with
   the centered grid below on wider viewports. */
.build-picker-header,
.build-picker-sub {
  width: 100%;
  max-width: 720px;
  margin-left: auto;
  margin-right: auto;
}
.build-picker-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 4px;
}
.build-picker-title {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.25rem;
  color: var(--gold-bright, var(--gold));
  letter-spacing: 0.06em;
  margin: 0;
}
.build-picker-sub {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.66rem;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  text-transform: uppercase;
  margin: 0 0 14px;
}

/* ─── Compact responsive grid ──────────────────────────────────
   auto-fill + minmax keeps tiles compact and forces the desktop
   layout to wrap rather than balloon a 3-col layout to full-width.
   max-width caps the grid so the picker reads like an inventory
   shelf, not a gallery. */
.build-picker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(112px, 1fr));
  gap: 10px;
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
}
@media (min-width: 760px) {
  .build-picker-grid {
    grid-template-columns: repeat(auto-fill, minmax(128px, 150px));
    justify-content: center;
    max-width: 920px;
  }
}

/* ─── Picker tile ─────────────────────────────────────────────
   Tile is a column: art-wrap (square) → name → 2 stat chips. The
   tile itself is NOT aspect-ratio constrained, so the chip row
   can expand naturally. Art-wrap is the only square element. */
.build-picker-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  text-align: left;
  border-radius: 12px;
  background:
    linear-gradient(180deg,
      rgba(30, 30, 63, 0.96) 0%,
      rgba(15, 15, 36, 0.98) 100%);
  border: 1px solid rgba(139, 92, 246, 0.32);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.03),
    0 6px 14px rgba(0, 0, 0, 0.28);
  overflow: hidden;
  padding: 0;
  cursor: pointer;
  color: var(--text-primary);
  appearance: none;
  -webkit-appearance: none;
  transition: transform 0.14s ease,
              box-shadow 0.20s ease,
              border-color 0.20s ease;
}
.build-picker-tile:hover,
.build-picker-tile:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(245, 158, 11, 0.52);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.04),
    0 10px 22px rgba(0, 0, 0, 0.40),
    0 0 18px rgba(139, 92, 246, 0.22);
  outline: none;
}
.build-picker-tile:active {
  transform: translateY(0);
  opacity: 0.96;
}

.build-picker-tile-art-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: rgba(0, 0, 0, 0.35);
  overflow: hidden;
}
.build-picker-tile-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.92) contrast(1.06);
  display: block;
}
.build-picker-tile-fallback {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: rgba(255, 255, 255, 0.55);
}

/* Rarity chip in top-left of art (Common / Rare / Ultra) */
.build-picker-tile-rarity {
  position: absolute;
  top: 6px;
  left: 6px;
  z-index: 3;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.48rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(139, 92, 246, 0.86);
  color: #fff;
  text-transform: uppercase;
  box-shadow: 0 0 8px rgba(0, 0, 0, 0.40);
}
.build-picker-tile-rarity--c { background: rgba(110, 110, 130, 0.88); }
.build-picker-tile-rarity--r { background: rgba(96, 165, 250, 0.92); }
.build-picker-tile-rarity--u {
  background: rgba(245, 158, 11, 0.95);
  color: #1a0f00;
  box-shadow: 0 0 10px rgba(245, 158, 11, 0.35);
}

/* Status badge in top-right of art (EQUIPPED / SLOT N) */
.build-picker-tile-badge {
  position: absolute;
  top: 6px;
  right: 6px;
  z-index: 3;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.48rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(245, 158, 11, 0.92);
  color: #1a0f00;
  text-transform: uppercase;
  box-shadow: 0 0 10px rgba(245, 158, 11, 0.32);
}
.build-picker-tile-badge--elsewhere {
  background: rgba(139, 92, 246, 0.92);
  color: #fff;
  box-shadow: 0 0 10px rgba(139, 92, 246, 0.28);
}

.build-picker-tile-name {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  line-height: 1.15;
  color: var(--text-primary);
  padding: 7px 8px 2px;
  min-height: 32px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.build-picker-tile-meta {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  padding: 0 8px 8px;
}
.build-picker-tile-chip {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 2px 5px;
  border-radius: 4px;
  background: rgba(245, 158, 11, 0.14);
  color: var(--gold-bright, var(--gold));
  border: 1px solid rgba(245, 158, 11, 0.22);
  white-space: nowrap;
}
.build-picker-tile-chip--more {
  background: rgba(139, 92, 246, 0.16);
  color: #c4b5fd;
  border-color: rgba(139, 92, 246, 0.30);
}

/* ─── Rarity-tinted tile borders/glow ─────────────────────────
   Compose with .build-rarity--{c,r,u} from the Hunter Build grid
   (same class names already wired in JS). Overrides scoped via
   .build-picker-tile so the Armory-grid versions stay intact. */
.build-picker-tile.build-rarity--c { border-color: rgba(139, 92, 246, 0.28); }
.build-picker-tile.build-rarity--r {
  border-color: rgba(96, 165, 250, 0.55);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.04),
    0 6px 14px rgba(0, 0, 0, 0.28),
    0 0 14px rgba(96, 165, 250, 0.18);
}
.build-picker-tile.build-rarity--u {
  border-color: rgba(245, 158, 11, 0.68);
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, 0.10),
    0 6px 14px rgba(0, 0, 0, 0.30),
    0 0 18px rgba(245, 158, 11, 0.18),
    0 0 18px rgba(139, 92, 246, 0.14);
}

/* Equipped-in-this-slot / elsewhere state outlines */
.build-picker-tile--equipped-here   { border-color: rgba(245, 158, 11, 0.85) !important; }
.build-picker-tile--equipped-elsewhere {
  opacity: 0.82;
  border-color: rgba(139, 92, 246, 0.60) !important;
}

.build-picker-empty {
  margin-top: 24px;
  text-align: center;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.7rem;
  color: var(--text-secondary);
  letter-spacing: 0.04em;
  padding: 0 24px;
}
.build-picker-empty.hidden { display: none; }

/* ─── BUILD DETAIL SHEET ────────────────────────────────────── */
.build-detail-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 9200;
}
.build-detail-overlay.hidden { display: none; }

.build-detail-sheet {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 9201;
  width: min(92vw, 380px);
  max-height: 88vh;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  background: var(--bg-raised);
  border: 1px solid var(--border-accent);
  border-radius: 18px;
  padding: 18px 18px 16px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.65);
  animation: build-detail-rise 0.28s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
}
.build-detail-sheet.hidden { display: none; }
@keyframes build-detail-rise {
  from { opacity: 0; transform: translate(-50%, -46%) scale(0.96); }
  to   { opacity: 1; transform: translate(-50%, -50%) scale(1);    }
}
.build-detail-close {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
}
.build-detail-art {
  width: 70%;
  aspect-ratio: 1 / 1;
  margin: 4px auto 12px;
  border-radius: 14px;
  overflow: hidden;
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid var(--border);
}
.build-detail-art-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.build-detail-rarity {
  text-align: center;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--gold-bright, var(--gold));
  text-transform: uppercase;
  margin-bottom: 4px;
}
.build-detail-name {
  text-align: center;
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 1.25rem;
  color: var(--text-primary);
  margin: 0 0 6px;
}
.build-detail-flavor {
  text-align: center;
  font-family: serif;
  font-style: italic;
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.72);
  margin: 0 0 12px;
  line-height: 1.4;
}
.build-detail-stats {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin-bottom: 14px;
  min-height: 4px;
}
.build-detail-actions {
  display: flex;
  gap: 10px;
  margin-top: 6px;
}
.build-detail-btn {
  flex: 1;
  padding: 11px 12px;
  border-radius: 10px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  cursor: pointer;
  border: 1px solid transparent;
  transition: transform 0.1s ease, box-shadow 0.18s ease, background 0.18s ease;
}
.build-detail-btn:active { transform: scale(0.98); }
/* Sole action button on the build-detail sheet (REPLACE was
   dropped — user can re-equip by tapping the now-empty slot). */
.build-detail-btn--unequip {
  color: #e9e6f7;
  background:
    linear-gradient(180deg,
      rgba(36, 36, 72, 0.95) 0%,
      rgba(23, 23, 48, 0.98) 100%);
  border-color: rgba(139, 92, 246, 0.34);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    inset 0 0 0 1px rgba(255, 255, 255, 0.02),
    0 8px 18px rgba(0, 0, 0, 0.32);
  min-height: 50px;
  border-radius: 14px;
}
.build-detail-btn--unequip:hover,
.build-detail-btn--unequip:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(139, 92, 246, 0.55);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    inset 0 0 0 1px rgba(255, 255, 255, 0.03),
    0 10px 22px rgba(0, 0, 0, 0.40),
    0 0 16px rgba(139, 92, 246, 0.18);
  outline: none;
}
.build-detail-btn--unequip:active {
  transform: translateY(0);
  opacity: 0.95;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, 0.36),
    0 4px 10px rgba(0, 0, 0, 0.30);
}


/* ─── Items tab: VIEW YOUR ARMORY button ─────────────────────
   Sits between the pokedex count + the rarity sections.
   Full-width, purple-tinted, sword icon + label + chevron. */
.armory-open-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  margin: 12px 0 8px;
  padding: 12px 14px;
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.16), rgba(91, 33, 182, 0.10) 60%);
  border: 1px solid rgba(139, 92, 246, 0.50);
  border-radius: 12px;
  color: var(--text-primary);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}
.armory-open-btn:hover {
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.26), rgba(91, 33, 182, 0.16) 60%);
  border-color: rgba(139, 92, 246, 0.75);
}
.armory-open-btn:active { transform: scale(0.99); }
.armory-open-icon {
  font-size: 1.2rem;
  color: var(--gold-bright, var(--gold));
  filter: drop-shadow(0 0 6px rgba(251, 191, 36, 0.45));
}
.armory-open-label {
  flex: 1;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.10em;
  color: var(--gold-bright, var(--gold));
  text-transform: uppercase;
}
.armory-open-chev {
  color: var(--text-secondary);
  font-size: 1.2rem;
}

/* Avatar tap affordance — soft cursor + faint hover hint so users
   know the silhouette is interactive. */
.sc-avatar {
  transition: filter 0.18s ease, transform 0.1s ease;
}
.sc-avatar:hover {
  filter: drop-shadow(0 0 14px rgba(139, 92, 246, 0.50));
}
.sc-avatar:active { transform: scale(0.97); }

/* ═══════════════════════════════════════════════════════════════
   v3 Phase 1i — Premium SPLASH / LOADING screen.
   Visible by default on every launch (no JS required to appear).
   Fades out via .is-hidden modifier once the underlying flow is
   ready. Min visible time ≈ 900ms governed by app.js.
   ═══════════════════════════════════════════════════════════════ */
/* v3 Phase 1i.1 — Restrained Tonal-style splash. Pure near-black
   background with one very subtle ambient orb. Small gold emblem
   stacks above the wordmark. No decorative ring. */
.awakened-splash {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: max(24px, env(safe-area-inset-top)) 24px max(24px, env(safe-area-inset-bottom));
  background: #050510;
  opacity: 1;
  visibility: visible;
  transition: opacity 0.65s ease, visibility 0.65s ease;
  -webkit-user-select: none;
  user-select: none;
}
.awakened-splash.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
/* Single very-subtle aura behind the centered stack — sets mood
   without competing with the wordmark. */
.splash-bg-orb {
  position: absolute;
  top: 50%; left: 50%;
  width: 540px;
  height: 540px;
  margin: -270px 0 0 -270px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(139, 92, 246, 0.10) 0%, transparent 60%);
  filter: blur(14px);
  pointer-events: none;
  animation: splash-orb-breathe 6s ease-in-out infinite;
}
.splash-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  /* Cap the stack width so the wordmark never gets within ~18px
     of the viewport edge on iPhone SE (320px). On desktop, this
     keeps the cluster from over-spreading. */
  width: 100%;
  max-width: 460px;
  padding: 0 18px;
}
.splash-emblem {
  /* ~9% smaller than before — quiet brand mark, not a focal point. */
  width: 38px;
  height: 38px;
  margin-bottom: 22px;
  color: #f59e0b;
  filter: drop-shadow(0 0 10px rgba(245, 158, 11, 0.30));
  animation: splash-emblem-glow 4s ease-in-out infinite;
}
.splash-emblem svg {
  width: 100%;
  height: 100%;
  display: block;
}
.splash-logo {
  font-family: 'Cinzel', Georgia, serif;
  font-weight: 900;
  /* Tighter clamp: SE never feels cramped; desktop never bloats. */
  font-size: clamp(36px, 9vw, 56px);
  letter-spacing: 0.14em;
  color: #f59e0b;
  text-shadow: 0 0 18px rgba(245, 158, 11, 0.22);
  /* Subtle, never bouncy. Pure opacity/glow breath. */
  animation: splash-logo-breathe 4s ease-in-out infinite;
}
.splash-subtitle {
  margin-top: 18px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.66rem;
  letter-spacing: 0.36em;
  text-transform: uppercase;
  color: rgba(242, 242, 247, 0.58);
}
.splash-loading-text {
  position: absolute;
  bottom: max(36px, env(safe-area-inset-bottom));
  left: 0; right: 0;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.58rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(242, 242, 247, 0.38);
  opacity: 0;
  transition: opacity 0.32s ease;
}
.awakened-splash.is-loading-long .splash-loading-text { opacity: 1; }
@keyframes splash-logo-breathe {
  0%, 100% { text-shadow: 0 0 14px rgba(245, 158, 11, 0.18); }
  50%      { text-shadow: 0 0 28px rgba(245, 158, 11, 0.42); }
}
@keyframes splash-emblem-glow {
  0%, 100% { filter: drop-shadow(0 0 6px rgba(245, 158, 11, 0.22)); }
  50%      { filter: drop-shadow(0 0 16px rgba(245, 158, 11, 0.48)); }
}
@keyframes splash-orb-breathe {
  0%, 100% { transform: scale(0.96); opacity: 0.85; }
  50%      { transform: scale(1.04); opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .splash-logo, .splash-emblem, .splash-bg-orb { animation: none; }
}

/* ═══════════════════════════════════════════════════════════════
   v3 Phase 1i — Educational ONBOARDING overlay.
   5 cards before the existing welcome flow. Gated by
   hb_onboarding_seen_v2 (one-shot, never re-shown).
   ═══════════════════════════════════════════════════════════════ */
.intro-onboarding {
  position: fixed;
  inset: 0;
  z-index: 9998;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: max(24px, env(safe-area-inset-top)) 22px max(24px, env(safe-area-inset-bottom));
  background:
    radial-gradient(circle at top, rgba(139, 92, 246, 0.20), transparent 38%),
    linear-gradient(180deg, #080816 0%, #13132a 100%);
  -webkit-user-select: none;
  user-select: none;
  animation: intro-ob-fade-in 0.36s ease both;
}
.intro-onboarding.hidden { display: none; }
@keyframes intro-ob-fade-in { from { opacity: 0; } to { opacity: 1; } }
.intro-onboarding-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 80% 12%, rgba(245, 158, 11, 0.10), transparent 40%),
    radial-gradient(circle at 18% 88%, rgba(139, 92, 246, 0.16), transparent 42%);
}
.intro-onboarding-skip {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  right: 18px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(242, 242, 247, 0.55);
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 999px;
  padding: 6px 14px;
  cursor: pointer;
  z-index: 3;
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}
.intro-onboarding-skip:hover {
  color: var(--text-primary);
  border-color: rgba(139, 92, 246, 0.35);
  background: rgba(139, 92, 246, 0.10);
}
.intro-onboarding-card {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 440px;
  margin: 0 auto 18px;
  padding: 28px 22px 26px;
  border-radius: 24px;
  background: linear-gradient(180deg, rgba(30, 30, 63, 0.94), rgba(18, 18, 42, 0.98));
  border: 1px solid rgba(139, 92, 246, 0.34);
  box-shadow:
    0 20px 60px rgba(0, 0, 0, 0.45),
    inset 0 0 0 1px rgba(255, 255, 255, 0.04);
  text-align: center;
  animation: intro-ob-card-rise 0.42s cubic-bezier(0.34, 1.3, 0.64, 1) both;
}
@keyframes intro-ob-card-rise {
  from { opacity: 0; transform: translateY(12px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0)    scale(1);    }
}
.intro-onboarding-card.is-leaving { animation: intro-ob-card-leave 0.22s ease both; }
@keyframes intro-ob-card-leave {
  from { opacity: 1; transform: translateY(0); }
  to   { opacity: 0; transform: translateY(-8px); }
}
.intro-onboarding-kicker {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 900;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #8b5cf6;
}
.intro-onboarding-title {
  margin: 10px 0 0;
  font-family: 'Cinzel', Georgia, serif;
  font-weight: 900;
  font-size: 1.6rem;
  line-height: 1.10;
  color: #f59e0b;
  text-shadow: 0 0 16px rgba(245, 158, 11, 0.20);
}
.intro-onboarding-body {
  margin: 14px auto 0;
  max-width: 380px;
  font-size: 0.92rem;
  line-height: 1.55;
  color: rgba(242, 242, 247, 0.78);
}
.intro-onboarding-visual {
  width: 84px;
  height: 84px;
  margin: 0 auto 4px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Cinzel', Georgia, serif;
  font-weight: 900;
  font-size: 2.2rem;
  color: #f8e7b0;
  background: radial-gradient(circle, rgba(139, 92, 246, 0.34), rgba(10, 10, 24, 0.92) 70%);
  border: 1px solid rgba(245, 158, 11, 0.40);
  box-shadow: 0 0 28px rgba(139, 92, 246, 0.30);
}
.intro-onboarding-extra {
  margin-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: stretch;
}
.intro-ob-stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 4px auto 0;
  max-width: 360px;
}
.intro-ob-stat-pill {
  padding: 8px 6px;
  border-radius: 12px;
  border: 1px solid rgba(139, 92, 246, 0.30);
  background: rgba(15, 15, 36, 0.85);
  text-align: center;
}
.intro-ob-stat-pill-id {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.10em;
  color: #f59e0b;
}
.intro-ob-stat-pill-name {
  margin-top: 2px;
  font-size: 0.58rem;
  letter-spacing: 0.04em;
  color: rgba(242, 242, 247, 0.62);
  text-transform: uppercase;
}
.intro-ob-slot-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 4px auto 0;
  max-width: 280px;
}
.intro-ob-slot-tile {
  aspect-ratio: 1 / 1;
  border-radius: 10px;
  background: radial-gradient(circle at center, rgba(139, 92, 246, 0.18), rgba(12, 12, 28, 0.95) 80%);
  border: 1px solid rgba(139, 92, 246, 0.30);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.50rem;
  font-weight: 900;
  letter-spacing: 0.10em;
  color: #f8e7b0;
  text-transform: uppercase;
}
.intro-ob-slot-tile--filled {
  border-color: rgba(245, 158, 11, 0.55);
  box-shadow: 0 0 10px rgba(245, 158, 11, 0.16);
  color: #fff7e6;
}
.intro-onboarding-progress {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 6px;
  margin: 4px auto 16px;
}
.intro-ob-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: rgba(139, 92, 246, 0.30);
  transition: width 0.22s ease, background 0.22s ease;
}
.intro-ob-dot.is-active {
  width: 22px;
  background: linear-gradient(90deg, #8b5cf6, #f59e0b);
  box-shadow: 0 0 10px rgba(245, 158, 11, 0.25);
}
.intro-onboarding-actions {
  position: relative;
  z-index: 2;
  display: flex;
  gap: 10px;
  width: 100%;
  max-width: 440px;
  margin: 0 auto;
}
.intro-onboarding-btn {
  flex: 1;
  min-height: 48px;
  border-radius: 14px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-weight: 900;
  font-size: 0.78rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  border: 1px solid rgba(139, 92, 246, 0.35);
  transition: transform 0.12s ease, box-shadow 0.18s ease, background 0.18s ease, opacity 0.18s ease;
}
.intro-onboarding-btn:active { transform: scale(0.98); }
.intro-onboarding-btn:disabled {
  opacity: 0.40;
  cursor: not-allowed;
  box-shadow: none;
}
.intro-onboarding-btn--primary {
  color: #fff7e6;
  background: linear-gradient(180deg, rgba(139, 92, 246, 0.42), rgba(58, 26, 99, 0.96));
  border-color: rgba(245, 158, 11, 0.55);
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, 0.12),
    0 10px 22px rgba(0, 0, 0, 0.35),
    0 0 18px rgba(139, 92, 246, 0.20);
}
.intro-onboarding-btn--primary:hover {
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, 0.22),
    0 12px 26px rgba(0, 0, 0, 0.45),
    0 0 24px rgba(245, 158, 11, 0.20);
}
.intro-onboarding-btn--secondary {
  color: rgba(242, 242, 247, 0.78);
  background: rgba(30, 30, 63, 0.78);
  border-color: rgba(139, 92, 246, 0.32);
}
.intro-onboarding-btn--secondary:hover {
  background: rgba(40, 40, 80, 0.85);
  border-color: rgba(139, 92, 246, 0.50);
}
@media (prefers-reduced-motion: reduce) {
  .intro-onboarding, .intro-onboarding-card { animation: none; }
}
@media (max-width: 360px) {
  .intro-onboarding-title { font-size: 1.4rem; }
  .intro-onboarding-body  { font-size: 0.86rem; }
  .intro-onboarding-card  { padding: 22px 16px 20px; }
}

/* ═══════════════════════════════════════════════════════════════
   v3 Phase 1k — CODEX HABIT CARDS (Habits-tab redesign).
   Ported from preview-habits.html. Layers on top of the existing
   .habit-item base styles via the `.codex` modifier class on the
   <li>. All drag/long-press/click logic stays on .habit-item; this
   file only changes the visual treatment.
   ═══════════════════════════════════════════════════════════════ */

/* Section header above the habit grid */
.codex-section-header {
  padding: 12px 14px 0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", system-ui, sans-serif;
}
.codex-section-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.codex-section-label {
  font-size: 11.5px;
  font-weight: 800;
  color: #f5b842;
  letter-spacing: 2px;
  text-transform: uppercase;
  line-height: 1;
}
.codex-section-counter {
  display: flex;
  align-items: baseline;
  font-size: 19px;
  font-weight: 800;
  color: #f5f5fa;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.5px;
  line-height: 1;
}
.codex-section-counter--all { color: #f5b842; text-shadow: 0 0 12px rgba(245, 184, 66, 0.32); }
.codex-section-counter-num { color: #f5b842; }
.codex-section-counter-sep { color: #54546e; font-size: 14px; font-weight: 600; }
.codex-section-subtitle {
  margin-top: 6px;
  font-size: 11px;
  font-weight: 500;
  color: #9090a8;
  letter-spacing: 0.2px;
  font-style: italic;
  font-family: Georgia, "Cormorant Garamond", "Times New Roman", serif;
  line-height: 1;
}
.codex-section-progress {
  margin-top: 12px;
  height: 1.5px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 1px;
  overflow: hidden;
}
.codex-section-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #8b5cf6 0%, #f5b842 100%);
  box-shadow: 0 0 6px rgba(245, 184, 66, 0.32);
  transition: width 0.45s cubic-bezier(0.2, 0.7, 0.3, 1);
}

/* Codex-mode grid — tightened gap, extra breathing room above */
.habit-list.habit-list--codex {
  /* v3 Phase 1o — top padding trimmed (16 → 8) and row gap tightened
     (11 → 9) so 6 full codex cards are visible on a standard iPhone
     viewport without the cards feeling cramped. */
  padding: 8px 12px 0;
  gap: 9px;
}

/* ── Habit-item CODEX modifier — overrides base .habit-item visuals ── */
.habit-item.codex {
  /* Reset the legacy bg/border/padding — codex layers below paint the surface */
  background: transparent;
  border: none;
  border-bottom: none;
  padding: 0;
  min-height: 0;
  aspect-ratio: 0.82;
  box-shadow: none;
  /* Stat color RGB tuple is set inline by buildItem */
  --stat-rgb: 139, 92, 246;
}
.habit-item.codex.completed { background: transparent; border-color: transparent; }
.habit-item.codex:hover { background: transparent; }

/* Outer gradient ring */
.habit-item.codex .codex-card-ring {
  position: absolute;
  inset: -1px;
  border-radius: 14px;
  opacity: 0.65;
  transition: opacity 0.3s, filter 0.3s;
  background: linear-gradient(160deg,
    rgba(var(--stat-rgb), 0.53) 0%,
    rgba(var(--stat-rgb), 0.06) 50%,
    rgba(var(--stat-rgb), 0.33) 100%);
  pointer-events: none;
}
.habit-item.codex.codex--auto:not(.completed) .codex-card-ring {
  background: linear-gradient(160deg,
    rgba(59, 130, 246, 0.55) 0%,
    rgba(59, 130, 246, 0.12) 50%,
    rgba(59, 130, 246, 0.40) 100%);
}
.habit-item.codex.completed .codex-card-ring {
  opacity: 0.95;
  filter: drop-shadow(0 0 8px rgba(245, 184, 66, 0.32));
  background: linear-gradient(160deg,
    #f5b842 0%,
    #c08418 50%,
    rgba(var(--stat-rgb), 0.53) 100%);
}

/* Card surface */
.habit-item.codex .codex-card-surface {
  position: absolute;
  inset: 0;
  border-radius: 13px;
  overflow: hidden;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  background:
    radial-gradient(120% 80% at 50% -20%, rgba(139, 92, 246, 0.18) 0%, transparent 55%),
    linear-gradient(180deg, #1d1d3d 0%, #131227 100%);
  transition: background 0.3s, box-shadow 0.3s;
  pointer-events: none;
}
.habit-item.codex.codex--auto:not(.completed) .codex-card-surface {
  background:
    radial-gradient(120% 80% at 50% -20%, rgba(59, 130, 246, 0.12) 0%, transparent 60%),
    linear-gradient(180deg, #161630 0%, #0e0e22 100%);
}
.habit-item.codex.completed .codex-card-surface {
  background:
    radial-gradient(120% 80% at 50% 110%, rgba(245, 158, 11, 0.20) 0%, transparent 55%),
    linear-gradient(180deg, #25204a 0%, #1a1532 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -20px 30px -10px rgba(245, 184, 66, 0.32);
}
.habit-item.codex .codex-card-surface::before {
  /* Stat-color radial overlay */
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 50% at 50% 20%, rgba(var(--stat-rgb), 0.10) 0%, transparent 60%);
  opacity: 0.9;
}
.habit-item.codex.completed .codex-card-surface::before { opacity: 0.4; }
.habit-item.codex .codex-card-surface::after {
  /* Dust motes */
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.5;
  background:
    radial-gradient(1px 1px at 25% 35%, rgba(255, 255, 255, 0.5), transparent),
    radial-gradient(1px 1px at 75% 55%, rgba(255, 255, 255, 0.3), transparent),
    radial-gradient(1px 1px at 45% 80%, rgba(255, 255, 255, 0.4), transparent);
  animation: codex-dust 14s ease-in-out infinite;
}
.habit-item.codex.completed .codex-card-surface .codex-bottom-glow {
  position: absolute;
  bottom: -10px;
  left: 22%;
  right: 22%;
  height: 28px;
  background: radial-gradient(closest-side, rgba(245, 184, 66, 0.22) 0%, transparent 75%);
  filter: blur(6px);
  pointer-events: none;
}

/* Streak — dim floating gold glyph.
   The wrapper is ALWAYS rendered (so existing toggleHabit hooks find
   `.streak-badge`). When count is 0 the wrapper is empty; we hide
   it visually via :empty so it doesn't render an empty box. */
.habit-item.codex .codex-streak {
  position: absolute;
  top: 7px;
  left: 8px;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 2px;
  font-size: 9px;
  font-weight: 600;
  color: rgba(245, 184, 66, 0.62);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.1px;
  text-shadow:
    0 1px 3px rgba(0, 0, 0, 0.85),
    0 0 6px rgba(0, 0, 0, 0.6);
  opacity: 0.9;
  pointer-events: none;
}
.habit-item.codex .codex-streak:empty { display: none; }
.habit-item.codex .codex-streak svg { opacity: 0.65; color: #f5b842; }
.habit-item.codex.completed .codex-streak { opacity: 0.55; }

/* Status indicator (top-right).
   The .codex-status wrapper carries the legacy `habit-cb` alias and
   contains BOTH pending + sealed children. CSS toggles which shows
   based on `.habit-item.codex.completed`. This makes toggleHabit's
   in-place `.completed` class toggle produce the right visual without
   needing a card rebuild. */
.habit-item.codex .codex-status {
  position: absolute;
  top: 6px;
  right: 6px;
  z-index: 2;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.habit-item.codex .codex-status-ring {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1.6px solid rgb(var(--stat-rgb));
  opacity: 0.55;
  animation: codex-pending-breathe 3.5s ease-in-out infinite;
}
.habit-item.codex .codex-status-auto {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1.4px dashed #79b4ff;
  background: rgba(59, 130, 246, 0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: codex-auto-breathe 3.2s ease-in-out infinite;
}
.habit-item.codex .codex-status-disc {
  position: relative;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #ffd270 0%, #f5b842 55%, #8a5a10 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 0 16px rgba(245, 184, 66, 0.32),
    inset 0 0 0 1px rgba(255, 255, 255, 0.32);
  animation: codex-disc-pop 600ms cubic-bezier(0.34, 1.56, 0.64, 1) backwards;
}
.habit-item.codex .codex-status-auto-dot {
  position: absolute;
  bottom: -2px;
  right: -2px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #0a0a1c;
  border: 1px solid #79b4ff;
  display: flex;
  align-items: center;
  justify-content: center;
}
/* Pending state — show ring/auto, hide disc */
.habit-item.codex:not(.completed) .codex-status-disc { display: none; }
.habit-item.codex .codex-status-ring,
.habit-item.codex .codex-status-auto { display: block; }
/* Completed state — show disc, hide ring/auto */
.habit-item.codex.completed .codex-status-ring,
.habit-item.codex.completed .codex-status-auto { display: none; }
.habit-item.codex.completed .codex-status-disc { display: flex; }

/* Icon — centered, larger than legacy emoji */
.habit-item.codex .codex-icon-wrap {
  position: absolute;
  top: 12%;
  left: 50%;
  transform: translateX(-50%);
  width: 58%;
  aspect-ratio: 1;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.habit-item.codex .codex-icon-wrap img,
.habit-item.codex .codex-icon-wrap .habit-icon-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: saturate(0.92);
  transition: filter 0.3s, opacity 0.3s;
}
.habit-item.codex .codex-icon-wrap--emoji .habit-emoji {
  font-size: 56px;
  line-height: 1;
}
.habit-item.codex.completed .codex-icon-wrap img,
.habit-item.codex.completed .codex-icon-wrap .habit-icon-img {
  filter: drop-shadow(0 0 8px rgba(245, 184, 66, 0.32));
}
.habit-item.codex.codex--auto:not(.completed) .codex-icon-wrap img,
.habit-item.codex.codex--auto:not(.completed) .codex-icon-wrap .habit-icon-img {
  opacity: 0.78;
}

/* Text block (bottom) */
.habit-item.codex .codex-text-block {
  position: absolute;
  bottom: 8px;
  left: 0;
  right: 0;
  padding: 0 6px;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.5px;
}
.habit-item.codex .codex-sealed-banner {
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 1.6px;
  color: rgba(245, 184, 66, 0.72);
  text-transform: uppercase;
  animation: codex-seal-fade 600ms ease-out 200ms backwards;
  /* Hidden by default; revealed when .habit-item.codex.completed */
  display: none;
}
.habit-item.codex.completed .codex-sealed-banner { display: block; }
.habit-item.codex .codex-name {
  font-size: 11.5px;
  font-weight: 600;
  color: #f5f5fa;
  text-align: center;
  line-height: 1.15;
  letter-spacing: -0.15px;
  max-height: 28px;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  white-space: normal;
}
.habit-item.codex .codex-xp-chip {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 2px 6px;
  border-radius: 7px;
  background: rgba(245, 184, 66, 0.08);
  border: 0.5px solid rgba(245, 184, 66, 0.18);
  font-size: 9.5px;
  font-weight: 700;
  color: #f5b842;
  font-variant-numeric: tabular-nums;
  transition: background 0.3s, border-color 0.3s, box-shadow 0.3s;
}
.habit-item.codex .codex-xp-chip svg { color: #f5b842; }
.habit-item.codex.completed .codex-xp-chip {
  background: rgba(245, 184, 66, 0.22);
  border-color: rgba(245, 184, 66, 0.6);
  box-shadow: 0 0 8px rgba(245, 184, 66, 0.32);
}
.habit-item.codex .codex-xp-chip-2x {
  margin-left: 4px;
  padding: 0 4px;
  border-radius: 4px;
  background: rgba(245, 184, 66, 0.20);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.3px;
}

/* ─────────────────────────────────────────────────────────────
   v3 Phase 1z.228C — Ultra-light Habit Completion Reward chip
   Rebuild of 1z.228B after on-device QA reported rapid-tap lag
   persisted despite spark removal. Bloom (radial-gradient) and
   ring (large scale animation) are now gone entirely — they were
   the two largest remaining composite costs per burst. The reward
   is now one floating chip + `#completed-count` pulse + bottom XP
   strip hide. Per-completion DOM cost: 1 node.

   Duplicate +XP prevention still active:
   • `.codex-xp-chip` (static bottom strip) fades while
     `.is-reward-bursting` is set on the li.
   • `.xp-float` (legacy 1z.165 floater) is suppressed at the
     source in toggleHabit so it cannot duplicate the chip.
   ───────────────────────────────────────────────────────────── */

.habit-item.is-reward-bursting .codex-xp-chip {
  opacity: 0;
  transition: opacity 160ms ease-out;
}

.habit-reward-chip {
  position: absolute;
  top: 38%;
  left: 50%;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 11px;
  border-radius: 10px;
  background: linear-gradient(180deg,
    rgba(42, 33, 12, 0.95),
    rgba(22, 16, 5, 0.95));
  border: 1px solid #f5b842;
  color: #ffd270;
  font-family: -apple-system, "SF Pro Display", system-ui, sans-serif;
  font-weight: 800;
  font-size: 15px;
  letter-spacing: 0.3px;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
  z-index: 6;
  transform: translate(-50%, 6px) scale(0.85);
  opacity: 0;
  animation: hab-rwd-chip 700ms cubic-bezier(0.2, 0.7, 0.3, 1) forwards;
  will-change: transform, opacity;
}
.habit-reward-chip svg { color: #ffd270; }
.habit-reward-chip-2x {
  margin-left: 4px;
  padding: 0 4px;
  border-radius: 4px;
  background: rgba(245, 184, 66, 0.22);
  color: #ffd270;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.3px;
}
