  top: 44%;
  font-family: "Cinzel", "Cormorant Garamond", Georgia, serif;
  font-size: 13px;
  letter-spacing: 2.2px;
  color: #ffd270;
  animation-duration: 1100ms;
}

/* Daily progress count pulse — fires once per successful completion.
   Opacity+transform only. */
.habit-progress-pulse {
  display: inline-block;
  animation: hab-rwd-count 360ms cubic-bezier(0.34, 1.56, 0.5, 1);
}

@keyframes hab-rwd-chip {
  0%   { transform: translate(-50%, 6px)   scale(0.85); opacity: 0; }
  22%  { transform: translate(-50%, -6px)  scale(1.06); opacity: 1; }
  34%  { transform: translate(-50%, -10px) scale(1);    opacity: 1; }
  72%  { opacity: 1; }
  100% { transform: translate(-50%, -36px) scale(0.96); opacity: 0; }
}
@keyframes hab-rwd-count {
  0%   { transform: scale(1); }
  40%  { transform: scale(1.28); }
  100% { transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .habit-reward-chip {
    animation-duration: 220ms !important;
    animation-timing-function: ease-out !important;
  }
  .habit-progress-pulse { animation: none !important; }
  .habit-item.is-reward-bursting .codex-xp-chip {
    transition: opacity 120ms ease-out;
  }
}

/* Drag handle + more button — preserved exact data attributes for
   existing drag/click logic. Positioned over the card surface so
   they remain tappable without disturbing the centered layout. */

/* v3 Phase 1z.50 — drag-handle dots HIDDEN.
   Habit drag-reorder is disabled for 2.2.1 (ENABLE_HABIT_DRAG_REORDER
   = false in app.js); the 6-dot affordance looks like an
   interactive control but does nothing when tapped. Hide it
   entirely so the manage button below can take this corner. The
   element stays in the DOM so the drag-reorder feature can be
   re-enabled later without a markup change. */
.habit-item.codex .drag-handle {
  display: none;
}

/* v3 Phase 1z.50 — manage button (the 3-dot ···) is now ALWAYS
   visible on every habit card, not just during long-press/reorder
   (which is disabled anyway). Tester feedback: there was no
   obvious way to reach Edit Habit / Schedule / Delete from the
   card. The button opens the existing context menu (Edit Habit /
   Add Note / Schedule / Delete) — same wiring as before, just
   discoverable now. Custom habits also get the inline Delete
   button inside the Edit Habit modal (1z.49). */
.habit-item.codex .habit-more-btn {
  position: absolute;
  bottom: 4px;
  right: 4px;
  z-index: 3;
  width: 28px;
  height: 28px;
  /* iOS HIG asks for 44x44 tap targets; the visible glyph is 28x28
     but we pad the hit area outward via a transparent border so
     the effective touch target is closer to 40x40 without
     visually enlarging the pill. */
  padding: 0;
  border: 6px solid transparent;
  background-clip: padding-box;
  background-color: rgba(20, 20, 35, 0.55);
  border-radius: 50%;
  color: rgba(255, 255, 255, 0.78);
  font-size: 1rem;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.4);
  /* iOS hit-testing hygiene — same set we used on the souls X. */
  pointer-events: auto;
  touch-action: manipulation;
  -webkit-tap-highlight-color: rgba(255, 255, 255, 0.08);
  transition: background 0.15s ease, color 0.15s ease, transform 0.12s ease;
}
.habit-item.codex .habit-more-btn:hover  { background-color: rgba(40, 40, 60, 0.8); color: #fff; }
.habit-item.codex .habit-more-btn:active { transform: scale(0.92); }

/* Schedule pills + No-alcohol challenge badge — keep visible but
   subordinate. Anchor bottom-left corner of card.
   v3 Phase 1z.273F — added `.habit-schedule-chip` (the new
   1z.273F single-chip class). The legacy `.habit-sched-pills`
   selector here was a dead reference (actual class emitted was
   `.sched-pills`), preserved for diff hygiene. */
.habit-item.codex .habit-schedule-chip,
.habit-item.codex .habit-sched-pills,
.habit-item.codex .na-challenge-badge {
  position: absolute;
  bottom: 4px;
  left: 4px;
  z-index: 2;
  pointer-events: none;
}

