/* ═══════════════════════════════════════════════════════════════
   v3 Phase 1o — Pack/Routine Progress Modal
   Reached by tapping the top "X / Y HABITS TODAY" tile on the
   Habits screen. Replaces the retired persistent footer strip.
   Reuses the .cp-prog-row markup inside .pp-body so all existing
   chip styles (streak / shield / honest / add-missing) carry over.
   ═══════════════════════════════════════════════════════════════ */
.pack-progress-overlay {
  position: fixed;
  inset: 0;
  background: rgba(8, 8, 20, 0.72);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  z-index: 160;
  opacity: 1;
  transition: opacity 0.18s ease;
}
.pack-progress-overlay.hidden { display: none !important; }
.pack-progress-modal {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 161;
  width: min(420px, calc(100vw - 32px));
  max-height: calc(100vh - 64px);
  pointer-events: none;
}
.pack-progress-modal.hidden { display: none !important; }
.pack-progress-modal .pp-card {
  pointer-events: auto;
  position: relative;
  background: linear-gradient(180deg, #1a1a36 0%, #131329 100%);
  border: 1px solid rgba(139, 92, 246, 0.35);
  border-radius: 14px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(245, 184, 66, 0.06) inset;
  padding: 18px 16px 14px;
  max-height: calc(100vh - 64px);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.pp-close-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 30px;
  height: 30px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font-size: 1rem;
  line-height: 1;
  cursor: pointer;
  border-radius: 6px;
  transition: background 0.15s ease, color 0.15s ease;
}
.pp-close-btn:hover { background: rgba(255, 255, 255, 0.06); color: var(--text-primary); }
.pp-title {
  font-family: 'Cinzel', serif;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--gold);
  letter-spacing: 0.04em;
  margin: 0 28px 4px 0;
}
.pp-subtitle {
  font-size: 0.72rem;
  color: var(--text-tertiary);
  margin-bottom: 14px;
  letter-spacing: 0.01em;
}
.pp-body { display: flex; flex-direction: column; gap: 8px; }
/* Inside the modal, the cp-prog-row rows render the same way as the old
   footer surface — no override needed. The rows are flex containers and
   already self-style. */
.pp-empty {
  font-size: 0.82rem;
  color: var(--text-secondary);
  text-align: center;
  padding: 18px 8px 6px;
  line-height: 1.5;
}
.pp-empty.hidden { display: none; }
.pp-empty-sub {
  display: inline-block;
  margin-top: 6px;
  font-size: 0.74rem;
  color: var(--text-tertiary);
}

/* ═══════════════════════════════════════════════════════════════
   v3 Phase 1p — History tab: Discipline Ledger redesign
   - Weekly grid becomes a stat-color "gem" ledger with legend.
   - New TrainedThisWeek section + premium WeeklyReport card.
   - Monthly / Yearly / Milestones layouts left untouched.
   ═══════════════════════════════════════════════════════════════ */

/* ── Refined date nav ── */
.hg-nav--ledger {
  padding: 4px 4px 10px;
  gap: 6px;
}
.hg-nav--ledger .hg-nav-center {
  flex: 1;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.hg-nav-eyebrow {
  font-size: 9.5px;
  font-weight: 800;
  color: var(--text-tertiary);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.hg-nav--ledger .hg-nav-range {
  font-size: 14.5px;
  font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}
.hist-nav-btn--chev {
  width: 32px;
  height: 32px;
  min-width: 32px;
  border-radius: 16px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  cursor: pointer;
  transition: color 0.15s, background 0.15s;
}
.hist-nav-btn--chev:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.hist-nav-btn--chev:active { transform: scale(0.95); }
.hist-nav-btn--chev:disabled { opacity: 0.3; cursor: default; }

/* ── Ledger card ── */
.hg-grid-wrap.hg-ledger {
  background: linear-gradient(180deg, #14143a 0%, #0e0e2a 100%);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.03);
}

.hg-row.hg-row--ledger {
  /* v3 Phase 1p final tighten — 44 → 38px. Two-line habit names still
     fit (line-height 1.08 × 11.5px ≈ 12.4px per line × 2 ≈ 25px,
     centered inside 38px with ~6px breathing each side). Reads as a
     compact training log, not a spaced-out table. */
  min-height: 38px;
}
/* Header row stays compact — no two-line label there. */
.hg-ledger .hg-row.hg-header-row { min-height: 26px; }

/* Eyebrow header inside label column. Stacked vertically; subtitle is
   subtle by design so day letters stay the visual anchor. */
.hg-ledger .hg-label.hg-label-hdr {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 2px;
  padding: 5px 6px 5px 11px;
}
.hg-ledger-eyebrow {
  display: block;
  font-size: 9.5px;
  font-weight: 800;
  color: var(--gold);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  line-height: 1;
  white-space: nowrap;
}
.hg-ledger-sub {
  display: block;
  font-size: 8.5px;
  font-weight: 600;
  color: var(--text-tertiary);
  letter-spacing: 0.02em;
  line-height: 1;
  white-space: nowrap;
}

/* Day header today marker — subtle gold underline glow */
.hg-day-hdr--today {
  color: var(--gold) !important;
  text-shadow: 0 0 8px rgba(245,184,66,0.40);
  position: relative;
}
.hg-day-hdr-mark {
  position: absolute;
  bottom: 1px;
  left: 30%;
  right: 30%;
  height: 1.5px;
  background: linear-gradient(90deg, transparent, var(--gold), transparent);
  box-shadow: 0 0 6px rgba(245,184,66,0.4);
  border-radius: 1px;
}

/* Label column — stat-color accent stripe + two-line name + AUTO badge */
.hg-label--ledger {
  position: relative;
  padding: 2px 4px 2px 10px;
  gap: 4px;
  align-items: center;
  overflow: hidden;
}
.hg-label-accent {
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 2px;
  border-radius: 0 1px 1px 0;
  opacity: 0.85;
}
.hg-label-name--wrap {
  /* v3 Phase 1p final tighten — two-line clamp with line-height 1.08
     so long names ("Strength training", "Meditate & Breathwork", "No
     phone after waking") still wrap cleanly inside the 38px row. */
  white-space: normal !important;
  overflow: hidden !important;
  text-overflow: clip !important;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  font-size: 11.5px;
  line-height: 1.08;
  word-break: break-word;
  font-weight: 600;
  flex: 1 1 auto;
  min-width: 0;
}
/* v3 Phase 1p polish — AUTO marker collapsed from a text pill to a
   tiny blue dot. Same semantic meaning (system-verified habit), zero
   label-column real estate stolen. The auto-source corner dot on the
   individual done-cells already carries the data signal per-day. */
.hg-label-auto {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #79b4ff;
  box-shadow: 0 0 4px rgba(121,180,255,0.55);
  flex: 0 0 auto;
  align-self: center;
  /* Strip the old pill chrome */
  font-size: 0;
  letter-spacing: 0;
  padding: 0;
  border: none;
  color: transparent;
  text-indent: -9999px;
  overflow: hidden;
}
/* Weekly ledger label is the tap target — entire row label opens the
   habit info sheet. Subtle hover/focus state communicates the
   interactivity without crowding the label with chrome. */
.hg-ledger .hg-label--ledger {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.15s ease;
}
.hg-ledger .hg-label--ledger:hover { background: rgba(255,255,255,0.025); }
.hg-ledger .hg-label--ledger:focus-visible {
  outline: 1px solid rgba(245,184,66,0.45);
  outline-offset: -2px;
  border-radius: 6px;
}

/* ── Cell states ── */
.hg-cell--done { border-radius: 5px; position: relative; }
.hg-cell--done-today {
  outline: 1px solid var(--gold);
  outline-offset: 1px;
  box-shadow: 0 0 8px rgba(245,184,66,0.32);
}
.hg-cell--done.hg-cell--auto::after {
  /* Override the legacy AUTO indicator with a smaller, framed dot in
     the bottom-right corner so it reads as "system-verified" without
     fighting the gem gradient. */
  content: '';
  position: absolute;
  bottom: -2px;
  right: -2px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #0a0a1c;
  border: 0.8px solid #79b4ff;
  box-shadow: 0 0 4px rgba(121,180,255,0.45);
}

.hg-cell--pending {
  background: rgba(245,184,66,0.04);
  border: 1.4px dashed var(--gold);
  animation: hg-today-pulse 2.5s ease-in-out infinite;
}
@keyframes hg-today-pulse {
  0%, 100% { opacity: 0.6; }
  50%      { opacity: 0.95; }
}

.hg-cell--missed {
  /* v3 Phase 1p polish — quieter missed state so a week with several
     misses doesn't read as a hostile red wall. */
  background: rgba(239,68,68,0.025);
  border: 0.5px solid rgba(239,68,68,0.10);
  display: flex;
  align-items: center;
  justify-content: center;
}
.hg-cell-miss-dot {
  display: inline-block;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(220,38,38,0.42);
}

.hg-cell--future {
  background: transparent;
  border: 0.5px solid rgba(255,255,255,0.035);
}
.hg-cell--off {
  background: transparent;
  border: 0.5px dashed rgba(255,255,255,0.05);
}

/* v3 Phase 1p polish — day cells tightened back to 22px so the
   ledger reads as a compact discipline log. The gem gradient + outer
   glow still carry legibility at this size. */
.hg-ledger .hg-cell {
  height: 22px;
  width: 22px;
  border-radius: 5px;
}

/* ── Legend strip ── */
.hg-legend {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 10px 12px 12px;
  background: rgba(0,0,0,0.20);
  border-top: 1px solid rgba(255,255,255,0.05);
  flex-wrap: wrap;
  border-radius: 0 0 12px 12px;
}
.hg-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 9.5px;
  font-weight: 600;
  color: var(--text-tertiary);
  letter-spacing: 0.04em;
}
.hg-legend-cell {
  width: 11px;
  height: 11px;
  border-radius: 2.5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}
.hg-legend-cell--done {
  background: radial-gradient(circle at 35% 30%, #ec4899 0%, #be1a6e 100%);
  box-shadow: 0 0 5px rgba(236,72,153,0.40), inset 0 0 0 0.5px rgba(255,255,255,0.18);
}
.hg-legend-cell--missed {
  background: rgba(239,68,68,0.04);
  border: 0.5px solid rgba(239,68,68,0.16);
}
.hg-legend-cell--missed .hg-cell-miss-dot {
  width: 2.5px;
  height: 2.5px;
}
.hg-legend-cell--pending {
  border: 1px dashed var(--gold);
  background: rgba(245,184,66,0.04);
}
.hg-legend-cell--off {
  border: 0.5px dashed rgba(255,255,255,0.10);
}

/* ── Trained This Week ── */
.hg-trained {
  margin-top: 12px;
  padding: 12px 14px 14px;
  background: linear-gradient(180deg, #14143a 0%, #0e0e2a 100%);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.03);
}
.hg-trained-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}
.hg-trained-title {
  font-size: 10.5px;
  font-weight: 800;
  color: var(--gold);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.hg-trained-meta {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-tertiary);
  letter-spacing: 0.02em;
}
.hg-trained-bars {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}
.hg-trained-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.hg-trained-bar {
  position: relative;
  height: 38px;
  width: 100%;
  max-width: 24px;
  background: rgba(255,255,255,0.04);
  border-radius: 3px;
  border: 0.5px solid rgba(255,255,255,0.06);
  overflow: hidden;
}
.hg-trained-fill {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  border-top-left-radius: 3px;
  border-top-right-radius: 3px;
  transition: height 0.3s ease;
}
.hg-trained-label {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--text-primary);
  line-height: 1;
}
.hg-trained-col--empty .hg-trained-label { color: var(--text-tertiary); }
.hg-trained-count {
  font-size: 11px;
  font-weight: 800;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  margin-top: 1px;
}
.hg-trained-insight {
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid rgba(255,255,255,0.05);
  text-align: center;
  font-size: 12px;
  font-style: italic;
  font-family: Georgia, "Cormorant Garamond", serif;
  color: var(--text-primary);
  line-height: 1.35;
  letter-spacing: 0.02em;
  opacity: 0.85;
}
.hg-trained-tag {
  font-style: normal;
  font-weight: 800;
  font-family: inherit;
  letter-spacing: 0.05em;
}

/* ── Weekly Report ── */
.hg-report {
  margin-top: 12px;
  margin-bottom: 12px;
  background:
    radial-gradient(120% 70% at 50% 0%, rgba(245,184,66,0.10) 0%, transparent 60%),
    linear-gradient(180deg, #1a1a3d 0%, #14142c 100%);
  border: 1px solid rgba(245,184,66,0.35);
  border-radius: 12px;
  box-shadow: 0 0 16px rgba(245,184,66,0.20), inset 0 1px 0 rgba(255,255,255,0.04);
  overflow: hidden;
}
.hg-report-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px 8px;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.hg-report-title-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.hg-report-star { color: var(--gold); opacity: 0.95; }
.hg-report-title {
  font-size: 11px;
  font-weight: 800;
  color: var(--gold);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.hg-report-range {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-tertiary);
  letter-spacing: 0.02em;
}
.hg-report-body {
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 14px 18px 12px;
}
.hg-report-hero { flex: 0 0 auto; }
.hg-report-pct {
  font-size: 34px;
  font-weight: 800;
  color: var(--gold);
  letter-spacing: -0.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px rgba(245,184,66,0.30);
}
.hg-report-pct-sym {
  font-size: 19px;
  font-weight: 700;
}
.hg-report-pct-lbl {
  font-size: 9.5px;
  font-weight: 700;
  color: var(--text-tertiary);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-top: 3px;
}
.hg-report-rows {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.hg-report-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.hg-report-row-lbl {
  font-size: 10.5px;
  font-weight: 700;
  color: var(--text-secondary);
  letter-spacing: 0.10em;
  text-transform: uppercase;
}
.hg-report-row-val {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}
.hg-report-row-val--gold {
  color: var(--gold);
  text-shadow: 0 0 10px rgba(245,184,66,0.30);
}
.hg-report-dom {
  margin: 4px 14px 14px;
  padding: 8px 12px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.hg-report-dom-lbl {
  font-size: 9.5px;
  font-weight: 700;
  color: var(--text-tertiary);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  min-width: 64px;
}
.hg-report-dom-stat {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.06em;
}
.hg-report-dom-count {
  flex: 1;
  text-align: right;
  font-size: 10.5px;
  font-style: italic;
  color: var(--text-secondary);
  font-family: Georgia, "Cormorant Garamond", serif;
}


/* ──────────────────────────────────────────────────────────────────
   Social tab — Friends section (v3 Phase 1x, retitled by 1z.279
   Duels permanent retirement).
   ────────────────────────────────────────────────────────────────── */

/* Ensure the Social tab panel can scroll past the safe-area inset on
   iPhone home-indicator devices. Without this the bottom 34pt of the
   tab-panel scroll region overlaps the indicator and the friends
   section feels "unreachable" even though it exists in the DOM. */
#social-panel {
  padding-bottom: calc(48px + var(--safe-bottom, 0px));
}


/* ──────────────────────────────────────────────────────────────
   v3 Phase 1z.7 — Boss Defeated overlay redesign (#boss-result-overlay)
   Visual restyle on the 1z.6 controller. Hero header with rune divider
   + Cinzel glow, boss card with portrait + diagonal slash + VERIFIED
   defeat-condition row, relic card with rarity-tinted border, no-drop
   card with mercy progress bars. Action stack: purple primary → gold
   secondary → ghost tertiary. Gold dust via radial gradients only.
   ────────────────────────────────────────────────────────────── */
.bro-overlay {
  position: fixed;
  inset: 0;
  z-index: 250;
  background:
    radial-gradient(60% 50% at 50% 30%, rgba(245,184,66,0.16) 0%, transparent 65%),
    radial-gradient(80% 50% at 50% 70%, rgba(139,92,246,0.20) 0%, transparent 65%),
    rgba(5, 5, 16, 0.96);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: calc(56px + var(--safe-top, 0px)) 18px calc(28px + var(--safe-bottom, 0px));
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  animation: bro-overlay-in 0.36s var(--ease-cinema, ease-out);
}
.bro-overlay.hidden { display: none !important; }
body.bro-locked { overflow: hidden; }

@keyframes bro-overlay-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* Gold dust — pure CSS radial-gradient layer, no JS animation. */
.bro-gold-dust {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.55;
  background:
    radial-gradient(2px 2px at 8%  15%, #ffd270, transparent),
    radial-gradient(1.5px 1.5px at 88% 22%, #f5b842, transparent),
    radial-gradient(2px 2px at 22% 78%, #ffd270, transparent),
    radial-gradient(1.5px 1.5px at 75% 86%, #f5b842, transparent),
    radial-gradient(1px 1px at 50% 50%, #f5b842, transparent),
    radial-gradient(2px 2px at 92% 60%, #ffd270, transparent),
    radial-gradient(1px 1px at 15% 50%, #f5b842, transparent),
    radial-gradient(1.5px 1.5px at 38% 8%,  #f5b842, transparent),
    radial-gradient(1px 1px at 62% 32%, #f5b842, transparent),
    radial-gradient(1.5px 1.5px at 30% 60%, #ffd270, transparent);
}

.bro-close-x {
  position: absolute;
  top: calc(14px + var(--safe-top, 0px));
  right: 16px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.08);
  background: rgba(0,0,0,0.5);
  color: var(--text-secondary, #9090a8);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}
.bro-close-x:hover { color: #fff; }

.bro-shell {
  position: relative;
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  z-index: 1;
  animation: bro-shell-in 0.46s var(--ease-cinema, cubic-bezier(0.22, 1, 0.36, 1));
}

@keyframes bro-shell-in {
  from { opacity: 0; transform: translateY(14px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0)    scale(1);    }
}

/* ── Hero header: rune divider + SYSTEM RESULT + BOSS DEFEATED + subline ─ */
.bro-hero {
  text-align: center;
  padding: 0 4px;
}
.bro-rune-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.bro-rune-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(245,184,66,0.35), transparent);
  max-width: 96px;
}
.bro-rune-sparkle {
  color: var(--gold, #f5b842);
  font-size: 12px;
  text-shadow: 0 0 6px rgba(245,184,66,0.6);
}
.bro-kicker {
  margin-top: 10px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 10px;
  font-weight: 800;
  color: var(--gold, #f5b842);
  letter-spacing: 0.35em;
  text-transform: uppercase;
}
.bro-overlay-title {
  margin: 6px 0 0;
  font-family: 'Cinzel', serif;
  font-weight: 700;
  font-size: 30px;
  line-height: 1.05;
  color: var(--gold, #f5b842);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  text-shadow: 0 0 18px rgba(245,184,66,0.6), 0 0 8px rgba(245,184,66,0.5);
}
.bro-subline {
  margin-top: 10px;
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 14px;
  color: var(--text-primary, #f5f5fa);
  letter-spacing: 0.01em;
  line-height: 1.4;
}

/* ── Boss card: portrait+slash + rank pill + name + Fallen + VERIFIED row ─ */
.bro-boss-card {
  padding: 14px 16px;
  background: linear-gradient(180deg, #1a1a3d 0%, #14142c 100%);
  border: 1px solid rgba(239,68,68,0.45);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 0 18px rgba(239,68,68,0.28), inset 0 1px 0 rgba(255,255,255,0.04);
}
.bro-boss-card-body {
  display: flex;
  align-items: center;
  gap: 12px;
}
.bro-boss-portrait {
  width: 64px;
  height: 64px;
  border-radius: 10px;
  background: radial-gradient(circle at 35% 30%, rgba(239,68,68,0.5), rgba(60,8,8,0.9));
  border: 1px solid rgba(239,68,68,0.45);
  flex: 0 0 auto;
  position: relative;
  overflow: hidden;
  box-shadow: 0 0 14px rgba(239,68,68,0.28), inset 0 0 8px rgba(239,68,68,0.3);
}
.bro-boss-portrait-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  filter: brightness(0.45) saturate(0.7);
}
.bro-boss-portrait-img[data-art="missing"] { display: none; }
.bro-boss-portrait-slash {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--gold, #f5b842), transparent);
  box-shadow: 0 0 6px rgba(245,184,66,0.7);
  transform: translate(-50%, -50%) rotate(-22deg);
  pointer-events: none;
}
.bro-boss-meta {
  flex: 1;
  min-width: 0;
}
.bro-rank-pill {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  background: rgba(239,68,68,0.10);
  border: 0.5px solid rgba(239,68,68,0.45);
  color: #ef4444;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.bro-rank-pill[data-rank="D"],
.bro-rank-pill[data-rank="C"],
.bro-rank-pill[data-rank="B"],
.bro-rank-pill[data-rank="A"],
.bro-rank-pill[data-rank="S"] {
  background: rgba(245,184,66,0.10);
  border-color: rgba(245,184,66,0.45);
  color: var(--gold, #f5b842);
}
.bro-boss-name {
  margin: 6px 0 4px;
  font-family: 'Cinzel', serif;
  font-weight: 600;
  font-size: 18px;
  color: var(--text-primary, #f5f5fa);
  letter-spacing: 0.08em;
  line-height: 1.15;
}
.bro-fallen {
  display: inline-block;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 10px;
  font-weight: 700;
  color: var(--gold, #f5b842);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: line-through;
  text-decoration-color: rgba(245,184,66,0.7);
}
.bro-defeat-row {
  margin-top: 12px;
  padding: 8px 10px;
  background: rgba(0,0,0,0.25);
  border: 0.5px solid rgba(245,184,66,0.35);
  border-left: 2px solid var(--gold, #f5b842);
  border-radius: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.bro-defeat-check {
  flex: 0 0 auto;
  color: var(--gold, #f5b842);
  font-size: 14px;
  font-weight: 800;
  filter: drop-shadow(0 0 3px rgba(245,184,66,0.6));
}
.bro-defeat-text {
  flex: 1;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-primary, #f5f5fa);
  letter-spacing: 0.02em;
  line-height: 1.3;
}
.bro-verified-chip {
  flex: 0 0 auto;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 8.5px;
  font-weight: 700;
  color: rgba(245,184,66,0.65);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

/* ── Reward block: shared shell ─────────────────────────────── */
.bro-reward {
  padding: 16px 16px 18px;
  border-radius: 14px;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(140% 80% at 50% 0%, rgba(245,184,66,0.10) 0%, transparent 60%),
    linear-gradient(180deg, #1a1a3d 0%, #14142c 100%);
  border: 1px solid rgba(255,255,255,0.07);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.05);
}
.bro-reward.hidden { display: none !important; }
.bro-reward-kicker {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 10px;
  font-weight: 800;
  color: var(--gold, #f5b842);
  letter-spacing: 0.30em;
  text-transform: uppercase;
  text-align: center;
}
.bro-reward-kicker--muted { color: var(--text-secondary, #9090a8); }

/* Relic variant — rarity-tinted border (default = common gray, overrides
   when JS sets data-rarity on the pill). The shell border picks up the
   rarity via [data-rarity] on the card itself. */
.bro-reward--relic[data-rarity="common"]     { border-color: rgba(144,144,168,0.55); box-shadow: 0 0 18px rgba(144,144,168,0.18), inset 0 1px 0 rgba(255,255,255,0.05); }
.bro-reward--relic[data-rarity="rare"]       { border-color: #79b4ff;                box-shadow: 0 0 22px rgba(121,180,255,0.32), inset 0 1px 0 rgba(255,255,255,0.05); }
.bro-reward--relic[data-rarity="ultra_rare"] { border-color: #a855f7;                box-shadow: 0 0 22px rgba(168,85,247,0.40), inset 0 1px 0 rgba(255,255,255,0.05); }

.bro-relic-row {
  margin-top: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.bro-relic-art-wrap {
  position: relative;
  width: 92px;
  height: 92px;
  border-radius: 10px;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(139,92,246,0.18), rgba(245,158,11,0.10));
  border: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}
.bro-relic-slot-icon {
  font-size: 2.4rem;
  opacity: 0.55;
}
.bro-relic-art {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.bro-relic-info {
  flex: 1;
  min-width: 0;
  text-align: left;
}
.bro-relic-rarity-pill {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: rgba(144,144,168,0.10);
  border: 0.5px solid rgba(144,144,168,0.5);
  color: #9090a8;
}
.bro-relic-rarity-pill[data-rarity="rare"] {
  background: rgba(121,180,255,0.10);
  border-color: rgba(121,180,255,0.5);
  color: #79b4ff;
  box-shadow: 0 0 8px rgba(121,180,255,0.32);
}
.bro-relic-rarity-pill[data-rarity="ultra_rare"] {
  background: rgba(168,85,247,0.10);
  border-color: rgba(168,85,247,0.6);
  color: #a855f7;
  box-shadow: 0 0 8px rgba(168,85,247,0.40);
}
.bro-relic-name {
  margin-top: 6px;
  font-family: 'Cinzel', serif;
  font-weight: 600;
  font-size: 17px;
  color: var(--text-primary, #f5f5fa);
  letter-spacing: 0.03em;
  line-height: 1.15;
}
.bro-relic-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  margin-top: 4px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.10em;
  color: var(--text-tertiary, #54546e);
  text-transform: uppercase;
}
.bro-relic-slot {
  color: var(--text-tertiary, #54546e);
  padding: 0;
  background: transparent;
  border-radius: 0;
}
.bro-relic-new {
  background: linear-gradient(135deg, #f59e0b, #fbbf24);
  color: #050510;
  padding: 2px 6px;
  border-radius: 4px;
  font-weight: 800;
  letter-spacing: 0.10em;
}
.bro-relic-stats { margin-top: 8px; }
.bro-relic-stats .stat-row { justify-content: flex-start; }

/* ── No-drop variant ────────────────────────────────────────── */
.bro-reward--none {
  border-style: dashed;
  border-color: rgba(245,184,66,0.35);
  text-align: center;
}
.bro-nodrop-body {
  margin-top: 4px;
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 11.5px;
  color: var(--text-tertiary, #54546e);
  line-height: 1.4;
}

/* v3 Phase 1z.56 — Hunt Failed variant.
   Re-uses the existing .bro-overlay shell. The .bro-overlay--failed
   class (toggled in _showBossResult) mutes the gold accents and
   leans red-ember so the failure is unmistakable but not punishing.
   The failure card mirrors the no-drop card structurally (kicker
   + body + supporting lines) and inherits its outer chrome from
   .bro-reward. */
.bro-reward-kicker--failed {
  color: rgba(248, 113, 113, 0.92);
  border-color: rgba(239, 68, 68, 0.45);
  background: linear-gradient(180deg, rgba(239, 68, 68, 0.12), rgba(239, 68, 68, 0.03));
}
.bro-reward--failed {
  border-color: rgba(239, 68, 68, 0.40);
  background: linear-gradient(135deg, rgba(40, 18, 22, 0.45), rgba(20, 12, 18, 0.65));
}
.bro-failed-rewards {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
}
.bro-failed-line {
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: rgba(248, 113, 113, 0.78);
  text-transform: uppercase;
}

/* Overlay-level theming for the failure variant -- mute the gold
   title accent + de-emphasize the boss portrait so the "escape"
   reads visually. The shared modal chrome stays in place so the
   user doesn't get visual whiplash between defeat + failure. */
.bro-overlay--failed .bro-overlay-title {
  color: #f87171;
  text-shadow: 0 0 12px rgba(239, 68, 68, 0.32);
}
.bro-overlay--failed .bro-kicker { color: rgba(248, 113, 113, 0.75); }
.bro-overlay--failed .bro-subline { color: rgba(248, 113, 113, 0.82); font-style: italic; }
.bro-overlay--failed .bro-rune-sparkle { color: rgba(239, 68, 68, 0.55); }
.bro-overlay--failed .bro-boss-portrait-img {
  filter: grayscale(0.35) brightness(0.85);
}
.bro-overlay--failed .bro-boss-portrait-slash { opacity: 0.25; }
.bro-overlay--failed .bro-fallen {
  color: rgba(248, 113, 113, 0.85);
}
.bro-overlay--failed .bro-gold-dust { opacity: 0.18; filter: hue-rotate(-30deg); }
.bro-mercy-block {
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 9px;
  text-align: left;
}
.bro-mercy-row { display: flex; flex-direction: column; }
.bro-mercy-row-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 4px;
}
.bro-mercy-label {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  color: var(--text-tertiary, #54546e);
  letter-spacing: 0.10em;
  text-transform: uppercase;
}
.bro-mercy-val {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.03em;
  font-variant-numeric: tabular-nums;
}
.bro-mercy-bar {
  height: 4px;
  background: rgba(255,255,255,0.05);
  border-radius: 2px;
  overflow: hidden;
}
.bro-mercy-bar-fill {
  height: 100%;
  border-radius: 2px;
  transition: width 0.4s ease;
}
.bro-mercy-row[data-tier="any"]   .bro-mercy-val { color: var(--gold, #f5b842); }
.bro-mercy-row[data-tier="any"]   .bro-mercy-bar-fill { background: linear-gradient(90deg, rgba(245,184,66,0.55), #f5b842); box-shadow: 0 0 6px rgba(245,184,66,0.35); }
.bro-mercy-row[data-tier="rare"]  .bro-mercy-val { color: #79b4ff; }
.bro-mercy-row[data-tier="rare"]  .bro-mercy-bar-fill { background: linear-gradient(90deg, rgba(121,180,255,0.55), #79b4ff); box-shadow: 0 0 6px rgba(121,180,255,0.35); }
.bro-mercy-row[data-tier="ultra"] .bro-mercy-val { color: #a855f7; }
.bro-mercy-row[data-tier="ultra"] .bro-mercy-bar-fill { background: linear-gradient(90deg, rgba(168,85,247,0.55), #a855f7); box-shadow: 0 0 6px rgba(168,85,247,0.35); }

/* ── Action stack ───────────────────────────────────────────── */
.bro-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 4px;
  padding-bottom: 4px;
}
.bro-btn {
  width: 100%;
  padding: 13px 14px;
  border-radius: 10px;
  border: 1px solid var(--border, rgba(255,255,255,0.10));
  background: var(--bg-card, #1e1e3f);
  color: var(--text-primary, #f2f2f7);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: filter 0.16s ease, transform 0.12s ease;
}
.bro-btn:hover { filter: brightness(1.1); }
.bro-btn:active { transform: scale(0.985); }
.bro-btn--primary {
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
  border: 1px solid rgba(139,92,246,0.65);
  color: #fff;
  font-weight: 700;
  box-shadow: 0 0 14px rgba(139,92,246,0.40), inset 0 1px 0 rgba(255,255,255,0.18);
}
.bro-btn--gold {
  background: linear-gradient(180deg, rgba(245,184,66,0.22), rgba(245,184,66,0.06));
  border: 1px solid rgba(245,184,66,0.65);
  color: var(--gold, #f5b842);
  font-weight: 800;
  box-shadow: 0 0 14px rgba(245,184,66,0.32), inset 0 1px 0 rgba(255,255,255,0.06);
  margin-top: 10px;
}
.bro-btn--ghost {
  background: transparent;
  border: none;
  color: var(--text-secondary, #9090a8);
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: none;
  font-size: 0.85rem;
}
.bro-btn--ghost:hover { color: #fff; filter: none; }
.bro-btn.hidden { display: none !important; }

@media (max-width: 360px) {
  .bro-overlay-title { font-size: 25px; letter-spacing: 0.14em; }
  .bro-boss-name { font-size: 16px; }
  .bro-relic-art-wrap { width: 76px; height: 76px; }
  .bro-relic-name { font-size: 15px; }
}

@media (prefers-reduced-motion: reduce) {
  .bro-overlay, .bro-shell { animation: none !important; }
}

/* ═══════════════════════════════════════════════════════════
   v3 Phase 1z.12 — Direction B "Premium Character Sheet"
   Status card rebuilt; header gains a subtle gold rune underline.
   Source: Claude Design handoff (Dashboard Explorations / dash-dir-b).
   Only the Status card structure changes; top dashboard is unchanged
   except for the rune underline.
   ═══════════════════════════════════════════════════════════ */

/* ── Header gold rune underline ──────────────────────────── */
.aw-header__rune {
  display: flex;
  align-items: center;
  gap: 6px;
  /* Slot inside the existing .header-top { margin-bottom: 16px } — the
     rune sits in that breathing space so total header height is
     unchanged. Pulls up tight against the wordmark, breathes 14px below. */
  margin: -10px 0 14px;
  pointer-events: none;
}
.aw-header__rune-diamond {
  width: 6px;
  height: 6px;
  transform: rotate(45deg);
  background: #f59e0b;
  opacity: 0.80;
  flex: 0 0 auto;
}
.aw-header__rune-line {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(90deg, rgba(245,158,11,0.55), rgba(245,158,11,0));
  opacity: 0.85;
}

/* ── Status card · Direction B Profile shell ─────────────── */
.sc-card.sc-card--profile {
  /* The profile variant deepens the card background gradient + tightens
     the border. Existing .sc-card rule still provides the base shadow. */
  background: linear-gradient(180deg, #15153a 0%, #0c0c24 100%);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  box-shadow:
    0 0 24px rgba(0,0,0,0.35),
    inset 0 1px 0 rgba(255,255,255,0.05);
  overflow: hidden;
}

/* Banner — rune-flanked HUNTER PROFILE kicker */
.sc-card--profile .sc-banner {
  padding: 14px 16px 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: linear-gradient(180deg, rgba(245,184,66,0.05), transparent);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  position: relative;
}
.sc-card--profile .sc-banner__rune {
  width: 28px;
  height: 1px;
  flex: 0 0 auto;
  opacity: 0.6;
}
.sc-card--profile .sc-banner__rune--left {
  background: linear-gradient(90deg, transparent, #f5b842);
}
.sc-card--profile .sc-banner__rune--right {
  background: linear-gradient(90deg, #f5b842, transparent);
}
.sc-card--profile .sc-banner__title {
  font-family: 'Cinzel', serif;
  font-size: 12px;
  font-weight: 700;
  color: #f5b842;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  text-shadow: 0 0 12px rgba(245,184,66,0.32);
  line-height: 1;
}

/* Identity hero row */
.sc-card--profile .sc-hero {
  padding: 14px 16px 10px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  background: transparent;
}
.sc-card--profile .sc-rank-hero {
  /* Stronger inner glow per Direction B spec; the existing per-rank color
     vars still drive the ring color via [data-rank] attribute selectors. */
  width: 54px;
  height: 54px;
  border-radius: 12px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 26px;
  background: radial-gradient(circle at 35% 30%, rgba(167,139,250,0.40) 0%, transparent 65%), #1d1d2e;
  box-shadow:
    0 0 14px rgba(167,139,250,0.55),
    inset 0 0 14px rgba(167,139,250,0.30);
}
/* Re-tint the rank disc by stored rank — uses the existing rank palette */
.sc-card--profile .sc-rank-hero[data-rank="E"]  { color: #a78bfa; border: 1.5px solid #a78bfa; box-shadow: 0 0 14px rgba(167,139,250,0.55), inset 0 0 14px rgba(167,139,250,0.30); }
.sc-card--profile .sc-rank-hero[data-rank="D"]  { color: #8b5cf6; border: 1.5px solid #8b5cf6; box-shadow: 0 0 14px rgba(139, 92,246,0.55), inset 0 0 14px rgba(139, 92,246,0.30); background: radial-gradient(circle at 35% 30%, rgba(139,92,246,0.40) 0%, transparent 65%), #1d1d2e; }
.sc-card--profile .sc-rank-hero[data-rank="C"]  { color: #8b5cf6; border: 1.5px solid #8b5cf6; box-shadow: 0 0 14px rgba(139, 92,246,0.55), inset 0 0 14px rgba(139, 92,246,0.30); background: radial-gradient(circle at 35% 30%, rgba(139,92,246,0.40) 0%, transparent 65%), #1d1d2e; }
.sc-card--profile .sc-rank-hero[data-rank="B"]  { color: #3b82f6; border: 1.5px solid #3b82f6; box-shadow: 0 0 14px rgba( 59,130,246,0.55), inset 0 0 14px rgba( 59,130,246,0.30); background: radial-gradient(circle at 35% 30%, rgba(59,130,246,0.40) 0%, transparent 65%), #1d1d2e; }
.sc-card--profile .sc-rank-hero[data-rank="A"]  { color: #a855f7; border: 1.5px solid #a855f7; box-shadow: 0 0 14px rgba(168, 85,247,0.55), inset 0 0 14px rgba(168, 85,247,0.30); background: radial-gradient(circle at 35% 30%, rgba(168,85,247,0.40) 0%, transparent 65%), #1d1d2e; }
.sc-card--profile .sc-rank-hero[data-rank="S"]  { color: #f97316; border: 1.5px solid #f97316; box-shadow: 0 0 14px rgba(249,115, 22,0.55), inset 0 0 14px rgba(249,115, 22,0.30); background: radial-gradient(circle at 35% 30%, rgba(249,115,22,0.40) 0%, transparent 65%), #1d1d2e; }
.sc-card--profile .sc-rank-hero.splus,
.sc-card--profile .sc-rank-hero[data-rank="S+"] { color: #f59e0b; border: 1.5px solid #f59e0b; box-shadow: 0 0 18px rgba(245,158, 11,0.65), inset 0 0 14px rgba(245,158, 11,0.32); background: radial-gradient(circle at 35% 30%, rgba(245,158,11,0.42) 0%, transparent 65%), #1d1d2e; }

.sc-card--profile .sc-hero-info {
  flex: 1 1 auto;
  min-width: 0;
}
.sc-card--profile .sc-hero-name {
  /* Cinzel 22 per Direction B spec */
  font-family: 'Cinzel', serif;
  font-size: 22px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 0.4px;
  line-height: 1.05;
}

/* Inline identity strip — RANK · PTS · CLASS */
.sc-card--profile .sc-identity-strip {
  margin-top: 6px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.5px;
  line-height: 1.2;
}
.sc-card--profile .sc-identity-rank {
  font-weight: 800;
