}
.sc-card--profile .sc-identity-rank[data-rank="E"]  { color: #a78bfa; }
.sc-card--profile .sc-identity-rank[data-rank="D"],
.sc-card--profile .sc-identity-rank[data-rank="C"]  { color: #8b5cf6; }
.sc-card--profile .sc-identity-rank[data-rank="B"]  { color: #3b82f6; }
.sc-card--profile .sc-identity-rank[data-rank="A"]  { color: #a855f7; }
.sc-card--profile .sc-identity-rank[data-rank="S"]  { color: #f97316; }
.sc-card--profile .sc-identity-rank[data-rank="S+"] { color: #f59e0b; }
.sc-card--profile .sc-identity-sep {
  color: var(--text-tertiary);
  margin: 0 6px;
  font-weight: 600;
}
/* The class segment of the strip carries the existing .sc-hero-class
   class + data-class-key so the delegated class-detail click handler
   still fires. Reset the legacy .sc-hero-class block layout for inline
   use here. */
.sc-card--profile .sc-identity-class.sc-hero-class {
  display: inline-flex;
  align-items: center;
  padding: 2px 6px;
  margin: 0;
  border-radius: 5px;
  background: transparent;
  font-size: 11.5px;
  letter-spacing: 0.5px;
  /* color inherits from inline style="color:cls.color" */
}
.sc-card--profile .sc-identity-class.sc-hero-class:hover  { background: rgba(255,255,255,0.04); }
.sc-card--profile .sc-identity-class.sc-hero-class:active { transform: scale(0.98); }
.sc-card--profile .sc-identity-class .sc-hero-class-name {
  font-weight: 800;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

/* Italic awakening / class flavor line */
.sc-card--profile .sc-awakening-msg {
  margin-top: 8px;
  font-family: Georgia, "Cormorant Garamond", "Times New Roman", serif;
  font-style: italic;
  font-size: 11.5px;
  color: var(--text-secondary);
  line-height: 1.45;
}

/* Awakening Path — full-width gold button */
.sc-card--profile .sc-origin-row {
  padding: 0 16px 14px;
}
/* ── W255 — Arena entry "Banner portal" (ClaudeDesign direction A) ──────────
   72px cinematic strip: painted summit crop (bg_s) → looming foe silhouette
   (right edge) → readability scrim → 7s gold light-sweep idle. One tap target;
   the scrim guarantees the text wins every contrast war. */
.scab { position: relative; display: block; width: 100%; height: 72px; margin: 0; padding: 0;
  border: 1px solid rgba(255,255,255,0.08); border-radius: 14px; overflow: hidden;
  background: #0e0e24; cursor: pointer; -webkit-tap-highlight-color: transparent;
  box-shadow: 0 8px 20px rgba(0,0,0,0.4);
  transition: transform 0.12s ease, box-shadow 0.12s ease, border-color 0.12s ease; }
.scab:active { transform: scale(0.98); border-color: rgba(245,184,66,0.45);
  box-shadow: 0 0 24px rgba(245,184,66,0.22), inset 0 0 30px rgba(245,184,66,0.06); }
.scab-vista { position: absolute; inset: 0; }
.scab-vista img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 64%; filter: saturate(0.9) brightness(0.85); }
.scab-foe { position: absolute; right: -10px; bottom: -6px; width: 86px; height: 86px; pointer-events: none; }
.scab-foe::before { content: ''; position: absolute; inset: -16px; background: radial-gradient(closest-side, rgba(167,139,250,0.18) 0%, transparent 70%); }
.scab-foe img { position: relative; width: 100%; height: 100%; object-fit: contain; object-position: bottom; filter: brightness(0.22) saturate(0.6); opacity: 0.85; }
.scab-scrim { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(7,7,15,0.80) 0%, rgba(7,7,15,0.48) 45%, rgba(7,7,15,0.16) 100%); }
.scab-sweep { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.scab-sweep i { position: absolute; top: 0; bottom: 0; width: 45%; opacity: 0;
  background: linear-gradient(100deg, transparent 0%, rgba(245,184,66,0.08) 50%, transparent 100%); }
@media (prefers-reduced-motion: no-preference) { .scab-sweep i { animation: scabSweep 7s ease-in-out -2.1s infinite; } }
@keyframes scabSweep {
  0%, 100% { transform: translateX(-120%); opacity: 0; }
  40% { opacity: 1; }
  60% { transform: translateX(220%); opacity: 0; }
  61% { transform: translateX(-120%); }
}
.scab-body { position: relative; height: 100%; box-sizing: border-box; display: flex; align-items: center; gap: 13px; padding: 0 16px; }
.scab-roundel { width: 38px; height: 38px; flex: none; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(245,184,66,0.35); background: rgba(245,184,66,0.07); box-shadow: 0 0 8px rgba(245,184,66,0.12); }
.scab:active .scab-roundel { box-shadow: 0 0 12px rgba(245,184,66,0.35); }
.scab-text { display: flex; flex-direction: column; gap: 2px; align-items: flex-start; flex: 1; min-width: 0; }
.scab-title { font-family: "Cinzel", Georgia, serif; font-size: 17px; font-weight: 700; letter-spacing: 0.2em; color: #f5f3fb;
  white-space: nowrap; text-shadow: 0 1px 8px rgba(0,0,0,0.7), 0 0 18px rgba(245,184,66,0.18); }
.scab-whisper { font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 14px; color: #9090a8;
  white-space: nowrap; text-shadow: 0 1px 6px rgba(0,0,0,0.8); }
.scab-chev { flex: none; }
/* Portrait frame — bounded zone, hex backdrop, gold corner brackets */
.sc-card--profile .sc-portrait-frame {
  position: relative;
  overflow: hidden;
  min-height: 220px;
  border-top: 1px solid rgba(255,255,255,0.06);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  background:
    radial-gradient(ellipse at 30% 60%, rgba(167,139,250,0.32) 0%, transparent 50%),
    radial-gradient(ellipse at 100% 100%, rgba(245,184,66,0.08), transparent 60%);
}
.sc-card--profile .sc-portrait-hex {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0.18;
  pointer-events: none;
}
.sc-card--profile .sc-portrait-corner {
  position: absolute;
  width: 18px;
  height: 18px;
  opacity: 0.65;
  pointer-events: none;
}
.sc-card--profile .sc-portrait-corner--tl { top: 8px;    left: 8px;    border-top:    1px solid #f5b842; border-left:   1px solid #f5b842; }
.sc-card--profile .sc-portrait-corner--tr { top: 8px;    right: 8px;   border-top:    1px solid #f5b842; border-right:  1px solid #f5b842; }
.sc-card--profile .sc-portrait-corner--bl { bottom: 8px; left: 8px;    border-bottom: 1px solid #f5b842; border-left:   1px solid #f5b842; }
.sc-card--profile .sc-portrait-corner--br { bottom: 8px; right: 8px;   border-bottom: 1px solid #f5b842; border-right:  1px solid #f5b842; }

/* Reuse existing .sc-portrait-row layout — already side-by-side. Just
   layer it above the hex backdrop and corner brackets. */
.sc-card--profile .sc-portrait-row {
  position: relative;
  z-index: 1;
  padding: 14px 16px;
  gap: 10px;
}
.sc-card--profile .sc-portrait-row .sc-avatar-row { background: none; padding: 0; }
.sc-card--profile .sc-portrait-row .sc-avatar { width: 130px; height: auto; }

/* Sigil tile footer — 4-up grid, TOTAL XP gold-rimmed primary */
.sc-card--profile .sc-metrics.sc-metrics--sigil {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  padding: 12px 12px 14px;
  background: transparent;
  border-top: none;
}
.sc-card--profile .sc-metric.sc-metric--sigil {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 9px 4px 8px;
  background: rgba(255,255,255,0.025);
  border: 1px solid rgba(255,255,255,0.07);
  border-right: 1px solid rgba(255,255,255,0.07);
  border-radius: 8px;
  box-shadow: none;
}
.sc-card--profile .sc-metric.sc-metric--sigil:last-child { border-right: 1px solid rgba(255,255,255,0.07); }
.sc-card--profile .sc-metric--sigil .sc-metric-val {
  font-size: 18px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--text-primary);
