}
.sc-card--profile .sc-metric--sigil .sc-metric-lbl {
  margin-top: 6px;
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--text-tertiary);
  text-transform: uppercase;
}
/* Primary tile — TOTAL XP, gold rim + glow */
.sc-card--profile .sc-metric--primary {
  background: linear-gradient(180deg, rgba(245,184,66,0.10), rgba(245,184,66,0.02));
  border: 1px solid rgba(245,184,66,0.35);
