/* Mobile — iPhone SE / sub-360px viewports */
@media (max-width: 360px) {
  .sc-card--profile .sc-portrait-row .sc-avatar { width: 110px; }
  .sc-card--profile .sc-metric--sigil .sc-metric-val { font-size: 16px; }
}
@media (max-width: 339px) {
