/* ═══════════════════════════════════════════════════════════
   v3 Phase 1z.74 — Sigil Bloom Relic Reveal
   ClaudeDesign-spec rare/ultra reveal animation. Replaces the
   loot-box concept with a magic-sigil bloom: motes gather → rune
   ignites → silhouette resolves → relic card slides in. Same
   anatomy for both rarities, intensity scales via .is-ultra.
   Common drops bypass this entirely.
   ═══════════════════════════════════════════════════════════ */

/* Stage — sits behind the reveal-card, hosts rune + motes + flash. */
.sigil-bloom-stage {
  position: absolute;
  inset: 0;
  pointer-events: none; /* taps fall through to overlay / card */
  z-index: 1;           /* below .reveal-card (z-index:2) */
  overflow: hidden;
  opacity: 0;
}
.reveal-overlay--sigil .sigil-bloom-stage { opacity: 1; }

/* When sigil bloom is active, suppress the existing materialize +
   pulse on .reveal-card. The card stays hidden through every bloom
   phase and only slides in when the user taps to continue — gated
   by the .is-card-revealed class added by the tap handler. */
.reveal-overlay--sigil .reveal-card {
  opacity: 0 !important;
  transform: translateY(12px) !important;
  animation: none !important;
  transition: opacity 500ms ease, transform 500ms ease,
              box-shadow 0.4s ease;
}
.reveal-overlay--sigil.is-card-revealed .reveal-card {
  opacity: 1 !important;
  transform: translateY(0) !important;
}
/* Tap-to-continue prompt during bloom should pulse softly. When the
   card is revealed, the prompt copy stays ("TAP TO CONTINUE" still
   means "tap to dismiss") but visually de-emphasises slightly. */
.reveal-overlay--sigil .reveal-continue-hint { opacity: 0.7; }
.reveal-overlay--sigil.is-bloom-ready:not(.is-card-revealed) .reveal-continue-hint {
  opacity: 1;
  animation: sb-continue-pulse 1.4s ease-in-out infinite;
}
@keyframes sb-continue-pulse {
  0%, 100% { opacity: 0.55; }
  50%      { opacity: 1; }
}
/* Once the card is revealed, fade out the rune/wordmark/silhouette
   so the relic is the only focal point. The relic-card slide-in
   replaces them in the same area. */
.reveal-overlay--sigil.is-card-revealed .sb-rune,
.reveal-overlay--sigil.is-card-revealed .sb-wordmark,
.reveal-overlay--sigil.is-card-revealed .sb-silhouette,
.reveal-overlay--sigil.is-card-revealed .sb-vignette {
  opacity: 0 !important;
  transition: opacity 350ms ease;
}

/* Hide the system lines + drifting particles during sigil bloom —
   the bloom owns the visual hierarchy. */
.reveal-overlay--sigil .reveal-systemline,
.reveal-overlay--sigil .reveal-particles { display: none; }

/* ── Rune circle ───────────────────────────────────────────── */
.sb-rune {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 280px;
  height: 280px;
  transform: translate(-50%, -50%) scale(0.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 500ms ease,
              transform 600ms cubic-bezier(.22, .61, .36, 1);
}
.reveal-overlay--sigil.is-phase-1 .sb-rune,
.reveal-overlay--sigil.is-phase-2 .sb-rune {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}
.reveal-overlay--sigil.is-phase-3 .sb-rune,
.reveal-overlay--sigil.is-phase-4 .sb-rune {
  opacity: 0;
  transform: translate(-50%, -50%) scale(1);
}
/* Inner dashed ring spins continuously after ignite. */
.sb-rune__inner {
  transform-origin: 140px 140px;
}
.reveal-overlay--sigil.is-phase-2 .sb-rune__inner,
.reveal-overlay--sigil.is-phase-3 .sb-rune__inner,
.reveal-overlay--sigil.is-phase-4 .sb-rune__inner {
  animation: sb-rune-spin 8s linear infinite;
}
@keyframes sb-rune-spin {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ── Vignette (ultra only) ─────────────────────────────────── */
.sb-vignette {
  position: absolute;
  inset: -20px;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 50%, transparent 30%, rgba(0, 0, 0, 0.5) 80%);
  opacity: 0;
  display: none;
}
.reveal-overlay--sigil.is-ultra .sb-vignette { display: block; }
.reveal-overlay--sigil.is-ultra.is-phase-1 .sb-vignette,
.reveal-overlay--sigil.is-ultra.is-phase-2 .sb-vignette,
.reveal-overlay--sigil.is-ultra.is-phase-3 .sb-vignette {
  animation: sb-vignette-in 1400ms ease-out forwards;
}
@keyframes sb-vignette-in {
  0%   { opacity: 0; }
  40%  { opacity: 1; }
  100% { opacity: 0.55; }
}

/* ── Motes (gather + burst) ────────────────────────────────── */
.sb-motes {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.sb-mote {
  position: absolute;
  top: 50%;
  left: 50%;
  border-radius: 50%;
  opacity: 0;
  will-change: transform, opacity;
}
.reveal-overlay--sigil.is-phase-1 .sb-mote--gather {
  animation: sb-gather var(--sb-gather-dur, 600ms)
             cubic-bezier(.42, 0, .2, 1) var(--sb-delay, 0ms) forwards;
}
@keyframes sb-gather {
  0%   { opacity: 0; transform: translate(-50%, -50%) translate(var(--sx, 0), var(--sy, 0)) scale(0.8); }
  25%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) translate(0, 0) scale(0.3); }
}
.reveal-overlay--sigil.is-phase-3 .sb-mote--burst,
.reveal-overlay--sigil.is-phase-4 .sb-mote--burst {
  animation: sb-burst var(--sb-burst-dur, 1300ms)
             cubic-bezier(.22, .61, .36, 1) var(--sb-delay, 0ms) forwards;
}
@keyframes sb-burst {
  0%   { opacity: 0; transform: translate(-50%, -50%) translate(0, 0) scale(0.4); }
  20%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) translate(var(--dx, 0), var(--dy, 0)) scale(1); }
}

/* ── Bloom flash (radial) ──────────────────────────────────── */
.sb-flash {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 220px;
  height: 220px;
  transform: translate(-50%, -50%) scale(0.4);
  border-radius: 50%;
  opacity: 0;
  background: radial-gradient(circle, rgba(230, 216, 255, 0.85), rgba(167, 139, 250, 0.45) 32%, transparent 65%);
  pointer-events: none;
}
.reveal-overlay--sigil.is-ultra .sb-flash {
  background: radial-gradient(circle, rgba(255, 250, 220, 0.95), rgba(245, 184, 66, 0.55) 30%, transparent 60%);
}
.reveal-overlay--sigil.is-phase-2 .sb-flash {
  animation: sb-bloom-flash 700ms ease-out forwards;
}
@keyframes sb-bloom-flash {
  0%   { opacity: 0; transform: translate(-50%, -50%) scale(0.4); }
  25%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.2); }
}

/* ── Ray fan (ultra only) ──────────────────────────────────── */
.sb-rays {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 320px;
  height: 320px;
  transform: translate(-50%, -50%) scale(0.5) rotate(-20deg);
  opacity: 0;
  pointer-events: none;
  display: none;
}
.reveal-overlay--sigil.is-ultra .sb-rays { display: block; }
.reveal-overlay--sigil.is-ultra.is-phase-2 .sb-rays {
  animation: sb-rays-fan 900ms ease-out forwards;
}
@keyframes sb-rays-fan {
  0%   { opacity: 0; transform: translate(-50%, -50%) scale(0.5) rotate(-20deg); }
  30%  { opacity: 0.9; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.3) rotate(20deg); }
}

/* ── Silhouette (sword for rare, crown for ultra) ──────────── */
.sb-silhouette {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  filter: blur(8px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 400ms ease, filter 400ms ease;
}
.reveal-overlay--sigil.is-phase-1 .sb-silhouette { opacity: 0.4; }
.reveal-overlay--sigil.is-phase-2 .sb-silhouette,
.reveal-overlay--sigil.is-phase-3 .sb-silhouette,
.reveal-overlay--sigil.is-phase-4 .sb-silhouette {
  opacity: 1;
  filter: blur(0);
}
/* v3 Phase 1z.76 — silhouette stays visible after settle so the
   "TAP TO CONTINUE" wait state has a focal subject. It only fades
   when the user taps and .is-card-revealed is added (handled below). */

/* ── Wordmark (rarity title + whisper) ─────────────────────── */
.sb-wordmark {
  position: absolute;
  left: 0;
  right: 0;
  top: 6%;
  text-align: center;
  pointer-events: none;
  opacity: 0;
}
.sb-wordmark-kicker {
  font-family: 'JetBrains Mono', 'SF Mono', ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 800;
  color: rgba(245, 245, 250, 0.6);
  letter-spacing: 0.24em;
  margin-bottom: 4px;
}
.sb-wordmark-title {
  font-family: 'Cinzel', 'Trajan Pro', Georgia, serif;
  font-size: 22px;
  font-weight: 700;
  color: #a78bfa;
  letter-spacing: 0.18em;
  line-height: 1;
  text-shadow: 0 0 16px rgba(167, 139, 250, 0.55);
}
.reveal-overlay--sigil.is-ultra .sb-wordmark-title {
  color: #f5b842;
  text-shadow: 0 0 18px rgba(245, 184, 66, 0.45);
}
.sb-wordmark-whisper {
  margin-top: 4px;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-style: italic;
  font-size: 11px;
  color: rgba(245, 245, 250, 0.55);
  letter-spacing: 0.4px;
}
.reveal-overlay--sigil.is-phase-2 .sb-wordmark,
.reveal-overlay--sigil.is-phase-3 .sb-wordmark,
.reveal-overlay--sigil.is-phase-4 .sb-wordmark {
  animation: sb-wordmark-in 600ms ease-out 100ms forwards;
}
@keyframes sb-wordmark-in {
  0%   { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* ── Reduced motion — skip the bloom; show static rarity title
   above the relic card. Audio still fires (audio is not motion). ── */
@media (prefers-reduced-motion: reduce) {
  .reveal-overlay--sigil .sb-rune,
  .reveal-overlay--sigil .sb-motes,
  .reveal-overlay--sigil .sb-flash,
  .reveal-overlay--sigil .sb-rays,
  .reveal-overlay--sigil .sb-silhouette,
  .reveal-overlay--sigil .sb-vignette {
    display: none !important;
  }
  .reveal-overlay--sigil .sb-wordmark {
    opacity: 1;
    animation: none !important;
  }
  .reveal-overlay--sigil .reveal-card {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
}

/* v3 Phase 1z.75 — for the reduced-motion path the bloom is hidden
   and the card shows immediately, so flag the overlay as already
   "card revealed" via JS on open. The CSS above gates the card on
   .is-card-revealed; without the class the card would stay hidden
   in reduced-motion. _runSigilBloom adds the class up-front when
   reduced-motion is detected (see app.js). */

/* ═══════════════════════════════════════════════════════════
   v3 Phase 1z.83 — Sealed Mystery Relic (ClaudeDesign).
   Boss Defeated reward panel for rare / ultra FIRST acquisitions.
   The relic identity is hidden until the user taps "Reveal Relic"
   which chains to the Sigil Bloom cinematic (1z.74). Commons and
   duplicate rare/ultra drops use the legacy #bro-relic-card path.
   ═══════════════════════════════════════════════════════════ */
.bro-reward--sealed {
  position: relative;
  padding: 1.5px;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(167,139,250,0.55), rgba(245,184,66,0.30), rgba(167,139,250,0.45));
  box-shadow: 0 0 24px rgba(167,139,250,0.30), 0 8px 24px rgba(0,0,0,0.4);
  overflow: visible;
}
.bro-reward--sealed::after {
  /* Inner navy card surface */
  content: '';
  position: absolute;
  inset: 1.5px;
  border-radius: 12.5px;
  background: #14143a;
  z-index: 0;
}
.bro-sealed-kicker {
  position: relative;
  z-index: 2;
  padding: 14px 14px 0;
  font-family: 'JetBrains Mono', 'SF Mono', ui-monospace, monospace;
  font-size: 10px;
  font-weight: 800;
  color: #f5b842;
  letter-spacing: 0.24em;
  text-align: center;
  text-shadow: 0 0 8px rgba(245,184,66,0.18);
}
.bro-sealed-aura {
  position: absolute;
  inset: -20px;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(circle at 28% 42%, rgba(167,139,250,0.32) 0%, transparent 50%),
    radial-gradient(circle at 80% 70%, rgba(245,184,66,0.18) 0%, transparent 50%);
}
.bro-sealed-motes {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  overflow: hidden;
  border-radius: 12.5px;
}
.bro-sealed-mote {
  position: absolute;
  width: 2px;
  height: 2px;
  border-radius: 50%;
  opacity: 0;
  animation: bro-sealed-motes-drift 4s ease-in-out infinite;
}
.bro-sealed-mote--v1 { left: 12%; top: 78%; background: #a78bfa; box-shadow: 0 0 5px #a78bfa; animation-delay: 0s; }
.bro-sealed-mote--g1 { left: 38%; top: 88%; background: #f5b842; box-shadow: 0 0 5px #f5b842; animation-delay: 0.6s; }
.bro-sealed-mote--v2 { left: 64%; top: 72%; background: #a78bfa; box-shadow: 0 0 5px #a78bfa; animation-delay: 1.2s; width: 1.6px; height: 1.6px; }
.bro-sealed-mote--g2 { left: 82%; top: 60%; background: #f5b842; box-shadow: 0 0 5px #f5b842; animation-delay: 1.8s; }
.bro-sealed-mote--v3 { left: 22%; top: 56%; background: #a78bfa; box-shadow: 0 0 5px #a78bfa; animation-delay: 2.4s; width: 1.4px; height: 1.4px; }
.bro-sealed-mote--g3 { left: 70%; top: 50%; background: #f5b842; box-shadow: 0 0 5px #f5b842; animation-delay: 3.0s; }
@keyframes bro-sealed-motes-drift {
  0%   { opacity: 0; transform: translateY(0); }
  25%  { opacity: 0.7; }
  75%  { opacity: 0.5; }
  100% { opacity: 0; transform: translateY(-60px); }
}
.bro-sealed-row {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 14px 16px;
}
.bro-sealed-sigil {
  flex: 0 0 auto;
  width: 88px;
  height: 88px;
  position: relative;
}
.bro-sealed-sigil-frame {
  position: absolute;
  inset: 0;
  border-radius: 14px;
  padding: 1.5px;
  background: linear-gradient(135deg, #f5b842, #a78bfa);
  box-shadow: 0 0 16px rgba(167,139,250,0.45), inset 0 1px 0 rgba(255,255,255,0.18);
}
.bro-sealed-sigil-well {
  width: 100%;
  height: 100%;
  border-radius: 13px;
  background:
    radial-gradient(circle at 50% 38%, rgba(167,139,250,0.22) 0%, transparent 60%),
    radial-gradient(circle at 50% 50%, #1a1640 0%, #08081a 75%);
  box-shadow: inset 0 0 12px rgba(0,0,0,0.65);
  position: relative;
  overflow: hidden;
}
.bro-sealed-sigil-aura {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at 50% 50%, rgba(245,184,66,0.18) 0%, transparent 60%);
  animation: bro-sealed-pulse 2.8s ease-in-out infinite;
}
.bro-sealed-sigil-well > svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
@keyframes bro-sealed-pulse {
  0%, 100% { opacity: 0.6; }
  50%      { opacity: 1.0; }
}
.bro-sealed-text {
  flex: 1;
  min-width: 0;
}
.bro-sealed-title {
  font-family: 'Cinzel', 'Trajan Pro', Georgia, serif;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.06em;
  line-height: 1.1;
}
.bro-sealed-title--1 { color: #f5f5fa; }
.bro-sealed-title--2 {
  margin-top: 3px;
  color: #f5b842;
  text-shadow: 0 0 12px rgba(245,184,66,0.18);
}
.bro-sealed-whisper {
  margin-top: 8px;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-style: italic;
  font-size: 12px;
  color: #9090a8;
  line-height: 1.4;
}

/* "Reveal Relic" CTA — violet glow + seal glyph icon. The button
   already uses .bro-btn--primary; the .is-armed modifier amplifies
   the violet glow + adds a pulsing aura so the sealed state's
   primary action reads as "the magic is here, tap me." */
.bro-btn--primary.is-armed {
  background: linear-gradient(180deg, rgba(167,139,250,0.32), rgba(167,139,250,0.12));
  border-color: rgba(167,139,250,0.85);
  color: #f5f5fa;
  box-shadow:
    0 0 16px rgba(167,139,250,0.55),
    inset 0 1px 0 rgba(255,255,255,0.12);
  animation: bro-armed-pulse 2.4s ease-in-out infinite;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.bro-btn--primary.is-armed:hover {
  box-shadow: 0 0 22px rgba(167,139,250,0.75), inset 0 1px 0 rgba(255,255,255,0.18);
}
.bro-btn-seal-glyph {
  display: inline-block;
  width: 13px;
  height: 13px;
}
.bro-btn-seal-glyph svg { display: block; width: 100%; height: 100%; }
@keyframes bro-armed-pulse {
  0%, 100% { box-shadow: 0 0 12px rgba(167,139,250,0.40), inset 0 1px 0 rgba(255,255,255,0.10); }
  50%      { box-shadow: 0 0 22px rgba(167,139,250,0.70), inset 0 1px 0 rgba(255,255,255,0.18); }
}

/* Reduced motion — skip the pulse / drift animations. The sealed
   sigil stays visually intact; only motion is suppressed. */
@media (prefers-reduced-motion: reduce) {
  .bro-sealed-sigil-aura,
  .bro-sealed-mote,
  .bro-btn--primary.is-armed {
    animation: none !important;
  }
}

/* ─── Global Rankings Hub (v3 Phase 1z.130) ─────────────────────────
   Bottom-sheet chooser opened from the header World Rank card. Houses
   the four ranking entry points (steps / sleep / workout / flights).
   Uses the shared `.vn-sheet` + `.vn-overlay` shell so drag and
   stacking behavior match every other sheet in the app. Per-metric
   leaderboard sheet (#lb-rank-sheet) is unchanged — the hub just
   hands off via openLeaderboardRanking(metric).
   ─────────────────────────────────────────────────────────────── */
.lb-hub-header {
  position: relative;
  padding: 4px 18px 0;
  flex-shrink: 0;
}
.lb-hub-eyebrow {
  font-family: 'JetBrains Mono', 'SF Mono', ui-monospace, monospace;
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: #a78bfa;
  margin-bottom: 6px;
}
.lb-hub-title {
  margin: 0;
  font-family: 'Cinzel', 'Cormorant Garamond', Georgia, serif;
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--text-primary, #f5b842);
  text-shadow: 0 0 14px rgba(245, 184, 66, 0.35);
  line-height: 1.05;
  padding-right: 44px;
}
.lb-hub-sub {
  margin: 8px 0 0;
  padding-right: 8px;
  font-size: 0.78rem;
  line-height: 1.45;
  color: var(--text-secondary, rgba(255, 255, 255, 0.68));
}
#lb-hub-close {
  position: absolute;
  top: 0;
  right: 18px;
}

.lb-hub-body {
  padding: 14px 18px 6px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
}

.lb-hub-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.lb-hub-row {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  color: inherit;
  text-align: left;
  font-family: inherit;
  cursor: pointer;
  transition: border-color 80ms ease, background 80ms ease, transform 80ms ease;
}
.lb-hub-row:active {
  border-color: rgba(167, 139, 250, 1);
  background: rgba(167, 139, 250, 0.18);
  transform: scale(0.995);
}

.lb-hub-row-icon {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: radial-gradient(circle at 50% 30%, rgba(167, 139, 250, 0.25), #050513 75%);
  border: 1px solid rgba(167, 139, 250, 0.75);
  box-shadow: 0 0 10px rgba(167, 139, 250, 0.30);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.lb-hub-row-icon img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  filter: drop-shadow(0 0 4px rgba(245, 184, 66, 0.35));
}
.lb-hub-row-icon svg {
  width: 22px;
  height: 22px;
}

.lb-hub-row-body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.lb-hub-row-headline {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
}
.lb-hub-row-value {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary, #fff);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.lb-hub-row-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-secondary, rgba(255, 255, 255, 0.68));
}
.lb-hub-row-sub {
  font-size: 0.7rem;
  color: rgba(255, 255, 255, 0.45);
}
.lb-hub-row-sub b {
  color: #f5b842;
  font-weight: 800;
}
.lb-hub-row-chev {
  flex: 0 0 auto;
  color: rgba(255, 255, 255, 0.35);
  font-size: 1.1rem;
  line-height: 1;
  padding-left: 4px;
}

.lb-hub-footer {
  margin-top: 14px;
  padding: 10px 0 2px;
  text-align: center;
  font-size: 0.68rem;
  font-style: italic;
  color: rgba(255, 255, 255, 0.4);
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

/* World Rank card affordance — violet glow + chevron in header row.
   The chevron already exists in markup (.steps-card__chev). We just
   tighten the border treatment so the card reads "tap me" against
   its plainer sibling cards. */
#steps-card.steps-card {
  border-color: rgba(167, 139, 250, 0.45);
  box-shadow: 0 0 14px rgba(167, 139, 250, 0.30), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition: border-color 80ms ease, background 80ms ease, box-shadow 80ms ease;
}
#steps-card.steps-card:active {
  border-color: rgba(167, 139, 250, 1);
  background: rgba(167, 139, 250, 0.18);
}

/* ─────────────────────────────────────────────────────────────
   v3 Phase 1z.164 — Social Hub / Guild Hall (Variation A from
   ClaudeDesign Social Hub Guild Hall.html). The body.social-hub-on
   master switch keeps the Variation A styling on; the legacy
   duels-public-hidden / duels-challenge-hidden body classes were
   removed in 1z.279 along with the Duels subsystem. Color tokens
   come from the existing app palette (--gold, --accent / violet,
   --bg-card, --border, --text-*).
   ───────────────────────────────────────────────────────────── */

/* v3 Phase 1z.173 — Guild Hall Command Panel (Variation B from
   ClaudeDesign Social Tab Polish). Wraps the page header, friend
   avatar stack, and three summary tiles into a single gold→violet
   gradient-rimmed hero so the title area reads as one Guild Hall
   surface. Inner navy with a radial gold glow at top edge to
   reinforce the "command" feel. */
.guildhall-command-panel {
  margin: 8px 14px 18px;
  padding: 1px; /* makes room for the gradient rim below */
  background: linear-gradient(135deg,
    rgba(167,139,250,0.55) 0%,
    rgba(245,184,66,0.65) 50%,
    rgba(167,139,250,0.55) 100%);
  border-radius: 16px;
  box-shadow: 0 0 18px rgba(167,139,250,0.20);
}
/* v3 Phase 1z.173 — Per-tile accent colors per ClaudeDesign spec.
   Each tile gets a 2px gradient line on its top edge in the tile's
   color, and the Cinzel value picks up the same color with a soft
   matching glow. Empty values (.is-empty added by renderer when
   the count is 0) render as text-tertiary "—" — never a fully
   colored 0, which would make a fresh install look broken. */
.guildhall-summary-tile {
  position: relative;
  overflow: hidden;
}
/* Empty-state muting — overrides all three color rules above. */
.guildhall-summary-tile-value.is-empty {
  color: var(--text-tertiary, #6b7280) !important;
  text-shadow: none !important;
}

/* v3 Phase 1z.167 — Guild Hall summary card.
   Three local tiles + up to 3 accepted-friend initial chips on the
   right. Sits between the page header and the activity feed.
   No fake online/LIVE state — Phase 1 displays only local-truth data
   (friends count from the in-memory cache, feat counts from the
   dedicated hb_guild_activity store). */
.guildhall-summary {
  margin: 8px 14px 12px;
  padding: 12px 14px;
  background: linear-gradient(180deg, rgba(167,139,250,0.08), rgba(16,18,38,0.6));
  border: 1px solid rgba(167,139,250,0.30);
  border-radius: 14px;
  box-shadow: 0 0 16px rgba(167,139,250,0.10), inset 0 1px 0 rgba(255,255,255,0.04);
  display: flex;
  align-items: center;
  gap: 12px;
}
.guildhall-summary-tile {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 6px 10px;
  background: rgba(16,18,38,0.55);
  border: 1px solid rgba(167,139,250,0.18);
  border-radius: 10px;
  min-width: 0;
}
.guildhall-summary-tile-value {
  font-family: 'Cinzel', serif;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--gold, #f5b842);
  text-shadow: 0 0 6px rgba(245,184,66,0.30);
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}
.guildhall-summary-chips {
  display: flex;
  flex-direction: row;
  gap: -4px;
  flex: 0 0 auto;
  margin-left: auto;
}
.guildhall-summary-chip {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: linear-gradient(180deg, rgba(167,139,250,0.30), rgba(16,18,38,0.8));
  border: 1.5px solid rgba(167,139,250,0.55);
  color: var(--gold, #f5b842);
  font-family: 'Cinzel', serif;
  font-size: 0.78rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: -8px;
  box-shadow: 0 0 6px rgba(167,139,250,0.30);
}
.guildhall-summary-chip:first-child { margin-left: 0; }
.guildhall-summary-chip--empty {
  background: rgba(167,139,250,0.06);
  border-color: rgba(167,139,250,0.16);
  box-shadow: none;
}

/* v3 Phase 1z.171 — clickable summary tiles. Buttons inherit the
   .guildhall-summary-tile look but get pointer + pressed feedback. */
button.guildhall-summary-tile {
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  color: inherit;
  font: inherit;
  text-align: left;
  transition: filter 80ms ease, background 80ms ease, border-color 80ms ease;
}
button.guildhall-summary-tile:hover  { filter: brightness(1.06); }
button.guildhall-summary-tile:active {
  background: rgba(167,139,250,0.16);
  border-color: rgba(167,139,250,0.45);
  transform: scale(0.99);
}

/* v3 Phase 1z.171 — Guild Members roster sheet body. */
.guild-roster-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 10px;
}
.guild-roster-row {
  display: grid;
  /* v3 Phase 1z.265 — 24H column removed. Was: 32px 36px 1fr 56px 64px.
     The dropped 56px slot freed up width for the name column. */
  grid-template-columns: 32px 36px minmax(0, 1fr) 72px;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: rgba(16,18,38,0.55);
  border: 1px solid rgba(167,139,250,0.18);
  border-radius: 10px;
}
.guild-roster-row--head {
  background: transparent;
  border: 0;
  padding: 4px 12px 2px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.55rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--text-secondary, #8b8fab);
}
.guild-roster-row--self {
  background: linear-gradient(180deg, rgba(245,184,66,0.08), rgba(16,18,38,0.55));
  border-color: rgba(245,184,66,0.40);
  box-shadow: 0 0 8px rgba(245,184,66,0.10);
}
.guild-roster-rank {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--text-secondary, #8b8fab);
  font-variant-numeric: tabular-nums;
}
.guild-roster-row--self .guild-roster-rank {
  color: var(--gold, #f5b842);
}
.guild-roster-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: linear-gradient(180deg, rgba(167,139,250,0.30), rgba(16,18,38,0.8));
  border: 1.5px solid rgba(167,139,250,0.55);
  color: var(--gold, #f5b842);
  font-family: 'Cinzel', serif;
  font-size: 0.80rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.guild-roster-avatar--self {
  border-color: var(--gold, #f5b842);
  box-shadow: 0 0 8px rgba(245,184,66,0.30);
}
.guild-roster-avatar--head {
  background: transparent;
  border: 0;
  box-shadow: none;
}
/* v3 Phase 1z.193 — tight rank-label variant for the Roster
   sheet's 30px circles. Mirrors the lower Guild accordion's
   .friend-avatar--rank treatment so "E III" / "D II" / "S+"
   fit without overflow. Real backend labels stay intact; the
   helper trims to 5 chars defensively before this style applies. */
.guild-roster-avatar--rank {
  font-size: 0.54rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1;
  padding: 0 2px;
  color: var(--gold, #f5b842);
}
/* v3 Phase 1z.193 — Roster rows no longer carry the "Guild member"
   subtitle. Center the alias vertically inside the row so the
   single-line layout reads balanced against the avatar + stats. */
.guild-roster-row--no-sub .guild-roster-name {
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.guild-roster-name {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.guild-roster-alias {
  font-family: 'Cinzel', serif;
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--text-primary, #f3f4f6);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.guild-roster-row--self .guild-roster-alias {
  color: var(--gold, #f5b842);
}
.guild-roster-stat {
  text-align: right;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--text-primary, #f3f4f6);
  font-variant-numeric: tabular-nums;
}
.guild-roster-row--self .guild-roster-stat {
  color: var(--gold, #f5b842);
}
.guild-roster-empty {
  margin-top: 12px;
  padding: 12px 14px;
  text-align: center;
  font-size: 0.78rem;
  font-style: italic;
  color: var(--text-secondary, #8b8fab);
  background: rgba(167,139,250,0.04);
  border: 1px dashed rgba(167,139,250,0.20);
  border-radius: 10px;
}
.guild-roster-empty.hidden { display: none !important; }

/* v3 Phase 1z.172 — Feats · Last 24h sheet body. Reuses the
   .guildhall-activity-* row styles from the main feed so the
   sheet visually matches Recent Feats. No new row CSS needed —
   the renderer calls _guildhallRowHtml directly. */
.guild-feats-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 10px;
}

/* v3 Phase 1z.172 — Bosses Slain sheet rows. */
/* v3 Phase 1z.187 — Kill Log Codex Ledger redesign.
   Implements Variation A from Claude Design's "Kill Log.html"
   bundle: ledger summary strip · single navy codex panel · shield
   crests · dominant Cinzel boss names with mono rank sublines ·
   gold kill capsules with crossed-swords glyph. Per-rank palette
   lives entirely on the row via --rank-color custom property. */

/* Italic-Cormorant blurb under the title. */
.guild-bosses-blurb {
  margin-top: 6px;
  margin-bottom: 0;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-style: italic;
  font-size: 0.78rem;
  color: var(--text-tertiary, #6b7280);
  letter-spacing: 0.01em;
}

/* TOTAL KILLS · BOSSES · TOP RANK ledger strip. */
.guild-bosses-ledger {
  display: flex;
  align-items: center;
  gap: 0;
  margin-top: 12px;
  padding: 10px 14px;
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(245,184,66,0.08), rgba(245,184,66,0.02));
  border: 1px solid rgba(245,184,66,0.32);
}
.guild-bosses-ledger[hidden] { display: none; }
.guild-bosses-ledger-stat {
  flex: 1;
  text-align: center;
}
.guild-bosses-ledger-val {
  font-family: 'Cinzel', serif;
  font-size: 1.20rem;
  font-weight: 700;
  line-height: 1;
  color: var(--gold, #f5b842);
  text-shadow: 0 0 8px rgba(245,184,66,0.30);
  font-variant-numeric: tabular-nums;
}
.guild-bosses-ledger-val--rank[data-rank="E"] { color: #a78bfa; text-shadow: 0 0 8px rgba(167,139,250,0.50); }
.guild-bosses-ledger-val--rank[data-rank="D"] { color: #f5b842; text-shadow: 0 0 8px rgba(245,184,66,0.50); }
.guild-bosses-ledger-val--rank[data-rank="C"] { color: #f97316; text-shadow: 0 0 8px rgba(249,115,22,0.50); }
.guild-bosses-ledger-val--rank[data-rank="B"] { color: #3b82f6; text-shadow: 0 0 8px rgba(59,130,246,0.50); }
.guild-bosses-ledger-val--rank[data-rank="A"] { color: #ec4899; text-shadow: 0 0 8px rgba(236,72,153,0.50); }
.guild-bosses-ledger-val--rank[data-rank="S"] { color: #ef4444; text-shadow: 0 0 8px rgba(239,68,68,0.55); }
.guild-bosses-ledger-lbl {
  margin-top: 4px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.50rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--text-tertiary, #6b7280);
  text-transform: uppercase;
}
.guild-bosses-ledger-sep {
  width: 1px;
  height: 26px;
  background: rgba(255,255,255,0.10);
}

/* v3 Phase 1z.188 — Variation C (Monster Archive) layout.
   The single codex panel is neutralized; each rank group renders
   its own left-accent panel inside the list. */
.guild-bosses-codex {
  margin-top: 12px;
  background: transparent;
  border: 0;
  box-shadow: none;
  overflow: visible;
}
.guild-bosses-codex[hidden] { display: none; }
.guild-bosses-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

/* Per-rank group (header + left-accent panel). The rank palette
   custom properties live on the group so both the header crest
   and the panel border use the same color without duplication. */
.guild-bosses-group {
  --rank-color: #f5b842;
  --rank-glow:  rgba(245,184,66,0.50);
  --rank-soft:  rgba(245,184,66,0.14);
  --rank-rule:  rgba(245,184,66,0.45);
}
.guild-bosses-group--rank-e { --rank-color: #a78bfa; --rank-glow: rgba(167,139,250,0.50); --rank-soft: rgba(167,139,250,0.16); --rank-rule: rgba(167,139,250,0.45); }
.guild-bosses-group--rank-d { --rank-color: #f5b842; --rank-glow: rgba(245,184,66,0.50); --rank-soft: rgba(245,184,66,0.14); --rank-rule: rgba(245,184,66,0.45); }
.guild-bosses-group--rank-c { --rank-color: #f97316; --rank-glow: rgba(249,115,22,0.50); --rank-soft: rgba(249,115,22,0.14); --rank-rule: rgba(249,115,22,0.45); }
.guild-bosses-group--rank-b { --rank-color: #3b82f6; --rank-glow: rgba(59,130,246,0.50); --rank-soft: rgba(59,130,246,0.14); --rank-rule: rgba(59,130,246,0.45); }
.guild-bosses-group--rank-a { --rank-color: #ec4899; --rank-glow: rgba(236,72,153,0.50); --rank-soft: rgba(236,72,153,0.14); --rank-rule: rgba(236,72,153,0.45); }
.guild-bosses-group--rank-s { --rank-color: #ef4444; --rank-glow: rgba(239,68,68,0.55); --rank-soft: rgba(239,68,68,0.16); --rank-rule: rgba(239,68,68,0.50); }

.guild-bosses-group-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}
.guild-bosses-group-crest {
  position: relative;
  width: 22px;
  height: 22px;
  display: inline-block;
  flex: 0 0 auto;
  filter: drop-shadow(0 0 4px var(--rank-glow));
}
.guild-bosses-group-crest svg { display: block; }
.guild-bosses-group-crest-letter {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Cinzel', serif;
  font-weight: 700;
  font-size: 0.58rem;
  color: var(--rank-color);
  text-shadow: 0 0 4px var(--rank-glow);
  line-height: 1;
  pointer-events: none;
}
.guild-bosses-group-label {
  font-family: 'Cinzel', serif;
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--rank-color);
}
.guild-bosses-group-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, var(--rank-rule), transparent);
}
.guild-bosses-group-total {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.56rem;
  font-weight: 800;
  letter-spacing: 0.10em;
  color: var(--text-tertiary, #6b7280);
  text-transform: uppercase;
}
.guild-bosses-group-panel {
  background: #14143a;
  border: 1px solid var(--rank-rule);
  border-left-width: 2px;
  border-radius: 10px;
  overflow: hidden;
}

/* Compact archive row inside each group — small rank-color dot +
   Cinzel name + gold kill capsule. Overrides the shield-row
   layout from 1z.187 (the shield helper is preserved but unused
   in this layout). */
.guild-bosses-row--archive {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.guild-bosses-row--archive:last-child { border-bottom: 0; }
.guild-bosses-row-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--rank-color);
  box-shadow: 0 0 5px var(--rank-glow);
  /* The dot inherits the row's rank-color via the parent group's
     custom properties — no per-row modifier class needed. */
}
.guild-bosses-row--archive .guild-bosses-title {
  font-family: 'Cinzel', serif;
  font-weight: 600;
  font-size: 0.88rem;
  letter-spacing: 0.02em;
  color: var(--text-primary, #f3f4f6);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.guild-bosses-row {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  /* Per-rank color is set by the modifier classes below. Defaults
     to the gold accent so unranked legacy rows still render. */
  --rank-color: #f5b842;
  --rank-glow:  rgba(245,184,66,0.50);
  --rank-soft:  rgba(245,184,66,0.14);
}
.guild-bosses-row:last-child { border-bottom: 0; }
/* W315 — archive rows carry BOTH .guild-bosses-row and --archive; the base
   rule above is later in source and re-declares grid-template-columns, so it
   overrode the modifier. This 2-class (higher-specificity) rule restores the
   4-track grid (dot | title | capsule | share) so the share button gets its
   own right-edge column instead of wrapping below the boss name. */
.guild-bosses-row.guild-bosses-row--archive {
  grid-template-columns: 10px minmax(0, 1fr) auto auto;
}
/* Fantasy shield crest — SVG path painted entirely in --rank-color. */
.guild-bosses-crest {
  position: relative;
  width: 32px;
  height: 35px;
  display: inline-block;
  flex: 0 0 auto;
  filter: drop-shadow(0 0 4px var(--rank-glow));
}
.guild-bosses-crest svg { display: block; }
.guild-bosses-crest-outer {
  fill: var(--rank-soft);
  stroke: var(--rank-color);
  stroke-width: 1.4;
}
.guild-bosses-crest-inner {
  fill: none;
  stroke: var(--rank-color);
  stroke-width: 0.5;
  opacity: 0.45;
}
.guild-bosses-title {
  font-family: 'Cinzel', serif;
  font-weight: 600;
  font-size: 0.92rem;
  letter-spacing: 0.025em;
  line-height: 1.15;
  color: var(--text-primary, #f3f4f6);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Gold kill capsule — crossed-swords glyph + Cinzel number + mono SLAIN. */
.guild-bosses-capsule {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px 4px 8px;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(245,184,66,0.16), rgba(245,184,66,0.04));
  border: 1px solid rgba(245,184,66,0.45);
  box-shadow: 0 0 8px rgba(245,184,66,0.20);
  flex: 0 0 auto;
  white-space: nowrap;
  color: var(--gold, #f5b842);
}
.guild-bosses-capsule-glyph {
  display: block;
  color: var(--gold, #f5b842);
}
.guild-bosses-capsule-num {
  font-family: 'Cinzel', serif;
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1;
  color: var(--gold, #f5b842);
  text-shadow: 0 0 6px rgba(245,184,66,0.30);
  font-variant-numeric: tabular-nums;
}
.guild-bosses-capsule-lbl {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.50rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--text-tertiary, #6b7280);
  align-self: flex-end;
  padding-bottom: 1px;
  text-transform: uppercase;
}

/* Section shell — used by Guild Activity + Your hunters. */
.guildhall-section {
  margin: 0 14px 16px;
}
.guildhall-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 8px;
  gap: 10px;
}

/* v3 Phase 1z.178 — Hunter / Guild segmented toggle. Sits inline
   with the GUILD ACTIVITY title on the right. Dark glass surface
   with violet active state to match the rest of the Guild Hall.
   Default state is muted neutral so the title still leads the eye;
   active button gains a violet glow + gold-tinged label. */
.guildhall-activity-filter {
  display: inline-flex;
  align-items: center;
  gap: 0;
  padding: 3px;
  background: rgba(16, 18, 38, 0.55);
  border: 1px solid rgba(167, 139, 250, 0.22);
  border-radius: 999px;
  flex-shrink: 0;
}
.guildhall-activity-filter-btn {
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  border: 0;
  color: var(--text-secondary, #8b8fab);
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.60rem;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding: 6px 12px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 80ms ease, color 80ms ease, box-shadow 80ms ease;
  min-width: 56px;
  text-align: center;
}
.guildhall-activity-filter-btn:hover {
  color: var(--text-primary, #f3f4f6);
}
.guildhall-activity-filter-btn:active {
  transform: scale(0.97);
}
.guildhall-activity-filter-btn[data-active="true"] {
  background: linear-gradient(180deg, rgba(167, 139, 250, 0.30), rgba(167, 139, 250, 0.14));
  color: var(--gold, #f5b842);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 0 8px rgba(167, 139, 250, 0.30);
}
.guildhall-section-title {
  margin-top: 2px;
  font-family: 'Cinzel', serif;
  font-weight: 600;
  font-size: 1rem;
  letter-spacing: 0.03em;
  color: var(--text-primary);
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
}
.guildhall-section-count {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--text-tertiary);
  letter-spacing: 0.06em;
}
/* Activity card — list of recent feats rendered by
   renderGuildActivity() in app.js. */
.guildhall-activity-body {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.guildhall-activity-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-top: 1px solid var(--border);
}
.guildhall-activity-row:first-child {
  border-top: 0;
}
.guildhall-activity-icon {
  width: 28px;
  height: 28px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: rgba(245, 158, 11, 0.10);
  border: 1px solid rgba(245, 158, 11, 0.35);
  color: var(--gold);
  font-size: 0.85rem;
}
.guildhall-activity-icon--violet {
  background: rgba(139, 92, 246, 0.10);
  border-color: rgba(139, 92, 246, 0.40);
  color: var(--accent, #8b5cf6);
}
.guildhall-activity-text {
  flex: 1;
  min-width: 0;
  font-size: 0.78rem;
  color: var(--text-secondary);
  line-height: 1.4;
}
.guildhall-activity-text strong {
  color: var(--text-primary);
  font-weight: 800;
}
.guildhall-activity-target {
  font-weight: 800;
}
.guildhall-activity-target--gold   { color: var(--gold); }
.guildhall-activity-target--violet { color: var(--accent, #8b5cf6); }

/* v3 Phase 1z.262 — ClaudeDesign color-system remap.
   Three-tier emphasis: Tier 1 (crown, big glow, w700), Tier 2
   (wins, medium glow, w600), Tier 3 (routine, NO glow, w500/600).
   Gold reserved for only two events (100K Club, ultra-rare) so
   it reads as "elite," not UI furniture. Boss (crimson) and Steps
   (teal) on opposite poles for instant separation. Verified
   family (streak/workout/sleep) unified mint green + ✓ glyph.
   Hunter renderer (_guildhallRowHtml) hardcodes --gold/--violet
   and is unaffected.

   The 1z.261 keys (boss / steps / club / streak / workout / sleep /
   flights / friend) are deliberately replaced with the design's
   keys (combat / step / club / verify / flight / social) — the
   helper now emits the new keys so older modifier rules are dead. */

/* ── Tier 2 — wins · medium glow · weight 600 ──────────────── */
.guildhall-activity-target--combat {
  color: #f0596b;
  font-weight: 600;
  text-shadow: 0 0 9px rgba(240, 89, 107, 0.40);
}
.guildhall-activity-target--step {
  color: #2dd4bf;
  font-weight: 600;
  text-shadow: 0 0 9px rgba(45, 212, 191, 0.40);
}
.guildhall-activity-target--flight {
  color: #38bdf8;
  font-weight: 600;
  text-shadow: 0 0 9px rgba(56, 189, 248, 0.40);
}
.guildhall-activity-target--rank {
  color: #a78bfa;
  font-weight: 600;
  text-shadow: 0 0 9px rgba(167, 139, 250, 0.40);
}
.guildhall-activity-target--rare {
  color: #3b82f6;
  font-weight: 600;
  text-shadow: 0 0 9px rgba(59, 130, 246, 0.40);
}

/* ── Tier 1 — crown moments · strong glow · weight 700 ─────── */
.guildhall-activity-target--ultra {
  color: #fbbf24;
  font-weight: 700;
  text-shadow: 0 0 12px rgba(251, 191, 36, 0.55);
}
.guildhall-activity-target--club {
  color: #f5b842;
  font-weight: 700;
  text-shadow: 0 0 13px rgba(245, 184, 66, 0.60);
}
/* W258 — Arena title earned · gold Tier-1 prestige (same family as club) */
.guildhall-activity-target--arenatitle {
  color: #f5b842;
  font-weight: 700;
  text-shadow: 0 0 13px rgba(245, 184, 66, 0.60);
}
/* W469 — Perfect Day streak milestone · radiant warm gold. Its own identity,
   distinct from the loot-gold ultra and the achievement-gold club/arenatitle,
   so a Perfect Day reads as a top-tier discipline flex at a glance. */
.guildhall-activity-target--perfect {
  color: #ffc24d;
  font-weight: 700;
  text-shadow: 0 0 14px rgba(255, 194, 77, 0.62);
}

/* ── Tier 3 — routine confirmations · NO glow ──────────────── */
.guildhall-activity-target--verify {
  color: #34d399;
  font-weight: 500;
}
.guildhall-activity-target--social {
  color: #94a3b8;
  font-weight: 600;
}

/* Small system ✓ glyph after the target phrase on verified events.
   Reinforces the "confirmed" feel and lets the Tier-3 verified
   family recede quietly while still being recognizable. */
.guildhall-activity-target-check {
  margin-left: 4px;
  color: #34d399;
  font-size: 0.78em;
  font-weight: 700;
  vertical-align: baseline;
}

/* ── Icon tile per-eventType tints ──────────────────────────── */
.guildhall-activity-icon--combat {
  color: #f0596b;
  border-color: rgba(240, 89, 107, 0.35);
  background: rgba(240, 89, 107, 0.10);
}
.guildhall-activity-icon--step {
  color: #2dd4bf;
  border-color: rgba(45, 212, 191, 0.35);
  background: rgba(45, 212, 191, 0.10);
}
.guildhall-activity-icon--flight {
  color: #38bdf8;
  border-color: rgba(56, 189, 248, 0.35);
  background: rgba(56, 189, 248, 0.10);
}
.guildhall-activity-icon--rank {
  color: #a78bfa;
  border-color: rgba(167, 139, 250, 0.35);
  background: rgba(167, 139, 250, 0.10);
}
.guildhall-activity-icon--rare {
  color: #3b82f6;
  border-color: rgba(59, 130, 246, 0.35);
  background: rgba(59, 130, 246, 0.10);
}
.guildhall-activity-icon--ultra {
  color: #fbbf24;
  border-color: rgba(251, 191, 36, 0.40);
  background: rgba(251, 191, 36, 0.12);
}
.guildhall-activity-icon--club {
  color: #f5b842;
  border-color: rgba(245, 184, 66, 0.40);
  background: rgba(245, 184, 66, 0.12);
}
/* W258 — Arena title icon tile (gold Tier-1, mirrors club) */
.guildhall-activity-icon--arenatitle {
  color: #f5b842;
  border-color: rgba(245, 184, 66, 0.40);
  background: rgba(245, 184, 66, 0.12);
}
/* W469 — Perfect Day icon tile · radiant warm gold (mirrors the target hue) */
.guildhall-activity-icon--perfect {
  color: #ffc24d;
  border-color: rgba(255, 194, 77, 0.42);
  background: rgba(255, 194, 77, 0.13);
}
.guildhall-activity-icon--verify {
  color: #34d399;
  border-color: rgba(52, 211, 153, 0.30);
  background: rgba(52, 211, 153, 0.08);
}
.guildhall-activity-icon--social {
  color: #94a3b8;
  border-color: rgba(148, 163, 184, 0.28);
  background: rgba(148, 163, 184, 0.06);
}
/* v3 Phase 1z.180 — souls-ledger / collapsed-boss-kill suffix.
   Renders the "· +50 souls" or "· Daily login" tail in a muted
   tone so the primary delta/target carries the eye, and the
   suffix reads as context rather than noise. */
.guildhall-activity-target-sub {
  color: var(--text-secondary, #8b8fab);
  font-weight: 600;
}

/* v3 Phase 1z.182 — date-grouped accordion for Guild Activity feed.
   Each calendar day becomes a group with a tappable header. Only
   one group is expanded at a time; the others render only their
   slim header. Visual language matches the dark-fantasy Social tab:
   thin violet border, gold date label, muted count, small chevron. */
.guildhall-activity-date-group {
  margin-top: 6px;
  border: 1px solid rgba(167, 139, 250, 0.18);
  border-radius: 10px;
  overflow: hidden;
  background: rgba(16, 18, 38, 0.40);
}
.guildhall-activity-date-group:first-child { margin-top: 0; }
.guildhall-activity-date-head {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 12px;
  background: transparent;
  border: 0;
  cursor: pointer;
  color: inherit;
  font-family: inherit;
  text-align: left;
  -webkit-appearance: none;
  appearance: none;
}
.guildhall-activity-date-head:hover {
  background: rgba(167, 139, 250, 0.06);
}
.guildhall-activity-date-head:active {
  background: rgba(167, 139, 250, 0.12);
  transform: scale(0.998);
}
.guildhall-activity-date-label {
  font-family: 'Cinzel', serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--gold, #f5b842);
  text-shadow: 0 0 6px rgba(245, 184, 66, 0.20);
}
.guildhall-activity-date-count {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text-secondary, #8b8fab);
  text-transform: uppercase;
  margin-left: auto;
}
.guildhall-activity-date-chev {
  font-size: 0.78rem;
  color: var(--text-tertiary, #6b7280);
  transition: transform 140ms ease;
  display: inline-block;
}
.guildhall-activity-date-group[data-expanded="true"] .guildhall-activity-date-chev {
  transform: rotate(0deg);
  color: var(--gold, #f5b842);
}
.guildhall-activity-date-group[data-expanded="false"] .guildhall-activity-date-chev {
  transform: rotate(-90deg);
}
.guildhall-activity-date-body {
  padding: 4px 8px 8px;
  border-top: 1px solid rgba(167, 139, 250, 0.12);
}
.guildhall-activity-date-group[data-expanded="false"] .guildhall-activity-date-body {
  display: none;
}
/* Loosen the row padding inside groups so the date-group border
   itself supplies the outer card frame and rows feel like an
   inline list rather than separately bordered cards. */
.guildhall-activity-date-body .guildhall-activity-row {
  border: 0;
  border-radius: 0;
  padding: 8px 4px;
  background: transparent;
  border-bottom: 1px solid rgba(167, 139, 250, 0.08);
}
.guildhall-activity-date-body .guildhall-activity-row:last-child {
  border-bottom: 0;
}
/* v3 Phase 1z.183 — See more button shown beneath the visible
   date groups when the feed has older days hidden. Compact,
   centered, dark-glass with a thin violet border so it reads
   as part of the Guild Activity system. */
.guildhall-activity-see-more {
  display: flex;
  justify-content: center;
  margin-top: 8px;
}
.guildhall-activity-see-more-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: rgba(16, 18, 38, 0.55);
  border: 1px solid rgba(167, 139, 250, 0.28);
  border-radius: 999px;
  color: var(--gold, #f5b842);
  font-family: 'Cinzel', serif;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 140ms ease, border-color 140ms ease, transform 140ms ease;
}
.guildhall-activity-see-more-btn:hover {
  background: rgba(167, 139, 250, 0.12);
  border-color: rgba(167, 139, 250, 0.45);
}
.guildhall-activity-see-more-btn:active {
  transform: translateY(1px);
}
.guildhall-activity-see-more-chev {
  font-size: 0.70rem;
  line-height: 1;
  color: var(--gold, #f5b842);
}
.guildhall-activity-time {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.60rem;
  color: var(--text-tertiary);
  letter-spacing: 0.05em;
  white-space: nowrap;
}
.guildhall-activity-empty {
  padding: 16px 16px;
  text-align: center;
  font-family: 'Cinzel', serif;
  font-size: 0.92rem;
  color: var(--gold);
  letter-spacing: 0.04em;
  font-weight: 600;
}
.guildhall-activity-empty-sub {
  margin-top: 4px;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  font-style: normal;
  font-size: 0.72rem;
  color: var(--text-secondary);
}

/* Friends — reuse existing .social-row internals; add a chip
   header row inside the section head. */
.guildhall-friend-add {
  display: flex;
  gap: 8px;
  margin-bottom: 10px;
}
.guildhall-friend-add .social-friend-input {
  flex: 1;
}
.guildhall-friend-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* Zero-friends empty state — design hero panel. */
.guildhall-empty-friends {
  padding: 20px 16px;
  border-radius: 12px;
  text-align: center;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(139,92,246,0.12), transparent 60%),
    rgba(255,255,255,0.02);
  border: 1px dashed rgba(139, 92, 246, 0.40);
}
.guildhall-empty-friends-icon {
  margin: 0 auto;
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: radial-gradient(circle at 50% 30%, rgba(139,92,246,0.30), #0a0a18);
  border: 1px solid var(--accent, #8b5cf6);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Cinzel', serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent, #8b5cf6);
}
.guildhall-empty-friends-title {
  margin-top: 12px;
  font-family: 'Cinzel', serif;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--gold);
  letter-spacing: 0.04em;
}
.guildhall-empty-friends-sub {
  margin-top: 4px;
  font-family: Georgia, 'Cormorant Garamond', serif;
  font-style: italic;
  font-size: 0.8rem;
  color: var(--text-secondary);
}

/* v3 Phase 1z.279 — Legacy flag-driven duel hides removed
   (body.duels-public-hidden / body.duels-challenge-hidden /
   body.social-hub-on .duels-page-header). The underlying DOM
   (#duels-hero, .social-section--duels, .duels-page-header)
   is also gone from index.html. The body.social-hub-on master
   switch survives separately and stays the Guild Hall layout
   trigger. */

/* v3 Phase 1z.173 — Social Tab Polish · panel treatment for the
   Recent Feats + Your Hunters sections (Variation B from
   ClaudeDesign). Section heads stay outside the panel; the panel
   itself is a single bordered card with hairline dividers between
   rows (no per-row borders or gaps — visually distinct from the
   pre-1z.173 "stacked bordered rows" look). */
.guildhall-section--activity .guildhall-activity-body,
.guildhall-section--friends .guildhall-friend-body {
  background: rgba(20, 22, 50, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 14px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
  overflow: hidden;
  padding: 0;
}
/* Hairline divider between rows inside the activity panel. The
   row component itself (.guildhall-activity-row) is unchanged — we
   add the border at the panel level via :not(:last-child). */
.guildhall-section--activity .guildhall-activity-body > .guildhall-activity-row {
  border-radius: 0;
  border: 0;
  background: transparent;
  margin: 0;
  padding: 10px 14px;
}
.guildhall-section--activity .guildhall-activity-body > .guildhall-activity-row + .guildhall-activity-row {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

/* Friends panel — same hairline-divided look. Wraps both the
   accepted friend rows and the empty/loading states inside the
   single bordered card. */
.guildhall-section--friends .guildhall-friend-body > .social-row,
.guildhall-section--friends .guildhall-friend-body > .friend-row {
  border-radius: 0;
  border: 0;
  background: transparent;
  margin: 0;
  padding: 12px 14px;
}
.guildhall-section--friends .guildhall-friend-body > .social-row + .social-row,
.guildhall-section--friends .guildhall-friend-body > .friend-row + .friend-row {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}
.guildhall-section--friends .guildhall-friend-body > .social-section-subhead {
  display: none;
}
.guildhall-section--friends .guildhall-friend-body > .social-empty,
.guildhall-section--friends .guildhall-friend-body > .social-error {
  padding: 16px 14px;
  background: transparent;
  border: 0;
  border-radius: 0;
  margin: 0;
}

/* Embed the Add Friend input row as the panel's first divider-
   separated row, matching the design's "input is the first row
   inside Your Hunters panel" rule. */
.guildhall-section--friends .guildhall-friend-add {
  margin: 0;
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 14px 14px 0 0;
  border-bottom: 0;
}
/* When the Add Friend row sits directly above the friends body
   panel, kill the body's top corner radius + top border to let
   them read as one continuous card. */
.guildhall-section--friends .guildhall-friend-add + .guildhall-friend-body {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 0 0 14px 14px;
}

/* v3 Phase 1z.173 — REMOVE button is now an outlined red ghost
   (per Variation B spec) instead of the older filled danger
   variant. Scoped to friend rows so the .social-btn--danger class
   used elsewhere keeps its original treatment. */
.guildhall-section--friends .friend-row--accepted .social-btn--danger {
  background: transparent;
  color: #ef4444;
  border: 1px solid rgba(239, 68, 68, 0.45);
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding: 5px 11px;
  border-radius: 8px;
  box-shadow: none;
}
.guildhall-section--friends .friend-row--accepted .social-btn--danger:hover {
  background: rgba(239, 68, 68, 0.08);
  border-color: rgba(239, 68, 68, 0.75);
  filter: none;
}
.guildhall-section--friends .friend-row--accepted .social-btn--danger:active {
  background: rgba(239, 68, 68, 0.16);
  transform: scale(0.97);
}

/* v3 Phase 1z.176 — friend-row overflow + two-step confirm.
   Row default state shows just a small "•••" icon button. Tapping
   flips data-row-mode="confirm" on the row which swaps the icon
   for an inline Cancel / Remove pair. Removes the fat-finger
   destructive button that sat on every row pre-1z.176. */
.guildhall-section--friends .friend-row--accepted .social-row-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.guildhall-section--friends .social-btn--icon {
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--text-secondary, #8b8fab);
  font-size: 1.10rem;
  line-height: 1;
  letter-spacing: 0.02em;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.guildhall-section--friends .social-btn--icon:hover {
  background: rgba(167, 139, 250, 0.10);
  border-color: rgba(167, 139, 250, 0.35);
  color: var(--text-primary, #f3f4f6);
}
.guildhall-section--friends .social-btn--icon:active {
  background: rgba(167, 139, 250, 0.18);
  transform: scale(0.96);
}

/* Inline confirm row — hidden in idle mode, revealed in confirm
   mode. Cancel is the ghost; Remove keeps the outlined red ghost
   styling from 1z.173. */
.guildhall-section--friends .social-row-confirm {
  display: none;
  align-items: center;
  gap: 6px;
}
.friend-row--accepted[data-row-mode="confirm"] .social-btn--icon {
  display: none;
}
.friend-row--accepted[data-row-mode="confirm"] .social-row-confirm {
  display: inline-flex;
}
.guildhall-section--friends .social-btn--ghost {
  background: transparent;
  color: var(--text-secondary, #8b8fab);
  border: 1px solid rgba(255, 255, 255, 0.14);
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 8px;
}
.guildhall-section--friends .social-btn--ghost:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-primary, #f3f4f6);
}
.guildhall-section--friends .social-btn--ghost:active {
  background: rgba(255, 255, 255, 0.10);
  transform: scale(0.97);
}

/* ─── v3 Phase 1z.174 — Social Tab w50 polish ─────────────────
   Stronger Command Panel rim, inline kicker+title, solo Activity
   heading, Friends accordion (collapsed-by-default), and Add
   Friend row reordered BELOW the friend list. */

/* Stronger Command Panel rim — bumps the gradient opacity to
   ~95% so the gold/violet border reads clearly on iPhone. Plus
   a small extra top-edge gold glow for depth. */
.guildhall-command-panel {
  background: linear-gradient(135deg,
    rgba(167,139,250,0.95) 0%,
    rgba(245,184,66,1.00) 50%,
    rgba(167,139,250,0.95) 100%);
  box-shadow:
    0 0 24px rgba(167, 139, 250, 0.28),
    0 0 12px rgba(245, 184, 66, 0.18);
}
/* Solo big activity heading — replaces the kicker+subtitle combo
   from 1z.173. Cinzel-styled gold so the section reads as
   prominent without the second line. */
.guildhall-section-title--solo {
  font-family: 'Cinzel', serif;
  font-weight: 700;
  font-size: 1.10rem;
  letter-spacing: 0.10em;
  color: var(--gold, #f5b842);
  text-shadow: 0 0 10px rgba(245, 184, 66, 0.35);
  text-transform: uppercase;
  margin: 0;
}

/* Friends accordion — header is now a full-width button with a
   chevron that rotates when expanded. Body wrap collapses to 0
   height when .is-collapsed is on the section. */
.guildhall-friends-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 0;
  margin: 0 0 8px;
  background: transparent;
  border: 0;
  cursor: pointer;
  color: inherit;
  text-align: left;
  font: inherit;
  -webkit-appearance: none;
  appearance: none;
}
.guildhall-friends-toggle .guildhall-section-headtxt {
  flex: 1 1 auto;
  min-width: 0;
}
.guildhall-friends-chevron {
  font-size: 1.10rem;
  color: var(--gold, #f5b842);
  transition: transform 180ms ease;
  margin-left: 8px;
  flex: 0 0 auto;
}
.guildhall-section--friends.is-collapsed .guildhall-friends-chevron {
  transform: rotate(-90deg);
}
.guildhall-friends-body-wrap {
  overflow: hidden;
  max-height: 1500px;
  transition: max-height 220ms ease;
}
.guildhall-section--friends.is-collapsed .guildhall-friends-body-wrap {
  max-height: 0;
}

/* 1z.174 reorder: friends body sits ABOVE Add Friend now.
   Reshape the rounded corners + dividers accordingly:
   - friends body rounds its TOP corners (was bottom in 1z.173).
   - add-friend--bottom rounds its BOTTOM corners with a hairline
     divider above it. */
.guildhall-section--friends .guildhall-friend-body {
  border-radius: 14px 14px 0 0;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-bottom: 0;
}
.guildhall-section--friends .guildhall-friend-add--bottom {
  margin: 0;
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 0 0 14px 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  align-items: center;
  gap: 8px;
}
/* Override the 1z.173 "Add Friend embedded on top" rules so they
