/* ═══════════════════════════════════════════════════════════════════
   v3 Phase 1z.247 — Habits tab "First Vow" empty state.
   Replaces the dim ✓ + "No habits yet" placeholder with a mythic
   sigil + 6 quick-pick vow cards. Tap a chip → habit is created via
   the canonical pack-add path; empty state disappears naturally
   because habits.length > 0 on next render.

   The same #empty-state container also surfaces the legacy "rest day"
   message — when `.empty-state--rest-day` is on the container, the
   first-vow hero/grid hide and the rest-day fallback shows.

   All rules scoped under .empty-state .ev-* so they cannot leak.
   ═══════════════════════════════════════════════════════════════════ */

.empty-state .empty-state-restday {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 48px 16px 16px;
  text-align: center;
}
/* v3 Phase 1z.248 — tighten vertical layout so First Vow fits on iPhone
   viewport between tab strip and bottom "+ Add Habits" without scroll.
   The base `.empty-state` rule above carries 72px of top padding +
   18px gap that was pushing the sigil below mid-screen. When first-vow
   mode is active we override both. */
.empty-state:not(.empty-state--rest-day) {
  padding: 8px 16px 4px;
  gap: 0;
}
.empty-state .empty-state-firstvow {
  display: flex;
  flex-direction: column;
  padding: 0;
  gap: 14px;
  width: 100%;
}

/* Rest-day mode: hide first-vow, show legacy ✓ + p */
.empty-state.empty-state--rest-day .empty-state-firstvow { display: none; }
.empty-state:not(.empty-state--rest-day) .empty-state-restday { display: none; }

/* ── Hero ────────────────────────────────────────────────────── */
.empty-state .ev-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 0;
}
.empty-state .ev-sigil-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  margin-bottom: 8px;
}
.empty-state .ev-sigil-ring {
  position: absolute;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  border: 1px solid rgba(167, 139, 250, 0.45);
  box-shadow: 0 0 20px rgba(139, 92, 246, 0.32);
  animation: ev-pulse 4.5s ease-out infinite;
}
@keyframes ev-pulse {
  0%   { transform: scale(0.78); opacity: 0.9; }
  70%  { opacity: 0; }
  100% { transform: scale(1.32); opacity: 0; }
}
.empty-state .ev-sigil-disc {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 42% 34%,
    rgba(245, 184, 66, 0.22),
    rgba(16, 14, 40, 0.9) 70%);
  border: 1.5px solid rgba(245, 184, 66, 0.50);
  box-shadow:
    0 0 18px rgba(245, 184, 66, 0.30),
    inset 0 0 12px rgba(245, 184, 66, 0.14);
  animation: ev-breathe 5s ease-in-out infinite;
  z-index: 1;
}
@keyframes ev-breathe {
  0%, 100% { transform: scale(0.96); }
  50%      { transform: scale(1.06); }
}
.empty-state .ev-sigil-disc svg {
  width: 24px;
  height: 24px;
  filter: drop-shadow(0 0 6px rgba(245, 184, 66, 0.55));
}

.empty-state .ev-headline {
  font-family: "Cinzel", "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 2px;
  color: #ecca84;
  text-align: center;
  white-space: nowrap;
  text-shadow: 0 0 22px rgba(245, 184, 66, 0.24);
}
.empty-state .ev-stanza {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-style: italic;
  font-size: 13.5px;
  color: #9aa0bd;
  text-align: center;
  margin: 6px auto 0;
  max-width: 260px;
  line-height: 1.4;
}

/* ── Quick-pick grid ────────────────────────────────────────── */
.empty-state .ev-grid {
  display: grid;
  /* v3 Phase 1z.249 — minmax(0, 1fr) so the track CAN collapse below
     content width, letting `min-width: 0` on .ev-chip-body engage and
     .ev-chip-name's ellipsis kick in. Otherwise "Meditate & Breathwork"
     forces the right column past viewport. */
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 8px;
  margin-top: 2px;
  width: 100%;
  box-sizing: border-box;
}
.empty-state .ev-chip {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 11px;
  border-radius: 13px;
  cursor: pointer;
  text-align: left;
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
  background: linear-gradient(180deg,
    rgba(26, 21, 56, 0.90),
    rgba(15, 12, 34, 0.90));
  border: 1px solid rgba(245, 184, 66, 0.34);
  box-shadow:
    0 0 14px rgba(245, 184, 66, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  color: inherit;
  font-family: inherit;
  appearance: none;
  -webkit-appearance: none;
  transition: transform 120ms ease, box-shadow 200ms ease, border-color 200ms ease;
}
.empty-state .ev-chip:hover {
  border-color: rgba(245, 184, 66, 0.60);
  box-shadow: 0 0 18px rgba(245, 184, 66, 0.18);
}
.empty-state .ev-chip:active {
  transform: scale(0.96);
}
.empty-state .ev-chip-ic {
  width: 36px;
  height: 36px;
  border-radius: 9px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  background: rgba(245, 184, 66, 0.08);
  border: 1px solid rgba(245, 184, 66, 0.20);
  overflow: hidden;
}
.empty-state .ev-chip-ic img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}
.empty-state .ev-chip-body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.empty-state .ev-chip-name {
  font-family: -apple-system, "SF Pro Display", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #f4f3fb;
  line-height: 1.15;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.empty-state .ev-chip-cad {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 8.5px;
  letter-spacing: 1px;
  color: #5c5c78;
  text-transform: uppercase;
}

/* v3 Phase 1z.250 — selected chip state + gold check badge.
   The chip becomes a touch warmer; the check badge floats top-right
   inside the chip without affecting layout (absolute positioning). */
.empty-state .ev-chip {
  position: relative;
}
.empty-state .ev-chip-check {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: rgba(245, 184, 66, 0);
  border: 1px solid rgba(245, 184, 66, 0);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: scale(0.7);
  transition: opacity 160ms ease, transform 160ms ease,
              background 160ms ease, border-color 160ms ease;
}
.empty-state .ev-chip-check svg { opacity: 0; transition: opacity 120ms ease 60ms; }
.empty-state .ev-chip.is-selected {
  border-color: rgba(245, 184, 66, 0.75);
  background: linear-gradient(180deg,
    rgba(40, 32, 14, 0.95),
    rgba(20, 15, 5, 0.95));
  box-shadow:
    0 0 22px rgba(245, 184, 66, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}
.empty-state .ev-chip.is-selected .ev-chip-check {
  background: linear-gradient(180deg, #f7c65c, #e3a52f);
  border-color: rgba(245, 184, 66, 0.75);
  opacity: 1;
  transform: scale(1);
}
.empty-state .ev-chip.is-selected .ev-chip-check svg { opacity: 1; }

/* Commit CTA — gold premium look, compact so it doesn't push the
   layout into scroll. Disabled state dims gracefully. */
.empty-state .ev-commit {
  margin-top: 10px;
  padding: 11px 16px;
  border-radius: 12px;
  font-family: "Cinzel", "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 2px;
  color: #1b1405;
  background: linear-gradient(180deg, #f7c65c, #e3a52f);
  border: 1px solid rgba(245, 184, 66, 0.6);
  box-shadow:
    0 0 22px rgba(245, 184, 66, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.4);
  cursor: pointer;
  text-transform: uppercase;
  transition: filter 160ms ease, transform 120ms ease,
              box-shadow 200ms ease;
}
.empty-state .ev-commit:active { transform: scale(0.98); }
.empty-state .ev-commit:disabled {
  background: rgba(245, 184, 66, 0.10);
  border-color: rgba(245, 184, 66, 0.28);
  color: rgba(245, 184, 66, 0.55);
  box-shadow: none;
  cursor: default;
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 2.5px;
}

/* ── Browse link ────────────────────────────────────────────── */
.empty-state .ev-browse {
  margin-top: 8px;
  padding: 8px 0 4px;
  text-align: center;
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 1.5px;
  color: #5c5c78;
  text-transform: uppercase;
  background: transparent;
  border: 0;
  cursor: pointer;
  width: 100%;
}
.empty-state .ev-browse:hover,
.empty-state .ev-browse:focus {
  color: #a78bfa;
  outline: none;
}

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .empty-state .ev-sigil-ring {
    animation: none;
    transform: scale(1);
    opacity: 0.5;
  }
  .empty-state .ev-sigil-disc { animation: none; }
  .empty-state .ev-chip:active { transform: none; }
  /* v3 Phase 1z.250 — instant chip selection / CTA state under
     reduce-motion so users don't see fade-in/scale animations. */
  .empty-state .ev-chip-check,
  .empty-state .ev-chip-check svg { transition: none; }
  .empty-state .ev-commit { transition: none; }
  .empty-state .ev-commit:active { transform: none; }
}

/* ═══════════════════════════════════════════════════════════════════
   v3 Phase 1z.273G — Onboarding · Training Week (cinematic step)
   Inserted between Path (#cin-scr4) and Pact (#cin-scr5). All rules
   scoped to #cin-onboarding .cin-tw-* so they cannot leak.
   ═══════════════════════════════════════════════════════════════════ */
#cin-onboarding .cin-tw-rows {
  display: flex;
  flex-direction: column;
  gap: 11px;
  margin-top: 18px;
  width: 100%;
  max-width: 320px;
}
#cin-onboarding .cin-tw-row {
  position: relative;
  background: linear-gradient(180deg, rgba(22,22,58,0.85), rgba(14,14,38,0.85));
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 16px;
  padding: 12px 13px 13px;
  text-align: left;
}
#cin-onboarding .cin-tw-rowtop {
  display: flex;
  align-items: center;
  gap: 10px;
}
#cin-onboarding .cin-tw-rowname { flex: 1 1 auto; min-width: 0; }
#cin-onboarding .cin-tw-nm {
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
  font-size: 15px;
  color: #f1f0fb;
  letter-spacing: 0.4px;
}
#cin-onboarding .cin-tw-freq {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 3px;
  flex-wrap: wrap;
}
#cin-onboarding .cin-tw-days {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 10.5px;
  letter-spacing: 1.4px;
  color: #ecca84;
}
#cin-onboarding .cin-tw-tag {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1.1px;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 9px;
}
#cin-onboarding .cin-tw-tag-rec {
  color: #34d399;
  background: rgba(52,211,153,0.10);
  border: 1px solid rgba(52,211,153,0.30);
}
#cin-onboarding .cin-tw-tag-cus {
  color: #a78bfa;
  background: rgba(167,139,250,0.10);
  border: 1px solid rgba(167,139,250,0.30);
}
#cin-onboarding .cin-tw-tag-evd {
  color: #f5b842;
  background: rgba(245,184,66,0.12);
  border: 1px solid rgba(245,184,66,0.34);
}

/* Seal row — 7 small oath-marks */
#cin-onboarding .cin-tw-seals {
  display: flex;
  gap: 5px;
  margin-top: 11px;
}
#cin-onboarding .cin-tw-seal {
  flex: 1 1 0;
  aspect-ratio: 1 / 1.04;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
  font-size: 13px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.10);
  color: #71718f;
  cursor: pointer;
  position: relative;
  -webkit-appearance: none;
  appearance: none;
  transition:
    transform 0.12s cubic-bezier(0.2,0.8,0.2,1),
    background 0.2s,
    color 0.2s,
    box-shadow 0.25s;
}
#cin-onboarding .cin-tw-seal:hover {
  border-color: rgba(255,255,255,0.2);
  color: #bdbad6;
}
#cin-onboarding .cin-tw-seal:active { transform: scale(0.9); }
#cin-onboarding .cin-tw-seal.lit {
  background: linear-gradient(180deg, #f7c65c, #e1a52c);
  border-color: rgba(245,184,66,0.6);
  color: #1b1405;
  box-shadow:
    0 0 12px rgba(245,184,66,0.42),
    inset 0 1px 0 rgba(255,255,255,0.5);
}
#cin-onboarding .cin-tw-seal.lit::after {
  content: "";
  position: absolute;
  top: 4px; left: 50%;
  transform: translateX(-50%);
  width: 3px; height: 3px;
  border-radius: 50%;
  background: rgba(27,20,5,0.5);
}
#cin-onboarding .cin-tw-seal.cin-tw-pop {
  animation: cin-tw-sealpop 0.34s cubic-bezier(0.2,0.8,0.2,1);
}
#cin-onboarding .cin-tw-seal.cin-tw-shake {
  animation: cin-tw-shake 0.42s;
}
@keyframes cin-tw-sealpop {
  0%   { transform: scale(0.78); }
  55%  { transform: scale(1.12); }
  100% { transform: scale(1); }
}
@keyframes cin-tw-shake {
  0%, 100% { transform: translateX(0); }
  20%      { transform: translateX(-4px); }
  40%      { transform: translateX(4px); }
  60%      { transform: translateX(-3px); }
  80%      { transform: translateX(3px); }
}

/* Per-row rest line */
#cin-onboarding .cin-tw-restline {
  margin-top: 9px;
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-style: italic;
  font-size: 12.5px;
  color: #bdbad6;
}
#cin-onboarding .cin-tw-restline .cin-tw-pip {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 7px #34d399;
  flex: 0 0 auto;
}
#cin-onboarding .cin-tw-restline.cin-tw-warn { color: #e7a06a; }
#cin-onboarding .cin-tw-restline.cin-tw-warn .cin-tw-pip {
  background: #e7a06a;
  box-shadow: 0 0 7px #e7a06a;
}

/* Quick-set collapsible */
#cin-onboarding .cin-tw-quick-toggle {
  margin-top: 9px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9.5px;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #71718f;
  background: none;
  border: 0;
  cursor: pointer;
  padding: 2px 0;
  transition: color 0.2s;
  -webkit-appearance: none;
  appearance: none;
}
#cin-onboarding .cin-tw-quick-toggle:hover { color: #bdbad6; }
#cin-onboarding .cin-tw-chev { transition: transform 0.25s; }
#cin-onboarding .cin-tw-row.cin-tw-quick-open .cin-tw-chev {
