  overflow: hidden;
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
}
#cin-onboarding .cin-tw-pill {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: #bdbad6;
  padding: 7px 12px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.09);
  background: rgba(255,255,255,0.03);
  cursor: pointer;
  transition: all 0.16s;
  -webkit-appearance: none;
  appearance: none;
}
#cin-onboarding .cin-tw-pill:hover {
  color: #f1f0fb;
  border-color: rgba(255,255,255,0.2);
}
#cin-onboarding .cin-tw-pill.on {
  color: #f5b842;
  border-color: rgba(245,184,66,0.5);
  background: rgba(245,184,66,0.10);
}

/* Persistent reassurance line */
#cin-onboarding .cin-tw-reassure {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 18px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-style: italic;
  font-size: 15px;
  color: #ecca84;
}
#cin-onboarding .cin-tw-star {
  color: #f5b842;
  font-size: 13px;
  filter: drop-shadow(0 0 5px rgba(245,184,66,0.5));
}

/* Ghost "you can change this any time" */
#cin-onboarding .cin-tw-ghost {
  display: block;
  width: 100%;
  margin-top: 12px;
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 10.5px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #71718f;
  background: none;
  border: 0;
  cursor: pointer;
