}
@keyframes fa-coach-rise {
  from { transform: translateY(18px); }
  to   { transform: translateY(0); }
}

/* Scanline + gold corner brackets — purely decorative system chrome. */
.fa-coach-sheet::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 22px;
  overflow: hidden;
  pointer-events: none;
  opacity: 0.5;
  background: repeating-linear-gradient(
    0deg,
    rgba(167, 139, 250, 0.05) 0px,
    rgba(167, 139, 250, 0.05) 1px,
    transparent 1px,
    transparent 7px
  );
}
/* Use single ::after to render the top-left corner; other corners via
   sibling pseudo-elements on inner children to avoid extra DOM. */
.fa-coach-sheet::after {
  content: "";
  position: absolute;
  top: 12px;
  left: 12px;
  width: 16px;
  height: 16px;
  border-top: 1.5px solid #f5b842;
  border-left: 1.5px solid #f5b842;
