   speech / footer pseudo-elements. */
.fa-coach-kicker::before,
.fa-coach-kicker::after {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  opacity: 0.7;
  pointer-events: none;
}
.fa-coach-kicker::before {
  /* repurposed slot — see .fa-coach-sheet::after for top-left.
     Here we render the top-right bracket. */
  top: -76px;
  right: -14px;
  border-top: 1.5px solid #f5b842;
  border-right: 1.5px solid #f5b842;
  border-radius: 0 4px 0 0;
}
.fa-coach-kicker::after {
  display: none;
}
.fa-coach-footer::before,
.fa-coach-footer::after {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  opacity: 0.7;
  pointer-events: none;
