@keyframes ar-shake { 0%,100% { transform: translateX(0); } 20% { transform: translateX(-5px); } 40% { transform: translateX(5px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(2px); } }
@keyframes ar-flash { from { opacity: 1; } to { opacity: 0; } }
@keyframes ar-dmgfloat { 0% { opacity: 0; transform: translateX(-50%) translateY(8px) scale(0.7); } 25% { opacity: 1; transform: translateX(-50%) translateY(-2px) scale(1.1); } 100% { opacity: 0; transform: translateX(-50%) translateY(-32px) scale(1); } }
/* W218 — combat RNG tags (crit / miss / type effectiveness) */
.ar-tag { display: inline-flex; align-items: center; vertical-align: middle; margin-left: 7px; padding: 2px 7px; border-radius: 5px; font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 800; letter-spacing: 0.13em; line-height: 1.4; }
