.ar-tag.miss  { color: #9090a8; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.14); }
.ar-tag.super { color: #34d399; background: rgba(52,211,153,0.14); border: 1px solid rgba(52,211,153,0.5); }
.ar-tag.weak  { color: #ef4444; background: rgba(239,68,68,0.13); border: 1px solid rgba(239,68,68,0.45); }
/* continue button */
.ar-contbtn { display: block; width: 100%; padding: 16px 0; border-radius: 12px; cursor: pointer; text-align: center; border: 1px solid rgba(245,184,66,0.35); background: linear-gradient(180deg, rgba(245,184,66,0.1), rgba(245,184,66,0.04)); box-shadow: inset 0 1px 0 rgba(255,255,255,0.06); font-family: "JetBrains Mono", monospace; font-size: 11.5px; font-weight: 800; letter-spacing: 0.3em; color: #f5b842; -webkit-tap-highlight-color: transparent; }
.ar-contbtn:active { filter: brightness(1.15); }
.ar-st { font-family: "JetBrains Mono", monospace; font-size: 7.5px; font-weight: 800; letter-spacing: 0.1em; padding: 2px 6px; border-radius: 4px; }
.ar-st.up { color: #34d399; background: rgba(52,211,153,0.12); border: 1px solid rgba(52,211,153,0.4); }
.ar-st.down { color: #ef4444; background: rgba(239,68,68,0.12); border: 1px solid rgba(239,68,68,0.4); }
.ar-st.burn { color: #f5853d; background: rgba(245,133,61,0.14); border: 1px solid rgba(245,133,61,0.45); }
.ar-bmoves { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.ar-bmove { display: flex; flex-direction: column; gap: 4px; padding: 12px 12px 11px; border-radius: 13px; cursor: pointer; text-align: left; background: linear-gradient(180deg, #12122c, #0e0e24); border: 1px solid rgba(255,255,255,0.09); box-shadow: inset 0 1px 0 rgba(255,255,255,0.05), 0 6px 14px rgba(0,0,0,0.35); -webkit-tap-highlight-color: transparent; transition: transform 0.12s ease, filter 0.12s ease; }
.ar-bmove:active { transform: scale(0.97); filter: brightness(1.18); }
.ar-bmove.cd { cursor: default; opacity: 0.5; filter: grayscale(0.5); }
.ar-bmove .top { display: flex; align-items: center; gap: 7px; }
.ar-bmove .top .g { flex: none; display: flex; }
.ar-bmove .top .nm { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 14.5px; color: #f5f3fb; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ar-bmove .top .cdn { font-family: "JetBrains Mono", monospace; font-size: 11px; font-weight: 800; color: #6b6b86; flex: none; }
.ar-bmove .ds { font-size: 10.5px; color: #9090a8; line-height: 1.3; min-height: 27px; }
.ar-bmove .tg { font-family: "JetBrains Mono", monospace; font-size: 7.5px; font-weight: 800; letter-spacing: 0.1em; color: #f5b842; }
.ar-bmove.cd .tg { color: #6b6b86; }
@keyframes arLowPulse { 0%,100% { filter: brightness(1); } 50% { filter: brightness(1.35); } }
/* VS intro effectiveness row */
.ar-vs-eff { display: flex; justify-content: center; margin: 12px 0 2px; min-height: 18px; }
.ar-vs-even { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.18em; color: #6b6b86; }
.ar-vs-eff .ar-tag { margin-left: 0; padding: 3px 11px; font-size: 9px; letter-spacing: 0.16em; }
@keyframes ar-lowhp {
  0%,100% { box-shadow: 0 0 8px rgba(239,68,68,0.45), inset 0 1px 0 rgba(255,255,255,0.45); filter: brightness(1); }
  50% { box-shadow: 0 0 18px rgba(239,68,68,0.85), 0 0 5px rgba(245,184,66,0.6), inset 0 1px 0 rgba(255,255,255,0.45); filter: brightness(1.3); }
}
/* Result rating tier line + promote/demote pulse */
.asc-rtier { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 800; letter-spacing: 0.14em; }
.asc-rtier .gem { width: 8px; height: 8px; border-radius: 2px; transform: rotate(45deg); }
.asc-rtier.asc-tier-pulse { animation: ar-tierpulse 0.8s ease 2; }
@keyframes ar-tierpulse { 0%,100% { transform: scale(1); filter: none; } 50% { transform: scale(1.1); filter: brightness(1.5); } }

@keyframes ar-ko-crumple { 0% { filter: none; transform: none; } 18% { filter: brightness(1.6); transform: scale(1.05); } 100% { filter: grayscale(1) brightness(0.4); transform: scale(0.88) rotate(6deg) translateY(8px); } }
@keyframes ar-ko-stamp { 0% { opacity: 0; transform: translate(-50%,-50%) rotate(-4deg) scale(2); filter: blur(7px); } 60% { opacity: 1; transform: translate(-50%,-50%) rotate(-4deg) scale(0.94); filter: blur(0); } 80% { transform: translate(-50%,-50%) rotate(-4deg) scale(1.04); } 100% { opacity: 1; transform: translate(-50%,-50%) rotate(-4deg) scale(1); } }
@keyframes ar-ko-flash { 0% { opacity: 0; } 22% { opacity: 0.85; } 100% { opacity: 0; } }
@keyframes ar-ko-slash { 0% { transform: rotate(-16deg) translateX(-130%); opacity: 0; } 30% { opacity: 1; } 70% { transform: rotate(-16deg) translateX(110%); opacity: 1; } 100% { transform: rotate(-16deg) translateX(130%); opacity: 0; } }
@keyframes ar-ko-shake { 0%,100% { transform: translate(0,0) rotate(0deg); } 18% { transform: translate(-6px, 4px) rotate(-0.6deg); } 36% { transform: translate(7px, -5px) rotate(0.5deg); } 54% { transform: translate(-5px, 3px) rotate(-0.4deg); } 72% { transform: translate(4px, -2px) rotate(0.3deg); } 88% { transform: translate(-2px, 1px) rotate(0deg); } }

@media (prefers-reduced-motion: reduce) {
  .ar-body, .ar-logline, .ar-versus, .ar-bossintro { animation: none; }
      .ar-sheet.ar-juice-you, .ar-sheet.ar-juice-foe,
  .ar-sheet.ar-juice-you::after, .ar-sheet.ar-juice-foe::after,
  .ar-dmg-float, .ar-hp-side .ar-hp-fill.low, .asc-rtier.asc-tier-pulse,
