/* ═══════════════════════════════════════════════════════════════════
   THE ASCENT — 100-floor tower UI (inside The Arena). Reuses .ar-*
   tokens; adds .asc-* for the tower header, bands, spine + floor
   cards, difficulty/power, and the result rating strip. Cold-iron
   (#7e8597) for opponents, gold for you, win-green/loss-red deltas.
   ═══════════════════════════════════════════════════════════════════ */
/* sticky tower header */
.asc-head { position: sticky; top: 0; z-index: 20; padding: calc(env(safe-area-inset-top,0px) + 12px) 18px 13px; background: linear-gradient(180deg, #0a0a1f 0%, rgba(10,10,31,0.94) 78%, rgba(10,10,31,0)); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border-bottom: 1px solid rgba(245,184,66,0.15); }
.asc-head-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; min-height: 26px; padding-right: 84px; }
/* W259 — always-visible Titles entry on the tower header; shows the equipped title */
.asc-titles-btn { flex: none; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  border: 1px solid rgba(245,184,66,0.33); border-radius: 999px; background: rgba(245,184,66,0.06);
  padding: 4px 11px; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800;
  letter-spacing: 0.1em; color: #f5b842; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.asc-titles-btn:active { transform: scale(0.96); background: rgba(245,184,66,0.14); }
.asc-head-main { display: flex; align-items: flex-end; justify-content: space-between; }
.asc-rating-lbl, .asc-daily-lbl { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.2em; color: #6b6b86; }
.asc-rating-row { display: flex; align-items: baseline; gap: 9px; margin-top: 3px; }
.asc-rating-num { font-family: "JetBrains Mono", monospace; font-weight: 800; font-size: 34px; line-height: 0.9; color: #f5b842; letter-spacing: -1px; text-shadow: 0 0 22px rgba(245,184,66,0.27); font-variant-numeric: tabular-nums; }
 .asc-rating-tier { display: inline-flex; align-items: center; gap: 6px; font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 0.2em; margin-top: 4px; }
.asc-rating-tier .gem { width: 6px; height: 6px; transform: rotate(45deg); }
.asc-daily { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.asc-daily-val { font-family: "JetBrains Mono", monospace; font-weight: 800; font-size: 17px; font-variant-numeric: tabular-nums; color: #f5f3fb; }
.asc-daily-val .max { color: #6b6b86; font-weight: 700; }
.asc-daily-val.spent { color: #ef4444; }
.asc-daily-pips { display: flex; align-items: center; gap: 5px; }
.asc-heart { display: inline-flex; color: rgba(255,255,255,0.13); }
.asc-heart svg { display: block; }
.asc-heart.on { color: #f5b842; filter: drop-shadow(0 0 4px rgba(245,184,66,0.5)); }
/* scroll body */
.asc-scroll { padding: 0 18px calc(env(safe-area-inset-bottom,0px) + 20px); }

/* band header */
.asc-band { display: flex; align-items: center; gap: 12px; padding: 20px 0 14px; }
.asc-band .rule { flex: 1; height: 1px; }
.asc-band .rule.l { background: linear-gradient(90deg, transparent, rgba(245,184,66,0.4)); }
.asc-band .rule.r { background: linear-gradient(90deg, rgba(245,184,66,0.4), transparent); }
.asc-band .range { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.2em; color: #6b6b86; }
.asc-band .name { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 14px; color: #f5f3fb; letter-spacing: 0.04em; white-space: nowrap; }
.asc-band .tier { display: inline-flex; align-items: center; justify-content: center; min-width: 20px; height: 20px; padding: 0 5px; border-radius: 6px; background: rgba(245,184,66,0.12); border: 1px solid rgba(245,184,66,0.4); font-family: "Cinzel", serif; font-weight: 700; font-size: 11px; color: #f5b842; }

/* spine row: [spine col] [card] */
.asc-row { display: flex; align-items: stretch; gap: 13px; }
.asc-spine { position: relative; width: 26px; flex: 0 0 auto; display: flex; justify-content: center; }
.asc-spine .line { position: absolute; left: 50%; transform: translateX(-50%); width: 2px; top: 0; bottom: 0; }
.asc-spine .line.cleared { background: rgba(245,184,66,0.4); }
.asc-spine .line.current { background: #f5b842; }
.asc-spine .line.locked  { background: rgba(255,255,255,0.09); }
