.asc-node { position: relative; z-index: 1; margin-top: 16px; }
.asc-node.shift { margin-top: 22px; }
.asc-node .dot-current { width: 16px; height: 16px; border-radius: 50%; background: #f5b842; border: 3px solid #0a0a1f; box-shadow: 0 0 0 2px #f5b842, 0 0 14px #f5b842; }
.asc-node .dot-cleared { width: 9px; height: 9px; border-radius: 50%; background: #f5b842; box-shadow: 0 0 7px rgba(245,184,66,0.53); }
.asc-node .dot-locked { width: 8px; height: 8px; border-radius: 50%; background: #0a0a1f; border: 1.5px solid rgba(255,255,255,0.18); }
.asc-node .diamond { width: 16px; height: 16px; transform: rotate(45deg); }
.asc-node .diamond.cleared { background: #f5b842; border: 2px solid #f5b842; box-shadow: 0 0 8px rgba(245,184,66,0.53); }
.asc-node .diamond.current { background: rgba(245,184,66,0.2); border: 2px solid #f5b842; box-shadow: 0 0 12px #f5b842; }
.asc-node .diamond.locked  { background: rgba(10,10,31,0.9); border: 2px solid #7e8597; }
.asc-card { flex: 1; min-width: 0; padding-bottom: 12px; }

/* floor eyebrow */
.asc-ftag { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 0.2em; color: #6b6b86; }
.asc-ftag.gold { color: #f5b842; }

/* difficulty pill */
.asc-diff { display: inline-flex; align-items: center; gap: 8px; }
.asc-diff .pill { display: inline-flex; align-items: center; gap: 6px; padding: 5px 11px; border-radius: 8px; font-family: "JetBrains Mono", monospace; font-size: 10px; font-weight: 800; letter-spacing: 0.15em; }
.asc-diff .pill.favored { background: rgba(52,211,153,0.1); border: 1px solid rgba(52,211,153,0.4); color: #34d399; }
.asc-diff .pill.even    { background: rgba(245,184,66,0.1); border: 1px solid rgba(245,184,66,0.4); color: #f5b842; }
.asc-diff .pill.tough   { background: rgba(239,68,68,0.1); border: 1px solid rgba(239,68,68,0.4); color: #ef4444; }
.asc-diff .pill .d { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.asc-diff .odds { font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 700; color: #6b6b86; letter-spacing: 0.04em; }
