.asc-faceoff .l { font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 700; letter-spacing: 0.15em; color: #6b6b86; margin-top: 3px; }
.asc-faceoff .vs { font-family: "Cinzel", serif; font-weight: 700; font-size: 13px; color: #6b6b86; }

/* current-floor card */
.asc-here-tab { display: inline-flex; align-items: center; gap: 6px; margin-left: 2px; padding: 4px 11px 6px; border-radius: 9px 9px 0 0; background: linear-gradient(180deg, #f7c558, #c08418); color: #1c1405; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.15em; position: relative; z-index: 1; }
.asc-cur { position: relative; padding: 15px 16px 16px; border-radius: 0 13px 14px 14px; background: linear-gradient(180deg, rgba(245,184,66,0.09), rgba(245,184,66,0.02) 60%, #0e0e24); border: 1.5px solid rgba(245,184,66,0.47); box-shadow: 0 12px 40px -14px rgba(245,184,66,0.4), inset 0 1px 0 rgba(255,255,255,0.06); }
.asc-cur-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.asc-cur-name { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 19px; color: #f5f3fb; margin-top: 4px; line-height: 1.1; }
.asc-arch { display: inline-flex; align-items: center; gap: 6px; padding: 3px 9px; border-radius: 7px; background: rgba(167,139,250,0.1); border: 1px solid rgba(167,139,250,0.35); font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 0.1em; color: #a78bfa; }
.asc-foe-med { width: 62px; height: 62px; flex: none; border-radius: 14px; overflow: hidden; display: flex; align-items: flex-end; justify-content: center; background: radial-gradient(120% 120% at 50% 30%, rgba(126,133,151,0.22), #04040d 74%); border: 1px solid rgba(126,133,151,0.5); }
.asc-foe-med svg { width: 38px; height: 50px; opacity: 0.9; }
.asc-cur-mid { margin-top: 13px; padding-top: 13px; border-top: 1px solid rgba(255,255,255,0.07); }
.asc-cur-cta { margin-top: 13px; }

/* compact cleared / locked rows */
.asc-mini { display: flex; align-items: center; gap: 11px; padding: 11px 14px; border-radius: 11px; }
.asc-mini.cleared { background: rgba(255,255,255,0.018); border: 1px solid rgba(255,255,255,0.07); }
.asc-mini.locked  { background: rgba(255,255,255,0.01); border: 1px dashed rgba(255,255,255,0.05); opacity: 0.5; }
.asc-mini.next    { background: rgba(255,255,255,0.022); border: 1px solid rgba(255,255,255,0.07); opacity: 0.92; }
.asc-mini .badge { width: 22px; height: 22px; flex: none; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
.asc-mini.cleared .badge { background: rgba(245,184,66,0.1); border: 1px solid rgba(245,184,66,0.27); color: #f5b842; }
.asc-mini.locked .badge, .asc-mini.next .badge { background: rgba(255,255,255,0.025); border: 1px solid rgba(255,255,255,0.08); color: #6b6b86; }
.asc-mini .mid { flex: 1; min-width: 0; }
.asc-mini .fname { font-family: "Cinzel", Georgia, serif; font-weight: 600; font-size: 13px; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.asc-mini.cleared .fname { color: #c8c6d8; }
.asc-mini.next .fname { color: #9090a8; }
.asc-mini.locked .fname { color: #6b6b86; letter-spacing: 0.2em; }
.asc-mini .rematch { display: inline-flex; align-items: center; gap: 5px; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 0.08em; color: #6b6b86; cursor: pointer; }
.asc-mini .pwr { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 700; color: #6b6b86; opacity: 0.7; }

/* boss card */
.asc-boss-ribbon { display: flex; align-items: center; justify-content: center; gap: 8px; margin: 6px 0 9px; }
.asc-boss-ribbon .rule { flex: 1; height: 1px; }
.asc-boss-ribbon .rule.l { background: linear-gradient(90deg, transparent, rgba(245,184,66,0.33)); }
.asc-boss-ribbon .rule.r { background: linear-gradient(90deg, rgba(245,184,66,0.33), transparent); }
.asc-boss-ribbon .lbl { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.25em; color: #f5b842; }
.asc-boss { position: relative; padding: 16px; border-radius: 16px; overflow: hidden; }
.asc-boss.current { background: radial-gradient(120% 80% at 50% 0%, rgba(245,184,66,0.12), transparent 55%), linear-gradient(180deg, #14122e, #0e0e24); border: 1.5px solid #f5b842; box-shadow: 0 16px 50px -16px rgba(245,184,66,0.53); }
.asc-boss.cleared { background: linear-gradient(180deg, rgba(245,184,66,0.07), #0e0e24); border: 1.5px solid #f5b842; box-shadow: 0 0 24px -10px rgba(245,184,66,0.4); opacity: 0.96; }
