.asc-load-exp .meta .nm { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 12.5px; color: #f5f3fb; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.asc-load-exp .meta .rr { font-family: "JetBrains Mono", monospace; font-size: 6.5px; font-weight: 800; letter-spacing: 0.15em; flex: none; }
.asc-load-exp .meta .sl { font-family: "JetBrains Mono", monospace; font-size: 7px; font-weight: 700; letter-spacing: 0.1em; color: #6b6b86; margin-top: 2px; }
