.asc-load-exp .pill { padding: 4px 8px; border-radius: 8px; background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.07); font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; }
.asc-load-totals { margin-top: 8px; padding: 7px 10px; border-radius: 9px; background: rgba(245,184,66,0.04); border: 1px solid rgba(245,184,66,0.18); display: flex; align-items: center; gap: 8px; }
