.asc-stakes .lbl.win { color: #34d399; }
.asc-stakes .row { display: flex; align-items: baseline; gap: 9px; margin-bottom: 6px; }
.asc-stakes .row .v { font-family: "JetBrains Mono", monospace; font-size: 10.5px; font-weight: 800; color: #f5b842; min-width: 34px; }
.asc-stakes .row .d { font-size: 10.5px; color: #c8c6d8; }
.asc-stakes .txt { font-size: 10.5px; line-height: 1.55; color: #9090a8; }
