}
/* END Ascent block */

/* ═══ W238 — Pokémon-composition battle screen (.pkb-*, scoped) ═══ */
.pkb { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.pkb-top { flex: none; text-align: center; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.22em; color: #6b6b86; padding: 2px 40px 8px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pkb-stage { position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column; justify-content: flex-end; gap: clamp(8px, 4.5vh, 38px); padding: 2px 4px 0; border-radius: 18px;   /* W253: flex gap 38px + ~19px player-row internal offset = sprite air gap ≤12% of stage */
  background: radial-gradient(120% 95% at 50% 28%, rgba(40,36,80,0.5) 0%, rgba(20,18,46,0.25) 45%, rgba(10,10,26,0) 75%); }
/* W241 — edge vignette pulls the eye into the combat band */
.pkb-stage::after { content: ''; position: absolute; inset: 0; border-radius: 18px; pointer-events: none; box-shadow: inset 0 0 56px 14px rgba(5,5,16,0.5); }
.pkb-stage.settle { animation: pkbSettle 0.4s ease-out; }
@keyframes pkbSettle { 0% { transform: scale(1.04); } 100% { transform: scale(1); } }
.pkb-stage.nudge { animation: pkbNudge 0.25s ease; }
@keyframes pkbNudge { 0%,100% { transform: translate(0,0); } 30% { transform: translate(-4px,2px); } 65% { transform: translate(3px,-1px); } }
/* W249 — tier backgrounds: full-bleed art BEHIND everything; the scrim wins
   every readability contest (heavier behind plates/text, lighter in the sky) */
.pkb-bgwrap { position: absolute; inset: 0; border-radius: 18px; overflow: hidden; }
.pkb-bgwrap .pkb-bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity 0.4s ease; }
.pkb-bgwrap .pkb-bg.on { opacity: 1; }
.pkb-bg-scrim { position: absolute; inset: 0; border-radius: 18px; pointer-events: none;
  background: linear-gradient(180deg, rgba(7,7,18,0.55) 0%, rgba(7,7,18,0.40) 26%, rgba(7,7,18,0.56) 55%, rgba(7,7,18,0.80) 100%); }
/* W249 — foe intro splash (sky band): name + archetype telegraph color */
.pkb-splash { position: absolute; top: 7%; left: 12px; right: 12px; text-align: center; opacity: 0; z-index: 3; pointer-events: none; }
.pkb-splash .nm { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 23px; line-height: 1.15; color: #f5f3fb; letter-spacing: 0.04em; text-shadow: 0 2px 16px rgba(0,0,0,0.9), 0 0 40px rgba(0,0,0,0.6); }
.pkb-splash .arch { margin-top: 5px; font-family: "JetBrains Mono", monospace; font-size: 10px; font-weight: 800; letter-spacing: 0.3em; text-shadow: 0 1px 10px rgba(0,0,0,0.9); }
/* W249 — in-arena victory floats (rise from the fallen foe) */
.pkb-vicfloat { position: absolute; transform: translate(-50%, 0); font-family: "JetBrains Mono", monospace; font-weight: 800; font-size: 15px; letter-spacing: 0.12em; color: #f5b842; text-shadow: 0 0 18px rgba(245,184,66,0.55), 0 2px 10px rgba(0,0,0,0.9); animation: pkbVicRise 0.9s ease-out forwards; pointer-events: none; white-space: nowrap; }
.pkb-vicfloat.unrated { color: #9090a8; font-size: 11px; text-shadow: 0 2px 10px rgba(0,0,0,0.9); }
.pkb-vicfloat.title { color: #a78bfa; font-size: 13px; text-shadow: 0 0 18px rgba(167,139,250,0.55), 0 2px 10px rgba(0,0,0,0.9); }
@keyframes pkbVicRise { 0% { opacity: 0; margin-top: 12px; } 15% { opacity: 1; } 78% { opacity: 1; } 100% { opacity: 0; margin-top: -36px; } }
/* shared ground plane — the space BETWEEN fighters reads as their floor */
.pkb-ground { position: absolute; inset: 12% 0 4%; pointer-events: none; border-radius: 18px; }
/* drifting motes (embers on boss floors) — transform/opacity only */
.pkb-motes { position: absolute; inset: 0; pointer-events: none; overflow: hidden; border-radius: 18px; }
.pkb-motes i { position: absolute; width: 3px; height: 3px; border-radius: 50%; background: rgba(200,198,216,0.35); animation: pkbMote 9s linear infinite; opacity: 0; }
.pkb-motes.embers i { background: rgba(245,140,66,0.5); box-shadow: 0 0 5px rgba(239,68,68,0.4); }
.pkb-motes i:nth-child(1) { left: 12%; bottom: 18%; animation-delay: 0s; }
.pkb-motes i:nth-child(2) { left: 30%; bottom: 32%; animation-delay: 1.6s; animation-duration: 11s; }
.pkb-motes i:nth-child(3) { left: 48%; bottom: 22%; animation-delay: 3.1s; animation-duration: 8s; }
.pkb-motes i:nth-child(4) { left: 64%; bottom: 38%; animation-delay: 4.4s; animation-duration: 12s; }
.pkb-motes i:nth-child(5) { left: 78%; bottom: 26%; animation-delay: 2.2s; animation-duration: 10s; }
.pkb-motes i:nth-child(6) { left: 90%; bottom: 34%; animation-delay: 5.5s; animation-duration: 9s; }
@keyframes pkbMote { 0% { transform: translate(0,0); opacity: 0; } 12% { opacity: 1; } 80% { opacity: 0.5; } 100% { transform: translate(-14px,-46px); opacity: 0; } }
.pkb-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; position: relative; z-index: 1; }
.pkb-row.foe { align-items: center; }      /* plate centers on the foe sprite's mass */
.pkb-row.you { align-items: flex-end; }
.pkb-row.you .pkb-plate { align-self: center; }
/* sprites + platforms — the Charmander treatment: big anchored fighters on a
   tight diagonal. Foe ~42vw (boss +15%); player ~1.7×, bottom-left, lower body
   cropped behind the text box. */
.pkb-spot { position: relative; flex: none; display: flex; align-items: flex-end; justify-content: center; transition: transform 0.18s ease, opacity 0.6s ease, filter 0.6s ease; }
/* W253 — the Charmander treatment, round 2: foe +25% (head eats the sky;
   feet stay on the platform — the spot grows upward from the row's bottom
   line). Width is the binding cap at phone width (~57vw). Bosses keep
   their +15% presence on top. */
.pkb-spot.foe { width: min(57vw, 250px); height: min(51vw, 23.5vh, 220px); }
.pkb-spot.foe.boss { width: min(64vw, 282px); height: min(57vw, 26.5vh, 248px); }
.pkb-spot.you { width: min(50vw, 214px); height: min(45vw, 21vh, 190px); margin-left: -10px; margin-bottom: -30px; z-index: 1; }
/* short screens: tighter air gap so the band never overflows the stage */
@media (max-height: 640px) { .pkb-stage { gap: clamp(6px, 4vh, 28px); } }
.pkb-spot .plat { position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); width: 94%; height: 26%; border-radius: 50%; border: 1px solid; }
/* soft contact shadow under each fighter */
.pkb-spot::before { content: ''; position: absolute; bottom: 2%; left: 50%; transform: translateX(-50%); width: 70%; height: 16%; border-radius: 50%; background: radial-gradient(closest-side, rgba(0,0,0,0.5), transparent 75%); }
.pkb-spot .spr { position: relative; width: 78%; height: 90%; display: flex; align-items: flex-end; justify-content: center; filter: drop-shadow(0 8px 12px rgba(0,0,0,0.55)); }
.pkb-spot .spr img, .pkb-spot .spr svg { width: 100%; height: 100%; object-fit: contain; }

/* ── W428 · Combat Attack VFX (ClaudeDesign) — the attacker's signature strike, mounted
   over the shared .pkb battle stage (Ascent + PvP). All scoped under .pkb-vfx so the inner
   class names can't collide; keyframes are pkbfx*-prefixed. ── */
.pkb-vfx { position: absolute; inset: 0; z-index: 6; pointer-events: none; overflow: hidden; }
.pkb-whitepop { position: absolute; inset: 0; z-index: 7; pointer-events: none; background: radial-gradient(circle at 50% 50%, rgba(255,255,255,.5), transparent 45%); opacity: 0; }
.pkb-whitepop.go { animation: pkbfxPop .3s ease-out both; }
