.pkb-vfx .burst .sp { position: absolute; left: 0; top: 0; width: 3px; height: 11px; border-radius: 2px; background: linear-gradient(var(--edge), var(--tint)); transform: translate(-50%, -50%) rotate(var(--a)) translateY(0); transform-origin: 50% 50%; opacity: 0; }
.pkb-strike.go .burst .flash { animation: pkbfxFlash .26s ease-out both var(--bd, 0s); }
