@keyframes pkbfxFlash { 0% { transform: translate(-50%,-50%) scale(0); opacity: 0; } 25% { opacity: 1; } 55% { transform: translate(-50%,-50%) scale(1.15); opacity: 1; } 100% { transform: translate(-50%,-50%) scale(1.4); opacity: 0; } }
@keyframes pkbfxRing { 0% { transform: translate(-50%,-50%) scale(.2); opacity: 0; } 30% { opacity: .9; } 100% { transform: translate(-50%,-50%) scale(2.4); opacity: 0; } }
@keyframes pkbfxSpark { 0% { opacity: 0; transform: translate(-50%,-50%) rotate(var(--a)) translateY(-4px) scaleY(.6); } 25% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%,-50%) rotate(var(--a)) translateY(-34px) scaleY(1.1); } }
.pkb-strike.crit .burst { transform: translate(-50%,-50%) scale(1.5); }
.pkb-strike.crit .burst .flash { background: radial-gradient(circle, #fff, #fff 30%, var(--tint) 55%, transparent 72%); }
/* melee arcs */
