/* blunt shock */
.pkb-vfx .shock { position: absolute; left: 0; top: 0; width: 40px; height: 40px; border-radius: 50%; border: 3px solid var(--edge); transform: translate(-50%,-50%) scale(0); box-shadow: 0 0 16px var(--tint); }
.pkb-strike.go .shock { animation: pkbfxShock .4s cubic-bezier(.2,.7,.3,1) both; }
@keyframes pkbfxShock { 0% { transform: translate(-50%,-50%) scale(.2); opacity: 0; } 22% { opacity: 1; } 100% { transform: translate(-50%,-50%) scale(3.2); opacity: 0; } }
.pkb-strike.fx-blunt .burst { transform: translate(-50%,-50%) scale(1.25); }
/* ranged projectile + trail */
