.pkb-vfx .proj svg { display: block; filter: drop-shadow(0 0 4px var(--tint)); }
.pkb-vfx .trail { position: absolute; left: 0; top: 0; width: 2px; height: 160px; transform: translate(-50%, 40px); transform-origin: 50% 100%; background: linear-gradient(var(--tint), transparent); opacity: 0; border-radius: 2px; }
.pkb-strike.go .proj { animation: pkbfxFly var(--ft, .19s) cubic-bezier(.45,0,.7,.4) both; }
