@keyframes pkbfxFly { from { transform: translate(-50%, 220px); } to { transform: translate(-50%, 0); } }
@keyframes pkbfxTrail { 0% { opacity: 0; transform: translate(-50%, 200px) scaleY(.2); } 40% { opacity: .8; } 100% { opacity: 0; transform: translate(-50%, 0) scaleY(1); } }
.pkb-strike.fx-bolt .proj svg { filter: drop-shadow(0 0 7px var(--tint)) drop-shadow(0 0 3px #fff); }
.pkb-strike.fx-bolt .trail { width: 3.5px; }
/* magic cast -> orb -> burst */
.pkb-vfx .cast { position: absolute; left: 0; top: 220px; transform: translate(-50%,-50%); }
.pkb-vfx .cast svg { display: block; }
