@keyframes pkbfxCast { 0% { opacity: 0; transform: scale(.3) rotate(-40deg); } 40% { opacity: 1; transform: scale(1.05) rotate(10deg); } 70% { opacity: .9; transform: scale(1) rotate(0); } 100% { opacity: 0; transform: scale(1.1) rotate(14deg); } }
.pkb-vfx .orb { position: absolute; left: 0; top: 0; width: 22px; height: 22px; border-radius: 50%; transform: translate(-50%, 220px) scale(0); background: radial-gradient(circle at 40% 35%, #fff, var(--tint) 55%, transparent 75%); box-shadow: 0 0 16px var(--tint), 0 0 6px #fff; }
