.pkb-strike.fx-frost .burst .flash { background: radial-gradient(circle, #fff, var(--tint) 45%, transparent 72%); }
.pkb-strike.fx-fire .burst .sp { width: 5px; height: 5px; border-radius: 50%; background: radial-gradient(circle, #fff, var(--tint) 60%, transparent); }
.pkb-vfx .ember { position: absolute; left: 0; top: 0; width: 4px; height: 4px; border-radius: 50%; background: var(--tint); opacity: 0; transform: translate(-50%,-50%); }
