@keyframes pkbfxEmber { 0% { opacity: 0; transform: translate(calc(-50% + var(--ex)), 0) scale(1); } 25% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(-50% + var(--ex)), -40px) scale(.3); } }
