@keyframes pkbReStatus { 0% { opacity: 0; transform: translate(-50%,6px) scale(.7); } 20% { opacity: 1; transform: translate(-50%,-10px) scale(1.1); } 34% { transform: translate(-50%,-16px) scale(1); } 100% { opacity: 0; transform: translate(-50%,-40px) scale(.95); } }
