.pkb-spot.r-hit .spk { animation: pkbReSpk .4s ease-out both; }
@keyframes pkbReRecoil { 12% { transform: translateX(-7px) rotate(-3deg); } 26% { transform: translateX(5px) rotate(2deg); } 42% { transform: translateX(-4px); } 60% { transform: translateX(2px); } 100% { transform: none; } }
@keyframes pkbReRed { 0% { filter: none; } 14% { filter: brightness(2.4) sepia(1) hue-rotate(-30deg) saturate(4); } 100% { filter: none; } }
@keyframes pkbReSpk { 0% { opacity: 0; transform: translate(-50%,-50%) rotate(var(--a)) translateY(-6px) scaleY(.5); } 25% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%,-50%) rotate(var(--a)) translateY(-40px) scaleY(1.1); } }
/* crit: stagger + white flash + shockring */
.pkb-spot.r-crit .spr { animation: pkbReStagger .5s cubic-bezier(.36,.07,.19,.97) both; }
.pkb-spot.r-crit .spr img, .pkb-spot.r-crit .spr svg { animation: pkbReWhite .45s ease-out both; }
.pkb-spot.r-crit .spk { animation: pkbReSpk .5s ease-out both; }
.pkb-rfx .shockring { width: 40px; height: 40px; border-radius: 50%; border: 3px solid #fff; transform: translate(-50%,-50%) scale(0); box-shadow: 0 0 16px #ff6b4a; }
.pkb-spot.r-crit .shockring { animation: pkbReShock .5s cubic-bezier(.2,.7,.3,1) both; }
@keyframes pkbReStagger { 8% { transform: translate(-12px,2px) rotate(-7deg); } 20% { transform: translate(10px,1px) rotate(5deg); } 34% { transform: translate(-7px,0) rotate(-3deg); } 50% { transform: translate(4px,0) rotate(1deg); } 68% { transform: translate(-2px,0); } 100% { transform: none; } }
@keyframes pkbReWhite { 0% { filter: none; } 10% { filter: brightness(3.5) saturate(0); } 30% { filter: brightness(1.6) sepia(1) hue-rotate(-30deg) saturate(3); } 100% { filter: none; } }
@keyframes pkbReShock { 0% { transform: translate(-50%,-50%) scale(.2); opacity: 0; } 22% { opacity: 1; } 100% { transform: translate(-50%,-50%) scale(3.4); opacity: 0; } }
/* dodge: slip aside + afterimage + swoosh */
.pkb-spot.r-dodge .spr { animation: pkbReDodge .5s cubic-bezier(.3,.9,.3,1) both; }
@keyframes pkbReDodge { 0% { transform: none; } 26% { transform: translateX(-30px) skewX(8deg); } 40% { transform: translateX(-30px) skewX(8deg); } 100% { transform: none; } }
.pkb-rfx .ghost { width: 60px; height: 60px; border-radius: 50%; transform: translate(-50%,-50%); opacity: 0; box-shadow: 0 0 0 1.6px rgba(255,255,255,.4); }
.pkb-spot.r-dodge .ghost { animation: pkbReGhost .5s ease-out both; }
@keyframes pkbReGhost { 0% { opacity: 0; } 20% { opacity: .4; } 100% { opacity: 0; transform: translate(-50%,-50%) translateX(8px); } }
.pkb-rfx .swoosh { width: 56px; height: 2px; background: linear-gradient(90deg, transparent, #f5f3fb); transform: translate(-50%,-50%); opacity: 0; border-radius: 2px; }
.pkb-spot.r-dodge .swoosh { animation: pkbReSwoosh .4s ease-out both; }
@keyframes pkbReSwoosh { 0% { opacity: 0; transform: translate(-20%,-50%) scaleX(.3); } 30% { opacity: .7; } 100% { opacity: 0; transform: translate(-90%,-50%) scaleX(1); } }
