@keyframes pkbReBraced { 16% { transform: translateY(3px) scale(.97); } 40% { transform: translateY(0) scale(1.01); } 100% { transform: none; } }
.pkb-rfx .ward { width: 110px; height: 110px; border-radius: 50%; transform: translate(-50%,-50%) scale(.7); opacity: 0; border: 2px solid #c084fc; box-shadow: inset 0 0 24px rgba(192,132,252,.35), 0 0 18px rgba(192,132,252,.3); }
.pkb-rfx .hexring { width: 110px; height: 110px; transform: translate(-50%,-50%); opacity: 0; }
.pkb-rfx .hexring svg { width: 110px; height: 110px; display: block; }
.pkb-spot.r-resist .ward, .pkb-spot.r-resist .hexring { animation: pkbReWard .6s ease-out both; }
@keyframes pkbReWard { 0% { opacity: 0; transform: translate(-50%,-50%) scale(.7); } 26% { opacity: 1; transform: translate(-50%,-50%) scale(1.04); } 100% { opacity: 0; transform: translate(-50%,-50%) scale(1.12); } }
/* defeat: fall + dissolve to ash */
.pkb-spot.r-defeat .spr { animation: pkbReDefeat 1s cubic-bezier(.5,0,.7,1) both; }
@keyframes pkbReDefeat { 0% { transform: none; opacity: 1; } 14% { transform: translateX(-8px) rotate(-4deg); } 30% { transform: translateX(6px) rotate(3deg); } 55% { transform: translateY(6px) rotate(-12deg) scale(.97); opacity: 1; } 100% { transform: translateY(20px) rotate(-22deg) scale(.9); opacity: 0; filter: grayscale(1) brightness(.5); } }
