.pkb-spot.r-defeat .ash { animation: pkbReAsh 1s ease-out both; }
@keyframes pkbReAsh { 0% { opacity: 0; transform: translate(calc(-50% + var(--ex)), 0); } 20% { opacity: .9; } 100% { opacity: 0; transform: translate(calc(-50% + var(--ex)), -48px) scale(.3); } }
