/* ── W431 · Focus / Powerup VFX (ClaudeDesign) — the empower beat on a self-buff cast, on the
   CASTER's .pkb-spot (Ascent + PvP). Tinted via --pc/--pcg. Keyframes pkbFo*-prefixed. ── */
/* charge: motes gather in, the actor swells, then a release burst */
.pkb-spot.p-charge .spr { animation: pkbFoCharge 1.1s cubic-bezier(.4,0,.3,1) both; }
@keyframes pkbFoCharge { 0% { transform: none; } 30% { transform: translateY(2px) scale(.97); } 55% { transform: translateY(0) scale(1.02); } 72% { transform: scale(1.06); } 100% { transform: scale(1.03); } }
.pkb-rfx .intake { width: 8px; height: 8px; border-radius: 50%; background: radial-gradient(circle, #fff, var(--pc,#f5b842) 60%, transparent); transform: translate(-50%,-50%) rotate(var(--a)) translateY(var(--r,60px)); opacity: 0; box-shadow: 0 0 8px var(--pc,#f5b842); }
.pkb-spot.p-charge .intake { animation: pkbFoIntake 1.1s cubic-bezier(.4,0,.5,1) both var(--id,0s); }
@keyframes pkbFoIntake { 0% { opacity: 0; transform: translate(-50%,-50%) rotate(var(--a)) translateY(72px) scale(.4); } 30% { opacity: 1; } 85% { opacity: 1; transform: translate(-50%,-50%) rotate(var(--a)) translateY(20px) scale(1); } 100% { opacity: 0; transform: translate(-50%,-50%) rotate(var(--a)) translateY(6px) scale(.3); } }
.pkb-rfx .chargering { width: 110px; height: 110px; border-radius: 50%; border: 2px dashed var(--pc,#f5b842); transform: translate(-50%,-50%) scale(1.4); opacity: 0; }
.pkb-spot.p-charge .chargering { animation: pkbFoChargeRing 1.1s ease-out both; }
@keyframes pkbFoChargeRing { 0% { opacity: 0; transform: translate(-50%,-50%) scale(1.5) rotate(0); } 40% { opacity: .8; } 100% { opacity: .9; transform: translate(-50%,-50%) scale(.92) rotate(140deg); } }
.pkb-rfx .chargeburst { width: 60px; height: 60px; border-radius: 50%; transform: translate(-50%,-50%) scale(0); background: radial-gradient(circle, #fff, var(--pc,#f5b842) 40%, transparent 70%); opacity: 0; }
.pkb-spot.p-charge .chargeburst { animation: pkbFoChargeBurst .5s ease-out both .85s; }
@keyframes pkbFoChargeBurst { 0% { opacity: 0; transform: translate(-50%,-50%) scale(.2); } 40% { opacity: .9; transform: translate(-50%,-50%) scale(1); } 100% { opacity: 0; transform: translate(-50%,-50%) scale(1.5); } }
/* buff applied: rune ring rises with up-arrows */
.pkb-spot.p-buff .spr { animation: pkbFoBuffBob .8s ease-out both; }
@keyframes pkbFoBuffBob { 20% { transform: translateY(-5px) scale(1.03); } 50% { transform: translateY(0) scale(1); } 100% { transform: none; } }
.pkb-rfx .buffring { width: 120px; height: 34px; transform: translate(-50%,-50%); opacity: 0; }
.pkb-rfx .buffring svg { width: 120px; height: 34px; display: block; }
.pkb-spot.p-buff .buffring { animation: pkbFoBuffRise .9s cubic-bezier(.3,1,.3,1) both; }
@keyframes pkbFoBuffRise { 0% { opacity: 0; transform: translate(-50%,40px) scale(.8); } 30% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%,-54px) scale(1.05); } }
.pkb-rfx .uparrow { width: 10px; height: 18px; transform: translate(-50%,-50%); opacity: 0; }
.pkb-rfx .uparrow svg { display: block; }
.pkb-spot.p-buff .uparrow { animation: pkbFoUp 1s ease-out both var(--id,0s); }
@keyframes pkbFoUp { 0% { opacity: 0; transform: translate(calc(-50% + var(--ex)),20px) scale(.6); } 25% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(-50% + var(--ex)),-46px) scale(1); } }
