  .pkb-spot.p-charge .spr, .pkb-spot.p-buff .spr { animation-duration: .001s !important; }
}
/* W254 — visual upscale on the FOE image only: grows upward from the feet
   (bottom origin) into the sky with ZERO layout movement — the box, plate,
   platform, and air gap are untouched. The art is ~35% narrower than its box,
   so the width absorbs the scale. On the img (not .spr) so the KO fall and
   lunge transforms compose cleanly. Player untouched (protected invariant). */
.pkb-spot.foe .spr img { transform: scale(1.18); transform-origin: 50% 100%; }
/* player faces up-right across the diagonal; darkened back-quarter + faint rim */
.pkb-spot.you .spr { transform: scaleX(-1); filter: brightness(0.8) saturate(0.92) drop-shadow(0 8px 12px rgba(0,0,0,0.6)) drop-shadow(-1px -1px 0 rgba(245,184,66,0.16)); }
.pkb-spot.lunge-you { transform: translate(16px, -10px); }
.pkb-spot.lunge-foe { transform: translate(-16px, 10px); }
.pkb-spot.shake { animation: pkbShake 0.25s ease; }
@keyframes pkbShake { 0%,100% { transform: translate(0,0); } 25% { transform: translate(-6px,0); } 50% { transform: translate(5px,0); } 75% { transform: translate(-3px,0); } }
/* W249 — KO is a transform on the SPRITE only: the spot/platform/plate never
   move (no layout drift), and the fall ends FULLY gone (no half-ghost). */
.pkb-spot.ko .spr { opacity: 0; transform: translateY(26px); filter: grayscale(1) brightness(0.5); transition: transform 0.6s ease, opacity 0.6s ease, filter 0.35s ease; }
.pkb-spot.you.ko .spr { transform: scaleX(-1) translateY(26px); }
/* info plates — glued to their owners */
.pkb-plate { flex: 1; min-width: 0; max-width: 215px; border-radius: 13px; background: rgba(14,14,36,0.92); border: 1px solid rgba(255,255,255,0.09); box-shadow: 0 6px 14px rgba(0,0,0,0.35); padding: 9px 11px 8px; transition: opacity 0.5s ease; }
.pkb-plate.ko { opacity: 0.4; }
.pkb-plate.healed { box-shadow: 0 0 16px rgba(52,211,153,0.35), 0 6px 14px rgba(0,0,0,0.35); }
.pkb-plate .nm { font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 800; letter-spacing: 0.14em; color: #c8c6d8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pkb-plate.you .nm { color: #f5b842; }
.pkb-plate .nm .wpn { color: #6b6b86; font-weight: 700; letter-spacing: 0.05em; }
.pkb-plate .hp { margin-top: 6px; height: 9px; border-radius: 5px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.08); overflow: hidden; }
.pkb-plate .hp i { display: block; height: 100%; border-radius: 4px; transform-origin: left center; transform: scaleX(1); transition: transform 0.5s cubic-bezier(0.2,0.8,0.2,1), background-color 0.3s ease; will-change: transform; }
.pkb-plate .hp i.ok   { background: linear-gradient(90deg, #1f9d6a, #34d399); box-shadow: 0 0 8px rgba(52,211,153,0.4); }
.pkb-plate .hp i.warn { background: linear-gradient(90deg, #c08418, #f5b842); box-shadow: 0 0 8px rgba(245,184,66,0.4); }
.pkb-plate .hp i.crit { background: linear-gradient(90deg, #b91c1c, #ef4444); box-shadow: 0 0 8px rgba(239,68,68,0.45); animation: arLowPulse 0.9s ease-in-out infinite; }
.pkb-plate .num { margin-top: 4px; font-family: "JetBrains Mono", monospace; font-size: 11.5px; font-weight: 800; color: #f5f3fb; font-variant-numeric: tabular-nums; }
.pkb-plate .num .mx { color: #6b6b86; font-weight: 700; font-size: 9px; }
.pkb-plate .chips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 5px; min-height: 14px; }
.pkb-plate .chips.pulse { animation: pkbChipPulse 0.45s ease; }
@keyframes pkbChipPulse { 0% { transform: scale(1); } 40% { transform: scale(1.12); } 100% { transform: scale(1); } }
.pkb-plate .chips .ar-st.cau { font-size: 8.5px; box-shadow: 0 0 8px rgba(52,211,153,0.45); }
/* fx layer — damage floats + toasts */
.pkb-fx { position: absolute; inset: 0; pointer-events: none; overflow: hidden; border-radius: 18px; z-index: 2; }
.pkb-float { position: absolute; transform: translate(-50%, 0); font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 22px; color: #f5f3fb; text-shadow: 0 2px 8px rgba(0,0,0,0.7); animation: pkbFloat 0.6s ease-out forwards; }
.pkb-float.you { color: #ffd98a; }
.pkb-float.foe { color: #ff9d9d; }
.pkb-float.crit { font-size: 30px; color: #f5b842; text-shadow: 0 0 18px rgba(245,184,66,0.65); animation: pkbFloatCrit 0.65s cubic-bezier(0.16,1.2,0.3,1) forwards; }
@keyframes pkbFloat { 0% { opacity: 0; margin-top: 6px; } 18% { opacity: 1; } 100% { opacity: 0; margin-top: -28px; } }
@keyframes pkbFloatCrit { 0% { opacity: 0; transform: translate(-50%,0) scale(1.6); } 22% { opacity: 1; transform: translate(-50%,0) scale(1); } 100% { opacity: 0; transform: translate(-50%,-30px) scale(1); } }
.pkb-toast { position: absolute; top: 38%; left: 50%; transform: translate(-50%,-50%); padding: 7px 16px; border-radius: 9px; font-family: "JetBrains Mono", monospace; font-size: 11px; font-weight: 800; letter-spacing: 0.18em; white-space: nowrap; background: rgba(10,10,26,0.88); border: 1px solid; animation: pkbToast 0.45s cubic-bezier(0.16,1.2,0.3,1) both; }
.pkb-toast.crit  { color: #f5b842; border-color: rgba(245,184,66,0.55); }
.pkb-toast.super { color: #34d399; border-color: rgba(52,211,153,0.55); }
.pkb-toast.weak  { color: #9090a8; border-color: rgba(144,144,168,0.45); }
.pkb-toast.miss  { color: #c8c6d8; border-color: rgba(200,198,216,0.4); }
.pkb-toast.cau   { color: #5eead4; border-color: rgba(94,234,212,0.55); }
@keyframes pkbToast { 0% { opacity: 0; transform: translate(-50%,-50%) scale(1.35); } 100% { opacity: 1; transform: translate(-50%,-50%) scale(1); } }
/* text box — typewriter narration, tap to complete */
.pkb-text { position: relative; z-index: 2; flex: none; margin-top: 10px; min-height: 52px; border-radius: 13px; background: rgba(14,14,36,0.96); border: 1px solid rgba(255,255,255,0.09); box-shadow: 0 -8px 16px rgba(5,5,16,0.45); padding: 10px 14px; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.pkb-text span { font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 15.5px; line-height: 1.35; color: #e3e0ee; }
/* move grid — thumb zone; locks during resolution */
.pkb-moves { flex: none; margin-top: 10px; }
.pkb-moves .ar-bmoves.lock { opacity: 0.45; pointer-events: none; filter: saturate(0.55); transition: opacity 0.2s ease; }
/* fast-forward indicator */
#arena-overlay.pkb-ff .pkb-text::after { content: '▶▶'; float: right; font-family: "JetBrains Mono", monospace; font-size: 10px; font-weight: 800; color: #f5b842; }
/* W243 — battle-audio volume sliders (settings) */
.aud-volrow input[type="range"] { -webkit-appearance: none; appearance: none; width: 132px; height: 4px; border-radius: 3px; background: rgba(255,255,255,0.12); outline: none; }
.aud-volrow input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 16px; height: 16px; border-radius: 50%; background: #f5b842; border: 2px solid #0e0e24; box-shadow: 0 0 6px rgba(245,184,66,0.5); }
/* reduced motion: collapse transforms to fades, keep the sequencing */
@media (prefers-reduced-motion: reduce) {
  .pkb-stage.nudge, .pkb-spot.shake, .pkb-stage.settle { animation: none; }
  .pkb-motes { display: none; }
  .pkb-spot.lunge-you, .pkb-spot.lunge-foe { transform: none; }
  .pkb-spot, .pkb-plate .hp i { transition-duration: 0.15s; }
  .pkb-float, .pkb-float.crit { animation: pkbFade 0.6s ease forwards; }
  .pkb-vicfloat { animation: pkbFade 0.9s ease forwards; }
  .pkb-bgwrap .pkb-bg { transition-duration: 0.01s; }
  .pkb-toast { animation: pkbFade 0.45s ease both; }
  @keyframes pkbFade { 0% { opacity: 0; } 25% { opacity: 1; } 100% { opacity: 0; } }
}

/* ── W260 — down-to-the-wire presentation + endgame telegraphs ─────────── */
/* clutch vignette: above the fighters (rows z1), below toasts/splash (z2+) */
.pkb-stage.clutch::before { content: ''; position: absolute; inset: 0; border-radius: 18px; pointer-events: none; z-index: 2;
