/* ── W268 — The Ascent: opening challenge + home climb tracker (ClaudeDesign) ── */
@media (prefers-reduced-motion: no-preference) {
  .ao-ember { animation: aoEmber 4.5s ease-in-out infinite; }
  .ao-beacon { animation: aoBeacon 3.4s ease-in-out infinite; }
  .ao-cta-glow { animation: aoCta 3.6s ease-in-out infinite; }
  .ao-rise { animation: aoRise 700ms cubic-bezier(.2,.8,.2,1) both; }
}
@keyframes aoEmber { 0%,100% { opacity:.3; } 50% { opacity:.7; } }
@keyframes aoBeacon { 0%,100% { opacity:.55; transform:translateX(-50%) scale(1); } 50% { opacity:1; transform:translateX(-50%) scale(1.12); } }
@keyframes aoCta { 0%,100% { box-shadow:0 4px 18px rgba(245,184,66,.22); } 50% { box-shadow:0 4px 26px rgba(245,184,66,.42); } }
@keyframes aoRise { 0% { opacity:0; transform:translateY(12px); } 100% { opacity:1; transform:translateY(0); } }

/* home climb tracker strip (replaces the W255 arena banner; same #sc-arena-btn) */
.sc-climb { width:100%; box-sizing:border-box; border-radius:16px; border:1px solid rgba(255,255,255,0.08);
  background:linear-gradient(180deg,#15132f,#0e0e24); box-shadow:0 8px 20px rgba(0,0,0,0.4);
  padding:16px 18px; display:flex; align-items:center; gap:18px; text-align:left; cursor:pointer;
  -webkit-tap-highlight-color:transparent; transition:transform 120ms ease, filter 120ms ease; }
.sc-climb:active { transform:scale(0.985); filter:brightness(1.06); }
.sc-climb-mid { display:flex; flex-direction:column; gap:7px; flex:1; min-width:0; }
.sc-climb-eyebrow { font-family:"JetBrains Mono",monospace; font-size:8px; font-weight:800; letter-spacing:2.5px; color:#f5b842; }
.sc-climb-floor { display:flex; align-items:baseline; gap:6px; }
.sc-climb-floor b { font-family:"Cinzel",Georgia,serif; font-size:30px; font-weight:700; color:#f5f3fb; line-height:1; }
.sc-climb-floor .of { font-family:"JetBrains Mono",monospace; font-size:11px; font-weight:700; color:#6b6b86; }
.sc-climb-floor .lbl { font-family:"JetBrains Mono",monospace; font-size:8px; font-weight:700; letter-spacing:1.5px; color:#6b6b86; margin-left:2px; }
.sc-climb-band { font-family:"Cormorant Garamond",Georgia,serif; font-style:italic; font-size:16px; color:#c8c6d8; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.sc-climb-band.summit { color:#f5b842; }
.sc-climb-right { display:flex; flex-direction:column; align-items:flex-end; gap:10px; flex:none; }
.sc-climb-cta { font-family:"JetBrains Mono",monospace; font-size:8px; font-weight:800; letter-spacing:1.5px; color:#9090a8; }
.sc-climb-cta.summit { color:#f5b842; }

/* W488 — home-screen Ranked PvP entry: slim, teal-accented (reads as combat), distinct from
   the gold Ascent climb banner. Matches the .sc-climb font family (Mono eyebrow + Cinzel title). */
.sc-pvp-row { margin-top:8px; }
.sc-pvp-btn { width:100%; box-sizing:border-box; display:flex; align-items:center; gap:13px; padding:12px 16px;
  border-radius:14px; border:1px solid rgba(45,212,191,0.30);
  background:linear-gradient(180deg, rgba(45,212,191,0.10), #0e1822); box-shadow:0 6px 16px rgba(0,0,0,0.34);
  text-align:left; cursor:pointer; -webkit-tap-highlight-color:transparent; transition:transform 120ms ease, filter 120ms ease; }
.sc-pvp-btn:active { transform:scale(0.985); filter:brightness(1.08); }
.sc-pvp-ico { flex:none; font-size:20px; line-height:1; filter:drop-shadow(0 0 6px rgba(45,212,191,0.4)); }
.sc-pvp-tx { display:flex; flex-direction:column; gap:2px; flex:1; min-width:0; }
.sc-pvp-eyebrow { font-family:"JetBrains Mono",monospace; font-size:8px; font-weight:800; letter-spacing:2.5px; color:#2dd4bf; }
.sc-pvp-title { font-family:"Cinzel",Georgia,serif; font-size:18px; font-weight:700; color:#eafaf6; line-height:1; }
.sc-pvp-chev { flex:none; font-size:20px; font-weight:700; color:rgba(45,212,191,0.7); }

/* W496 — ClaudeDesign "Merged Ascent + PvP Button" (Direction D). One "THE ARENA"
   umbrella card holding two independently-tappable inset tiles (gold ASCENT /
   teal RANKED PVP). Replaces the W255 .sc-climb banner + the W488 .sc-pvp-btn row
   (both now orphaned). Values ported 1:1 from the mock's inline styles. */
.sc-arena-merged {
  box-sizing:border-box; border-radius:16px; padding:13px 13px 14px;
  border:1px solid rgba(255,255,255,0.08); box-shadow:0 10px 30px rgba(0,0,0,0.35);
  background:linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.012));
}
.sc-am-head { display:flex; align-items:center; justify-content:center; gap:11px; margin-bottom:13px; }
.sc-am-word { font-family:"Cinzel",Georgia,serif; font-weight:700; font-size:11px; letter-spacing:3.5px;
  color:#f5b842; text-shadow:0 0 12px rgba(245,184,66,0.35); }
.sc-am-rule { width:26px; height:1px; flex:none; }
.sc-am-rule--l { background:linear-gradient(90deg, transparent, rgba(245,184,66,0.5)); }
.sc-am-rule--r { background:linear-gradient(90deg, rgba(94,234,212,0.5), transparent); }
.sc-am-tiles { display:flex; gap:11px; }
.sc-am-tile { flex:1; min-width:0; box-sizing:border-box; display:flex; flex-direction:column;
  border-radius:12px; padding:13px; text-align:left; cursor:pointer;
  appearance:none; -webkit-appearance:none; -webkit-tap-highlight-color:transparent;
  transition:transform 120ms ease, box-shadow 200ms ease, border-color 200ms ease; }
.sc-am-tile--climb { border:1px solid rgba(245,184,66,0.28);
  background:linear-gradient(160deg, rgba(245,184,66,0.12), rgba(245,184,66,0.025)); }
.sc-am-tile--duel  { border:1px solid rgba(94,234,212,0.28);
  background:linear-gradient(160deg, rgba(94,234,212,0.12), rgba(94,234,212,0.025)); }
.sc-am-tile:active { transform:translateY(1px); }
.sc-am-tile--climb:active, .sc-am-tile--climb:hover { box-shadow:0 6px 18px rgba(245,184,66,0.18); border-color:rgba(245,184,66,0.45); }
.sc-am-tile--duel:active,  .sc-am-tile--duel:hover  { box-shadow:0 6px 18px rgba(94,234,212,0.18); border-color:rgba(94,234,212,0.45); }
.sc-am-tile-top { display:flex; align-items:center; gap:9px; }
.sc-am-tower { flex:none; display:block; }
.sc-am-swords { flex:none; display:block; }
.sc-am-tx { min-width:0; }
.sc-am-kick { display:block; font-family:"JetBrains Mono",ui-monospace,monospace; font-size:8.5px;
  font-weight:800; letter-spacing:2.5px; text-transform:uppercase; }
.sc-am-kick--gold { color:#f5b842; }
.sc-am-kick--teal { color:#5eead4; }
.sc-am-floor { display:flex; align-items:baseline; gap:3px; margin-top:6px; }
.sc-am-floor b { font-family:"Cinzel",Georgia,serif; font-weight:800; font-size:26px; line-height:0.8; color:#f3f1fb; }
.sc-am-floor .of { font-family:"Cinzel",Georgia,serif; font-size:12px; color:#5f5d78; }
.sc-am-duel { display:block; font-family:"Cinzel",Georgia,serif; font-weight:700; font-size:17px; line-height:1; color:#f3f1fb; margin-top:6px; }
.sc-am-foot { display:flex; align-items:center; gap:4px; margin-top:11px; }
.sc-am-cta { font-family:"JetBrains Mono",ui-monospace,monospace; font-size:9px; font-weight:800; letter-spacing:1.6px; }
.sc-am-cta--gold { color:#f5b842; }
.sc-am-cta--teal { color:#5eead4; }
.sc-am-chev { display:block; flex:none; }
/* PvP-disabled fallback — a single climb tile shouldn't stretch full-bleed. */
.sc-arena-merged--solo .sc-am-tiles { justify-content:flex-start; }
.sc-arena-merged--solo .sc-am-tile { flex:0 1 60%; }

/* W490 — shared, subtle tappability cue for Status interactive elements (a dim "›"). v1 applies
   it to the always-tappable class chip; radar dots + conditional rank hero are a careful follow-up. */
.sc-tap-cue { display:inline-block; margin-left:4px; font-size:0.78em; line-height:1; font-weight:700;
  color:rgba(255,255,255,0.32); transition:color .18s ease; -webkit-user-select:none; user-select:none; pointer-events:none; }
.sc-hero-class:active .sc-tap-cue { color:currentColor; }
/* W493 — avatar tap cue: the avatar is an <img> (no child possible), so a small ✎ badge pinned to
   its lower-right corner inside the row signals "tap to change your look" (✎ = the app's edit verb,
   matching the name-edit cue). The radar's "TAP A STAT" hint is styled inline in the SVG. */
.sc-avatar-row { position:relative; }
.sc-avatar-cue { position:absolute; right:14px; bottom:6px; width:18px; height:18px;
  display:flex; align-items:center; justify-content:center; font-size:10px; line-height:1;
  color:rgba(255,255,255,0.6); background:rgba(15,12,30,0.74); border:1px solid rgba(255,255,255,0.18);
  border-radius:50%; pointer-events:none; }

/* opening challenge overlay (one-time, full-screen) */
.ao-opening { position:fixed; inset:0; z-index:99000; overflow:hidden; opacity:1;
  background:radial-gradient(120% 70% at 50% 0%, #12122c 0%, #07070f 62%);
  display:flex; flex-direction:column; transition:opacity 400ms ease; }
.ao-opening.is-hiding { opacity:0; }
.ao-open-portrait { position:absolute; top:0; left:0; right:0; height:66%; overflow:hidden;
  display:flex; align-items:center; justify-content:center;
  background:radial-gradient(80% 70% at 50% 30%, #1d1a3d 0%, #0d0c22 70%); }
/* W271 — CONTAIN, not cover: show the FULL figure (head-to-hem, no shin crop)
   as a centered portrait with negative space, instead of a width-cropped
   edge-to-edge blow-up. Sized to ~72% so it clears the THE ASCENT kicker and
   leaves the robe hem visible above the quote. Square 600×600 asset → width
   is the binding cap on a phone; the modest side air reads as composed. */
.ao-open-portrait img { width:auto; height:auto; max-width:90%; max-height:46vh;
  object-fit:contain; object-position:center; filter:drop-shadow(0 10px 34px rgba(0,0,0,0.5)); }
/* max-height in vh (not %) so SHORT screens (16:9) shrink the figure just
   enough to keep air above the head + the hem clear of the quote; on tall
   screens the 90% width cap binds first, so the composition is unchanged. */
.ao-open-portrait .ao-ember { position:absolute; width:3px; height:3px; border-radius:50%; background:#f5b842; }
.ao-open-scrim { position:absolute; inset:0; background:linear-gradient(180deg, rgba(7,7,15,0.35) 0%, rgba(7,7,15,0) 28%, rgba(7,7,15,0.55) 56%, #07070f 86%); }
.ao-open-body { position:relative; flex:1; display:flex; flex-direction:column; padding:max(58px,env(safe-area-inset-top)) 30px max(30px,env(safe-area-inset-bottom)); }
.ao-open-kicker { text-align:center; font-family:"JetBrains Mono",monospace; font-size:9px; font-weight:800; letter-spacing:4px; color:#f5b842; }
.ao-open-spacer { flex:1; }
.ao-open-line { text-align:center; margin-bottom:26px; }
.ao-open-line .q { font-family:"Cormorant Garamond",Georgia,serif; font-style:italic; font-size:25px; line-height:1.35; color:#c8c6d8; text-shadow:0 2px 12px rgba(0,0,0,0.8); }
.ao-open-line .by { display:block; margin-top:12px; font-family:"JetBrains Mono",monospace; font-size:8px; font-weight:700; letter-spacing:2.5px; color:#6b6b86; }
.ao-open-obj { display:flex; align-items:stretch; justify-content:center; margin-bottom:26px; }
.ao-open-obj .cell { flex:1; display:flex; flex-direction:column; align-items:center; gap:4px; padding:0 6px; }
.ao-open-obj .cell b { font-family:"Cinzel",Georgia,serif; font-size:26px; font-weight:700; color:#f5b842; line-height:1; }
.ao-open-obj .cell i { font-family:"JetBrains Mono",monospace; font-style:normal; font-size:7.5px; font-weight:800; letter-spacing:2px; color:#9090a8; }
.ao-open-obj .div { width:1px; background:rgba(255,255,255,0.08); margin:4px 0; }
.ao-open-cta { border:none; cursor:pointer; border-radius:13px; padding:17px 0; width:100%; text-align:center;
  background:linear-gradient(180deg,#f5b842,#c08418); font-family:"JetBrains Mono",monospace; font-size:12px; font-weight:800; letter-spacing:3.5px; color:#241502;
  -webkit-tap-highlight-color:transparent; }

/* ── W269 — The Summit (finale) + Hall of the Awakened (ClaudeDesign) ───── */
@keyframes fnHalo   { 0%,100% { opacity:.5; } 50% { opacity:.95; } }
@keyframes fnEmber  { 0%,100% { opacity:.25; transform: translateY(0); } 50% { opacity:.7; transform: translateY(-8px); } }
@keyframes fnCta    { 0%,100% { box-shadow: 0 4px 18px rgba(245,184,66,0.24); } 50% { box-shadow: 0 4px 28px rgba(245,184,66,0.46); } }
@keyframes fnRise   { 0% { opacity:0; transform: translateY(13px); } 100% { opacity:1; transform: translateY(0); } }
@keyframes fnStrike { 0% { opacity:0; transform: scale(1.35); letter-spacing: 12px; } 100% { opacity:1; transform: scale(1); } }

.fn-summit { position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.fn-portrait { position: absolute; top: 0; left: 0; right: 0; height: 64%; display: flex; align-items: center; justify-content: center;
  background: repeating-linear-gradient(45deg, rgba(245,184,66,0.045) 0 6px, rgba(245,184,66,0.012) 6px 12px), radial-gradient(70% 65% at 50% 26%, #211c12 0%, #0d0c20 72%); }
.fn-portrait img { max-width: 78%; max-height: 92%; object-fit: contain; object-position: center top; filter: drop-shadow(0 8px 30px rgba(0,0,0,0.6)); position: relative; z-index: 1; }
.fn-portrait .fn-halo { position: absolute; top: 30%; left: 50%; transform: translate(-50%,-50%); width: 210px; height: 210px; border-radius: 50%; background: radial-gradient(circle, rgba(245,184,66,0.18) 0%, transparent 68%); }
.fn-portrait .fn-ember { position: absolute; width: 3px; height: 3px; border-radius: 50%; background: #f5b842; }
.fn-portrait-scrim { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(7,7,15,0.25) 0%, rgba(7,7,15,0) 24%, rgba(7,7,15,0.5) 50%, #07070f 80%); }
.fn-summit-body { position: relative; z-index: 2; flex: 1; display: flex; flex-direction: column; padding: max(56px, env(safe-area-inset-top)) 30px max(28px, env(safe-area-inset-bottom)); }
.fn-summit-kick { text-align: center; font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 4px; color: #f5b842; }
.fn-summit-spacer { flex: 1; }
.fn-struck-line { text-align: center; margin-bottom: 22px; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 17px; line-height: 1.4; color: #9090a8; text-decoration: line-through; text-decoration-color: rgba(245,184,66,0.5); text-decoration-thickness: 1px; }
.fn-summit-answer { text-align: center; margin-bottom: 26px; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 25px; line-height: 1.34; color: #c8c6d8; text-shadow: 0 2px 12px rgba(0,0,0,0.8); }
.fn-summit-answer .by { margin-top: 11px; font-family: "JetBrains Mono", monospace; font-style: normal; font-size: 8px; font-weight: 700; letter-spacing: 2.5px; color: #6b6b86; }
.fn-trophy { text-align: center; margin-bottom: 20px; display: flex; flex-direction: column; align-items: center; gap: 9px; }
.fn-trophy .eyebrow { font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 800; letter-spacing: 3px; color: #9090a8; }
.fn-trophy-plate { clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 12px 100%, 0 50%); padding: 13px 30px;
  background: radial-gradient(120% 200% at 50% -40%, #2a2150 0%, #15122e 55%, #0e0e24 100%);
  border: 1.5px solid transparent; filter: drop-shadow(0 0 14px rgba(245,184,66,0.27)); }
.fn-trophy-name { font-family: "Cinzel", Georgia, serif; font-size: 23px; font-weight: 700; letter-spacing: 2px; white-space: nowrap;
  background-image: linear-gradient(180deg, #ffe9b0 0%, #f5b842 50%, #9a6c14 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 1px 0 rgba(0,0,0,0.6)); }
.fn-obj-complete { display: flex; align-items: stretch; justify-content: center; width: 250px; margin: 0 auto 9px; }
.fn-obj-complete .cell { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 4px; }
.fn-obj-complete .cell b { font-family: "Cinzel", Georgia, serif; font-size: 22px; font-weight: 700; color: #f5b842; line-height: 1; }
.fn-obj-complete .cell i { font-family: "JetBrains Mono", monospace; font-style: normal; font-size: 7.5px; font-weight: 800; letter-spacing: 2px; color: #9090a8; }
.fn-obj-complete .div { width: 1px; background: rgba(255,255,255,0.08); margin: 3px 0; }
.fn-obj-stamp { display: flex; align-items: center; justify-content: center; gap: 8px; margin-bottom: 22px; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 3.5px; color: #f5b842; }
.fn-obj-stamp .d { width: 5px; height: 5px; transform: rotate(45deg); background: #f5b842; border-radius: 1px; box-shadow: 0 0 7px #f5b842; }
.fn-cta { border: none; cursor: pointer; width: 100%; border-radius: 13px; padding: 16px 0; text-align: center; background: linear-gradient(180deg, #f5b842, #c08418); font-family: "JetBrains Mono", monospace; font-size: 11.5px; font-weight: 800; letter-spacing: 3px; color: #241502; -webkit-tap-highlight-color: transparent; box-shadow: 0 4px 18px rgba(245,184,66,0.24); }

.fn-hall { flex: 1; min-height: 0; display: flex; flex-direction: column; padding: max(54px, env(safe-area-inset-top)) 0 max(22px, env(safe-area-inset-bottom)); }
.fn-hall-head { display: flex; align-items: center; justify-content: center; gap: 10px; padding: 0 20px; }
.fn-hall-head .rule { width: 22px; height: 1px; background: rgba(255,255,255,0.08); }
.fn-hall-head .k { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 3px; color: #f5b842; }
.fn-hall-title { text-align: center; margin-top: 7px; font-family: "Cinzel", Georgia, serif; font-size: 25px; font-weight: 700; letter-spacing: 1.5px; color: #f5f3fb; }
.fn-hall-sub { text-align: center; margin-top: 6px; padding: 0 30px; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 14.5px; color: #9090a8; }
.fn-hall-plate { margin: 24px 22px 0; position: relative; border-radius: 6px; box-sizing: border-box; display: flex; align-items: center; gap: 14px; padding: 16px 18px;
  background: repeating-linear-gradient(100deg, rgba(255,255,255,0.016) 0 3px, transparent 3px 9px), radial-gradient(130% 100% at 30% -10%, #232038 0%, #16142c 55%, #100e22 100%);
  border: 1px solid rgba(245,184,66,0.4); box-shadow: 0 0 30px rgba(245,184,66,0.10), inset 0 1px 0 rgba(255,255,255,0.07), inset 0 -3px 10px rgba(0,0,0,0.5); }
.fn-hall-plate .med { width: 46px; height: 46px; border-radius: 10px; flex: none; overflow: hidden; background: #14122c; border: 1px solid rgba(245,184,66,0.4); }
.fn-hall-plate .med img { width: 100%; height: 100%; object-fit: cover; }
.fn-hall-plate .who { flex: 1; min-width: 0; }
.fn-hall-plate .you { font-family: "Cinzel", Georgia, serif; font-size: 20px; font-weight: 700; letter-spacing: 1px; color: #f5f3fb; }
.fn-hall-plate .chip { margin-top: 6px; display: inline-block; font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 800; letter-spacing: 2px; color: #f5b842; border: 1px solid rgba(245,184,66,0.4); border-radius: 999px; padding: 3px 10px 2px; }
.fn-hall-plate .when { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 1px; color: #6b6b86; flex: none; align-self: flex-start; }
.fn-hall-note { margin: 18px 28px 0; text-align: center; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 15px; line-height: 1.45; color: #9090a8; }
.fn-hall-foot { flex: 1; }
.fn-hall .ar-cta { margin: 0 20px; }

.tm-row--summit { border-color: rgba(245,184,66,0.45) !important; background: linear-gradient(180deg, rgba(245,184,66,0.07), rgba(245,184,66,0.02)) !important; }
.tm-prog--summit .n { color: #f5b842 !important; }
.tm-prog--summit .bar > span { background: linear-gradient(90deg, #c08418, #ffe9b0) !important; }

@media (prefers-reduced-motion: no-preference) {
  .fn-summit .fn-halo { animation: fnHalo 5s ease-in-out infinite; }
  .fn-summit .fn-ember { animation: fnEmber 4.5s ease-in-out infinite; }
  .fn-summit .fn-cta { animation: fnCta 3.6s ease-in-out infinite; }
  .fn-summit .fn-rise { animation: fnRise 760ms cubic-bezier(.2,.8,.2,1) both; }
  .fn-summit .fn-rise-2 { animation: fnRise 760ms cubic-bezier(.2,.8,.2,1) 220ms both; }
  .fn-summit .fn-rise-3 { animation: fnRise 760ms cubic-bezier(.2,.8,.2,1) 440ms both; }
  .fn-trophy-name { animation: fnStrike 620ms cubic-bezier(.16,1,.3,1) 520ms both; }
}

/* ── W270 — The Hall of the Awakened: the live Roll (ClaudeDesign A) ────── */
.fn-hall-youline { text-align: center; padding: 14px 0 4px; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 15px; color: #f5b842; }
.fn-roll { display: flex; flex-direction: column; gap: 7px; padding: 18px 20px 0; }
.fn-roll-row { border-radius: 11px; box-sizing: border-box; min-height: 56px; display: flex; align-items: center; gap: 14px; padding: 8px 16px;
  border: 1px solid rgba(255,255,255,0.08); background: rgba(255,255,255,0.025); }
.fn-roll-row.first { border-color: rgba(245,184,66,0.22); background: rgba(245,184,66,0.04); }
.fn-roll-row.you { border-color: rgba(245,184,66,0.5); background: linear-gradient(180deg, #241a10, #16110c); box-shadow: 0 0 16px rgba(245,184,66,0.12); }
.fn-roll-row .ord { display: flex; flex-direction: column; align-items: center; width: 34px; flex: none; }
.fn-roll-row .ord b { font-family: "Cinzel", Georgia, serif; font-size: 19px; font-weight: 700; color: #9090a8; line-height: 1; }
.fn-roll-row.first .ord b, .fn-roll-row.you .ord b { color: #f5b842; }
.fn-roll-row .ord i { font-family: "JetBrains Mono", monospace; font-style: normal; font-size: 5.5px; font-weight: 800; letter-spacing: 1px; color: #f5b842; margin-top: 2px; }
.fn-roll-row .who { display: flex; flex-direction: column; gap: 3px; flex: 1; min-width: 0; }
.fn-roll-row .who .nm { font-family: "JetBrains Mono", monospace; font-size: 13px; font-weight: 700; color: #c8c6d8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fn-roll-row.you .who .nm { font-family: "Cinzel", Georgia, serif; font-size: 16px; letter-spacing: 0.5px; color: #f5f3fb; }
.fn-roll-row .who .sub { font-family: "JetBrains Mono", monospace; font-size: 7.5px; font-weight: 700; letter-spacing: 1.5px; color: #6b6b86; }
.fn-roll-row .date { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 1px; color: #6b6b86; flex: none; }
.fn-roll-row.you .date { color: #f5b842; }
.fn-roll-divider { display: flex; align-items: center; gap: 10px; padding: 4px 8px; font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 700; letter-spacing: 2px; color: #6b6b86; }
.fn-roll-divider span { flex: 1; height: 1px; background: rgba(255,255,255,0.08); }

/* ── W274 — Steps ⇄ Highest Floor metric switch + finisher crown ──────────── */
/* The metric switch is the headline toggle (which board am I viewing); the
   .lb-rank-tabs below it stay the per-Steps sub-views (This Week / HoF / 100K).
   Slightly bolder than the sub-tabs so the two levels read as a hierarchy. */
.lb-metric-switch {
  display: flex;
  gap: 0;
  margin: 0 0 12px;
  padding: 3px;
  background: var(--bg-card);
  border: 1px solid rgba(245, 184, 66, 0.28);
  border-radius: 11px;
  font-size: 0.86rem;
}
.lb-metric-btn {
  flex: 1;
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  border: 0;
  color: var(--text-secondary);
  padding: 9px 10px;
  border-radius: 8px;
  font-weight: 700;
  letter-spacing: 0.3px;
  cursor: pointer;
  transition: background 0.14s ease, color 0.14s ease;
}
.lb-metric-btn:focus-visible { outline: 2px solid rgba(245, 184, 66, 0.7); outline-offset: 2px; }
.lb-metric-btn.is-active {
  background: linear-gradient(180deg, rgba(245,184,66,0.30), rgba(245,184,66,0.14));
  color: var(--text);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.10);
}
/* Finisher crown — sits between the alias and the value on Floor-100 rows. */
.lb-rank-crown {
