  margin: 0 6px 0 2px;
  flex: none;
  filter: drop-shadow(0 0 5px rgba(245,184,66,0.5));
}
.lb-rank-row--awakened {
  border-color: rgba(245,184,66,0.42) !important;
  background: linear-gradient(180deg, rgba(245,184,66,0.07), rgba(245,184,66,0.02)) !important;
}

/* ── W278 — Player Profile Card (ClaudeDesign "The Medallion") ──────────── */
.pc-head { display: flex; align-items: center; justify-content: space-between; padding: 4px 18px 0; flex: 0 0 auto; }
.pc-eyebrow { font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 700; letter-spacing: 2.2px; color: #a78bfa; }
/* W374 — swipe-to-close hint (replaces the X on the profile sheet) */
.pc-swipe-hint { display: inline-flex; align-items: center; gap: 5px; font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 700; letter-spacing: 1.8px; color: rgba(150,162,190,0.5); user-select: none; -webkit-user-select: none; }
.pc-swipe-hint b { font-size: 12px; line-height: 1; font-weight: 700; color: rgba(150,162,190,0.72); }
.pc-body { overflow-y: auto; -webkit-overflow-scrolling: touch; flex: 1 1 auto; }

/* hero block — radial glow stage behind the medallion */
.pc-hero { position: relative; padding: 30px 22px 8px; display: flex; flex-direction: column; align-items: center; }
.pc-hero::before { content: ''; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(85% 60% at 50% 14%, rgba(245,184,66,0.13), transparent 60%),
              radial-gradient(70% 55% at 50% 92%, rgba(167,139,250,0.16), transparent 72%); }
.pc-med-wrap { position: relative; }

/* the medallion — circular, gold gradient frame, glowing rarity ring, gem mounts */
.pc-med { position: relative; width: 176px; height: 176px; border-radius: 50%; flex: none;
  background: linear-gradient(150deg, #ffe9b0, var(--pc-ring, #f5b842) 42%, #c08418);
  padding: 4px; box-shadow: 0 0 34px rgba(245,184,66,0.40), inset 0 1px 0 rgba(255,255,255,0.28); }
.pc-med-ring { position: absolute; inset: -13px; border-radius: 50%; border: 1px solid var(--pc-ring, #f5b842); opacity: 0.55;
  box-shadow: 0 0 30px rgba(245,184,66,0.22), inset 0 0 20px rgba(245,184,66,0.12); }
@media (prefers-reduced-motion: no-preference) { .pc-med-ring { animation: pcRing 3.4s ease-in-out infinite; } }
@keyframes pcRing { 0%,100% { opacity: 0.4; } 50% { opacity: 0.85; } }
.pc-med-portrait { width: 100%; height: 100%; border-radius: 50%; overflow: hidden; position: relative;
  background: repeating-linear-gradient(135deg, #15132f, #15132f 7px, #0e0e24 7px, #0e0e24 14px);
  display: flex; align-items: center; justify-content: center; }
.pc-med-portrait img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 12%; display: block; }
.pc-gem { position: absolute; width: 16px; height: 16px; transform: translate(-50%,-50%) rotate(45deg);
  background: linear-gradient(135deg, #ffe9b0, var(--pc-ring, #f5b842)); box-shadow: 0 0 10px rgba(245,184,66,0.7); border-radius: 2px; }
.pc-gem.n { left: 50%; top: -13px; } .pc-gem.s { left: 50%; top: calc(100% + 13px); }
.pc-gem.w { left: -13px; top: 50%; } .pc-gem.e { left: calc(100% + 13px); top: 50%; }

/* rank crest — pinned to the base of the medallion, in the rank's own color */
.pc-crest { position: absolute; bottom: -12px; left: 50%; transform: translateX(-50%);
  width: 50px; height: 50px; border-radius: 13px; border: 3px solid #07070f;
  background: radial-gradient(circle at 50% 30%, var(--pc-rank), color-mix(in srgb, var(--pc-rank) 80%, black));
  display: flex; align-items: center; justify-content: center;
  font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 25px; color: #07070f; line-height: 1;
  box-shadow: 0 0 20px var(--pc-rank), 0 4px 12px rgba(0,0,0,0.5); }
.pc-med-floor { width: 200px; height: 22px; margin-top: 16px; border-radius: 50%;
  background: radial-gradient(ellipse, rgba(245,184,66,0.40), transparent 70%); filter: blur(5px); }

/* skin tag — signals the avatar is swappable / purchasable */
.pc-skintag { display: inline-flex; align-items: center; gap: 8px; padding: 5px 13px; margin-top: -2px;
  border-radius: 20px; background: rgba(245,184,66,0.08); border: 1px solid rgba(245,184,66,0.27); }
.pc-skintag i { width: 7px; height: 7px; transform: rotate(45deg); background: #f5b842; box-shadow: 0 0 7px #f5b842; }
.pc-skintag span { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 700; letter-spacing: 2px; color: #f5b842; }
/* ClaudeDesign "Hunter Profile - 100K Club" (W373) — the 100K STEP CLUB as a coveted gold seal */
.pc-club100k { position: relative; display: inline-flex; align-items: center; gap: 11px; margin-top: 12px;
  padding: 9px 18px 9px 13px; border-radius: 999px; overflow: hidden;
  background: linear-gradient(180deg, #ffe9b0 0%, #f5b842 46%, #c08418 100%);
  box-shadow: 0 0 22px rgba(245,184,66,0.40), 0 4px 14px rgba(0,0,0,0.45), inset 0 1px 0 rgba(255,255,255,0.6), inset 0 -2px 6px rgba(120,70,0,0.4);
  border: 1px solid rgba(255,236,180,0.7); }
.pc-club100k-shine { position: absolute; top: 0; bottom: 0; left: -40%; width: 28%;
  background: linear-gradient(105deg, transparent, rgba(255,255,255,0.85), transparent);
  transform: skewX(-18deg); animation: pc-club-sweep 3.4s ease-in-out infinite; pointer-events: none; }
@keyframes pc-club-sweep { 0% { left: -45%; } 55% { left: 125%; } 100% { left: 125%; } }
.pc-club100k-seal { position: relative; width: 30px; height: 30px; flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; }
.pc-club100k-seal-n { position: absolute; font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 9.5px; color: #ffe9b0; letter-spacing: -0.3px; text-shadow: 0 0 6px #f5b842; }
.pc-club100k-txt { position: relative; display: inline-flex; flex-direction: column; line-height: 1.1; }
.pc-club100k-t1 { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 14px; letter-spacing: 1.2px; color: #241502; }
.pc-club100k-t2 { font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 800; letter-spacing: 2.4px; color: rgba(40,21,2,0.66); margin-top: 2px; }
@media (prefers-reduced-motion: reduce) { .pc-club100k-shine { animation: none; opacity: 0; } }

/* W453 — Prestige (the S+ endgame): gold ✦ stars that the long-term player
   base wears to "stunt on noobs". Profile-card chip + inline leaderboard stars. */
.pc-prestige { display: inline-flex; align-items: center; gap: 7px; margin-top: 9px; padding: 4px 13px;
  border-radius: 999px; background: linear-gradient(180deg, rgba(245,184,66,0.22), rgba(192,132,24,0.10));
  border: 1px solid rgba(245,184,66,0.55); box-shadow: 0 0 16px rgba(245,184,66,0.25), inset 0 1px 0 rgba(255,236,180,0.35); }
.pc-prestige-stars { font-size: 14px; line-height: 1; color: #ffd76a; letter-spacing: 1px; text-shadow: 0 0 8px rgba(245,184,66,0.7); }
.pc-prestige-lbl { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 2px; color: #f5d99a; }
.lb-rank-prestige { margin-left: 5px; font-size: 11px; line-height: 1; color: #ffd76a; letter-spacing: 0.5px;
  text-shadow: 0 0 6px rgba(245,184,66,0.65); vertical-align: middle; white-space: nowrap; }

/* identity */
.pc-identity { padding: 6px 22px 0; display: flex; flex-direction: column; align-items: center; }
.pc-alias { font-family: "Cinzel", Georgia, serif; font-size: 27px; font-weight: 700; color: #f5f3fb; letter-spacing: 0.4px; }
.pc-shard { display: inline-flex; align-items: center; gap: 7px; margin-top: 9px; padding: 4px 11px 4px 9px; border-radius: 3px;
  background: color-mix(in srgb, var(--pc-tier) 8%, transparent); border: 1px solid color-mix(in srgb, var(--pc-tier) 34%, transparent); }
.pc-shard i { width: 8px; height: 8px; transform: rotate(45deg); background: var(--pc-tier); box-shadow: 0 0 8px var(--pc-tier); }
.pc-shard span { font-family: "JetBrains Mono", monospace; font-size: 10.5px; font-weight: 700; letter-spacing: 1.4px; color: var(--pc-tier); text-transform: uppercase; }
/* W385 — title (shard) + 100K Club seal share one centered row under the name */
.pc-idrow { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 10px; margin-top: 9px; }
.pc-idrow .pc-shard, .pc-idrow .pc-club100k { margin-top: 0; }

/* stat grid + floor bar */
.pc-stats { padding: 18px 22px 0; }
.pc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.pc-stat { background: rgba(255,255,255,0.035); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 13px 14px; display: flex; flex-direction: column; gap: 5px; }
.pc-stat .k { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 1.4px; color: #9090a8; }
.pc-stat .v { font-family: "Cinzel", Georgia, serif; font-size: 25px; font-weight: 700; color: #f5f3fb; line-height: 1; font-variant-numeric: tabular-nums; }
.pc-stat .v.gold { color: #f5b842; } .pc-stat .v.violet { color: #a78bfa; }
.pc-floor { margin-top: 9px; background: rgba(255,255,255,0.035); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 13px 14px; }
.pc-floor-top { display: flex; align-items: baseline; justify-content: space-between; }
.pc-floor-top .k { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 1.4px; color: #9090a8; }
.pc-floor-top .v { font-family: "Cinzel", Georgia, serif; font-size: 17px; font-weight: 700; color: #f5b842; }
.pc-floor-top .v small { color: #6b6b86; font-size: 12px; }
.pc-floor-bar { margin-top: 9px; height: 4px; border-radius: 3px; background: rgba(255,255,255,0.07); overflow: hidden; }
.pc-floor-bar i { display: block; height: 100%; background: linear-gradient(90deg, #c08418, #f5b842); box-shadow: 0 0 8px rgba(245,184,66,0.40); }

/* flavor + provenance */
.pc-flavor { margin: 16px 22px 0; display: flex; align-items: center; gap: 9px; padding: 11px 14px; border-radius: 10px;
  background: rgba(94,234,212,0.06); border: 1px solid rgba(94,234,212,0.2); }
.pc-flavor i { width: 7px; height: 7px; border-radius: 4px; background: #5eead4; box-shadow: 0 0 8px #5eead4; flex: none; }
.pc-flavor span { font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 15px; color: #f5f3fb; }
/* W440 — "Duel a Friend's Echo" action (teal Echo accent, shown for friends who've published a loadout) */
.pc-echo-btn { width: calc(100% - 44px); margin: 16px 22px 0; display: flex; align-items: center; gap: 12px; padding: 13px 15px;
  border-radius: 13px; cursor: pointer; text-align: left; -webkit-tap-highlight-color: transparent;
  background: linear-gradient(180deg, rgba(90,214,200,0.13), rgba(90,214,200,0.05));
  border: 1px solid rgba(90,214,200,0.34); box-shadow: 0 6px 20px -12px rgba(90,214,200,0.6), inset 0 1px 0 rgba(255,255,255,0.05);
  transition: transform .12s ease, border-color .12s ease, background .12s ease; }
.pc-echo-btn:active { transform: scale(0.985); background: linear-gradient(180deg, rgba(90,214,200,0.2), rgba(90,214,200,0.08)); border-color: rgba(90,214,200,0.5); }
.pc-echo-ic { flex: 0 0 auto; width: 30px; height: 30px; display: inline-flex; align-items: center; justify-content: center; filter: drop-shadow(0 0 6px rgba(90,214,200,0.55)); }
.pc-echo-ic svg { width: 26px; height: 26px; }
.pc-echo-tx { flex: 1 1 auto; display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pc-echo-tx b { font-family: "Cinzel", Georgia, serif; font-size: 15px; font-weight: 700; color: #d8fbf5; letter-spacing: 0.3px; }
.pc-echo-tx i { font-family: "JetBrains Mono", monospace; font-style: normal; font-size: 9.5px; font-weight: 600; letter-spacing: 0.6px; color: #7fd6cb; }
.pc-echo-go { flex: 0 0 auto; font-size: 22px; line-height: 1; color: #5ad6c8; opacity: 0.85; }
/* W444 — Arena Rating row (ClaudeDesign Hunter Profile refresh); --at = the hunter's tier accent */
.pc-arena { width: calc(100% - 44px); margin: 9px 22px 0; display: flex; align-items: center; gap: 13px; padding: 12px 13px;
  border-radius: 12px; cursor: pointer; text-align: left; -webkit-tap-highlight-color: transparent;
  background: rgba(255,255,255,0.035); border: 1px solid color-mix(in srgb, var(--at, #fbbf24) 30%, transparent);
  box-shadow: inset 0 0 24px color-mix(in srgb, var(--at, #fbbf24) 9%, transparent); transition: transform .12s ease; }
.pc-arena:active { transform: translateY(1px); }
.pc-arena-crest { width: 42px; height: 42px; flex: none; filter: drop-shadow(0 0 7px color-mix(in srgb, var(--at,#fbbf24) 45%, transparent)); }
.pc-arena-body { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.pc-arena-top { display: flex; align-items: baseline; justify-content: space-between; }
.pc-arena-top .k { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 1.4px; color: #9090a8; }
.pc-arena-global { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 0.6px; color: #c8c6d8; }
.pc-arena-global i { font-style: normal; color: #6b6b86; }
.pc-arena-mid { display: flex; align-items: baseline; gap: 8px; margin-top: 4px; }
.pc-arena-mid .tier { font-family: "Cinzel", Georgia, serif; font-size: 19px; font-weight: 700; color: var(--at, #fbbf24); letter-spacing: 0.4px; }
.pc-arena-mid .sub { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 1px; color: #6b6b86; }
.pc-arena-mid .elo { margin-left: auto; font-family: "Cinzel", Georgia, serif; font-size: 18px; font-weight: 700; color: #f5f3fb; line-height: 1; }
.pc-arena-mid .elo i { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; font-style: normal; color: #6b6b86; letter-spacing: 1px; }
.pc-arena-bar { display: block; margin-top: 8px; height: 3px; border-radius: 3px; background: rgba(255,255,255,0.07); overflow: hidden; }
.pc-arena-bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--at, #fbbf24), #ffe9b0); box-shadow: 0 0 8px color-mix(in srgb, var(--at,#fbbf24) 45%, transparent); }
.pc-arena-tonext { margin-top: 5px; font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 700; letter-spacing: 0.8px; color: #6b6b86; }
.pc-arena-chev { flex: none; font-size: 18px; line-height: 1; color: #6b6b86; }
.pc-prov { margin-top: 16px; padding: 12px 18px 4px; text-align: center; border-top: 1px solid rgba(255,255,255,0.05); }
.pc-prov span { font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 13px; color: #9090a8; }
.pc-skeleton { padding: 60px 22px; text-align: center; font-family: "JetBrains Mono", monospace; font-size: 11px; letter-spacing: 2px; color: #6b6b86; }

/* leaderboard rows become tappable */
.lb-rank-row[data-profile-alias], .lb-rank-row--me[data-profile-alias] { cursor: pointer; -webkit-tap-highlight-color: transparent; }

/* ── W279 — The Wardrobe (avatar skins, Layer 1) ────────────────────────── */
.wd-body { overflow-y: auto; -webkit-overflow-scrolling: touch; flex: 1 1 auto; padding: 4px 20px 8px; }
.wd-hero { display: flex; flex-direction: column; align-items: center; padding: 14px 0 6px; position: relative; }
.wd-hero::before { content: ''; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(70% 55% at 50% 22%, rgba(245,184,66,0.12), transparent 62%); }
.wd-hero .pc-med { width: 132px; height: 132px; }
.wd-hero-name { margin-top: 16px; font-family: "Cinzel", Georgia, serif; font-size: 18px; font-weight: 700; color: #f5f3fb; }
.wd-hero-sub { margin-top: 3px; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 2px; color: #6b6b86; text-transform: uppercase; }
.wd-section-label { display: flex; align-items: center; gap: 9px; margin: 20px 0 12px; }
.wd-section-label span { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 2.4px; color: #9090a8; flex: none; }
.wd-section-label .rule { flex: 1; height: 1px; background: rgba(255,255,255,0.08); }
.wd-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 11px; }
.wd-tile { display: flex; flex-direction: column; align-items: center; gap: 7px; cursor: pointer; -webkit-tap-highlight-color: transparent;
  background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 13px; padding: 12px 6px 9px; position: relative; transition: border-color 0.15s ease, background 0.15s ease; }
.wd-tile.is-equipped { border-color: rgba(245,184,66,0.6); background: rgba(245,184,66,0.07); box-shadow: 0 0 16px rgba(245,184,66,0.14); }
.wd-tile-av { width: 64px; height: 64px; border-radius: 50%; overflow: hidden; flex: none;
  background: #14122c; border: 2px solid rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; }
.wd-tile.is-equipped .wd-tile-av { border-color: #f5b842; box-shadow: 0 0 12px rgba(245,184,66,0.4); }
.wd-tile-av img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 12%; }
.wd-tile-name { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.6px; color: #c8c6d8; }
.wd-tile.is-equipped .wd-tile-name { color: #f5b842; }
.wd-tile-badge { position: absolute; top: 6px; right: 6px; font-family: "JetBrains Mono", monospace; font-size: 6.5px; font-weight: 800; letter-spacing: 0.8px; color: #07070f; background: #5eead4; border-radius: 5px; padding: 2px 5px; }
.wd-tile-tick { position: absolute; top: 6px; left: 6px; width: 16px; height: 16px; border-radius: 50%; background: #f5b842; color: #07070f; font-size: 11px; line-height: 16px; text-align: center; font-weight: 800; }
/* paid-shop teaser (Layer 2 lands here) */
.wd-shop .wd-tile { cursor: default; opacity: 0.5; }
.wd-shop .wd-tile-av { background: repeating-linear-gradient(135deg, #15132f, #15132f 6px, #0e0e24 6px, #0e0e24 12px); }
.wd-lock { font-size: 20px; color: #6b6b86; }
.wd-shop-note { margin-top: 12px; text-align: center; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 14px; color: #9090a8; }

/* ── W281 — premium skin tiles (Wardrobe SHOP; full art + rarity ring) ──── */
.wd-shop .wd-tile--premium { opacity: 1; cursor: default; }
.wd-tile--premium .wd-tile-av { border-width: 2px; background: #14122c; }
.wd-tile--mythic .wd-tile-av { border-color: #f5b842; box-shadow: 0 0 14px rgba(245,184,66,0.45); }
.wd-tile--legendary .wd-tile-av { border-color: #a78bfa; box-shadow: 0 0 14px rgba(167,139,250,0.45); }
.wd-tile-lockbadge { position: absolute; top: 6px; right: 6px; font-family: "JetBrains Mono", monospace; font-size: 6.5px; font-weight: 800; letter-spacing: 0.8px; color: #0e0e24; background: #9090a8; border-radius: 5px; padding: 2px 5px; }
.wd-tile-rarity { font-family: "JetBrains Mono", monospace; font-size: 7px; font-weight: 800; letter-spacing: 1.4px; }
.wd-tile--mythic .wd-tile-rarity { color: #f5b842; }
.wd-tile--legendary .wd-tile-rarity { color: #a78bfa; }

/* ── W283 — premium skin preview lightbox ──────────────────────────────── */
.wd-preview-overlay { position: fixed; inset: 0; z-index: 340; background: rgba(5,5,16,0.88);
  display: flex; align-items: center; justify-content: center; padding: 24px; animation: vn-fade 0.2s ease; }
.wd-preview-overlay.hidden { display: none !important; }
.wd-preview-card { display: flex; flex-direction: column; align-items: center; text-align: center; max-width: 320px; }
.wd-preview-art { width: 234px; height: 351px; display: flex; align-items: center; justify-content: center; filter: drop-shadow(0 14px 44px rgba(0,0,0,0.75)); }
.wd-preview-art img { max-width: 100%; max-height: 100%; object-fit: contain; }
.wd-preview-name { margin-top: 14px; font-family: "Cinzel", Georgia, serif; font-size: 24px; font-weight: 700; color: #f5f3fb; letter-spacing: 0.4px; }
.wd-preview-rarity { margin-top: 8px; font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 3px; padding: 3px 13px 2px; border-radius: 999px; border: 1px solid; }
.wd-preview-rarity--mythic { color: #f5b842; border-color: rgba(245,184,66,0.5); background: rgba(245,184,66,0.06); }
.wd-preview-rarity--legendary { color: #a78bfa; border-color: rgba(167,139,250,0.5); background: rgba(167,139,250,0.06); }
.wd-preview-blurb { margin-top: 13px; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: 16px; color: #c8c6d8; }
.wd-preview-soon { margin-top: 16px; font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 700; letter-spacing: 2px; color: #6b6b86; }
.wd-preview-hint { margin-top: 6px; font-family: "JetBrains Mono", monospace; font-size: 8px; letter-spacing: 1.5px; color: #4a4a5e; }

/* ══ W286 — Mythic rarity (the lone apex tier; only Nightfall holds it).
   Prismatic gold-magenta-cyan, brighter and busier than ultra-rare's
   purple/gold so the one Mythic in the game unmistakably outshines every
   other drop. Appended last → wins on source order over the ultra rules. ══ */
.bfs-last-drop[data-rarity="mythic"] { border-color: rgba(255,210,74,0.85); box-shadow: 0 0 16px rgba(255,210,74,0.55), 0 0 26px rgba(255,93,177,0.35), inset 0 1px 0 rgba(255,255,255,0.06); }
.bfs-last-drop[data-rarity="mythic"] .bfs-last-drop-meta { color: #ffd24a; }
.bfs-hunt-history-row-rarity[data-rarity="mythic"] { color: #ffd24a; background: rgba(255,210,74,0.12); border: 0.5px solid rgba(255,210,74,0.6); }
.archive-card--new-mythic { box-shadow: 0 0 20px rgba(255,210,74,0.6), 0 0 32px rgba(255,93,177,0.35), inset 0 1px 0 rgba(255,255,255,0.05); }
.market-sheet-art--mythic { border-color: rgba(255,210,74,0.6); background: radial-gradient(120% 120% at 50% 36%, rgba(255,210,74,0.22), rgba(255,93,177,0.12) 45%, #04040d 78%); box-shadow: 0 0 26px -5px rgba(255,210,74,0.55); }
.market-sheet-rarity--mythic { color: #ffd24a; text-shadow: 0 0 12px rgba(255,210,74,0.4), 0 0 18px rgba(255,93,177,0.3); }
.pokedex-card--mythic { border-color: rgba(255,210,74,0.7); box-shadow: 0 0 18px rgba(255,210,74,0.4), 0 0 26px rgba(255,93,177,0.28); }
.pokedex-card--mythic .pokedex-card-art { background: linear-gradient(135deg, rgba(94,234,255,0.18), rgba(255,93,177,0.20), rgba(255,210,74,0.20), rgba(0,0,0,0.40)); }
.reveal-overlay--mythic .reveal-particles { display: block; }
.reveal-overlay--mythic .reveal-card { border-image: linear-gradient(135deg, #5eeaff 0%, #ff5db1 35%, #ffd24a 70%, #5eeaff 100%) 1; box-shadow: 0 0 34px rgba(255,210,74,0.55), 0 0 34px rgba(255,93,177,0.5), 0 0 34px rgba(94,234,255,0.4); }
.reveal-overlay--showing.reveal-overlay--mythic .reveal-card { animation: reveal-card-materialize 0.6s 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards, reveal-card-ultra-pulse 2.6s 1.0s ease-in-out infinite; }
.reveal-overlay--mythic .reveal-card-rarity { background: linear-gradient(90deg, #5eeaff, #ff5db1, #ffd24a, #5eeaff); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.carddetail-overlay--mythic .carddetail-modal { border-image: linear-gradient(135deg, #5eeaff 0%, #ff5db1 35%, #ffd24a 70%, #5eeaff 100%) 1; box-shadow: 0 0 26px rgba(255,210,74,0.45), 0 0 26px rgba(255,93,177,0.42), 0 0 26px rgba(94,234,255,0.32); }
.carddetail-overlay--mythic .carddetail-rarity { background: linear-gradient(90deg, #5eeaff, #ff5db1, #ffd24a, #5eeaff); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.bro-reward--relic[data-rarity="mythic"] { border-color: #ffd24a; box-shadow: 0 0 26px rgba(255,210,74,0.5), 0 0 30px rgba(255,93,177,0.3), inset 0 1px 0 rgba(255,255,255,0.06); }
.bro-relic-rarity-pill[data-rarity="mythic"] { background: rgba(255,210,74,0.12); border-color: rgba(255,210,74,0.65); color: #ffd24a; box-shadow: 0 0 10px rgba(255,210,74,0.45); }

/* ════════════════════════════════════════════════════════════════════════
   W296 — NIGHTFALL · THE ECLIPSE CORONATION — mythic mega-rare reveal cinematic
   Ported from ClaudeDesign "Nightfall - The Eclipse Coronation". Scoped under
   .reveal-overlay--mythic; mega-* classes avoid the rare/ultra bloom's hooks.
   ════════════════════════════════════════════════════════════════════════ */
.reveal-overlay--mythic{
  --void:#04040d; --gold:#ffd24a; --gold-hot:#fff3c4;
  --vio-core:#6a3cff; --vio-core2:#7b2ff7; --vio-glow:#a855f7; --vio-glow2:#b07bff; --vio-umbra:#2a0d5e;
  --prism-cyan:#5eeaff; --prism-pink:#ff5db1; --prism-gold:#ffd24a;
  --blade-seam-x:50%;
  --mega-reveal:3000ms; --mega-mark:1200ms;
  --mr-serif:"Cinzel","Trajan Pro",Georgia,serif;
  --mr-mono:"JetBrains Mono",ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  background:radial-gradient(125% 95% at 50% 46%, #0b0a18 0%, var(--void) 52%, #000 100%);
}
/* hide the standard system-window chrome during the mythic cinematic */
.reveal-overlay--mythic > .reveal-systemline,
.reveal-overlay--mythic > .reveal-particles,
.reveal-overlay--mythic > .reveal-card,
.reveal-overlay--mythic > .reveal-continue-hint{ display:none !important; }
.reveal-overlay--mythic #sigil-bloom-stage > *{ pointer-events:none; }

.reveal-overlay--mythic .pre-snapshot{ position:absolute; inset:0; z-index:1; pointer-events:none;
  background:radial-gradient(60% 40% at 50% 30%, rgba(245,184,66,.10), transparent 60%), linear-gradient(180deg,#0d0c1e,#070710);
  display:flex; align-items:center; justify-content:center; filter:brightness(.5) saturate(.6); }
.reveal-overlay--mythic .pre-snapshot b{ font-family:var(--mr-mono); font-size:11px; letter-spacing:3px; color:#5a5a78; font-weight:700; }

.reveal-overlay--mythic .light-drain{ position:absolute; inset:0; z-index:6; pointer-events:none; --drain:150%;
  background:radial-gradient(circle at 50% 50%, transparent var(--drain), var(--void) calc(var(--drain) + 0.6%)); }

.reveal-overlay--mythic .mega-vignette{ position:absolute; inset:-10%; opacity:0;
  background:radial-gradient(ellipse at 50% 50%, transparent 38%, rgba(0,0,0,.85) 92%); }
.reveal-overlay--mythic .is-mega-phase-1 .mega-vignette,
.reveal-overlay--mythic .is-mega-phase-2 .mega-vignette{ animation:vignette-breathe 4s ease-in-out infinite; }
@keyframes vignette-breathe{ 0%,100%{opacity:0;} 50%{opacity:.06;} }

.reveal-overlay--mythic .mega-rays{ position:absolute; left:50%; top:50%; width:200vmax; height:200vmax;
  transform:translate(-50%,-50%); opacity:0; mix-blend-mode:screen; }
.reveal-overlay--mythic .mega-rays--umbral{
  background:conic-gradient(from 0deg, transparent 0 6deg, rgba(123,47,247,.10) 7deg 9deg, transparent 10deg 30deg,
    rgba(123,47,247,.07) 31deg 33deg, transparent 34deg 60deg, rgba(106,60,255,.10) 61deg 63deg, transparent 64deg 92deg,
    rgba(123,47,247,.07) 93deg 95deg, transparent 96deg); }
.reveal-overlay--mythic .is-mega-phase-1 .mega-rays--umbral{ animation:rays-bleed 26s linear infinite, rays-fade-umbral 3s ease forwards .8s; }
.reveal-overlay--mythic .is-mega-phase-2 .mega-rays--umbral{ opacity:.5; animation:rays-bleed 26s linear infinite; }
@keyframes rays-bleed{ to{ transform:translate(-50%,-50%) rotate(360deg);} }
@keyframes rays-fade-umbral{ from{opacity:0;} to{opacity:.45;} }
.reveal-overlay--mythic .mega-rays--prism{
  background:conic-gradient(from 0deg, var(--prism-cyan) 0 1.5deg, transparent 1.5deg 15deg, var(--prism-pink) 15deg 16.5deg,
    transparent 16.5deg 30deg, var(--prism-gold) 30deg 31.5deg, transparent 31.5deg 45deg, var(--vio-glow) 45deg 46.5deg, transparent 46.5deg 60deg);
  -webkit-mask:radial-gradient(circle, transparent 8%, #000 9%, #000 46%, transparent 52%);
          mask:radial-gradient(circle, transparent 8%, #000 9%, #000 46%, transparent 52%); }
.reveal-overlay--mythic .is-strike-2 .mega-rays--prism{ animation:rays-fan 900ms cubic-bezier(.16,1,.3,1) forwards; }
@keyframes rays-fan{ 0%{opacity:0; transform:translate(-50%,-50%) scale(.35) rotate(-12deg);} 35%{opacity:.85;}
  100%{opacity:0; transform:translate(-50%,-50%) scale(1.15) rotate(14deg);} }

.reveal-overlay--mythic .mega-silhouette{ position:absolute; left:50%; bottom:-2vh; width:64vh; height:74vh; transform:translateX(-50%); opacity:0; z-index:1; }
.reveal-overlay--mythic .is-mega-phase-1 .mega-silhouette{ animation:erebus-loom 2.6s ease forwards 1.4s; }
.reveal-overlay--mythic .is-mega-phase-2 .mega-silhouette{ opacity:.9; }
.reveal-overlay--mythic .is-mega-phase-3 .mega-silhouette,
.reveal-overlay--mythic .is-mega-phase-4 .mega-silhouette{ opacity:0; transition:opacity 1.2s ease; }
@keyframes erebus-loom{ from{opacity:0; transform:translateX(-50%) translateY(4vh) scale(1.04);} to{opacity:.92; transform:translateX(-50%) translateY(0) scale(1);} }
.reveal-overlay--mythic .mega-silhouette .body{ position:absolute; left:50%; bottom:0; width:58%; height:64%; transform:translateX(-50%);
  background:radial-gradient(60% 80% at 50% 20%, #0a0716 0%, #050409 70%, transparent 100%); border-radius:46% 46% 0 0 / 60% 60% 0 0;
  box-shadow:0 0 60px 10px #000, inset 0 30px 60px rgba(123,47,247,.18); }
.reveal-overlay--mythic .mega-silhouette .head{ position:absolute; left:50%; bottom:54%; width:20%; aspect-ratio:1; transform:translateX(-50%);
  background:radial-gradient(circle at 50% 40%, #0b0818, #050409 72%); border-radius:50%; box-shadow:0 -2px 18px rgba(168,85,247,.30), inset 0 6px 14px rgba(123,47,247,.20); }
.reveal-overlay--mythic .mega-silhouette .crown{ position:absolute; left:50%; bottom:72%; width:30%; height:11%; transform:translateX(-50%); background:#070512;
  clip-path:polygon(0% 100%,0% 36%,14% 64%,28% 0%,42% 56%,50% 12%,58% 56%,72% 0%,86% 64%,100% 36%,100% 100%); box-shadow:0 -4px 16px rgba(168,85,247,.45); }
.reveal-overlay--mythic .mega-silhouette .eye{ position:absolute; left:50%; bottom:60%; width:9px; height:9px; transform:translateX(-50%); border-radius:50%; background:var(--vio-glow2); opacity:0; }
.reveal-overlay--mythic .is-mega-phase-1 .mega-silhouette .eye{ animation:eye-ignite 700ms ease forwards 2.5s; }
.reveal-overlay--mythic .is-mega-phase-2 .mega-silhouette .eye{ opacity:1; box-shadow:0 0 16px 4px var(--vio-glow), 0 0 40px 8px rgba(123,47,247,.7); }
@keyframes eye-ignite{ from{opacity:0; box-shadow:0 0 0 0 var(--vio-glow);} to{opacity:1; box-shadow:0 0 16px 4px var(--vio-glow), 0 0 40px 8px rgba(123,47,247,.7);} }

.reveal-overlay--mythic .black-sun{ position:absolute; left:50%; top:50%; width:33vh; height:33vh; transform:translate(-50%,-50%) scale(.55); opacity:0; z-index:2; }
.reveal-overlay--mythic .is-mega-phase-1 .black-sun{ animation:sun-ignite 1.6s cubic-bezier(.22,1,.36,1) forwards 1.7s; }
.reveal-overlay--mythic .is-mega-phase-2 .black-sun{ opacity:1; transform:translate(-50%,-50%) scale(1); animation:sun-collapse 1.8s ease forwards; }
.reveal-overlay--mythic .is-mega-phase-3 .black-sun,
.reveal-overlay--mythic .is-mega-phase-4 .black-sun{ opacity:0; transition:opacity .8s ease; }
@keyframes sun-ignite{ from{opacity:0; transform:translate(-50%,-50%) scale(.55);} 60%{opacity:1;} to{opacity:1; transform:translate(-50%,-50%) scale(1);} }
@keyframes sun-collapse{ from{opacity:1; transform:translate(-50%,-50%) scale(1);} to{opacity:0; transform:translate(-50%,-50%) scale(.2) scaleX(.04);} }
.reveal-overlay--mythic .black-sun .disc{ position:absolute; inset:0; border-radius:50%; background:#000; box-shadow:0 0 50px 14px #000, inset 0 0 30px 6px #000; }
.reveal-overlay--mythic .black-sun .corona{ position:absolute; inset:-3%; border-radius:50%;
  background:radial-gradient(circle, transparent 58%, rgba(255,210,74,.20) 60%, var(--gold) 63.5%, var(--gold-hot) 65.5%, rgba(255,210,74,.25) 68%, transparent 74%);
  filter:blur(1.4px); animation:corona-breathe 3.2s ease-in-out infinite, corona-spin 60s linear infinite; }
@keyframes corona-breathe{ 0%,100%{filter:blur(1.4px); opacity:.85; transform:scale(1);} 50%{filter:blur(2.6px); opacity:1; transform:scale(1.018);} }
@keyframes corona-spin{ to{ transform:rotate(360deg);} }
.reveal-overlay--mythic .black-sun .beads{ position:absolute; inset:-3%; animation:beads-crawl 14s linear infinite; }
.reveal-overlay--mythic .black-sun .beads i{ position:absolute; top:50%; left:50%; width:5px; height:5px; margin:-2.5px; border-radius:50%;
  background:var(--gold-hot); box-shadow:0 0 8px 2px var(--gold), 0 0 16px 4px rgba(255,210,74,.7); }
.reveal-overlay--mythic .black-sun .beads i:nth-child(1){ transform:rotate(20deg) translateX(16.5vh); }
.reveal-overlay--mythic .black-sun .beads i:nth-child(2){ transform:rotate(160deg) translateX(16.5vh); width:3px; height:3px; }
.reveal-overlay--mythic .black-sun .beads i:nth-child(3){ transform:rotate(275deg) translateX(16.5vh); }
@keyframes beads-crawl{ to{ transform:rotate(360deg);} }

.reveal-overlay--mythic .eclipse-seam{ position:absolute; left:50%; top:50%; width:3px; height:46vh; transform:translate(-50%,-50%) scaleY(0); transform-origin:50% 50%; opacity:0; z-index:4; border-radius:3px;
  background:linear-gradient(180deg, transparent, var(--gold-hot) 16%, var(--gold) 50%, var(--gold-hot) 84%, transparent); box-shadow:0 0 12px var(--gold), 0 0 34px rgba(123,47,247,.65); }
.reveal-overlay--mythic .is-mega-phase-2 .eclipse-seam{ animation:seam-form 1.5s cubic-bezier(.22,1,.36,1) forwards; }
@keyframes seam-form{ 0%{opacity:0; transform:translate(-50%,-50%) scaleY(0);} 30%{opacity:1;} 100%{opacity:1; transform:translate(-50%,-50%) scaleY(1);} }
.reveal-overlay--mythic .is-mega-phase-3 .eclipse-seam,
.reveal-overlay--mythic .is-mega-phase-4 .eclipse-seam{ opacity:0; transition:opacity .7s ease; }

.reveal-overlay--mythic .mega-particles{ position:absolute; inset:0; z-index:3; }
.reveal-overlay--mythic .mega-mote{ position:absolute; left:50%; top:50%; width:3px; height:3px; border-radius:50%; opacity:0; will-change:transform,opacity; animation:mote-forge 1.8s cubic-bezier(.42,0,.2,1) forwards; }
@keyframes mote-forge{ 0%{opacity:0; transform:translate(calc(-50% + var(--sx)), calc(-50% + var(--sy))) scale(.5);} 18%{opacity:1;} 100%{opacity:.9; transform:translate(-50%, calc(-50% + var(--ty))) scale(.85);} }
.reveal-overlay--mythic .mega-mote--drift{ animation:mote-drift 6.5s ease-in-out infinite; }
@keyframes mote-drift{ 0%{opacity:0; transform:translate(calc(-50% + var(--sx)), calc(-50% + var(--sy))) scale(.7);} 20%{opacity:.7;} 80%{opacity:.5;}
  100%{opacity:0; transform:translate(calc(-50% + var(--sx) + var(--dx)), calc(-50% + var(--sy) - 90px)) scale(1);} }

.reveal-overlay--mythic .mega-flash{ position:absolute; left:50%; top:50%; transform:translate(-50%,-50%); opacity:0; z-index:5; }
.reveal-overlay--mythic .mega-flash--1{ width:6px; height:60vh; background:linear-gradient(180deg, transparent, var(--gold-hot), var(--gold), var(--gold-hot), transparent); box-shadow:0 0 26px 6px var(--gold), 0 0 60px 16px rgba(255,210,74,.6); }
.reveal-overlay--mythic .is-strike-1 .mega-flash--1{ animation:strike-wedge 220ms ease-out forwards; }
@keyframes strike-wedge{ 0%{opacity:0; transform:translate(-50%,-50%) scaleY(.2);} 40%{opacity:1;} 100%{opacity:.0; transform:translate(-50%,-50%) scaleX(2.4) scaleY(1);} }
.reveal-overlay--mythic .mega-flash--2{ width:64vh; height:64vh; border-radius:50%; background:radial-gradient(circle, #fff 0%, var(--gold-hot) 14%, rgba(255,210,74,.5) 28%, transparent 56%); }
.reveal-overlay--mythic .is-strike-2 .mega-flash--2{ animation:strike-bloom 360ms ease-out forwards; }
@keyframes strike-bloom{ 0%{opacity:0; transform:translate(-50%,-50%) scale(.2);} 18%{opacity:1;} 100%{opacity:0; transform:translate(-50%,-50%) scale(1.1);} }
.reveal-overlay--mythic .mega-flash--ghost{ width:14vh; height:52vh; border-radius:40% 40% 46% 46%/8% 8% 30% 30%; border-left:2px solid var(--gold-hot); border-right:2px solid var(--vio-glow); }
.reveal-overlay--mythic .is-strike-2 .mega-flash--ghost{ animation:ghost-echo 520ms ease-out forwards; }
@keyframes ghost-echo{ 0%{opacity:0; transform:translate(-50%,-50%) scaleY(.7);} 30%{opacity:.7;} 60%{opacity:.35; transform:translate(-50%,-50%) scaleY(1) translateX(3px);} 100%{opacity:0; transform:translate(-50%,-50%) scaleY(1.02) translateX(-3px);} }

/* is-kick rides the STAGE (not the overlay) so it stays a single-element hook */
.reveal-overlay--mythic #sigil-bloom-stage.is-kick{ animation:screen-kick 140ms ease-out; }
@keyframes screen-kick{ 0%{transform:translateY(0);} 30%{transform:translateY(-4px);} 100%{transform:translateY(0);} }

.reveal-overlay--mythic .mega-systemline{ position:absolute; left:50%; top:50%; width:78vw; max-width:520px; height:2px; transform:translate(-50%,-50%) scaleX(0); transform-origin:50% 50%; opacity:0; z-index:5;
  background:linear-gradient(90deg, transparent, var(--gold) 18%, var(--gold-hot) 50%, var(--gold) 82%, transparent); box-shadow:0 0 10px var(--gold), 0 1px 14px rgba(123,47,247,.7); }
.reveal-overlay--mythic .is-mega-phase-0 .mega-systemline{ animation:systemline-snap 200ms cubic-bezier(.2,.8,.2,1) forwards; }
.reveal-overlay--mythic .is-mega-phase-1 .mega-systemline{ opacity:1; transform:translate(-50%,-50%) scaleX(1); }
@keyframes systemline-snap{ 0%{opacity:0; transform:translate(-50%,-50%) scaleX(0);} 60%{opacity:1;} 100%{opacity:1; transform:translate(-50%,-50%) scaleX(1);} }
.reveal-overlay--mythic .is-mega-phase-2 .mega-systemline,
.reveal-overlay--mythic .is-mega-phase-3 .mega-systemline,
.reveal-overlay--mythic .is-mega-phase-4 .mega-systemline{ opacity:0; transform:translate(-50%,-50%) scaleX(1); transition:opacity .5s ease; }

.reveal-overlay--mythic .mega-wordmark{ position:absolute; left:0; right:0; top:14%; text-align:center; z-index:5; }
.reveal-overlay--mythic .mega-wordmark-kicker{ font-family:var(--mr-mono); font-size:11px; letter-spacing:5px; font-weight:700; color:var(--gold); opacity:0; text-shadow:0 0 12px rgba(255,210,74,.6); }
.reveal-overlay--mythic .mega-wordmark-whisper{ margin-top:10px; font-family:"Cormorant Garamond",Georgia,serif; font-style:italic; font-size:15px; letter-spacing:2px; color:var(--vio-glow2); opacity:0; }
.reveal-overlay--mythic .mega-wordmark.is-kicker .mega-wordmark-kicker{ animation:type-in 700ms steps(24,end) forwards; }
.reveal-overlay--mythic .mega-wordmark.is-whisper .mega-wordmark-whisper{ animation:whisper-in 1100ms ease forwards; }
@keyframes type-in{ from{opacity:0; clip-path:inset(0 100% 0 0);} 10%{opacity:1;} to{opacity:1; clip-path:inset(0 0 0 0);} }
@keyframes whisper-in{ from{opacity:0; transform:translateY(4px);} to{opacity:.9; transform:translateY(0);} }
.reveal-overlay--mythic .is-mega-phase-2 .mega-wordmark,
.reveal-overlay--mythic .is-mega-phase-3 .mega-wordmark,
.reveal-overlay--mythic .is-mega-phase-4 .mega-wordmark{ opacity:0; transition:opacity .6s ease; }

.reveal-overlay--mythic .reveal-group{ position:absolute; inset:0; z-index:7; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:11px; padding:3vh 20px; opacity:0; }
.reveal-overlay--mythic .is-revealed .reveal-group{ animation:group-in .6s ease forwards; }
@keyframes group-in{ to{ opacity:1; } }
@media (max-height:760px){ .reveal-overlay--mythic .reveal-group{ transform:scale(.8); } }
