.coopdf-av { width: 46px; height: 46px; border-radius: 13px; display: flex; align-items: center; justify-content: center; font-family: "Cinzel", Georgia, serif; font-weight: 800; font-size: 20px; background: linear-gradient(155deg, #1c1b34, #11101f); }
.coopdf-av.you { color: #bdfdef; border: 1.5px solid rgba(94,234,212,0.7); box-shadow: 0 0 14px rgba(94,234,212,0.22); }
