/* ════════════════════════════════════════════════════════════════
   W376 — Co-op Hunt "Twin Maw Summons" (ClaudeDesign handoff).
   The recipient's pending-invite view becomes a cinematic war summons.
   Layout overrides target shared .bfs-* / .coop-* classes and so are
   scoped under .coop-overlay--summons; the rest are uniquely prefixed
   `coopsm-` (rendered only in that state) and self-isolating.
   Ported from project/"Co-op Hunt - Twin Maw Summons.html".
   ════════════════════════════════════════════════════════════════ */

/* --- summons-mode overlay layout overrides --- */
.coop-overlay--summons .bfs-name-block { display: none; }            /* title lives over the hero */
.coop-overlay--summons .bfs-rank-pill { display: none; }             /* threat tag carries the rank */
/* Keep the Back band ABOVE the hero (as in the mockup) so it never
   overlaps the top-left "Incoming Summons" tag; just tint Back purple. */
.coop-overlay--summons .bfs-back { color: #8b5cf6; }
.coop-overlay--summons .bfs-hero {
  max-width: none; margin: 0; border-radius: 0;
  aspect-ratio: 393 / 292;                                           /* match the design crop box */
}
.coop-overlay--summons .bfs-hero img,
.coop-overlay--summons .bfs-hero-fade { display: none; }             /* replaced by .coopsm-art + fade */
.coop-overlay--summons .coop-body {
  padding: 12px 16px calc(40px + var(--safe-bottom));
  max-width: 440px;
}

/* --- FX container (hidden unless summons mode) --- */
.coopsm-fx { display: none; position: absolute; inset: 0; }
.coop-overlay--summons .coopsm-fx { display: block; }

/* art + slow Ken Burns */
.coopsm-art {
  position: absolute; inset: 0;
  background: url("assets/bosses/the-twin-maw-summons.png") center/cover no-repeat;
  transform: scale(1.06);
  animation: coopsmKenburns 18s ease-in-out infinite alternate;
}
@keyframes coopsmKenburns { from { transform: scale(1.06) translateY(0); } to { transform: scale(1.13) translateY(-8px); } }

/* bottom fade into bg + vignette */
.coopsm-art-fade {
  position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(180deg, rgba(8,8,26,.45) 0%, rgba(8,8,26,0) 22%, rgba(8,8,26,0) 55%, rgba(8,8,26,.7) 82%, #08081a 100%);
}
.coopsm-vig { position: absolute; inset: 0; pointer-events: none; box-shadow: inset 0 0 120px 30px rgba(0,0,0,.55); }

/* pulsing dragon eyes — positioned by % so they track the cover crop at any width */
.coopsm-eye {
  position: absolute; width: 30px; height: 30px; border-radius: 50%; pointer-events: none;
  background: radial-gradient(circle, rgba(255,170,60,.95) 0%, rgba(255,120,30,.55) 35%, rgba(255,90,20,0) 70%);
  mix-blend-mode: screen; animation: coopsmEyepulse 2.6s ease-in-out infinite;
}
.coopsm-eye--l { left: 35.1%; top: 23.3%; }
.coopsm-eye--r { left: 72.8%; top: 14.4%; animation-delay: .5s; }
@keyframes coopsmEyepulse { 0%,100% { opacity:.55; transform:scale(.9); } 50% { opacity:1; transform:scale(1.18); } }

/* lightning flicker */
.coopsm-flick {
  position: absolute; inset: 0; pointer-events: none; mix-blend-mode: screen; opacity: 0;
  background: radial-gradient(120% 80% at 55% 60%, rgba(150,255,235,.5), rgba(150,255,235,0) 55%);
  animation: coopsmFlick 6.5s steps(1) infinite;
}
@keyframes coopsmFlick { 0%,3%,6%,100% { opacity:0; } 1% { opacity:.5; } 2% { opacity:.15; } 4% { opacity:.7; } 5% { opacity:.1; } }

/* hero tags */
.coopsm-tag {
  position: absolute; top: 14px; z-index: 5;
  display: flex; align-items: center; gap: 6px;
  padding: 5px 10px; border-radius: 8px;
  background: rgba(8,8,20,.55);
  -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  font-size: 9.5px; font-weight: 800; letter-spacing: 1.6px; text-transform: uppercase;
}
.coopsm-tag--summons { left: 14px; padding-left: 8px; border: 1px solid rgba(239,68,68,.5); color: #ff9a9a; }
.coopsm-blip { width: 6px; height: 6px; border-radius: 50%; background: #ef4444; box-shadow: 0 0 8px #ef4444; animation: coopsmBlip 1.1s ease-in-out infinite; }
@keyframes coopsmBlip { 0%,100% { opacity:1; transform:scale(1); } 50% { opacity:.35; transform:scale(.7); } }
.coopsm-threat {
  right: 14px; border: 1px solid rgba(245,184,66,.45); color: #f5b842;
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 10px; letter-spacing: 1px;
}
.coopsm-skull { font-size: 11px; }

/* title block over the fade */
.coopsm-titlewrap { position: absolute; left: 0; right: 0; bottom: 6px; z-index: 6; text-align: center; }
.coopsm-kicker {
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 11px; font-weight: 700;
  letter-spacing: 5px; color: #46e0c8; text-transform: uppercase;
  text-shadow: 0 0 14px rgba(70,224,200,.5); margin-bottom: 4px;
}
.coopsm-title {
  font-family: "Cinzel", "Trajan Pro", Georgia, serif; font-size: 38px; font-weight: 800;
  letter-spacing: 2px; line-height: .95; color: #f5b842; text-transform: uppercase;
  text-shadow: 0 0 22px rgba(245,184,66,.45), 0 2px 4px rgba(0,0,0,.6);
}

/* ── summons message card (the redesigned "X wants to hunt" line) ── */
.coopsm-msg {
  position: relative; margin-top: 2px; padding: 12px 14px 13px; border-radius: 14px; overflow: hidden;
  background: linear-gradient(180deg, rgba(139,92,246,.12), rgba(20,20,58,.5));
  border: 1px solid rgba(139,92,246,.32);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.04), 0 0 22px rgba(139,92,246,.12);
}
.coopsm-msg::before {
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px;
  background: linear-gradient(180deg, #8b5cf6, #f5b842); box-shadow: 0 0 12px rgba(139,92,246,.6);
}
.coopsm-msg-head { display: flex; align-items: center; gap: 10px; margin-bottom: 9px; }
.coopsm-av {
  position: relative; width: 42px; height: 42px; flex: none; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(150deg, #3a2a6a, #1a1638);
  font-family: "Cinzel", "Trajan Pro", Georgia, serif; font-weight: 800; font-size: 19px; color: #f5b842;
  border: 1.5px solid rgba(245,184,66,.7); box-shadow: 0 0 14px rgba(245,184,66,.3);
}
.coopsm-eyebrow {
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9.5px; font-weight: 800;
  letter-spacing: 2.2px; color: #f5b842; text-transform: uppercase; margin-bottom: 5px;
  display: flex; align-items: center; gap: 7px;
}
.coopsm-eyebrow::after { content: ""; flex: 1; height: 1px; background: linear-gradient(90deg, rgba(245,184,66,.4), transparent); }
.coopsm-meta { min-width: 0; }
.coopsm-name { font-size: 14px; font-weight: 800; letter-spacing: .4px; color: #f5f5fa; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.coopsm-sub {
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9.5px; font-weight: 600;
  letter-spacing: 1.4px; color: #9aa0bd; text-transform: uppercase; margin-top: 2px;
}
.coopsm-cry {
  font-family: "Cinzel", "Trajan Pro", Georgia, serif; font-size: 19px; font-weight: 700;
  font-style: italic; line-height: 1.25; color: #fff; letter-spacing: .2px;
}
.coopsm-accent { color: #f5b842; font-style: normal; }
.coopsm-q { color: #8b5cf6; font-size: 24px; line-height: 0; vertical-align: -6px; font-style: normal; }

/* ── The Pact card ── */
.coopsm-pact {
  margin-top: 10px; border-radius: 14px; padding: 12px 16px 13px; text-align: center;
  background: linear-gradient(180deg, rgba(20,20,58,.7), rgba(14,14,42,.7));
  border: 1px solid rgba(245,184,66,.18); box-shadow: inset 0 1px 0 rgba(255,255,255,.03);
}
.coopsm-pact-label {
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9.5px; font-weight: 700;
  letter-spacing: 3px; color: #9aa0bd; text-transform: uppercase; margin-bottom: 6px;
}
.coopsm-pact-num {
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 36px; font-weight: 800;
  letter-spacing: 1px; line-height: .9; color: #f5b842; text-shadow: 0 0 26px rgba(245,184,66,.4);
}
.coopsm-pact-sub { font-size: 12.5px; color: #9aa0bd; font-weight: 500; margin-top: 9px; letter-spacing: .2px; }
.coopsm-pact-sub b { color: #f5f5fa; font-weight: 700; }
.coopsm-pact-split { display: flex; align-items: center; gap: 8px; margin-top: 12px; }
.coopsm-who {
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9px; font-weight: 700;
  letter-spacing: 1px; color: #9aa0bd; text-transform: uppercase;
  max-width: 84px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.coopsm-bar { flex: 1; height: 6px; border-radius: 4px; overflow: hidden; background: rgba(255,255,255,.06); display: flex; }
.coopsm-me { width: 50%; background: linear-gradient(90deg, #8b5cf6, #b98bff); }
.coopsm-them { width: 50%; background: linear-gradient(90deg, #b98741, #f5b842); }

/* ── CTAs ── */
.coopsm-ctas { margin-top: 14px; }
.coopsm-join {
  width: 100%; height: 52px; border: none; border-radius: 14px; cursor: pointer;
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 16px; font-weight: 800;
  letter-spacing: 3px; color: #1a1206; text-transform: uppercase;
  background: linear-gradient(180deg, #ffd574, #f5b842);
  box-shadow: 0 0 26px rgba(245,184,66,.5), inset 0 1px 0 rgba(255,255,255,.5), inset 0 -2px 6px rgba(120,70,0,.4);
  display: flex; align-items: center; justify-content: center; gap: 11px;
  animation: coopsmJoinpulse 2.4s ease-in-out infinite;
}
@keyframes coopsmJoinpulse {
  0%,100% { box-shadow: 0 0 22px rgba(245,184,66,.42), inset 0 1px 0 rgba(255,255,255,.5), inset 0 -2px 6px rgba(120,70,0,.4); }
  50% { box-shadow: 0 0 38px rgba(245,184,66,.72), inset 0 1px 0 rgba(255,255,255,.6), inset 0 -2px 6px rgba(120,70,0,.4); }
}
.coopsm-join:active { transform: translateY(1px); }
.coopsm-join[disabled] { opacity: .6; cursor: default; animation: none; }
.coopsm-decline {
  width: 100%; height: 44px; margin-top: 9px; border-radius: 13px; cursor: pointer;
  background: rgba(255,255,255,.02); border: 1px solid rgba(255,255,255,.1);
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 12px; font-weight: 700;
  letter-spacing: 3px; color: #8a8aa8; text-transform: uppercase;
}
.coopsm-decline:active { background: rgba(255,255,255,.05); }
.coopsm-decline[disabled] { opacity: .55; cursor: default; }
.coopsm-expires { text-align: center; margin-top: 12px; font-size: 10.5px; color: #5a5a78; letter-spacing: .3px; line-height: 1.4; }

/* entrance animations */
.coopsm-reveal { opacity: 0; transform: translateY(14px); animation: coopsmRise .7s cubic-bezier(.2,.7,.2,1) forwards; }
@keyframes coopsmRise { to { opacity: 1; transform: none; } }
.coopsm-d1 { animation-delay: .12s; }
.coopsm-d2 { animation-delay: .24s; }
.coopsm-d3 { animation-delay: .36s; }
.coopsm-d4 { animation-delay: .48s; }

@media (prefers-reduced-motion: reduce) {
  .coopsm-reveal, .coopsm-eye, .coopsm-art, .coopsm-blip {
    animation: none !important; opacity: 1 !important; transform: none !important;
  }
  .coopsm-flick { animation: none !important; opacity: 0 !important; }
  .coopsm-join { animation: none !important; }
}


/* ── W393 — Co-op invite TOP BANNER (ClaudeDesign "Co-op Summons Banner") ──
   Namespaced csb-* (the design's .msg/.txt/.ally/.answer would collide). Fixed at
   the top, slides in; .arriving = entrance pulse peak, .resting = breathing glow. */
@property --csb-glow { syntax:'<number>'; inherits:false; initial-value:.32; }
.csb-banner{
  position:fixed; top:calc(env(safe-area-inset-top, 0px) + 8px); left:10px; right:10px; z-index:9000;
  display:flex; align-items:center; gap:13px; padding:13px 14px; border-radius:16px;
  background:linear-gradient(157deg,#12122c 0%,#0a0a1c 55%,#07070f 100%);
  border:1px solid rgba(255,255,255,.08);
  box-shadow:0 18px 40px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.05);
  overflow:hidden; cursor:pointer; --csb-glow:.32;
  transform:translateY(-140%); opacity:0;
  transition:transform .5s cubic-bezier(.16,1,.3,1), opacity .45s ease;
}
.csb-banner.csb-in{ transform:translateY(0); opacity:1; }
.csb-banner::before{ content:""; position:absolute; top:-40%; right:-10%; width:150px; height:180%;
  background:radial-gradient(closest-side,rgba(255,122,60,.22),rgba(255,122,60,0) 75%); pointer-events:none; }
.csb-banner::after{ content:""; position:absolute; inset:0; border-radius:16px; pointer-events:none;
  box-shadow:inset 0 0 0 1px rgba(90,214,200,calc(var(--csb-glow) * .9)), 0 0 26px rgba(90,214,200,calc(var(--csb-glow) * .8)); }
.csb-banner > *{ position:relative; z-index:1; }
.csb-ally{ width:46px; height:46px; flex:none; border-radius:50%; display:flex; align-items:center; justify-content:center;
  font-family:"Cinzel",Georgia,serif; font-weight:700; font-size:19px; color:#5ad6c8; letter-spacing:1px;
  background:radial-gradient(circle at 50% 35%,rgba(43,182,166,.30),rgba(8,8,26,.6) 72%);
  box-shadow:0 0 0 1.6px #5ad6c8, 0 0 16px rgba(90,214,200,.45), inset 0 0 10px rgba(90,214,200,.18); }
.csb-txt{ flex:1; min-width:0; }
.csb-eyebrow{ font-family:"JetBrains Mono",monospace; font-size:10px; font-weight:800; letter-spacing:2.4px;
  color:#5ad6c8; text-transform:uppercase; margin-bottom:5px; display:flex; align-items:center; gap:7px; }
.csb-spark{ width:5px; height:5px; border-radius:50%; background:#5ad6c8; box-shadow:0 0 8px #5ad6c8; }
.csb-msg{ font-family:"Cinzel",Georgia,serif; font-weight:600; font-size:15.5px; line-height:1.14; color:#f5f3fb; letter-spacing:.1px; }
.csb-who{ color:#f5b842; font-weight:700; }
