.pvp-hub-stat .k { font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 700; letter-spacing: 0.14em; color: #54546c; text-transform: uppercase; margin-top: 5px; }
.pvp-hub-pips { display: flex; gap: 4px; justify-content: center; align-items: center; min-height: 13px; }
