.pvp-hub-peak .box.hi { border-color: rgba(245,184,66,0.3); background: linear-gradient(170deg, rgba(245,184,66,0.07), #101019); }
.pvp-hub-peak .v { font-family: "JetBrains Mono", monospace; font-weight: 800; font-size: 23px; color: #f5b842; }
