.pvp-ld-sparse { height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 0 30px 80px; }
.pvp-ld-sparse .sig { width: 90px; height: 90px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin-bottom: 22px; border: 1px solid rgba(245,184,66,0.3); box-shadow: 0 0 36px rgba(245,184,66,0.12), inset 0 0 24px rgba(245,184,66,0.06); }
.pvp-ld-sparse .sig span { font-family: "Cinzel", Georgia, serif; font-size: 28px; color: #f5b842; text-shadow: 0 0 16px rgba(245,184,66,0.5); }
.pvp-ld-sparse .eyebrow { font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 800; letter-spacing: 0.24em; color: #f5b842; text-transform: uppercase; margin-bottom: 12px; }
.pvp-ld-sparse h3 { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 22px; letter-spacing: 0.5px; margin: 0; color: #f5f3fb; }
.pvp-ld-sparse p { font-size: 12px; color: #8a8aa2; margin: 14px 0 0; line-height: 1.5; max-width: 250px; }

/* Find Match secondary ("duel a friend") button */
.pvp-mid { display: flex; flex-direction: column; gap: 2px; padding: 12px 16px; border-radius: 13px; cursor: pointer; text-align: center; align-items: center;
  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.11); -webkit-tap-highlight-color: transparent; transition: transform 0.12s ease, filter 0.12s ease; }
.pvp-mid:active { transform: scale(0.985); filter: brightness(1.12); }
.pvp-mid-t { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 14px; color: #f5f3fb; }
.pvp-mid-s { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.06em; color: #9090a8; }

/* ── W423 · Pre-Match VS (ClaudeDesign "The Pre-Match VS") — vertical face-off,
   you (teal) over your rival (ember/gold-friendly), seam + medal, slam-in, stakes,
   countdown. Baked rgba (iOS 14 floor), no color-mix. ── */
.pvp-vs2 { position: relative; display: flex; flex-direction: column; min-height: 82vh; overflow: hidden; border-radius: 16px; }
.pvp-vs2-stage { position: absolute; inset: 0; overflow: hidden; z-index: 0; }
.pvp-vs2-tint { position: absolute; inset: 0; pointer-events: none; }
.pvp-vs2-tint.you { clip-path: polygon(0 0, 100% 0, 100% 47%, 0 53%); background: radial-gradient(120% 80% at 30% 14%, rgba(90,214,200,.22), transparent 60%), linear-gradient(180deg, rgba(90,214,200,.06), transparent 55%); }
.pvp-vs2-tint.foe { clip-path: polygon(0 53%, 100% 47%, 100% 100%, 0 100%); background: radial-gradient(120% 80% at 70% 86%, rgba(255,107,74,.22), transparent 60%), linear-gradient(0deg, rgba(255,107,74,.07), transparent 55%); }
.pvp-vs2-tint.foe.friend { background: radial-gradient(120% 80% at 70% 86%, rgba(245,184,66,.2), transparent 60%), linear-gradient(0deg, rgba(245,184,66,.06), transparent 55%); }
.pvp-vs2-seam { position: absolute; left: -6%; right: -6%; top: 50%; height: 2px; transform: rotate(-4deg); z-index: 2; background: linear-gradient(90deg, transparent, #5ad6c8 18%, #f5b842 50%, #ff6b4a 82%, transparent); box-shadow: 0 0 18px rgba(245,184,66,.5); opacity: .9; }
.pvp-vs2-seam.friend { background: linear-gradient(90deg, transparent, #5ad6c8 22%, #f5b842 50%, #ffd574 78%, transparent); }
.pvp-vs2-medal { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); z-index: 3; width: 66px; height: 66px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-family: "Cinzel", Georgia, serif; font-weight: 900; font-size: 25px; letter-spacing: 1px; color: #ffd574; background: radial-gradient(circle, #1a1408, #0a0a12 72%); border: 1px solid rgba(245,184,66,.5); box-shadow: 0 0 30px rgba(245,184,66,.4), inset 0 0 14px rgba(245,184,66,.25); text-shadow: 0 0 16px rgba(245,184,66,.6); }
.pvp-vs2-content { position: relative; z-index: 4; display: flex; flex-direction: column; flex: 1; padding: 8px 14px 16px; }
.pvp-vs2-eyebrow { text-align: center; font-family: "JetBrains Mono", monospace; font-size: 10px; font-weight: 800; letter-spacing: 0.2em; text-transform: uppercase; color: #f5b842; }
.pvp-vs2-eyebrow .season { display: block; color: #54546c; font-size: 8.5px; letter-spacing: 0.14em; margin-top: 5px; }
.pvp-vs2-hunter { display: flex; flex-direction: column; align-items: center; text-align: center; }
.pvp-vs2-hunter--you { margin-top: 12px; }
.pvp-vs2-hunter--foe { margin-top: auto; }
.pvp-vs2-crestwrap { width: 92px; height: 92px; position: relative; display: flex; align-items: center; justify-content: center; }
.pvp-vs2-hunter--you .pvp-vs2-crestwrap { filter: drop-shadow(0 0 16px rgba(90,214,200,.4)); }
.pvp-vs2-hunter--foe .pvp-vs2-crestwrap { filter: drop-shadow(0 0 16px rgba(255,107,74,.4)); }
.pvp-vs2-hunter--foe.friend .pvp-vs2-crestwrap { filter: drop-shadow(0 0 16px rgba(245,184,66,.4)); }
.pvp-vs2-crestwrap img { width: 84px; height: 84px; border-radius: 16px; object-fit: cover; object-position: top center; }
.pvp-vs2-crestwrap .pvp-mono { width: 84px; height: 84px; border-radius: 16px; display: flex; align-items: center; justify-content: center; font-family: "Cinzel", Georgia, serif; font-size: 30px; font-weight: 800; color: #f5f3fb; background: rgba(255,255,255,.05); }
.pvp-vs2-badge { position: absolute; bottom: -7px; right: -7px; filter: drop-shadow(0 2px 4px rgba(0,0,0,.5)); }
.pvp-vs2-side { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; margin-top: 9px; }
.pvp-vs2-hunter--you .pvp-vs2-side { color: #5ad6c8; }
.pvp-vs2-hunter--foe .pvp-vs2-side { color: #ff6b4a; }
.pvp-vs2-hunter--foe.friend .pvp-vs2-side { color: #f5b842; }
.pvp-vs2-alias { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 24px; letter-spacing: 0.5px; line-height: 1; margin-top: 5px; color: #f5f3fb; }
.pvp-vs2-tier { font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; margin-top: 7px; }
.pvp-vs2-wpn { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 700; color: #8a8aa2; margin-top: 5px; }
.pvp-vs2-foot { margin-top: 14px; }
.pvp-vs2-stakes { display: flex; align-items: center; justify-content: center; margin-bottom: 12px; }
.pvp-vs2-stakes .lab { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; color: #54546c; margin-right: 12px; }
.pvp-vs2-stakes .chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 9px; font-family: "JetBrains Mono", monospace; font-size: 11px; font-weight: 800; background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.07); }
.pvp-vs2-stakes .chip + .chip { margin-left: 8px; }
.pvp-vs2-stakes .win { color: #5ad6c8; }
.pvp-vs2-stakes .loss { color: #ff6b4a; }
.pvp-vs2-stakes.friend { font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #8a8aa2; }
.pvp-vs2-stakes.friend b { color: #f5b842; }
.pvp-vs2-count { width: 100%; height: 58px; border-radius: 15px; display: flex; align-items: center; justify-content: center; gap: 12px; cursor: pointer; background: linear-gradient(180deg, #15151f, #0c0c16); border: 1px solid rgba(245,184,66,.3); box-shadow: 0 0 26px rgba(245,184,66,.12), inset 0 1px 0 rgba(255,255,255,.05); }
.pvp-vs2-count .lab { font-family: "JetBrains Mono", monospace; font-size: 11px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; color: #8a8aa2; }
.pvp-vs2-count .num { font-family: "Cinzel", Georgia, serif; font-weight: 900; font-size: 28px; color: #ffd574; line-height: 1; min-width: 22px; text-align: center; text-shadow: 0 0 18px rgba(245,184,66,.5); }
.pvp-vs2-hint { text-align: center; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: #54546c; margin-top: 10px; }
.pvp-vs2.play .pvp-vs2-tint.you, .pvp-vs2.play .pvp-vs2-hunter--you { animation: pvpVsSlamTop .6s cubic-bezier(.2,1.1,.3,1) both; }
.pvp-vs2.play .pvp-vs2-tint.foe, .pvp-vs2.play .pvp-vs2-hunter--foe { animation: pvpVsSlamBot .6s cubic-bezier(.2,1.1,.3,1) both .12s; }
.pvp-vs2.play .pvp-vs2-seam { animation: pvpVsSeam .5s ease both .5s; }
.pvp-vs2.play .pvp-vs2-medal { animation: pvpVsMedal .5s cubic-bezier(.2,1.5,.4,1) both .55s; }
.pvp-vs2.play .pvp-vs2-foot { animation: pvpVsFade .6s ease both .9s; }
@keyframes pvpVsSlamTop { from { opacity: 0; transform: translateX(-50px); } to { opacity: 1; transform: none; } }
@keyframes pvpVsSlamBot { from { opacity: 0; transform: translateX(50px); } to { opacity: 1; transform: none; } }
@keyframes pvpVsSeam { 0% { opacity: 0; } 40% { opacity: 1; box-shadow: 0 0 36px rgba(245,184,66,.9); } 100% { opacity: .9; } }
@keyframes pvpVsMedal { from { opacity: 0; transform: translate(-50%, -50%) scale(.3) rotate(-25deg); } to { opacity: 1; transform: translate(-50%, -50%) scale(1) rotate(0); } }
@keyframes pvpVsFade { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
/* searching scan */
.pvp-vs2-search { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 14px 8px 8px; }
.pvp-vs2-scan { width: 168px; height: 168px; position: relative; display: flex; align-items: center; justify-content: center; margin: 8px 0 6px; }
.pvp-vs2-scan .ring { position: absolute; inset: 0; border-radius: 50%; border: 1px solid rgba(90,214,200,.5); animation: pvpVsScan 2.6s ease-out infinite; }
.pvp-vs2-scan .r2 { animation-delay: .87s; }
.pvp-vs2-scan .r3 { animation-delay: 1.74s; }
.pvp-vs2-scan .spr { width: 88px; height: 88px; border-radius: 18px; object-fit: cover; object-position: top center; position: relative; z-index: 2; filter: drop-shadow(0 0 16px rgba(90,214,200,.4)); }
.pvp-vs2-scan .emb { position: relative; z-index: 2; }
.pvp-vs2-search-eb { font-family: "JetBrains Mono", monospace; font-size: 10px; font-weight: 800; letter-spacing: 0.2em; text-transform: uppercase; color: #5ad6c8; margin-top: 18px; }
.pvp-vs2-search-h { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 22px; margin-top: 12px; }
.pvp-vs2-search-w { font-family: "JetBrains Mono", monospace; font-size: 11px; color: #8a8aa2; margin-top: 10px; }
@keyframes pvpVsScan { 0% { transform: scale(.32); opacity: 0; } 25% { opacity: .85; } 100% { transform: scale(1); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .pvp-vs2.play *, .pvp-vs2-scan .ring { animation: none !important; } .pvp-vs2-scan .ring { opacity: .4; } }

/* ── W427 · Post-Match Result card (ClaudeDesign "The Post-Match Result") ── */
.pvp-rz-card { display: flex; flex-direction: column; min-height: 80vh; padding: 2px 4px 8px; }
.pvp-rz-outcome { flex: none; text-align: center; padding: 16px 0 18px; position: relative; border-radius: 18px; overflow: hidden; margin-top: 2px; }
.pvp-rz-outcome::before { content: ""; position: absolute; inset: 0; z-index: 0; }
.pvp-rz-card.win .pvp-rz-outcome::before { background: radial-gradient(120% 130% at 50% 0%, rgba(245,184,66,.2), transparent 62%); }
.pvp-rz-card.loss .pvp-rz-outcome::before { background: radial-gradient(120% 130% at 50% 0%, rgba(255,107,74,.16), transparent 62%); }
.pvp-rz-card.draw .pvp-rz-outcome::before { background: radial-gradient(120% 130% at 50% 0%, rgba(203,213,225,.12), transparent 62%); }
.pvp-rz-rays { position: absolute; top: -40px; left: 50%; transform: translateX(-50%); width: 360px; height: 240px; z-index: 0; pointer-events: none; opacity: .5; background: repeating-conic-gradient(from 0deg at 50% 30%, rgba(245,184,66,.12) 0deg 3deg, transparent 3deg 16deg); -webkit-mask-image: radial-gradient(circle at 50% 30%, #000 8%, transparent 60%); mask-image: radial-gradient(circle at 50% 30%, #000 8%, transparent 60%); }
.pvp-rz-card.loss .pvp-rz-rays, .pvp-rz-card.draw .pvp-rz-rays { display: none; }
.pvp-rz-outcome > .pvp-rz-eyebrow, .pvp-rz-outcome > .pvp-rz-word, .pvp-rz-outcome > .pvp-rz-flavor { position: relative; z-index: 1; }
.pvp-rz-eyebrow { font-family: "JetBrains Mono", monospace; font-size: 9.5px; font-weight: 800; letter-spacing: 0.2em; text-transform: uppercase; color: #8a8aa2; }
.pvp-rz-card.win .pvp-rz-eyebrow { color: #f5b842; }
.pvp-rz-word { font-family: "Cinzel", Georgia, serif; font-weight: 900; font-size: 46px; letter-spacing: 3px; line-height: 1; margin-top: 9px; text-transform: uppercase; }
.pvp-rz-card.win .pvp-rz-word { color: #f5b842; text-shadow: 0 0 30px rgba(245,184,66,.5); }
.pvp-rz-card.loss .pvp-rz-word { color: #ff6b4a; text-shadow: 0 0 24px rgba(255,107,74,.35); }
.pvp-rz-card.draw .pvp-rz-word { color: #cbd5e1; text-shadow: 0 0 20px rgba(203,213,225,.3); }
.pvp-rz-flavor { font-family: "Cinzel", Georgia, serif; font-style: italic; font-size: 13.5px; color: #8a8aa2; margin-top: 11px; line-height: 1.4; padding: 0 14px; }
.pvp-rz-recap { flex: none; display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 14px; }
.pvp-rz-side { display: flex; flex-direction: column; align-items: center; gap: 5px; min-width: 92px; position: relative; }
.pvp-rz-side.dim { opacity: .5; }
.pvp-rz-crest { line-height: 0; }
.pvp-rz-alias { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 15px; color: #f5f3fb; }
.pvp-rz-tier { font-family: "JetBrains Mono", monospace; font-size: 7.5px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }
.pvp-rz-badge { position: absolute; top: -6px; right: 14px; width: 18px; height: 18px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 9px; font-weight: 900; color: #06231f; z-index: 2; background: #f5b842; box-shadow: 0 0 10px rgba(245,184,66,.6); }
.pvp-rz-badge.foe { background: #ff6b4a; box-shadow: 0 0 10px rgba(255,107,74,.6); }
.pvp-rz-mid { display: flex; flex-direction: column; align-items: center; gap: 3px; }
.pvp-rz-score { font-family: "JetBrains Mono", monospace; font-weight: 800; font-size: 19px; color: #f5f3fb; letter-spacing: 1px; }
.pvp-rz-final { font-family: "JetBrains Mono", monospace; font-size: 8px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; color: #54546c; }
.pvp-rz-elo { flex: none; margin-top: 16px; background: linear-gradient(170deg, rgba(255,255,255,.035), rgba(255,255,255,.01)); border: 1px solid rgba(255,255,255,.07); border-radius: 16px; padding: 15px 16px; }
.pvp-rz-ehead { display: flex; align-items: center; justify-content: space-between; }
.pvp-rz-ehead .lab { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; color: #54546c; }
.pvp-rz-delta { font-family: "JetBrains Mono", monospace; font-size: 13px; font-weight: 800; padding: 4px 10px; border-radius: 8px; }
.pvp-rz-elo--pos .pvp-rz-delta { color: #5ad6c8; background: rgba(90,214,200,.1); border: 1px solid rgba(90,214,200,.3); }
.pvp-rz-elo--neg .pvp-rz-delta { color: #ff6b4a; background: rgba(255,107,74,.1); border: 1px solid rgba(255,107,74,.3); }
.pvp-rz-elo--zero .pvp-rz-delta { color: #8a8aa2; background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.08); }
.pvp-rz-big { display: flex; align-items: baseline; gap: 10px; margin-top: 9px; }
.pvp-rz-big .now { font-family: "JetBrains Mono", monospace; font-weight: 800; font-size: 31px; color: #f5f3fb; letter-spacing: .5px; line-height: 1; }
.pvp-rz-big .from { font-family: "JetBrains Mono", monospace; font-size: 11px; font-weight: 600; color: #54546c; }
.pvp-rz-track { height: 9px; border-radius: 6px; background: rgba(255,255,255,.05); overflow: hidden; margin-top: 13px; box-shadow: inset 0 0 0 1px rgba(255,255,255,.05); }
.pvp-rz-fill { height: 100%; border-radius: 6px; transition: width 1.1s cubic-bezier(.3,1,.4,1); background: linear-gradient(90deg, #5b6675, #cbd5e1); box-shadow: 0 0 12px rgba(203,213,225,.4); }
.pvp-rz-elo--neg .pvp-rz-fill { background: linear-gradient(90deg, #e2531c, #ff6b4a); box-shadow: 0 0 12px rgba(255,107,74,.3); }
.pvp-rz-brow { display: flex; justify-content: space-between; margin-top: 7px; font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 0.08em; color: #54546c; text-transform: uppercase; }
.pvp-rz-brow b { color: #cbd5e1; }
.pvp-rz-meta { flex: none; display: flex; gap: 10px; margin-top: 11px; }
.pvp-rz-m { flex: 1; background: #101019; border: 1px solid rgba(255,255,255,.07); border-radius: 12px; padding: 10px 8px; text-align: center; }
.pvp-rz-m .mv { font-family: "JetBrains Mono", monospace; font-weight: 800; font-size: 15px; color: #f5f3fb; letter-spacing: .3px; }
.pvp-rz-m.streak .mv { color: #f5b842; }
.pvp-rz-m .mk { font-family: "JetBrains Mono", monospace; font-size: 7.5px; font-weight: 700; letter-spacing: 0.12em; color: #54546c; text-transform: uppercase; margin-top: 4px; }
.pvp-rz-promo { flex: none; margin-top: 12px; border-radius: 14px; padding: 12px 14px; display: flex; align-items: center; gap: 12px; cursor: pointer; position: relative; overflow: hidden; background: linear-gradient(120deg, rgba(245,184,66,.16), rgba(245,184,66,.04)); border: 1px solid rgba(245,184,66,.4); box-shadow: 0 0 22px rgba(245,184,66,.14); animation: pvpRzPromo 2.2s ease-in-out infinite; }
@keyframes pvpRzPromo { 0%,100% { box-shadow: 0 0 16px rgba(245,184,66,.12); } 50% { box-shadow: 0 0 30px rgba(245,184,66,.3); } }
.pvp-rz-promo .pcrest { flex: none; line-height: 0; filter: drop-shadow(0 0 8px rgba(245,184,66,.5)); }
.pvp-rz-promo .ptxt { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.pvp-rz-promo .pe { font-family: "JetBrains Mono", monospace; font-size: 8.5px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; color: #f5b842; }
.pvp-rz-promo .pt { font-family: "Cinzel", Georgia, serif; font-weight: 700; font-size: 17px; color: #f5f3fb; letter-spacing: .5px; margin-top: 3px; }
.pvp-rz-promo .pgo { font-family: "JetBrains Mono", monospace; font-size: 9px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: #f5b842; flex: none; }
.pvp-rz-ctas { flex: none; margin-top: auto; padding-top: 16px; display: flex; flex-wrap: wrap; gap: 10px; }
.pvp-rz-btn { flex: 1; min-width: 130px; height: 52px; border-radius: 13px; margin: 0; }
.pvp-rz-card .pvp-friendly-note { margin-top: 16px; }
.pvp-rz-card .bks-share-cta { margin-top: 12px; }
.pvp-rz-card.play .pvp-rz-outcome { animation: pvpRzPop .6s cubic-bezier(.2,1.3,.4,1) both; }
.pvp-rz-card.play .pvp-rz-recap { animation: pvpRzUp .5s ease both .25s; }
.pvp-rz-card.play .pvp-rz-elo { animation: pvpRzUp .5s ease both .4s; }
.pvp-rz-card.play .pvp-rz-meta { animation: pvpRzUp .5s ease both .55s; }
.pvp-rz-card.play .pvp-rz-promo { animation: pvpRzUp .5s ease both .7s, pvpRzPromo 2.2s ease-in-out infinite .7s; }
.pvp-rz-card.play .pvp-rz-ctas { animation: pvpRzUp .5s ease both .8s; }
@keyframes pvpRzPop { from { opacity: 0; transform: scale(.85) translateY(-10px); } to { opacity: 1; transform: none; } }
@keyframes pvpRzUp { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .pvp-rz-card.play * { animation: none !important; } .pvp-rz-fill { transition: none !important; } .pvp-rz-promo { animation: none !important; } }
